// admin.js v2 — the admin panel (order lookup, org/product management, image
// uploads). Lazily loaded via a <script src="admin.js"> tag injected by
// loadAdminScript() in index.html, ONLY when /api/catalog reports
// status:"admin" — i.e. only on the admin subdomain. Never shipped to a
// storefront visitor.
//
// This is a classic (non-module) script, loaded as a sibling <script> tag
// to index.html's own inline script — top-level `let`/`const`/function
// declarations in one classic script are visible to code in any other
// classic script tag in the same document (they share one global lexical
// environment), so everything here can freely use index.html's shared
// state (currentOrg, route, SIZE_ORDER) and
// utilities (escapeHtml, showToast, announceStatus, promptAdminPassphrase,
// thumbUrl, go) exactly as if this code were part of index.html.

let adminKey = null; // "cookie" when signed in via the HttpOnly session cookie, or the raw passphrase (TOTP off)
// A step the signed-in user must finish before anything else is shown: "account" (a name, an
// email and a password of their own), "password" (replace a temporary one) or "2fa" (enrol, when
// two-step sign-in is required). The SERVER refuses everything else until it is done
// (functions/_lib/adminAuth.js); this only decides which screen to draw.
let adminPending = null;
// Who is signed in: { name, email, role } with role "staff" | "manager" | "admin", or null.
let adminMe = null;
// Roles, lowest to highest. The menu and the router hide what a role can't use; the server is
// what actually refuses it. A role this page doesn't know (or none yet) hides nothing.
const ADMIN_ROLE_LABELS = { staff: "Back office", manager: "Manager", admin: "Admin" };
const adminRoleRank_ = (role) => role === "admin" ? 3 : role === "manager" ? 2 : role === "staff" ? 1 : 0;
function adminCan_(need){ const mine = adminMe && adminRoleRank_(adminMe.role); return !mine || mine >= adminRoleRank_(need); }
let _adminJustSignedIn = false; // set by a fresh sign-in (not a remembered session); read once by loadAdminOrgList
let _boxPresetsCache = null; // cached from DB; null = not yet loaded

// ---- Session management ----
// The session itself is an HttpOnly cookie set by /api/admin-session — this
// script can't read it (so an XSS can't steal it); the browser attaches it to
// every same-origin /api call automatically. localStorage only remembers a
// non-secret marker ({token:"cookie", expires}) so we know not to re-prompt.
// Sessions last 24 hours.
// The install's root domain, worked out from where the admin panel itself is served
// ("admin.myshop.com" → "myshop.com"); shops live at <subdomain>.<root domain>.
function siteRootDomain_(){ const h = String(location.hostname || ""); const i = h.indexOf("."); return i > 0 ? h.slice(i + 1) : h; }
const ADMIN_SESSION_STORAGE_KEY = "oddAdminSession";

function loadStoredSession(){
  try{
    const s = JSON.parse(localStorage.getItem(ADMIN_SESSION_STORAGE_KEY) || "null");
    if(!s || !s.token || !s.expires) return null;
    // Anything other than the cookie marker (a bearer token) doesn't belong here, and the
    // server wouldn't accept it — drop it so it isn't left lying around.
    if(s.token !== "cookie"){ localStorage.removeItem(ADMIN_SESSION_STORAGE_KEY); return null; }
    if(new Date(s.expires) <= new Date()) return null; // expired
    return s;
  }catch(e){ return null; }
}

// The marker also remembers who signed in and any step they still owe, so a reload draws the
// right menu and screen straight away. None of it is a credential.
function saveAdminSession(token, expires){
  try{ localStorage.setItem(ADMIN_SESSION_STORAGE_KEY, JSON.stringify({token, expires, pending: adminPending || null, user: adminMe || null})); }catch(e){}
}
// After a step is finished (or the server says where we stand): keep the marker in line.
function updateStoredSession_(){
  const s = loadStoredSession();
  if(s) saveAdminSession(s.token, s.expires);
}
// The email typed at the last sign-in, to save typing it again (never the password).
const ADMIN_EMAIL_STORAGE_KEY = "oddAdminEmail";
function rememberedAdminEmail_(){ try{ return localStorage.getItem(ADMIN_EMAIL_STORAGE_KEY) || ""; }catch(e){ return ""; } }
function rememberAdminEmail_(email){ try{ if(email) localStorage.setItem(ADMIN_EMAIL_STORAGE_KEY, email); }catch(e){} }

function clearAdminAuth(){
  // Revoke the session server-side and clear the cookie. The cookie is
  // HttpOnly, so only the server can remove it.
  fetch("/api/admin-session", { method: "DELETE" }).catch(function(){});
  adminKey = null;
  adminPending = null;
  adminMe = null;
  try{ localStorage.removeItem(ADMIN_SESSION_STORAGE_KEY); }catch(e){}
}

// Ends every session of the signed-in user on every device (a lost laptop, a browser left open
// somewhere), this one included; the next visit asks them to sign in again.
async function adminSignOutEverywhere(){
  if(!await askConfirm_("Sign out everywhere?\n\nEvery device and browser you're signed in on — including this one — will have to sign in again.")) return;
  try{
    const res = await fetch("/api/admin-session?all=1", { method: "DELETE" });
    const data = await res.json().catch(() => ({}));
    if(!res.ok || data.status === "error"){ showToast((data && data.message) || "Could not sign out everywhere.", true); return; }
  }catch(e){ showToast("Could not reach the server.", true); return; }
  showToast("Signed out everywhere.");
  adminSignOut();
}

function adminSignOut(){
  clearAdminAuth();
  adminOrgs = null;
  renderAdminNav();
  const app = document.getElementById("app");
  if(app) renderAdminPicker(app);
}

// ---- Hash-based URL routing ----
// _currentAdminHash tracks what hash WE set most recently, so the hashchange
// listener can skip firings that we triggered ourselves (vs. the user pressing
// the browser back/forward button). This avoids a double-render loop:
// a render function calls adminSetHash() → location.hash changes → hashchange
// fires → we check _currentAdminHash → same → bail out.
let _currentAdminHash = null;

function adminSetHash(hash) {
  _currentAdminHash = hash;
  if (location.hash !== "#" + hash) location.hash = hash;
  if (typeof renderAdminNav === "function") renderAdminNav();
}

// Breadcrumb bar — items is [{label, hash}] (last item is current page, no hash).
function adminBreadcrumbs(items) {
  if (!items || items.length <= 1) return "";
  const parts = items.map((item, i) => {
    if (i === items.length - 1) return `<span class="bc-current">${escapeHtml(item.label)}</span>`;
    if (!item.hash) return `<span class="bc-group">${escapeHtml(item.label)}</span>`;   // a menu name, not a page
    return `<a class="bc-link" href="#${escapeHtml(item.hash)}">${escapeHtml(item.label)}</a>`;
  });
  return `<nav class="breadcrumbs" aria-label="Breadcrumb">${parts.join('<span class="bc-sep"> › </span>')}</nav>`;
}

// Every admin page's tab title: "<Business> — <Page> (Admin)".
function adminTitle_(page){ return bizName_() + " — " + page + " (Admin)"; }
// Every admin page's heading: breadcrumbs, the title and (optionally) more under it. A page in a menu gets
// "<Menu> › <Page>" by itself; pass crumbs for a page deeper down (a shop's products, a design). The heading is
// hidden on screen (index.html .admin-hero — the highlighted menu says where you are) but kept for screen readers'
// page structure and tests, so put anything the admin must SEE or use in the page itself, not in `after`.
function adminPageHead_(title, opts){
  opts = opts || {};
  let crumbs = opts.crumbs;
  if (!crumbs) {
    const page = (typeof adminNavActive_ === "function") ? adminNavActive_() : "";
    const g = (typeof ADMIN_NAV_GROUPS !== "undefined" ? ADMIN_NAV_GROUPS : []).find(gr => gr.items.some(it => Array.isArray(it) && it[0] === page));
    crumbs = g ? [{ label: g.label }, { label: title }] : [];
  }
  return `<div class="org-hero admin-hero" style="--org-accent:var(--accent);">${adminBreadcrumbs(crumbs)}<h1 class="org-name">${escapeHtml(title)}</h1>${opts.after || ""}</div>`;
}

// A shop or product id taken from the address bar names the screen to draw, so it has to look like
// an id — letters, digits, "-" and "_", which is all a real one is made of
// (functions/_lib/catalogValidation.js) — before anything is drawn with it. Returns null otherwise.
function routeId_(part) {
  let v = "";
  try { v = decodeURIComponent(part); } catch (_) { return null; }
  return /^[A-Za-z0-9_-]{1,64}$/.test(v) ? v : null;
}

// Dispatches to the right render function based on location.hash.
// Called on load (after admin.js loads) and on hashchange (browser back/forward).
// The shop last opened on a per-shop page (Orders, Products, Designs, Graphics), for pages reached from the menu.
function adminLastShop_(){
  const ids = (adminOrgs || []).map(o => o.orgId);
  return ids.includes(window._adminLastShop) ? window._adminLastShop : (ids[0] || "");
}
function adminNoteShop_(orgId){ if (orgId && orgId !== "all") window._adminLastShop = orgId; }
async function adminRoute() {
  const app = document.getElementById("app");
  const raw = location.hash.replace(/^#\/?/, "");
  renderAdminNav();

  // Not authed yet? Show the picker shell WITHOUT changing the hash — loadAdminOrgList() reads
  // this same destination hash and re-invokes adminRoute() once authed, so we land on the real
  // page (with the menu) instead of a headerless one. Covers a deep-linked refresh too.
  if (!adminOrgs) {
    renderAdminPicker(app);
    return;
  }

  // A step still owed (account set-up, a new password, two-step enrolment) comes first, whatever the address says.
  if (adminPending) { renderPendingStep_(app); return; }

  // A page of a feature that's switched off (Global settings → Features): say so instead of
  // showing a screen whose every request the server would refuse.
  // The desktop version has no Vendor integrations page: its vendors are in Global settings →
  // Features → Supplier connections.
  if (adminDesktop_() && String(raw).split("/")[0] === "vendors") { window._gScrollTo = "gFeatRow-suppliers"; renderGlobalSettings(app); return; }
  if (adminDesktopHides_(raw)) { renderDesktopOff_(app, raw); return; }
  { const off = adminPageFeature_(raw); if (off && !featureOn_(off)) { renderFeatureOff_(app, off, raw); return; } }
  // A page this user's role can't use: say so (the server would refuse every request it makes).
  if (!adminCan_(adminPageRole_(raw))) { renderRoleOff_(app, raw); return; }

  // The Orders page opens on the first shop (the top of the Shop dropdown); "All shops" is #orders/all
  // ("all" is reserved, never a shop's id). #picker and an empty hash land on the first shop too.
  if (raw === "orders/all") { renderOrdersPage(app); return; }
  if (!raw || raw === "picker" || raw === "orders") {
    const first = (adminOrgs || [])[0];
    if (first) renderAdminOrders(app, first); else renderOrdersPage(app);
    return;
  }

  // A single shop's orders: #orders/<orgId>.
  const ordersMatch = raw.match(/^orders\/([^/]+)$/);
  if (ordersMatch) {
    const orgId = decodeURIComponent(ordersMatch[1]);
    const org = adminOrgs.find(o => o.orgId === orgId);
    if (org) renderAdminOrders(app, org);
    else renderOrdersPage(app);
    return;
  }

  if (raw === "catalog") { renderAdminOrgList(app); return; }

  if (raw === "inventory") { renderAdminBlanks(app); return; }
  if (raw === "threads")   { renderThreadCatalog(app); return; }
  if (raw === "hoops")     { renderHoopCatalog(app); return; }
  if (raw === "locations") { renderLocationsCatalog(app); return; }
  if (raw === "categories") { renderProductCategories(app); return; }
  if (raw === "abortreasons") { renderAbortReasons(app); return; }
  if (raw === "packages")  { renderPackageSizes(app); return; }
  if (raw === "orphans")   { renderOrphanImages(app); return; }
  if (raw === "vendors")   { renderVendorIntegrations(app); return; }
  if (raw === "brandrules") { renderBrandRules(app); return; }
  if (raw === "runreport") { renderRunReport(app); return; }
  if (raw === "machines")  { renderMachines(app); return; }
  if (raw === "maintenance" || raw.startsWith("maintenance/")) { renderMaintenance(app, raw.split("/")[1] || ""); return; }
  if (raw === "machinefiles") { renderMachineFiles(app); return; }
  if (raw === "runorder")  { renderRunOrder(app); return; }
  if (raw === "runtransfer") { renderRunTransfer(app); return; }
  if (raw === "transfers") { renderTransfers(app); return; }
  if (raw === "audit")     { renderAuditLog(app); return; }
  if (raw === "revenue")   { renderRevenueReport(app); return; }
  if (raw === "salestax")  { renderSalesTaxReport(app); return; }
  if (raw === "cogs")      { renderInventoryReport(app); return; }
  if (raw === "blankorder") { renderBlanksToOrder(app); return; }
  if (raw === "books")     { renderBooks(app); return; }
  if (raw === "comms")     { renderCommunications(app); return; }
  if (raw === "expenses")  { renderExpenses(app); return; }
  if (raw === "money")     { renderMoney(app); return; }
  if (raw === "reconcile") { renderReconcile(app); return; }
  if (raw === "accountviewer") { renderAccountViewer(app); return; }
  if (raw === "security") { render2FASetup(app); return; }
  if (raw === "password") { renderChangePassword(app, false); return; }
  if (raw === "users") { renderUsers(app); return; }
  // Global Settings lives in the Tools menu (#settings); the old #catalog/settings link still works.
  if (raw === "settings" || raw === "catalog/settings") { renderGlobalSettings(app); return; }
  // A new shop is made with the New shop setup wizard; the old form's address leads there.
  if (raw === "catalog/new-org" || raw === "wizard/new") { await renderShopWizard(app, null); return; }
  const wizardMatch = raw.match(/^wizard\/([^/]+)(\/products)?$/);
  if (wizardMatch) { const id = routeId_(wizardMatch[1]); if (id) await renderShopWizard(app, id, { products: !!wizardMatch[2] }); else renderAdminOrgList(app); return; }

  const orgEditMatch = raw.match(/^catalog\/orgs\/([^/]+)\/edit$/);
  if (orgEditMatch) { const id = routeId_(orgEditMatch[1]); if (id) await renderEditOrgForm(app, id); else renderAdminOrgList(app); return; }

  const productListMatch = raw.match(/^catalog\/orgs\/([^/]+)\/products$/);
  if (productListMatch) { const id = routeId_(productListMatch[1]); if (id) await renderProductList(app, id); else renderAdminOrgList(app); return; }

  const newProductMatch = raw.match(/^catalog\/orgs\/([^/]+)\/products\/new$/);
  if (newProductMatch) { const id = routeId_(newProductMatch[1]); if (id) renderCreateProductForm(app, id); else renderAdminOrgList(app); return; }

  const productEditMatch = raw.match(/^catalog\/orgs\/([^/]+)\/products\/([^/]+)\/edit$/);
  if (productEditMatch) {
    const id = routeId_(productEditMatch[1]), pid = routeId_(productEditMatch[2]);
    if (id && pid) await renderEditProductForm(app, id, pid); else renderAdminOrgList(app);
    return;
  }

  // The menu's Designs / Graphics / Shop setup open the shop last worked on (else the first); each has a shop switch.
  if (raw === "designs" || raw === "graphics" || raw === "setup") {
    const org = adminLastShop_();
    if (org) { adminSetHash(raw + "/" + encodeURIComponent(org)); raw = raw + "/" + encodeURIComponent(org); }
  }
  // Shop setup is the wizard now (the step-list page it replaced lived at #setup/<shop>).
  const setupMatch = raw.match(/^setup\/([^/]+)$/);
  if (setupMatch) {
    const sOrgId = routeId_(setupMatch[1]);
    if (sOrgId) await renderShopWizard(app, sOrgId);
    else renderOrdersPage(app);
    return;
  }
  const designsMatch = raw.match(/^designs\/([^/]+)(?:\/(\d+))?$/);
  if (designsMatch) {
    const dOrgId = routeId_(designsMatch[1]);
    if (dOrgId) await renderDesigns(app, dOrgId, designsMatch[2] ? Number(designsMatch[2]) : null);
    else renderOrdersPage(app);
    return;
  }

  const graphicsMatch = raw.match(/^graphics\/([^/]+)$/);
  if (graphicsMatch) { const id = routeId_(graphicsMatch[1]); if (id) await renderGraphics(app, id); else renderAdminOrgList(app); return; }

  adminSetHash("picker");
  renderAdminPicker(app);
}

// The sign-in prompt: email and password. (It began as a replacement for window.prompt() for the
// one admin passphrase, hence the name.) A native prompt()
// echoes every typed character in plain text with no way to mask it
// (shoulder-surfable) and can't be styled. This renders a small overlay
// with a real type="password" input instead. Resolves with the entered
// string, or "" if the user cancels/dismisses it — matching prompt()'s
// existing cancel behavior, which every call site already treats as
// empty via `|| ""`.
function promptAdminPassphrase(){
  return new Promise((resolve) => {
    const overlay = document.createElement("div");
    overlay.className = "admin-pass-overlay";
    overlay.innerHTML = `
      <form class="admin-pass-box" id="adminPassForm" autocomplete="on">
        <label for="adminEmailInput">Email</label>
        <input type="email" id="adminEmailInput" name="username" autocomplete="username" autocapitalize="off" spellcheck="false" value="${escapeHtml(rememberedAdminEmail_())}" style="margin-bottom:10px;" />
        <label for="adminPassInput">Password</label>
        <input type="password" id="adminPassInput" name="password" autocomplete="current-password" autocapitalize="off" spellcheck="false" />
        <p style="font-size:12px;margin:8px 0 0;color:#666;">New install? Leave the email empty and type the passphrase the installer printed.</p>
        <div class="admin-pass-actions">
          <button type="button" class="admin-pass-cancel">Cancel</button>
          <button type="submit" class="admin-pass-submit">Submit</button>
        </div>
      </form>
    `;
    document.body.appendChild(overlay);
    const input = overlay.querySelector("#adminPassInput");
    const emailInput = overlay.querySelector("#adminEmailInput");
    const form  = overlay.querySelector("#adminPassForm");
    const finish = (value) => {
      _adminSignInEmail = value ? emailInput.value.trim() : "";
      document.body.removeChild(overlay);
      resolve(value);
    };
    // form submit handles both button click and Enter key in one place
    form.addEventListener("submit", (e) => { e.preventDefault(); finish(input.value); });
    overlay.querySelector(".admin-pass-cancel").addEventListener("click", () => finish(""));
    // click outside does not close — use Cancel or Submit
    input.addEventListener("keydown", (e) => { if(e.key === "Escape") finish(""); });
    emailInput.addEventListener("keydown", (e) => { if(e.key === "Escape") finish(""); });
    (emailInput.value ? input : emailInput).focus();
  });
}
// The email typed into the sign-in prompt above (the prompt itself resolves with the password).
let _adminSignInEmail = "";

// Blank-ordered detail modal — vendor, supplier order #, estimated delivery.
// Returns {vendor, vendorOrderId, estimatedDelivery} on submit, or null on cancel.
// Shared tracking-number prompt. required=true enforces a non-empty value (used
// by bulkAddTracking). required=false makes it optional (used by Mark shipped).
function showTrackingModal(title, { required = false, submitLabel = "Save tracking" } = {}){
  return new Promise((resolve) => {
    const overlay = document.createElement("div");
    overlay.className = "admin-pass-overlay";
    overlay.style.zIndex = "1002";
    overlay.innerHTML = `
      <form class="admin-pass-box" style="max-width:420px;">
        <label style="font-weight:600;font-size:15px;margin-bottom:14px;display:block;">${escapeHtml(title)}</label>
        <label style="font-size:13px;font-weight:600;margin-bottom:4px;display:block;">Tracking number${required ? "" : " (optional)"}</label>
        <input type="text" class="tracking-input" placeholder="e.g. 9400100000000000000000" maxlength="100" autocomplete="off" spellcheck="false"
               style="width:100%;padding:8px 10px;border:1px solid var(--border,#ccc);border-radius:5px;font-size:14px;margin-bottom:10px;box-sizing:border-box;font-family:monospace;background:var(--surface,#fff);color:var(--ink,#111);">
        <div class="tracking-err" style="color:#c0392b;font-size:13px;margin-bottom:8px;display:none;"></div>
        <div class="admin-pass-actions">
          <button type="button" class="admin-pass-cancel">Cancel</button>
          <button type="submit" class="admin-pass-submit">${escapeHtml(submitLabel)}</button>
        </div>
      </form>
    `;
    document.body.appendChild(overlay);
    const input  = overlay.querySelector(".tracking-input");
    const errEl  = overlay.querySelector(".tracking-err");
    const finish = (result) => { document.body.removeChild(overlay); resolve(result); };
    overlay.querySelector("form").addEventListener("submit", (e) => {
      e.preventDefault();
      const tn = input.value.trim();
      if(required && !tn){ errEl.textContent = "Enter a tracking number."; errEl.style.display = ""; input.focus(); return; }
      finish(tn || null);
    });
    overlay.querySelector(".admin-pass-cancel").addEventListener("click", () => finish(undefined));
    // click outside does not close — use Cancel or Submit
    document.addEventListener("keydown", function esc(e){
      if(e.key === "Escape"){ finish(undefined); document.removeEventListener("keydown", esc); }
    }, {once: true});
    input.focus();
  });
}

function showBlankOrderModal(title){
  return new Promise((resolve) => {
    const overlay = document.createElement("div");
    overlay.className = "admin-pass-overlay";
    overlay.style.zIndex = "1002";
    overlay.innerHTML = `
      <form class="admin-pass-box" id="blankOrderForm" style="max-width:420px;">
        <label style="font-weight:600;font-size:15px;margin-bottom:14px;display:block;">${escapeHtml(title)}</label>

        <label for="blankVendorSelect" style="font-size:13px;font-weight:600;margin-bottom:4px;display:block;">Vendor</label>
        <select id="blankVendorSelect" style="width:100%;padding:8px 10px;border:1px solid var(--border,#ccc);border-radius:5px;font-size:14px;margin-bottom:10px;background:var(--surface,#fff);color:var(--ink,#111);">
          <option value="SanMar">SanMar</option>
          <option value="S&S">S&amp;S</option>
          <option value="Amazon">Amazon</option>
          <option value="OttoCap">OttoCap</option>
          <option value="Other">Other…</option>
        </select>

        <div id="blankVendorOtherWrap" style="display:none;margin-bottom:10px;">
          <label for="blankVendorOther" style="font-size:13px;font-weight:600;margin-bottom:4px;display:block;">Vendor name</label>
          <input type="text" id="blankVendorOther" placeholder="Enter vendor name" maxlength="100"
                 style="width:100%;padding:8px 10px;border:1px solid var(--border,#ccc);border-radius:5px;font-size:14px;box-sizing:border-box;background:var(--surface,#fff);color:var(--ink,#111);">
        </div>

        <label for="blankVendorOrderId" style="font-size:13px;font-weight:600;margin-bottom:4px;display:block;">Supplier order # <span style="font-weight:400;color:var(--ink-soft,#888)">(optional)</span></label>
        <input type="text" id="blankVendorOrderId" placeholder="e.g. PO-12345" maxlength="100"
               style="width:100%;padding:8px 10px;border:1px solid var(--border,#ccc);border-radius:5px;font-size:14px;margin-bottom:10px;box-sizing:border-box;background:var(--surface,#fff);color:var(--ink,#111);">

        <label for="blankEstDelivery" style="font-size:13px;font-weight:600;margin-bottom:4px;display:block;">Estimated delivery <span style="font-weight:400;color:var(--ink-soft,#888)">(optional)</span></label>
        <input type="date" id="blankEstDelivery" autocomplete="off"
               style="width:100%;padding:8px 10px;border:1px solid var(--border,#ccc);border-radius:5px;font-size:14px;margin-bottom:16px;box-sizing:border-box;background:var(--surface,#fff);color:var(--ink,#111);">

        <div id="blankOrderFormErr" style="color:#c0392b;font-size:13px;margin-bottom:8px;display:none;"></div>
        <div class="admin-pass-actions">
          <button type="button" class="admin-pass-cancel">Cancel</button>
          <button type="submit" class="admin-pass-submit">Mark blank ordered</button>
        </div>
      </form>
    `;
    document.body.appendChild(overlay);

    const vendorSelect = overlay.querySelector("#blankVendorSelect");
    const otherWrap = overlay.querySelector("#blankVendorOtherWrap");
    const otherInput = overlay.querySelector("#blankVendorOther");
    const errEl = overlay.querySelector("#blankOrderFormErr");

    vendorSelect.addEventListener("change", () => {
      const isOther = vendorSelect.value === "Other";
      otherWrap.style.display = isOther ? "" : "none";
      if(isOther) otherInput.focus();
    });

    const finish = (result) => { document.body.removeChild(overlay); resolve(result); };

    overlay.querySelector("#blankOrderForm").addEventListener("submit", (e) => {
      e.preventDefault();
      const isOther = vendorSelect.value === "Other";
      const otherName = otherInput.value.trim();
      if(isOther && !otherName){
        errEl.textContent = "Enter a vendor name.";
        errEl.style.display = "";
        otherInput.focus();
        return;
      }
      finish({
        vendor: isOther ? otherName : vendorSelect.value,
        vendorOrderId: overlay.querySelector("#blankVendorOrderId").value.trim(),
        estimatedDelivery: overlay.querySelector("#blankEstDelivery").value
      });
    });
    overlay.querySelector(".admin-pass-cancel").addEventListener("click", () => finish(null));
    // click outside does not close — use Cancel or Submit
    document.addEventListener("keydown", function esc(e){
      if(e.key === "Escape"){ finish(null); document.removeEventListener("keydown", esc); }
    }, {once: true});
    vendorSelect.focus();
  });
}

// Blank receiving + inspection modal — returns {receivedDate, condition, itemConditions} or null on cancel.
// Toggle at top switches between "by order" (default) and "by product/size" views.
// data-idx on every input is always the index into the fixed rows array, so the
// confirm handler's querySelector-by-idx collection works regardless of display order.
function showBlankReceiveModal(title, orders){
  return new Promise((resolve) => {
    const today = new Date().toISOString().slice(0, 10);

    // One row per line item; qty >1 shown as ×N.
    const rows = [];
    for(const o of (orders || [])){
      for(const it of (o.items || [])){
        if(it.cancelDate || it.noBlank) continue;   // noBlank: nothing to receive for it (migrations/0052)
        const hasSize = itemHasSize_(it);
        const productKey = (it.name || it.type || "Item") + (hasSize ? " (" + it.size + ")" : "");
        const qty = Number(it.qty) || 1;
        rows.push({
          orderId:      o.orderId,
          sheetRow:     it.sheetRow,
          type:         it.type || "",
          size:         it.size || "",
          qty,
          productKey,                                                       // used for grouping in byProduct mode
          byOrderLabel: qty > 1 ? productKey + " \xd7" + qty : productKey, // label when grouped by order
          byProductLabel: qty > 1 ? o.orderId + " \xd7" + qty : o.orderId  // label when grouped by product
        });
      }
    }

    const multiOrder = (orders || []).length > 1;
    const thStyle = "text-align:left;padding:6px 10px;font-size:12px;font-weight:600;color:var(--ink-soft);white-space:nowrap";
    const tdLabel = "padding:6px 10px;font-size:13px;color:var(--ink)";
    const tdMuted = "padding:6px 10px;font-size:12px;color:var(--ink-soft);white-space:nowrap";
    const sectionRow = (label, cols) =>
      `<tr class="br-section" style="background:var(--card-line)"><td colspan="${cols + 1}" style="padding:5px 10px;font-size:12px;font-weight:700;color:var(--ink-soft)">${escapeHtml(label)}</td></tr>`;
    const condInput = (i) =>
      `<select data-idx="${i}" class="br-cond" style="padding:4px 6px;border:1px solid var(--card-line);border-radius:4px;background:#fff;color:var(--ink);font-size:13px"><option value="Good">Good</option><option value="Other">Other</option></select>`;
    const noteInput = (i) =>
      `<input type="text" data-idx="${i}" class="br-note" maxlength="200" placeholder="optional note" autocomplete="off" style="width:160px;padding:4px 6px;border:1px solid var(--card-line);border-radius:4px;background:#fff;color:var(--ink);font-size:13px">`;

    function buildBody(mode){
      if(!rows.length) return "";
      const row = (label, labelStyle, i) =>
        `<tr data-idx="${i}" style="border-top:1px solid var(--card-line)">
           <td style="padding:6px 10px;text-align:center"><input type="checkbox" class="br-incl" data-idx="${i}" checked aria-label="Include this line"></td>
           <td class="br-label" style="${labelStyle}">${escapeHtml(label)}</td>
           <td style="padding:6px 10px">${condInput(i)}</td>
           <td style="padding:6px 10px">${noteInput(i)}</td>
         </tr>`;

      // Always render in byOrder/flat order initially; applyMode reorders live DOM later.
      // Each <tr> carries data-idx so applyMode can locate it without recreating inputs.
      if(multiOrder){
        const orderMap = new Map();
        rows.forEach((r, i) => { if(!orderMap.has(r.orderId)) orderMap.set(r.orderId, []); orderMap.get(r.orderId).push({...r, idx: i}); });
        let html = "";
        for(const [oid, items] of orderMap){
          html += sectionRow(oid, 3);
          for(const r of items) html += row(r.byOrderLabel, tdLabel, r.idx);
        }
        return html;
      } else {
        return rows.map((r, i) => row(r.byOrderLabel, tdLabel, i)).join("");
      }
    }

    function buildTable(mode){
      if(!rows.length) return `<p style="color:var(--ink-soft);font-size:13px;margin-bottom:16px">No item details available.</p>`;
      return `
        <div style="overflow-x:auto;margin-bottom:18px;border:1px solid var(--card-line);border-radius:4px">
          <table style="border-collapse:collapse;width:100%;min-width:400px">
            <thead style="background:var(--card-line)">
              <tr>
                <th style="${thStyle};text-align:center">✓</th>
                <th id="brItemHeader" style="${thStyle}">Item</th>
                <th style="${thStyle}">Condition</th>
                <th style="${thStyle}">Notes</th>
              </tr>
            </thead>
            <tbody id="brTbody">${buildBody(mode)}</tbody>
          </table>
        </div>`;
    }

    let mode = "byOrder";

    const overlay = document.createElement("div");
    overlay.className = "admin-pass-overlay";
    overlay.style.zIndex = "1002";
    overlay.innerHTML = `
      <div class="admin-pass-box" style="max-width:680px;width:calc(100% - 32px);max-height:85vh;overflow-y:auto">
        <div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:16px;gap:12px">
          <div style="font-weight:700;font-size:16px;color:var(--ink)">${escapeHtml(title)}</div>
          ${rows.length > 1 ? `
          <div style="display:flex;border:1px solid var(--card-line);border-radius:6px;overflow:hidden;flex-shrink:0;font-size:12px;font-weight:600">
            <button id="brByOrder" type="button" style="padding:5px 10px;background:var(--accent);color:#fff;border:none;cursor:pointer">By order</button>
            <button id="brByProduct" type="button" style="padding:5px 10px;background:transparent;color:var(--ink-soft);border:none;cursor:pointer">By product</button>
          </div>` : ""}
        </div>

        <div style="display:flex;align-items:center;gap:10px;margin-bottom:16px;font-size:13px;font-weight:600;color:var(--ink)">
          Date received
          <input type="date" id="blankReceivedDate" value="${today}" autocomplete="off"
                 style="padding:5px 8px;border:1px solid var(--card-line);border-radius:5px;font-size:13px;background:#fff;color:var(--ink)">
        </div>

        <div id="brTable">${buildTable(mode)}</div>

        <div class="admin-pass-actions">
          <button id="brCancel" type="button" class="admin-pass-cancel">Cancel</button>
          <button id="brConfirm" type="button" class="admin-pass-submit">Mark blanks received</button>
        </div>
      </div>
    `;
    document.body.appendChild(overlay);

    // Toggle: move existing <tr data-idx> elements in the DOM rather than
    // recreating them — preserves all entered condition/note values.
    const sizeIdx = s => { const i = (typeof SIZE_ORDER_ALL !== "undefined" ? SIZE_ORDER_ALL : []).indexOf(s); return i === -1 ? 999 : i; };
    const makeSectionRow = (label) => {
      const tr = document.createElement("tr");
      tr.className = "br-section";
      tr.innerHTML = `<td colspan="3" style="padding:5px 10px;font-size:12px;font-weight:700;color:var(--ink-soft);background:var(--card-line)">${escapeHtml(label)}</td>`;
      return tr;
    };

    const applyMode = (newMode) => {
      mode = newMode;
      const tbody = overlay.querySelector("#brTbody");
      const itemHeader = overlay.querySelector("#brItemHeader");
      // Remove all section headers (they're recreated on each switch)
      tbody.querySelectorAll(".br-section").forEach(el => el.remove());
      // Collect live data rows by idx — does NOT recreate them
      const dataRows = rows.map((_, i) => tbody.querySelector(`tr[data-idx="${i}"]`));

      if(newMode === "byProduct"){
        if(itemHeader) itemHeader.textContent = "Order";
        const sorted = rows.map((r, i) => ({...r, idx: i}))
          .sort((a, b) => a.productKey.localeCompare(b.productKey) || sizeIdx(a.size) - sizeIdx(b.size));
        let lastKey = null;
        for(const r of sorted){
          if(r.productKey !== lastKey){ tbody.appendChild(makeSectionRow(r.productKey)); lastKey = r.productKey; }
          dataRows[r.idx].querySelector(".br-label").textContent = r.byProductLabel;
          tbody.appendChild(dataRows[r.idx]); // move (not clone) to end
        }
      } else {
        if(itemHeader) itemHeader.textContent = "Item";
        if(multiOrder){
          const orderMap = new Map();
          rows.forEach((r, i) => { if(!orderMap.has(r.orderId)) orderMap.set(r.orderId, []); orderMap.get(r.orderId).push({...r, idx: i}); });
          for(const [oid, items] of orderMap){
            tbody.appendChild(makeSectionRow(oid));
            for(const r of items){ dataRows[r.idx].querySelector(".br-label").textContent = r.byOrderLabel; tbody.appendChild(dataRows[r.idx]); }
          }
        } else {
          rows.forEach((r, i) => { dataRows[i].querySelector(".br-label").textContent = r.byOrderLabel; tbody.appendChild(dataRows[i]); });
        }
      }
      const accent = "background:var(--accent);color:#fff;padding:5px 10px;border:none;cursor:pointer";
      const dim    = "background:transparent;color:var(--ink-soft);padding:5px 10px;border:none;cursor:pointer";
      const byOrderBtn   = overlay.querySelector("#brByOrder");
      const byProductBtn = overlay.querySelector("#brByProduct");
      if(byOrderBtn)   byOrderBtn.style.cssText   = newMode === "byOrder"   ? accent : dim;
      if(byProductBtn) byProductBtn.style.cssText = newMode === "byProduct" ? accent : dim;
    };

    const byOrderBtn = overlay.querySelector("#brByOrder");
    const byProductBtn = overlay.querySelector("#brByProduct");
    if(byOrderBtn)   byOrderBtn.addEventListener("click",   () => applyMode("byOrder"));
    if(byProductBtn) byProductBtn.addEventListener("click", () => applyMode("byProduct"));

    const finish = (result) => { document.body.removeChild(overlay); resolve(result); };

    overlay.querySelector("#brConfirm").addEventListener("click", () => {
      const receivedDate = overlay.querySelector("#blankReceivedDate").value;
      let anyOther = false;
      // Only the ticked lines are received (migrations/0039 — partial receive).
      const incl = (i) => { const el = overlay.querySelector(`.br-incl[data-idx="${i}"]`); return !el || el.checked; };
      const itemConditions = rows.map((r, i) => {
        if(!incl(i)) return null;
        const condEl = overlay.querySelector(`.br-cond[data-idx="${i}"]`);
        const noteEl = overlay.querySelector(`.br-note[data-idx="${i}"]`);
        const condition = condEl ? condEl.value : "Good";
        const note = noteEl ? noteEl.value.trim() : "";
        if(condition === "Other") anyOther = true;
        return { sheetRow: r.sheetRow, condition, note };
      }).filter(Boolean);
      const items = rows.map((r, i) => incl(i) ? { orderId: r.orderId, itemId: r.sheetRow } : null).filter(Boolean);
      if(!items.length){ showToast("Tick at least one line to receive.", true); return; }
      finish({ receivedDate, condition: anyOther ? "Other" : "Good", itemConditions, items });
    });
    overlay.querySelector("#brCancel").addEventListener("click", () => finish(null));
    // click outside does not close — use Cancel or Submit
    document.addEventListener("keydown", function esc(e){
      if(e.key === "Escape"){ finish(null); document.removeEventListener("keydown", esc); }
    }, {once: true});
  });
}

// Active line items across a set of orders, for the blank-shipped checklists (migrations/0039).
function blankItemsOf_(orders){
  const items = [];
  for(const o of (orders || [])) for(const it of (o.items || [])){
    if(it.cancelDate || it.noBlank) continue;   // noBlank: its product is made with no blank (migrations/0052)
    const hasSize = itemHasSize_(it);
    items.push({ orderId: o.orderId, itemId: it.sheetRow,
      label: o.orderId + " · " + (it.name || it.type || "Item") + (hasSize ? " (" + it.size + ")" : "") + ((Number(it.qty) || 1) > 1 ? " \xd7" + it.qty : "") });
  }
  return items;
}

// Existing blank shipments across a set of orders, deduped by shipment id (a shipment can cover
// items in more than one of the passed orders). Each carries its live carrier status for display.
function blankShipmentsOf_(orders){
  const byId = {};
  for(const o of (orders || [])) for(const s of (o.blankShipments || [])){
    if(!byId[s.id]) byId[s.id] = { id: s.id, carrier: s.carrier || "", trackingNumber: s.trackingNumber || "",
      shippedAt: (s.shippedAt || "").slice(0, 10), status: s.status || "", itemIds: (s.itemIds || []).map(Number) };
  }
  return Object.values(byId);
}

// Add, edit or remove blank (garment) tracking (migrations/0039): one block per shipment — existing
// ones pre-filled and editable, plus any number of new ones — each with a carrier, ship date and its
// own checklist of which line items it covers. A blank order can arrive in several shipments over
// time, so the numbers aren't known at order time and are maintained here. Resolves to
// { add:[{carrier,trackingNumber,shippedAt,itemIds}], update:[{id,...}], remove:[id,...] } or null.
function showBlankShippedModal(title, orders){
  return new Promise((resolve) => {
    const items = blankItemsOf_(orders);
    const existing = blankShipmentsOf_(orders);
    const inp = "padding:6px 8px;border:1px solid #ccc;border-radius:4px;font-size:13px;background:#fff;color:#111;";
    const today = new Date().toISOString().slice(0, 10);
    const carriers = ["UPS", "FedEx", "USPS", "DHL", "Other"];
    let n = 0;
    // ship: an existing shipment to pre-fill (null = a blank new block).
    const blockHtml = (idx, ship) => {
      const sel = ship ? ship.carrier : "";
      const carrierOpts = `<option value="">—</option>` + carriers.map(c => `<option${c === sel ? " selected" : ""}>${c}</option>`).join("");
      const checkedSet = ship ? new Set(ship.itemIds.map(Number)) : null;
      const checkAll = !ship;  // a brand-new block defaults to all items ticked
      const statusLine = ship && ship.status ? `<div style="font-size:11px;color:#555;margin-bottom:4px;">Carrier status: ${escapeHtml(blankStatusLabel_(ship.status))}</div>` : "";
      return `<div class="bsBlock" data-bi="${idx}"${ship ? ` data-ship-id="${ship.id}"` : ""} style="border:1px solid #e5e7eb;border-radius:6px;padding:10px;margin-bottom:10px;">
        ${statusLine}
        <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:end;margin-bottom:6px;">
          <label style="font-size:12px;font-weight:600;">Carrier<br><select class="bsCarrier" style="${inp}">${carrierOpts}</select></label>
          <label style="font-size:12px;font-weight:600;">Tracking #<br><input class="bsTrack" maxlength="100" value="${ship ? escapeHtml(ship.trackingNumber) : ""}" style="${inp}width:180px;"></label>
          <label style="font-size:12px;font-weight:600;">Shipped<br><input type="date" class="bsDate" value="${ship && ship.shippedAt ? escapeHtml(ship.shippedAt) : today}" style="${inp}"></label>
          <button type="button" class="bsRm admin-btn admin-btn-danger" style="padding:4px 8px;">Remove</button>
        </div>
        <div style="font-size:11px;color:#666;margin-bottom:3px;">Line items in this shipment:</div>
        <div style="display:flex;flex-wrap:wrap;gap:4px 12px;">${items.map(it => `<label style="font-size:12px;font-weight:400;display:flex;gap:4px;align-items:center;"><input type="checkbox" class="bsItem" data-order="${escapeHtml(it.orderId)}" data-item="${it.itemId}" ${(checkedSet ? checkedSet.has(Number(it.itemId)) : checkAll) ? "checked" : ""}> ${escapeHtml(it.label)}</label>`).join("") || `<em style="color:#888;">No line items.</em>`}</div>
      </div>`;
    };
    const ov = document.createElement("div"); ov.className = "admin-pass-overlay"; ov.style.zIndex = "1002";
    ov.innerHTML = `<div class="admin-pass-box" style="max-width:700px;width:calc(100% - 32px);max-height:85vh;overflow-y:auto;">
        <div style="font-weight:700;font-size:16px;margin-bottom:6px;">${escapeHtml(title)}</div>
        <div style="font-size:12px;color:#666;margin-bottom:10px;">Add a tracking number for each vendor shipment and tick the line items it covers. Existing tracking numbers are shown below — edit them in place, or Remove one to delete it.</div>
        <div id="bsBlocks"></div>
        <button type="button" id="bsAdd" class="admin-btn" style="padding:4px 12px;">+ Add tracking number</button>
        <div id="bsErr" style="color:#b03a2e;font-size:13px;min-height:18px;margin:8px 0;"></div>
        <div class="admin-pass-actions"><button type="button" class="admin-pass-cancel">Cancel</button><button type="button" id="bsSave" class="admin-pass-submit">Save shipments</button></div>
      </div>`;
    document.body.appendChild(ov);
    const blocks = ov.querySelector("#bsBlocks");
    const removedIds = [];
    // Pre-fill one block per existing shipment; if there are none, start with one empty block.
    for(const s of existing) blocks.insertAdjacentHTML("beforeend", blockHtml(n++, s));
    if(!existing.length) blocks.insertAdjacentHTML("beforeend", blockHtml(n++, null));
    ov.querySelector("#bsAdd").onclick = () => blocks.insertAdjacentHTML("beforeend", blockHtml(n++, null));
    blocks.addEventListener("click", e => {
      if(!e.target.classList.contains("bsRm")) return;
      const block = e.target.closest(".bsBlock");
      const sid = block.getAttribute("data-ship-id");
      if(sid) removedIds.push(Number(sid));          // an existing shipment → delete on save
      // Keep at least one block on screen when nothing existed to delete.
      if(blocks.querySelectorAll(".bsBlock").length > 1 || sid) block.remove();
      if(!blocks.querySelectorAll(".bsBlock").length) blocks.insertAdjacentHTML("beforeend", blockHtml(n++, null));
    });
    const finish = (v) => { document.body.removeChild(ov); resolve(v); };
    ov.querySelector(".admin-pass-cancel").onclick = () => finish(null);
    ov.querySelector("#bsSave").onclick = () => {
      const add = [], update = [], err = ov.querySelector("#bsErr");
      for(const b of ov.querySelectorAll(".bsBlock")){
        const sid = b.getAttribute("data-ship-id");
        const track = b.querySelector(".bsTrack").value.trim();
        const checked = [...b.querySelectorAll(".bsItem:checked")];
        if(!sid && !track && !checked.length) continue;   // untouched new block
        if(!checked.length){ err.textContent = "Tick at least one line item for each tracking number."; return; }
        const rec = { carrier: b.querySelector(".bsCarrier").value, trackingNumber: track, shippedAt: b.querySelector(".bsDate").value,
          itemIds: checked.map(c => Number(c.dataset.item)), items: checked.map(c => ({ orderId: c.dataset.order, itemId: Number(c.dataset.item) })) };
        if(sid) update.push({ id: Number(sid), ...rec }); else add.push(rec);
      }
      if(!add.length && !update.length && !removedIds.length){ err.textContent = "Add a tracking number and tick the items it covers."; return; }
      finish({ add, update, remove: removedIds });
    };
    document.addEventListener("keydown", function esc(e){ if(e.key === "Escape"){ finish(null); document.removeEventListener("keydown", esc); } }, { once: true });
  });
}

async function blankShippedFlow_(orgId, orders){
  const res = await showBlankShippedModal("Blank shipped — " + orders.length + " order" + (orders.length === 1 ? "" : "s"), orders);
  if(!res) return;
  if(!adminKey) adminKey = (await adminLogin()) || "";
  if(!adminKey) return;
  const post = (payload) => fetch("/api/orders", { method: "POST", headers: {"Content-Type": "application/json"},
    body: JSON.stringify({ key: adminKey, org: orgId, ...payload }) }).then(r => r.json().then(d => ({ r, d })));
  try{
    for(const id of (res.remove || [])){
      const { r, d } = await post({ action: "deleteBlankShipment", id });
      if(!r.ok || d.status === "error"){ if(d && d.message === "Unauthorized") clearAdminAuth(); showToast("Could not remove a shipment: " + ((d && d.message) || "error"), true); return; }
    }
    for(const s of (res.update || [])){
      const { r, d } = await post({ action: "updateBlankShipment", id: s.id, orderId: (s.items[0] && s.items[0].orderId) || "",
        carrier: s.carrier, trackingNumber: s.trackingNumber, shippedAt: s.shippedAt, itemIds: s.itemIds });
      if(!r.ok || d.status === "error"){ if(d && d.message === "Unauthorized") clearAdminAuth(); showToast("Could not update a shipment: " + ((d && d.message) || "error"), true); return; }
    }
    for(const s of (res.add || [])){
      const { r, d } = await post({ action: "addBlankShipment", orderId: (s.items[0] && s.items[0].orderId) || "",
        carrier: s.carrier, trackingNumber: s.trackingNumber, shippedAt: s.shippedAt, itemIds: s.itemIds });
      if(!r.ok || d.status === "error"){ if(d && d.message === "Unauthorized") clearAdminAuth(); showToast("Shipment failed: " + ((d && d.message) || "error"), true); return; }
    }
    const changed = (res.add || []).length + (res.update || []).length + (res.remove || []).length;
    showToast("Blank shipment" + (changed === 1 ? "" : "s") + " saved.");
    const oo = (adminOrgs || []).find(x => x.orgId === orgId);
    if(oo) refreshOrdersInPlace_(oo);
  }catch(e){ showToast("Could not reach the server.", true); }
}

// 6-digit TOTP prompt — same overlay style as promptAdminPassphrase().
// Shown by adminLogin() when the server responds {status:"totp_required"}.
function promptTOTPCode(){
  return new Promise((resolve) => {
    const overlay = document.createElement("div");
    overlay.className = "admin-pass-overlay";
    overlay.innerHTML = `
      <div class="admin-pass-box">
        <label for="adminTOTPInput">Authentication code</label>
        <p style="font-size:13px;margin:4px 0 12px;color:#666;">Enter the 6-digit code from your authenticator app, or one of your recovery codes.</p>
        <input type="text" id="adminTOTPInput" autocomplete="one-time-code"
               maxlength="12" autocapitalize="off" spellcheck="false" />
        <div class="admin-pass-actions">
          <button type="button" class="admin-pass-cancel">Cancel</button>
          <button type="button" class="admin-pass-submit">Verify</button>
        </div>
      </div>
    `;
    document.body.appendChild(overlay);
    const input = overlay.querySelector("#adminTOTPInput");
    const finish = (value) => { document.body.removeChild(overlay); resolve(value); };
    overlay.querySelector(".admin-pass-submit").addEventListener("click", () => finish(input.value.trim()));
    overlay.querySelector(".admin-pass-cancel").addEventListener("click", () => finish(""));
    // click outside does not close — use Cancel or Submit
    input.addEventListener("keydown", (e) => {
      if(e.key === "Enter"){ e.preventDefault(); finish(input.value.trim()); }
      if(e.key === "Escape") finish("");
    });
    input.focus();
  });
}

// Full sign-in flow: a remembered session → the sign-in prompt (email + password) → POST to
// /api/admin-session → a code prompt if the user has two-step sign-in → the server sets the
// session cookie. Returns "cookie" on success, or "" on cancel / failure. Also notes who signed
// in (adminMe) and any step they must finish first (adminPending).
// Called everywhere adminKey needs to be established (never promptAdminPassphrase() directly).
async function adminLogin(){
  // 1. Valid stored session — use it without prompting
  const stored = loadStoredSession();
  if(stored){ adminPending = stored.pending || null; adminMe = stored.user || null; return stored.token; }

  // 2. Sign-in prompt — except the desktop program's very first start, which signs in with the
  // passphrase it made itself (desktop/preload.js) and goes straight to "Finish setting up".
  const desktopKey = adminDesktop_() ? await adminDesktopFirstRunKey_() : null;
  const key = desktopKey || (await promptAdminPassphrase()) || "";
  if(!key) return "";
  const email = desktopKey ? "" : _adminSignInEmail;

  // 3. POST to /api/admin-session (email + password first)
  let data;
  try{
    const res = await fetch("/api/admin-session", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({email, key})
    });
    data = await res.json();
  }catch(e){
    showToast("Login request failed — check your connection.", true);
    return "";
  }

  // 4. Two-step sign-in — prompt for the code and retry
  if(data && data.status === "totp_required"){
    const totpCode = await promptTOTPCode();
    if(!totpCode) return "";
    try{
      const res2 = await fetch("/api/admin-session", {
        method: "POST",
        headers: {"Content-Type": "application/json"},
        body: JSON.stringify({email, key, totpCode})
      });
      data = await res2.json();
    }catch(e){
      showToast("Login request failed — check your connection.", true);
      return "";
    }
  }

  if(data && data.status === "ok"){
    if(data.session === "cookie"){
      // The real credential is the HttpOnly cookie the server just set.
      adminPending = data.pending || null;
      adminMe = data.user || null;
      _adminJustSignedIn = true;
      rememberAdminEmail_((data.user && data.user.email) || "");
      saveAdminSession("cookie", data.expires);
      return "cookie";
    }
    // Fallback: server accepted passphrase but issued no token (shouldn't happen)
    return key;
  }

  showToast(data && data.message === "Unauthorized" ? "That email and password don't match." : ((data && data.message) || "Login failed."), true);
  return "";
}

async function fetchOrders(orgId){
  if(!adminKey){
    adminKey = (await adminLogin()) || "";
  }
  try{
    const res = await fetch("/api/orders", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      // Only the filter's date window comes back (the server pads it a day each side; the exact range
      // is applied here by ordersDateFilter_). Changing the dates re-fetches.
      body: JSON.stringify({action: "getOrders", org: orgId, key: adminKey,
        dateFrom: (window._ordersFilter || {}).from || "", dateTo: (window._ordersFilter || {}).to || ""})
    });
    if(!res.ok){
      console.error("Admin orders fetch failed — HTTP " + res.status, await res.text().catch(()=>""));
      return {error: "Server error (HTTP " + res.status + ")"};
    }
    const data = await res.json();
    if(data && data.status === "error"){
      clearAdminAuth();
      return {error: data.message || "Unauthorized"};
    }
    const rows = Array.isArray(data) ? data : (data.orders || []);
    rows.sort((a,b)=> new Date(b.placedAt) - new Date(a.placedAt));
    return rows;
  }catch(e){
    console.error("Admin orders fetch threw an exception:", e);
    return {error: "Could not reach the server."};
  }
}

/* ---------------- admin ----------------
   Reached only via the dedicated admin subdomain (admin.yourdomain.com —
   see functions/_lib/hostConfig.js and functions/api/orders.js). Not tied
   to currentOrg at all: the passphrase is checked once via "listOrgs" to
   get the org picker, then reused for "getOrders" per org selected. */
let adminOrgs = null; // cached org list for this session, once the passphrase checks out

function renderAdminPicker(app){
  document.title = adminTitle_("Sign in");
  app.innerHTML = `
    <div class="org-hero admin-hero" style="--org-accent:var(--accent);">
            <h1>Orders</h1>
      <div class="stitch stitch-thick"></div>
    </div>
    <div class="admin-panel" style="--org-accent:var(--accent);" id="adminPanel">
      <div class="admin-summary">Loading&hellip;</div>
    </div>
  `;
  loadAdminOrgList();
}

// Asks the server who is signed in (Security → Users' "me") and keeps it with the session. A failure
// leaves what was known; the server refuses anything above the user's role either way.
async function refreshAdminMe_(){
  try{
    const res = await fetch("/api/admin-users", { method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify({ action: "me", key: adminKey }) });
    const data = await res.json().catch(() => null);
    if(res.ok && data && data.status === "ok" && data.user){ adminMe = data.user; updateStoredSession_(); }
  }catch(e){ /* keep what we had */ }
}
async function loadAdminOrgList(){
  const panel = document.getElementById("adminPanel");
  if(!adminKey){
    adminKey = (await adminLogin()) || "";
  }
  if(!adminKey){
    panel.innerHTML = `
      <div class="admin-empty">Passphrase required.</div>
      <div class="admin-actions"><button class="admin-btn" onclick="loadAdminOrgList()">Try again</button></div>
    `;
    return;
  }
  // A step still owed: the server answers nothing else until it is done, so go straight to it.
  if(adminPending){ renderPendingStep_(document.getElementById("app")); return; }
  try{
    const res = await fetch("/api/orders", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({action: "listOrgs", key: adminKey})
    });
    const data = await res.json();
    if(!res.ok || data.status === "error"){
      // The server says a step is owed that this browser didn't know about (an older marker).
      if(data && data.code === "setup_required"){ adminPending = data.pending || "account"; updateStoredSession_(); renderPendingStep_(document.getElementById("app")); return; }
      clearAdminAuth(); // not signed in any more — clear so it re-prompts next time
      panel.innerHTML = `
        <div class="admin-empty">${(data && data.message === "Unauthorized") ? "Not signed in." : escapeHtml((data && data.message) || "Could not load shops.")}</div>
        <div class="admin-actions"><button class="admin-btn" onclick="loadAdminOrgList()">Try again</button></div>
      `;
      return;
    }
    adminOrgs = data.orgs;
    // Who is signed in, from the server — not only the copy this browser kept at sign-in, which can be
    // missing (an older sign-in) or out of date. The menu, links and buttons follow this role.
    await refreshAdminMe_();
    renderAdminNav();
    if (adminFeatureOn_("shipping")) fetchBoxPresets(); // warm cache in background; sync loadBoxPresets() reads from it
    adminDesktopBackupNudge_();
    // Only an admin can change what the setup list complains about, so only an admin is sent to it.
    if (_adminJustSignedIn) {
      _adminJustSignedIn = false;
      // The address may still point at a page the last person had open; if this user's role can't use it, start at Orders.
      if (!adminCan_(adminPageRole_(location.hash))) adminSetHash("orders");
      if (adminMe && adminMe.role === "admin") await openSettingsIfSetupIncomplete_();
    }
    // Now authed — route to wherever the hash points (empty/picker/orders all land on the unified
    // Orders page; a deep link like #machines goes there).
    adminRoute();
  }catch(e){
    panel.innerHTML = `
      <div class="admin-empty">Could not reach the server.</div>
      <div class="admin-actions"><button class="admin-btn" onclick="loadAdminOrgList()">Try again</button></div>
    `;
  }
}

// Straight after signing in: when the install still has something required or recommended that
// isn't set (Global settings → Setup status), open Global settings instead of Orders. Only from
// the plain landing address — a link to a particular page still goes to that page — and a
// failure here never gets in the way of signing in.
async function openSettingsIfSetupIncomplete_(){
  const raw = location.hash.replace(/^#\/?/, "");
  if (raw && raw !== "picker" && raw !== "orders") return;
  if (!adminCanOpen_("settings")) return;   // only an admin can finish it there
  try{
    const res = await fetch("/api/orders", { method: "POST", headers: {"Content-Type": "application/json"},
      body: JSON.stringify({action: "getSetupStatus", key: adminKey}) });
    const data = await res.json();
    if (res.ok && data && data.status === "ok" && data.summary && (data.summary.required > 0 || data.summary.recommended > 0)) adminSetHash("settings");
  }catch(e){ /* the Orders page it is */ }
}

function renderPickerOrgButtons(panel){
  panel.innerHTML = `<h2>Open orders</h2><div id="dashBody" class="admin-summary">Loading&hellip;</div>`;
  loadOpenOrdersDashboard_();
}

// Admin home dashboard: every open order across every shop (not completed, not voided, not a
// test, not fully cancelled), oldest first, each with where it is in fulfillment.
const DASH_STATUSES_ = [
  ["unpaid", "Awaiting payment"], ["notStarted", "Paid — not started"], ["blankOrderedAt", "Blank ordered"],
  ["digitizingCompleteAt", "Digitizing done"], ["blankReceivedAt", "Blank received"], ["designApprovedAt", "Design approved"],
  ["manufacturedAt", "Manufactured"], ["qaPackedAt", "QA & packed"], ["shippedAt", "Shipped"], ["deliveredAt", "Delivered"],
];
// The furthest milestone an order has reached (later stages win), else paid/unpaid.
function dashOrderStatus_(o){
  for (let i = DASH_STATUSES_.length - 1; i >= 2; i--) if (o[DASH_STATUSES_[i][0]]) return DASH_STATUSES_[i][0];
  return o.paid ? "notStarted" : "unpaid";
}
window._dashFilter = window._dashFilter || "";

async function loadOpenOrdersDashboard_(){
  const el = document.getElementById("dashBody");
  if (!el) return;
  try {
    const r = await fetch("/api/orders", { method: "POST", headers: {"Content-Type": "application/json"},
      body: JSON.stringify({ action: "getOpenOrders", key: adminKey }) });
    const d = await r.json().catch(() => ({ status: "error", message: "Server error (" + r.status + ")" }));
    if (!r.ok || d.status === "error") { el.textContent = (d && d.message) || "Could not load open orders."; return; }
    window._dashOrders = d.orders || [];
    drawOpenOrdersDashboard_();
  } catch (e) { el.textContent = "Could not reach the server."; }
}

function drawOpenOrdersDashboard_(){
  const el = document.getElementById("dashBody");
  if (!el) return;
  const all = window._dashOrders || [];
  if (!all.length) { el.innerHTML = `<div style="color:#555;">No open orders — everything is completed.</div>`; return; }
  const money = (n) => "$" + Number(n || 0).toFixed(2);
  const counts = {};
  all.forEach(o => { const s = dashOrderStatus_(o); counts[s] = (counts[s] || 0) + 1; });
  const filter = counts[window._dashFilter] ? window._dashFilter : "";
  const shown = filter ? all.filter(o => dashOrderStatus_(o) === filter) : all;
  const label = Object.fromEntries(DASH_STATUSES_);
  const totalDue = all.reduce((s, o) => s + (Number(o.balanceDue) || 0), 0);
  const byShop = {};
  all.forEach(o => { byShop[o.orgName] = (byShop[o.orgName] || 0) + 1; });

  const chip = (key, text, n) => `<button type="button" class="admin-btn dash-chip" data-status="${key}" style="font-size:12px;padding:4px 10px;${filter === key ? "background:#111;color:#fff;border-color:#111;" : ""}">${escapeHtml(text)} (${n})</button>`;
  const th = "padding:7px 10px;text-align:left;background:#f0f0f0;color:#333;font-size:12px;font-weight:700;border-bottom:2px solid #ccc;white-space:nowrap;";
  const td = "padding:8px 10px;border-bottom:1px solid #e5e7eb;vertical-align:top;color:#111;background:#fff;";
  const sub = "color:#666;font-size:12px;";
  const now = Date.now();
  const rows = shown.map(o => {
    const active = (o.items || []).filter(it => !it.cancelDate);
    const lines = active.slice(0, 3).map(it => escapeHtml(`${it.qty}× ${it.name}${it.size ? ` (${it.size})` : ""}`)).join("<br>")
      + (active.length > 3 ? `<br><span style="${sub}">+${active.length - 3} more</span>` : "");
    const days = o.placedAt ? Math.floor((now - new Date(o.placedAt).getTime()) / 86400000) : null;
    const status = dashOrderStatus_(o);
    const due = Number(o.balanceDue) || 0;
    return `<tr class="dash-row" data-org="${escapeHtml(o.orgId)}" data-order="${escapeHtml(o.orderId)}" style="cursor:pointer;">
      <td style="${td}white-space:nowrap;">${o.placedAt ? escapeHtml(new Date(o.placedAt).toLocaleDateString()) : ""}${days !== null ? `<br><span style="${sub}${days >= 21 ? "color:#b45309;font-weight:600;" : ""}">${days} day${days === 1 ? "" : "s"} ago</span>` : ""}</td>
      <td style="${td}white-space:nowrap;font-family:monospace;font-size:12px;">${escapeHtml(o.orderId)}</td>
      <td style="${td}">${escapeHtml(o.orgName)}</td>
      <td style="${td}">${escapeHtml(o.customerName || "")}</td>
      <td style="${td}font-size:13px;">${lines}</td>
      <td style="${td}text-align:right;white-space:nowrap;">${money(o.effectiveTotal)}</td>
      <td style="${td}text-align:right;white-space:nowrap;font-weight:600;color:${due > 0.005 ? "#b03a2e" : "#15803d"};">${due > 0.005 ? money(due) : "Paid"}</td>
      <td style="${td}white-space:nowrap;">${escapeHtml(label[status])}</td>
    </tr>`;
  }).join("");

  el.innerHTML = `
    <div style="margin-bottom:10px;"><strong>${all.length}</strong> open order${all.length === 1 ? "" : "s"} &middot; <strong style="color:${totalDue > 0.005 ? "#b03a2e" : "inherit"};">${money(totalDue)}</strong> balance due &middot; ${Object.entries(byShop).map(([n, c]) => `${escapeHtml(n)}: ${c}`).join(" &middot; ")}</div>
    <div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:12px;">${chip("", "All", all.length)}${DASH_STATUSES_.filter(([k]) => counts[k]).map(([k, t]) => chip(k, t, counts[k])).join("")}</div>
    <div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;"><table style="width:100%;border-collapse:collapse;font-size:14px;">
      <thead><tr><th style="${th}">Placed</th><th style="${th}">Order</th><th style="${th}">Shop</th><th style="${th}">Customer</th><th style="${th}">Items</th><th style="${th}text-align:right;">Total</th><th style="${th}text-align:right;">Balance due</th><th style="${th}">Status</th></tr></thead>
      <tbody>${rows}</tbody></table></div>
    <div style="${sub}margin-top:6px;">Oldest first. Click an order to open it in its shop's orders list.</div>`;
  el.querySelectorAll(".dash-chip").forEach(b => b.onclick = () => { window._dashFilter = b.dataset.status; drawOpenOrdersDashboard_(); });
  el.querySelectorAll(".dash-row").forEach(tr => tr.onclick = () => openOrderFromDashboard_(tr.dataset.org, tr.dataset.order));
}

// Opens the order's shop, then scrolls to and briefly highlights that order's row once it renders.
async function openOrderFromDashboard_(orgId, orderId){
  selectAdminOrg(orgId);
  for (let i = 0; i < 80; i++) {
    const row = [...document.querySelectorAll("#adminPanel tr[data-order]")].find(tr => tr.dataset.order === orderId && !tr.classList.contains("dash-row"));
    if (row) {
      if (row.scrollIntoView) row.scrollIntoView({ block: "center", behavior: "smooth" });
      const cells = [...row.querySelectorAll("td")];
      cells.forEach(c => { c.dataset.prevBg = c.style.background; c.style.background = "#fef3c7"; });
      setTimeout(() => cells.forEach(c => { c.style.background = c.dataset.prevBg || ""; }), 2500);
      return;
    }
    await new Promise(res => setTimeout(res, 100));
  }
}

// Persistent admin header, shown on every admin page once signed in. One line: Orders, then a
// series of dropdown groups. It lives outside #app so the page renderers (which replace #app's
// contents) never touch it. Each item is either ["hash","Label"] (a page) or {action, label} (a
// function call). ADMIN_NAV_TOOLS is kept (flat list of every page hash) for other code that
// still iterates it — see below.
const ADMIN_NAV_GROUPS = [
  // Orders, Run Order, Run Transfer Sheets and Manage catalog are the buttons before these menus.
  { label: "Catalog", items: [
    ["setup", "Shop setup"], ["designs", "Designs"], ["graphics", "Graphics"], ["categories", "Product categories"], ["locations", "Decoration locations"],
    ["brandrules", "Brand rules"], ["packages", "Package sizes"],
  ]},
  { label: "Production", items: [
    ["machines", "Machines"], ["maintenance", "Machine maintenance"], ["machinefiles", "Machine files"], ["hoops", "Hoops"],
    ["threads", "Threads"], ["abortreasons", "Abort reasons"],
  ]},
  { label: "Inventory", items: [ ["inventory", "Blanks"], ["blankorder", "Blanks to order"], ["transfers", "Transfers"] ]},
  { label: "Finance", items: [ ["expenses", "Expenses"], ["money", "Accounts & money"], ["reconcile", "Reconcile"], ["accountviewer", "Account viewer"] ]},
  { label: "Reports", items: [ ["audit", "Audit log"], ["revenue", "Revenue report"], ["salestax", "Sales tax report"], ["cogs", "Inventory & COGS"], ["runreport", "Run times"], ["books", "Periods & export"] ]},
  { label: "Settings", items: [
    ["settings", "Global settings"], ["vendors", "Vendor integrations"], ["comms", "Communications"], ["orphans", "Orphaned images"],
    ["users", "Users"], ["security", "Security (2FA)"], ["password", "Change password"],
    { action: "adminSignOut()", label: "Sign out" }, { action: "adminSignOutEverywhere()", label: "Sign out everywhere" },
  ]},
];
// Flat list of every page hash → label (derived from the groups), for code that enumerates tools.
const ADMIN_NAV_TOOLS = ADMIN_NAV_GROUPS.flatMap(g => g.items.filter(Array.isArray));

// ---- Features (Global settings → Features) -------------------------------------------------------
// Which optional feature a page belongs to, by the first part of its hash. A page that isn't
// listed is always there. The switches come with /api/catalog (index.html's siteFeatures /
// featureOn_); the server refuses a switched-off feature's actions whatever this file shows.
const ADMIN_PAGE_FEATURE = {
  runorder: "production", machines: "production", maintenance: "production", machinefiles: "production", hoops: "production", threads: "production",
  abortreasons: "production", runreport: "production", designs: "production",
  expenses: "bookkeeping", money: "bookkeeping", reconcile: "bookkeeping", books: "bookkeeping", accountviewer: "bookkeeping",
  packages: "shipping",
};
// Names for the "turned off" page; replaced by the server's own list once Global settings has loaded it.
let FEATURE_LABELS_ = { storefront: "Storefront", production: "Production", bookkeeping: "Bookkeeping", shipping: "Shipping", designVerification: "Design approval" };
function adminFeatureOn_(key){ return typeof featureOn_ !== "function" || featureOn_(key); }
function adminPageFeature_(hash){ return ADMIN_PAGE_FEATURE[String(hash || "").replace(/^#\/?/, "").split("/")[0]] || ""; }
function adminPageOn_(hash){ const f = adminPageFeature_(hash); return !adminDesktopHides_(hash) && (!f || adminFeatureOn_(f)); }

// ---- The desktop edition (desktop/; /api/catalog says edition "desktop") ---------------------------
// The same admin, inside the desktop program on one computer. What needs the internet is left out:
// these pages, and the buttons that send email, take card payments, attach a web address or talk
// to a supplier's live connection (the server refuses those actions there too — orders.js
// DESKTOP_REFUSED_ACTIONS). Everything else is the same screen as a cloud install's.
function adminDesktop_(){ return typeof siteEdition !== "undefined" && siteEdition === "desktop"; }
const ADMIN_DESKTOP_HIDDEN_PAGES = ["vendors", "comms"];
// Vendor integrations is never a page of its own there (its vendors are in Global settings → Features
// → Supplier connections, adminRoute), and Communications (and the buttons that send email) is back
// once the owner turns Email on there.
function adminDesktopSuppliers_(){ return adminDesktop_() && typeof siteDesktopSuppliers !== "undefined" && siteDesktopSuppliers === true; }
function adminDesktopEmail_(){ return adminDesktop_() && typeof siteDesktopEmail !== "undefined" && siteDesktopEmail === true; }
function adminDesktopNoEmail_(){ return adminDesktop_() && !adminDesktopEmail_(); }
function adminDesktopHides_(hash){
  const page = String(hash || "").replace(/^#\/?/, "").split("/")[0];
  return adminDesktop_() && ADMIN_DESKTOP_HIDDEN_PAGES.includes(page) && !(page === "comms" && adminDesktopEmail_());
}
// The passphrase for the program's own first sign-in, or null (a normal start, or not the program).
async function adminDesktopFirstRunKey_(){
  if(!adminDesktop_() || !window.oddDesktop || typeof window.oddDesktop.firstRunKey !== "function") return null;
  try{ return (await window.oddDesktop.firstRunKey()) || null; }catch(e){ return null; }
}
// ---- Global settings → Features: each switch opens to show what it needs ---------------------------
// A ticked feature shows its panel right under it — Production: Machine Files; Shipping: the Shippo key
// and the ship-from address; in the desktop version also Email (the mailbox, with Design approval
// under it) and Supplier connections (the vendors, as on the Vendor integrations page). Unticking
// closes the panel and keeps what's in it. Save (submitGlobalSettings) checks every open panel
// first and saves nothing while one is incomplete; in the desktop version it then hands the
// program its part (key, mailbox, supplier switch) in one go, which restarts its server once.
async function adminDesktopHasShippoKey_(){
  if(!window.oddDesktop || typeof window.oddDesktop.hasShippoKey !== "function") return null;
  try{ return !!(await window.oddDesktop.hasShippoKey()); }catch(e){ return null; }
}
// The mailbox presets fill in the server settings for the common mailboxes.
const DESKTOP_MAIL_PRESETS = [
  { id: "gmail", label: "Gmail or Google Workspace", host: "smtp.gmail.com", port: 587, security: "starttls", note: "Use an app password: Google Account → Security → 2-Step Verification → App passwords. About 500 emails a day." },
  { id: "icloud", label: "iCloud Mail", host: "smtp.mail.me.com", port: 587, security: "starttls", note: "Use an app-specific password from account.apple.com → Sign-In and Security. The username is your iCloud email address." },
  { id: "fastmail", label: "Fastmail", host: "smtp.fastmail.com", port: 465, security: "tls", note: "Use an app password from Fastmail's Settings → Privacy & Security." },
  { id: "zoho", label: "Zoho Mail", host: "smtp.zoho.com", port: 465, security: "tls", note: "With two-factor sign-in on, use an application-specific password." },
  { id: "other", label: "Another provider (your web host's mail…)", host: "", port: 587, security: "starttls", note: "Your provider's help pages list its SMTP (outgoing mail) server, port and security." },
];
// The saved mailbox ({ host, port, security, user, from, on }, never the password), null when none is
// saved, undefined outside the desktop program.
async function adminDesktopEmailSettings_(){
  if(!window.oddDesktop || typeof window.oddDesktop.emailSettings !== "function") return undefined;
  try{ return (await window.oddDesktop.emailSettings()) || null; }catch(e){ return undefined; }
}
const G_REQ_ = `<span class="g-req" aria-hidden="true">*</span>`;
// One feature: its box and name, what it covers, and its panel (opened while ticked).
function gFeatureRowHtml_(key, { label, desc, checked, panel = "", sub = false, hidden = false, cls = "gFeature", disabled = false, extra = "" }){
  return `<div class="g-feat${sub ? " g-feat-sub" : ""}" id="gFeatRow-${key}"${hidden ? ' style="display:none;"' : ""}>
          <label class="checkbox-row g-feat-head"><input type="checkbox" class="${cls}" data-feature="${key}"${checked ? " checked" : ""}${disabled ? " disabled" : ""}> <strong>${escapeHtml(label)}</strong>${extra}</label>
          <div class="admin-note g-feat-desc">${desc}</div>
          ${panel ? `<div class="g-feat-panel" id="gPanel-${key}"${checked ? "" : " hidden"}>${panel}</div>` : ""}
        </div>`;
}
function gRequiredNote_(what, all = true){ return `<div class="g-feat-req">${all ? "All fields below are" : `Every field marked ${G_REQ_} is`} required while ${what} is on.${all ? ` ${G_REQ_} required` : ""}</div>`; }
function gProductionPanelHtml_(machineSettings, loaded){
  return `<div id="gMachineSection" data-loaded="${loaded ? "1" : ""}">
            <div style="font-weight:600;margin-bottom:4px;">Machine Files</div>
            <div class="admin-note" style="margin-bottom:8px;">The Machine Files screen can show a <strong>Delete</strong> button on each file. Deleting over the machine protocol is currently disabled in the machines' firmware (the command exists but always refuses — see <code>the send-agent's PROTOCOL.md</code>), so the button is hidden by default. Turn it on only if a firmware update enables delete.</div>
            <label class="checkbox-row"><input type="checkbox" id="gMachShowDelete" ${machineSettings.showDeleteButton ? "checked" : ""}> Show delete buttons on Machine Files</label>
          </div>`;
}
// Shipping: the Shippo key (typed in the desktop version; a server secret on a cloud install), then
// the ship-from address — all required while Shipping is on.
function gShippingPanelHtml_({ shipFrom, us, desktop, keySet, cloudKey }){
  const f = (id, label, key, attrs, style) => `<label${style ? ` style="${style}"` : ""}><span>${label} ${G_REQ_}</span>
              <input type="${key === "email" ? "email" : "text"}" id="${id}" value="${escapeHtml(shipFrom[key] || "")}" ${attrs || ""}>
            </label>`;
  const keyHtml = desktop
    ? `<label><span>Shippo key ${G_REQ_}</span>
              <input type="password" id="gShippoKey" maxlength="200" autocomplete="off" spellcheck="false" placeholder="${keySet ? "A key is saved — paste a new one to replace it" : "shippo_live_… or shippo_test_…"}" style="max-width:360px;">
            </label>
            <div class="admin-note" id="gShippoStatus" style="margin:-4px 0 12px;">${keySet ? `✓ A key is saved (never shown). ` : ""}From your Shippo account: Settings → API. Labels are paid to Shippo. Carrier rates, labels and tracking need the internet.
              ${keySet ? `<button type="button" class="admin-btn admin-btn-secondary" id="gShippoRemove" style="padding:2px 10px;font-size:12px;margin-left:6px;">Remove key</button>` : ""}</div>`
    : `<div style="margin-bottom:12px;"><strong>Shippo key</strong> ${G_REQ_} — ${cloudKey ? `✓ set (the <code>SHIPPO_API_KEY</code> secret)` : `<span style="color:#b03a2e;">not set</span>: add the <code>SHIPPO_API_KEY</code> secret (docs/configuration.md)`}</div>`;
  return `${gRequiredNote_("Shipping")}
            ${keyHtml}
            <div id="gShipFromSection">
            <div style="font-weight:600;margin:4px 0;">Ship-from address ${G_REQ_}</div>
            <div class="admin-note" style="margin-bottom:8px;">Printed on every shipping label as the sender, and used for shipping-rate quotes${desktop ? "" : " on the storefront"}.${us ? "" : " <strong>Carrier rates and labels need the country in Region to be the United States.</strong>"}</div>
            ${f("gShipName", "Name", "name", 'maxlength="100"')}
            ${f("gShipStreet1", "Street address", "street1", 'maxlength="200"')}
            <div style="display:flex;gap:10px;flex-wrap:wrap;">
              ${f("gShipCity", "City", "city", 'maxlength="100"', "flex:2;min-width:160px;")}
              <label style="${us ? "flex:0 0 80px;" : "flex:1;min-width:120px;"}"><span><span id="gShipStateLabel">${us ? "State" : "State / region"}</span> ${G_REQ_}</span>
                <input type="text" id="gShipState" maxlength="${us ? 2 : 50}" value="${escapeHtml(shipFrom.state || "")}" style="${us ? "text-transform:uppercase;" : ""}">
              </label>
              <label style="flex:0 0 130px;"><span><span id="gShipZipLabel">${us ? "ZIP" : "Postal code"}</span> ${G_REQ_}</span>
                <input type="text" id="gShipZip" maxlength="12" value="${escapeHtml(shipFrom.zip || "")}">
              </label>
            </div>
            <div style="display:flex;gap:10px;flex-wrap:wrap;">
              ${f("gShipPhone", "Phone", "phone", `maxlength="30" placeholder="${us ? "555-555-0100" : ""}"`, "flex:1;min-width:160px;")}
              ${f("gShipEmail", "Email", "email", 'maxlength="200"', "flex:1;min-width:200px;")}
            </div>
            </div>
            <div class="admin-note"><a href="#packages">Package sizes</a> — the boxes you ship in, for rates and labels.</div>`;
}
// Email (desktop): the mailbox. `saved` is what the program has (or null).
function gEmailPanelHtml_(saved){
  const presetOf = (c) => (c && DESKTOP_MAIL_PRESETS.find(p => p.host && p.host === c.host)) || (c ? DESKTOP_MAIL_PRESETS.find(p => p.id === "other") : DESKTOP_MAIL_PRESETS[0]);
  const pre = presetOf(saved), v = saved || { host: pre.host, port: pre.port, security: pre.security, user: "", from: "" };
  return `${gRequiredNote_("Email", false)}
            <div class="admin-note" style="margin-bottom:10px;">They go out from your mailbox's address, as if you had sent them, and copies land in its Sent folder with Gmail, iCloud and most others. Microsoft 365 and Outlook.com mailboxes aren't supported yet.</div>
            <div id="gEmailStatus" style="font-size:14px;margin-bottom:10px;">${saved ? (saved.on ? `Email is on: sending from <strong>${escapeHtml(saved.from)}</strong> through ${escapeHtml(saved.host)}.` : `A mailbox is saved (${escapeHtml(saved.from)}), not in use while Email is off.`) : "No mailbox yet."}</div>
            <label style="max-width:360px;"><span>Your mailbox ${G_REQ_}</span><select id="gEmailPreset">${DESKTOP_MAIL_PRESETS.map(p => `<option value="${p.id}"${p.id === pre.id ? " selected" : ""}>${escapeHtml(p.label)}</option>`).join("")}</select></label>
            <div id="gEmailPresetNote" class="admin-note" style="margin:-4px 0 10px;max-width:520px;">${escapeHtml(pre.note)}</div>
            <label style="max-width:360px;"><span>Email address ${G_REQ_}</span><input type="email" id="gEmailFrom" maxlength="200" autocomplete="off" spellcheck="false" value="${escapeHtml(v.from || "")}" placeholder="you@example.com"></label>
            <label style="max-width:360px;"><span>Password or app password ${G_REQ_}</span><input type="password" id="gEmailPass" maxlength="300" autocomplete="new-password" spellcheck="false" placeholder="${saved ? "Leave empty to keep the saved one" : ""}"></label>
            <details id="gEmailServer"${pre.id === "other" ? " open" : ""} style="margin:0 0 10px;max-width:520px;"><summary style="cursor:pointer;font-size:13px;">Server settings <span style="color:#666;" id="gEmailServerSummary">${escapeHtml([v.host, v.port, v.security === "tls" ? "SSL/TLS" : "STARTTLS"].filter(Boolean).join(" · "))}</span></summary>
              <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px;">
                <label style="flex:2 1 200px;"><span>Outgoing (SMTP) server ${G_REQ_}</span><input type="text" id="gEmailHost" maxlength="200" spellcheck="false" value="${escapeHtml(v.host || "")}" placeholder="smtp.example.com"></label>
                <label style="flex:0 1 90px;"><span>Port ${G_REQ_}</span><input id="gEmailPort" type="number" min="1" max="65535" value="${escapeHtml(String(v.port || 587))}"></label>
                <label style="flex:1 1 150px;"><span>Security ${G_REQ_}</span><select id="gEmailSecurity"><option value="starttls"${v.security !== "tls" ? " selected" : ""}>STARTTLS (587)</option><option value="tls"${v.security === "tls" ? " selected" : ""}>SSL/TLS (465)</option></select></label>
                <label style="flex:1 1 200px;">Username <span style="font-weight:400;color:#666;">(if not the email address)</span><input type="text" id="gEmailUser" maxlength="200" spellcheck="false" autocomplete="off" value="${escapeHtml(saved && saved.user !== saved.from ? saved.user : "")}"></label>
              </div>
            </details>
            ${saved && saved.on ? `<div><button type="button" class="admin-btn admin-btn-secondary" id="gEmailTest" style="padding:3px 10px;font-size:12px;">Send a test email</button> <span id="gEmailTestResult" style="font-size:13px;"></span></div>` : `<div class="admin-note">Save signs in to the mailbox first; nothing is saved if it can't.</div>`}`;
}
// Supplier connections (desktop): the vendors, once the program has them on.
function gSuppliersPanelHtml_(on){
  return `<div class="admin-note" style="margin-bottom:10px;">Importing a supplier's files (product files, CSV, PDF invoices) always works. These need the internet; your logins with each supplier are saved encrypted on this computer, and shipment notices are checked every two hours while the program is open.</div>
            <div id="gSuppliersBody">${on ? `<div class="admin-summary">Loading&hellip;</div>` : `<div class="admin-note"><strong>Save</strong> with this ticked to turn supplier connections on; then connect your vendors here.</div>`}</div>`;
}
// The Features list: cloud rows in the server's order; the desktop version adds Email (with Design
// approval under it) and Supplier connections, and leaves out the storefront (it can't be on there).
function globalFeaturesHtml_(c){
  const desc = (k) => escapeHtml((c.featureList.find(f => f.key === k) || {}).description || "");
  const on = (k) => c.features[k] !== false;
  const rows = [];
  for (const f of c.featureList) {
    const k = f.key;
    if (c.desktop && k === "designVerification") continue;   // under Email, below
    const locked = c.lockedFeatures.includes(k) && !(c.desktop && k === "shipping");
    const panel = k === "production" ? gProductionPanelHtml_(c.machineSettings, c.machineLoaded)
      : k === "shipping" ? gShippingPanelHtml_(c) : "";
    rows.push(gFeatureRowHtml_(k, { label: f.label, desc: desc(k), checked: on(k) && !locked, panel, hidden: c.desktop && locked, disabled: locked }));
  }
  if (c.desktop) {
    const emailOn = !!(c.emailSaved && c.emailSaved.on);
    rows.push(gFeatureRowHtml_("email", { label: "Email", cls: "gProgramFeature", checked: emailOn, panel: gEmailPanelHtml_(c.emailSaved),
      desc: "Order emails (received, payment confirmed, shipped, cancelled), invoices with a PDF, design proofs and your morning roll-up — sent from your own mailbox." }));
    rows.push(gFeatureRowHtml_("designVerification", { label: "Design approval", sub: true, checked: on("designVerification") && emailOn, disabled: !emailOn,
      extra: ` <span class="g-feat-needs" style="font-size:12px;color:#666;"${emailOn ? " hidden" : ""}>(needs Email)</span>`,
      desc: "Proofs go out by email with the pictures attached; the customer replies, and you mark the order Design approved. Orders with free-form personalization wait for it." }));
    rows.push(gFeatureRowHtml_("suppliers", { label: "Supplier connections", cls: "gProgramFeature", checked: !!c.suppliersOn, panel: gSuppliersPanelHtml_(!!c.suppliersOn),
      desc: "A supplier's live product data and prices (PromoStandards), ordering blanks from it from Blanks to order, and its shipment notices." }));
  }
  return `<h2 style="margin:22px 0 6px;">Features</h2>
        <div class="admin-note" style="margin-bottom:10px;">Tick what you use; each one opens to show what it needs. Turning one off hides its pages and stops its actions; nothing is deleted, and turning it back on brings everything back as it was. Stock of blanks and transfers, and cost of goods, are always on — making an order uses them.${c.desktop ? "" : `<br>
          <strong>Storefront</strong> is the one switch that hides nothing here: with it off, customers see an “online ordering isn't available” page on every shop address, and you keep entering orders, sending payment links and design proofs, and using Publish, a shop's “ready” box and its custom domain exactly as before (they only matter once it's back on).`}</div>
        <div id="gFeatures">${rows.join("")}</div>`;
}
// Open / close panels as boxes are ticked, and the panels' own controls.
function wireGlobalFeatures_(c){
  const $ = (id) => document.getElementById(id);
  document.querySelectorAll("#gFeatures .g-feat-head input[type=checkbox]").forEach(box => box.addEventListener("change", () => {
    const panel = $("gPanel-" + box.dataset.feature);
    if (panel) { panel.hidden = !box.checked; if (box.checked && panel.scrollIntoView) panel.scrollIntoView({ block: "nearest" }); }
    if (box.dataset.feature === "production" && $("gProductionExtra")) $("gProductionExtra").style.display = box.checked ? "" : "none";
    if (box.dataset.feature === "email") {
      const dv = document.querySelector('#gFeatRow-designVerification .gFeature');
      if (dv) { dv.disabled = !box.checked; if (!box.checked) dv.checked = false; }
      const needs = document.querySelector("#gFeatRow-designVerification .g-feat-needs"); if (needs) needs.hidden = box.checked;
    }
  }));
  if ($("gEmailPreset")) {
    const summary = () => { if ($("gEmailServerSummary")) $("gEmailServerSummary").textContent = [$("gEmailHost").value, $("gEmailPort").value, $("gEmailSecurity").value === "tls" ? "SSL/TLS" : "STARTTLS"].filter(Boolean).join(" · "); };
    $("gEmailPreset").onchange = () => {
      const p = DESKTOP_MAIL_PRESETS.find(x => x.id === $("gEmailPreset").value) || DESKTOP_MAIL_PRESETS[0];
      $("gEmailPresetNote").textContent = p.note;
      if (p.host) { $("gEmailHost").value = p.host; $("gEmailPort").value = p.port; $("gEmailSecurity").value = p.security; }
      else { $("gEmailHost").value = ""; $("gEmailServer").open = true; }
      summary();
    };
    // The usual pairing, when the port is changed by hand: 465 is SSL/TLS, 587 STARTTLS.
    $("gEmailPort").onchange = () => { const n = Number($("gEmailPort").value); if (n === 465) $("gEmailSecurity").value = "tls"; else if (n === 587) $("gEmailSecurity").value = "starttls"; summary(); };
    $("gEmailHost").oninput = summary; $("gEmailSecurity").onchange = summary;
  }
  if ($("gEmailTest")) $("gEmailTest").onclick = async () => {
    const out = $("gEmailTestResult"); out.textContent = "Sending…";
    try {
      const r = await hoopApi_({ action: "sendTestEmail", to: (c.emailSaved && c.emailSaved.from) || "" });
      const rep = r.report || {};
      out.textContent = rep.ok ? "✓ Sent to " + rep.to + " — " + (rep.providerMessage || "accepted") : "✗ " + (rep.providerMessage || (rep.hints || []).join(" ") || "Not sent.");
    } catch (e) { out.textContent = "✗ " + e.message; }
  };
  if ($("gShippoRemove")) $("gShippoRemove").onclick = () => {
    const removing = $("gShippoRemove").dataset.remove !== "1";
    $("gShippoRemove").dataset.remove = removing ? "1" : "";
    $("gShippoRemove").textContent = removing ? "Keep the key" : "Remove key";
    $("gShippoKey").placeholder = removing ? "The key is removed when you save" : "A key is saved — paste a new one to replace it";
    if (removing) $("gShippoKey").value = "";
  };
  // A field outlined by a refused save is cleared as soon as it's filled in.
  document.querySelectorAll("#gFeatures input, #gFeatures select").forEach(e => e.addEventListener("input", () => { e.style.outline = ""; }));
  if (c.suppliersOn && $("gSuppliersBody")) mountVendorConnections_($("gSuppliersBody"));
  if (window._gScrollTo && $(window._gScrollTo)) { const t = $(window._gScrollTo); window._gScrollTo = null; if (t.scrollIntoView) t.scrollIntoView({ block: "start" }); }
}
// What would make this save invalid, checked before anything is sent: "" or the message (the fields
// to fill in are outlined, and the first panel with one is scrolled to).
function globalSettingsProblem_(){
  const $ = (id) => document.getElementById(id);
  const val = (id) => (($(id) || {}).value || "").trim();
  const ticked = (k) => { const b = document.querySelector(`#gFeatRow-${k} .g-feat-head input[type=checkbox]`); return !!b && b.checked && !b.disabled; };
  document.querySelectorAll("#gFeatures input, #gFeatures select").forEach(e => { e.style.outline = ""; });
  const c = window._gSettingsCtx || {};
  const problems = [], flagged = [];
  const need = (what, missing, bad) => { if (missing.length || bad.length) problems.push(`${what} needs ${[missing.length ? missing.map(m => m[1]).join(", ") : "", ...bad.map(b => b[1])].filter(Boolean).join("; ")}`); flagged.push(...missing.map(m => m[0]), ...bad.map(b => b[0])); };
  if (ticked("shipping")) {
    const us = (val("gLocaleCountry") || (adminIsUS_() ? "US" : "OTHER")) !== "OTHER";
    const fields = [["gShipName", "Name"], ["gShipStreet1", "Street address"], ["gShipCity", "City"], ["gShipState", us ? "State" : "State / region"], ["gShipZip", us ? "ZIP" : "Postal code"], ["gShipPhone", "Phone"], ["gShipEmail", "Email"]];
    const missing = fields.filter(([id]) => !val(id)).map(([id, l]) => [id, "the ship-from " + (l === "ZIP" ? l : l.toLowerCase())]);
    const bad = [];
    if (us && val("gShipZip") && !/^\d{5}(-\d{4})?$/.test(val("gShipZip"))) bad.push(["gShipZip", "a 5-digit ZIP (or ZIP+4)"]);
    if (us && val("gShipState") && !/^[A-Za-z]{2}$/.test(val("gShipState"))) bad.push(["gShipState", "a 2-letter state"]);
    if (val("gShipEmail") && !/^\S+@\S+\.\S+$/.test(val("gShipEmail"))) bad.push(["gShipEmail", "a ship-from email that looks like one"]);
    const removing = $("gShippoRemove") && $("gShippoRemove").dataset.remove === "1";
    const hasKey = c.desktop ? (!!val("gShippoKey") || (c.keySet && !removing)) : window._gShippoKey !== false;
    if (!hasKey) { missing.unshift([c.desktop ? "gShippoKey" : "", "a Shippo key"]); }
    need("Shipping", missing, bad);
  }
  if (c.desktop && ticked("email")) {
    const missing = [["gEmailFrom", "the email address"], ["gEmailHost", "the outgoing (SMTP) server"], ["gEmailPort", "the port"]].filter(([id]) => !val(id));
    if (!val("gEmailPass") && !c.emailSaved) missing.push(["gEmailPass", "the password"]);
    const bad = val("gEmailFrom") && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(val("gEmailFrom")) ? [["gEmailFrom", "an email address that looks like one"]] : [];
    if (missing.some(m => m[0] === "gEmailHost" || m[0] === "gEmailPort") && $("gEmailServer")) $("gEmailServer").open = true;
    need("Email", missing, bad);
  }
  if (c.desktop && ticked("designVerification") && !ticked("email")) problems.push("Design approval needs Email");
  if (!problems.length) return "";
  flagged.filter(Boolean).forEach(id => { const e = $(id); if (e) e.style.outline = "2px solid #b03a2e"; });
  const first = flagged.filter(Boolean).map($).find(Boolean);
  if (first) { const panel = first.closest(".g-feat-panel"); if (panel) panel.hidden = false; if (first.scrollIntoView) first.scrollIntoView({ block: "center" }); }
  return `Nothing was saved. ${problems.join(". ")}. Fill ${flagged.length > 1 ? "them" : "it"} in, or untick ${problems.length > 1 ? "those features" : "it"}.`;
}
// The desktop program's part of a save: what changed in the Shipping key, Email and Supplier
// connections. { shippoKey?, email?: { on, settings, password }, suppliers? } — empty when nothing did.
function globalProgramChanges_(){
  const $ = (id) => document.getElementById(id), c = window._gSettingsCtx || {};
  if (!c.desktop) return {};
  const out = {}, val = (id) => (($(id) || {}).value || "").trim();
  const box = (k) => document.querySelector(`#gFeatRow-${k} .g-feat-head input[type=checkbox]`);
  if (val("gShippoKey")) out.shippoKey = val("gShippoKey");
  else if ($("gShippoRemove") && $("gShippoRemove").dataset.remove === "1") out.shippoKey = null;
  const email = box("email"), saved = c.emailSaved;
  if (email && email.checked) {
    const settings = { host: val("gEmailHost"), port: Number(val("gEmailPort")), security: ($("gEmailSecurity") || {}).value || "starttls", from: val("gEmailFrom"), user: val("gEmailUser") || val("gEmailFrom") };
    const same = saved && saved.on && saved.host === settings.host.toLowerCase() && Number(saved.port) === settings.port && saved.security === settings.security && saved.from === settings.from && saved.user === settings.user;
    if (!same || val("gEmailPass")) out.email = { on: true, settings, password: ($("gEmailPass") || {}).value || "" };
  } else if (email && saved && saved.on) out.email = { on: false };
  const sup = box("suppliers");
  if (sup && sup.checked !== !!c.suppliersOn) out.suppliers = sup.checked;
  return out;
}

// The desktop version's backup reminder: there is no copy in the cloud, so a slim note under the menu
// once the last backup is a week old — or a day after the program was first used, with none yet. It
// says when, and Back up now opens File → Back up…. "Later" hides it until the program is next opened.
const DESKTOP_BACKUP_DAYS = 7;
function desktopBackupNote_(status, now){
  if (!status) return "";
  const day = 864e5, t = (iso) => { const v = Date.parse(iso || ""); return Number.isFinite(v) ? v : null; };
  const last = t(status.lastBackupAt), created = t(status.createdAt);
  if (last !== null) {
    const days = Math.floor((now - last) / day);
    return days >= DESKTOP_BACKUP_DAYS ? `Your last backup was ${days} days ago.` : "";
  }
  return created !== null && now - created >= day ? "Nothing has been backed up yet." : "";
}
async function adminDesktopBackupNudge_(){
  if (!adminDesktop_() || !window.oddDesktop || typeof window.oddDesktop.backupStatus !== "function") return;
  try { if (sessionStorage.getItem("oddBackupLater")) return; } catch (e) {}
  let note = "";
  try { note = desktopBackupNote_(await window.oddDesktop.backupStatus(), Date.now()); } catch (e) { return; }
  const old = document.getElementById("desktopBackupNote");
  if (old) old.remove();
  if (!note) return;
  const nav = document.getElementById("adminNav"), bar = document.createElement("div");
  bar.id = "desktopBackupNote";
  bar.setAttribute("role", "status");
  bar.style.cssText = "display:flex;gap:10px;align-items:center;flex-wrap:wrap;max-width:1180px;margin:8px auto;padding:8px 12px;background:#fffbeb;border:1px solid #fcd34d;border-radius:6px;font-size:13px;color:#78350f;";
  bar.innerHTML = `<span>${escapeHtml(note)} Everything is only on this computer — keep a copy somewhere else (a USB drive or a synced folder).</span>
    <button type="button" class="admin-btn" id="desktopBackupNow" style="padding:3px 10px;font-size:12px;">Back up now&hellip;</button>
    <button type="button" class="admin-btn admin-btn-secondary" id="desktopBackupLater" style="padding:3px 10px;font-size:12px;">Later</button>`;
  if (nav && nav.parentNode) nav.parentNode.insertBefore(bar, nav.nextSibling); else document.body.prepend(bar);
  bar.querySelector("#desktopBackupNow").onclick = () => { window.oddDesktop.backUp(); };
  bar.querySelector("#desktopBackupLater").onclick = () => { try { sessionStorage.setItem("oddBackupLater", "1"); } catch (e) {} bar.remove(); };
}

function renderDesktopOff_(app, hash){
  adminSetHash(hash);
  document.title = adminTitle_("Not in the desktop version");
  app.innerHTML = `
    <div class="org-hero admin-hero" style="--org-accent:var(--accent);">
      <h1>Not in the desktop version</h1>
      <div class="stitch stitch-thick"></div>
    </div>
    <div class="admin-panel" style="--org-accent:var(--accent);" id="desktopOffPanel">
      <div class="admin-empty">Communications is about email. Turn on <a href="#settings">Email under Global settings → Features</a> to send order emails, invoices and the morning roll-up.</div>
      <div class="admin-actions" style="margin-top:14px;"><button class="admin-btn" onclick="location.hash='#orders'">Back to Orders</button></div>
    </div>`;
}
// The lowest role a page is for (see ACTION_ROLE in functions/api/orders.js — the server is the
// authority; this keeps people from landing on screens that could only show refusals).
// Global settings is an admin's page: every change on it is (updateGlobalSettings, updateFeatures, the
// business profile, region, sales tax, ship-from), so nobody else is shown it at all.
const ADMIN_ONLY_PAGES = ["users", "audit", "settings", "catalog/settings", "vendors", "orphans"];
const ADMIN_MANAGER_PAGES = ["packages", "brandrules", "money", "reconcile", "accountviewer", "books", "catalog/new-org"];
function adminPageRole_(hash){
  const raw = String(hash || "").replace(/^#\/?/, "");
  if (ADMIN_ONLY_PAGES.includes(raw)) return "admin";
  // Shop setup (and the wizard) make and open shops: a manager's, like creating one.
  if (ADMIN_MANAGER_PAGES.includes(raw) || /^catalog\/orgs\/[^/]+\/edit$/.test(raw) || /^(setup|wizard)(\/|$)/.test(raw)) return "manager";
  return "staff";
}
// The menu without the pages of switched-off features or of a higher role (a group left empty disappears).
function adminNavGroups_(){
  return ADMIN_NAV_GROUPS.map(g => ({ label: g.label, items: g.items.filter(it => !Array.isArray(it) || (adminPageOn_(it[0]) && adminCan_(adminPageRole_(it[0])))) }))
    .filter(g => g.items.length);
}
// Can the signed-in user open that page (their role, and the page's feature switched on)? Links and
// buttons to a page they can't use aren't drawn at all.
function adminCanOpen_(hash){ return adminPageOn_(hash) && adminCan_(adminPageRole_(hash)); }
function renderRoleOff_(app, hash){
  adminSetHash(hash);
  const need = adminPageRole_(hash);
  document.title = adminTitle_("Not available");
  app.innerHTML = `
    <div class="org-hero admin-hero" style="--org-accent:var(--accent);">
      ${adminBreadcrumbs([{label:"Orders", hash:"picker"}, {label:"Not available"}])}
      <h1>Not available to you</h1>
      <div class="stitch stitch-thick"></div>
    </div>
    <div class="admin-panel" style="--org-accent:var(--accent);" id="roleOffPanel" data-need="${escapeHtml(need)}">
      <div class="admin-empty"><strong>Not available to you.</strong> This page is for ${need === "admin" ? "an admin" : "a manager or an admin"}. You are signed in as ${escapeHtml(ADMIN_ROLE_LABELS[adminMe && adminMe.role] || "a user")}.</div>
    </div>`;
}
function renderFeatureOff_(app, feature, hash){
  adminSetHash(hash);
  const label = FEATURE_LABELS_[feature] || feature;
  document.title = adminTitle_(label + " is turned off");
  app.innerHTML = `
    <div class="org-hero admin-hero" style="--org-accent:var(--accent);">
      ${adminBreadcrumbs([{label:"Orders", hash:"picker"}, {label: label}])}
      <h1>${escapeHtml(label)} is turned off</h1>
      <div class="stitch stitch-thick"></div>
    </div>
    <div class="admin-panel" style="--org-accent:var(--accent);" id="featureOffPanel" data-feature="${escapeHtml(feature)}">
      <div class="admin-empty"><strong>${escapeHtml(label)} is turned off.</strong> This feature is turned off — ${adminCanOpen_("settings") ? "turn it on under Global settings" : "an admin can turn it on"}.
        Nothing was deleted: everything comes back as it was when it's turned on again.</div>
      <div class="admin-actions" style="margin-top:14px;">
        ${adminCanOpen_("settings") ? `<button class="admin-btn" onclick="location.hash='#settings'">Open Global settings</button>` : ""}
        <button class="admin-btn" onclick="location.hash='#orders'">Back to Orders</button>
      </div>
    </div>`;
}
// With Bookkeeping off, the money side of the inventory forms (what it was paid from, a receipt,
// the parts that become an expense or an owner draw) is hidden; the stock side works as always.
// The fields stay in the page, empty, so the code that reads them doesn't change.
function hideBookkeepingFields_(root, selectors){
  if (adminFeatureOn_("bookkeeping") || !root) return;
  selectors.forEach(sel => root.querySelectorAll(sel).forEach(el => {
    const box = el.matches("details, div") ? el : (el.closest("label") || el);
    box.style.display = "none";
  }));
}

// A configurable line's readable summary (migrations/0036): garment color + each location's graphic
// (the auto reorder-QR application is left out). "" when the line isn't configurable.
function cfgSummary_(it){
  const c = it && it.config; if (!c || !Array.isArray(c.locations)) return "";
  const parts = c.locations.filter(l => !l.auto && !l.fixed && l.location !== "reorderqr")
    .map(l => `${l.label || l.location}: ${l.graphicName}${l.ink ? " (" + l.ink + ")" : ""}`);
  return [c.garmentColor, ...parts].filter(Boolean).join(" · ");
}
// Plain-text detail after a line's name: a configurable line's picks AND any personalization (typed name or
// preset word) — a line can have both. "" when it has neither.
function lineDetail_(it){
  const cfg = cfgSummary_(it);
  const pers = it && it.personalized ? "\u201c" + (it.persName || "yes") + "\u201d" : "";
  // Filled from the shop's finished stock (migrations/0060): no blank, design or making steps.
  const stock = it && it.fromStock ? "From stock" : "";
  return [stock, cfg, pers].filter(Boolean).join(" \u00b7 ");
}
function adminNavActive_(){
  const raw = location.hash.replace(/^#\/?/, "");
  const m = raw.match(/^orders(?:\/([^/]+))?$/);
  if(m) return "orders";
  if(raw === "picker" || raw === "") return "orders";
  if(raw.startsWith("catalog")) return "catalog";
  // A page with a shop or record in its address belongs to its menu entry (#designs/<shop>/3 → Designs).
  const top = raw.split("/")[0];
  if(top === "designs" || top === "graphics" || top === "maintenance" || top === "setup") return top;
  if(top === "wizard") return "setup";
  return raw;
}
// ---- Small action menus (the Blanks toolbar and rows) ------------------------------------------------
// A button that opens a short list of actions (index.html .admin-menu). The list opens below the button
// (above it near the bottom of the window), fixed to the window so a scrolling table can't cut it off. It
// closes on choosing an item, on Escape, on a click anywhere else, and when the page or a table scrolls.
// Arrow keys move between the items. `opts`: id, hidden (start hidden — shown by the caller later), dots
// (a "⋯" button with no ▾), ariaLabel, title, btnStyle.
function adminMenuHtml_(label, itemsHtml, opts){
  opts = opts || {};
  return `<div class="admin-menu${opts.dots ? " admin-menu-dots" : ""}"${opts.id ? ` id="${escapeHtml(opts.id)}"` : ""}${opts.hidden ? ' style="display:none;"' : ""}>`
    + `<button type="button" class="admin-btn" style="${opts.btnStyle || ""}" aria-haspopup="menu" aria-expanded="false"${opts.title ? ` title="${escapeHtml(opts.title)}"` : ""}${opts.ariaLabel ? ` aria-label="${escapeHtml(opts.ariaLabel)}"` : ""} onclick="toggleAdminMenu_(this)" onkeydown="adminMenuKey_(event)">${label}</button>`
    + `<div class="admin-menu-list" role="menu" onkeydown="adminMenuKey_(event)">${itemsHtml}</div></div>`;
}
// One item: `attrs` is its id / onclick / data- / title attributes, already escaped by the caller.
function adminMenuItem_(attrs, label, danger){
  return `<button type="button" role="menuitem" class="admin-menu-item${danger ? " danger" : ""}" ${attrs || ""}>${label}</button>`;
}
function closeAdminMenus_(except){
  document.querySelectorAll(".admin-menu.open").forEach(m => {
    if (m === except) return;
    m.classList.remove("open");
    const b = m.querySelector(":scope > button"); if (b) b.setAttribute("aria-expanded", "false");
  });
}
function toggleAdminMenu_(btn){
  if (!window._adminMenusWired) {
    window._adminMenusWired = true;
    // Choosing an item or clicking elsewhere closes it (the item's own action runs first).
    document.addEventListener("click", (e) => {
      if (e.target.closest(".admin-menu-item") || !e.target.closest(".admin-menu")) closeAdminMenus_();
    });
    document.addEventListener("scroll", (e) => { if (!(e.target && e.target.closest && e.target.closest(".admin-menu-list"))) closeAdminMenus_(); }, true);
    window.addEventListener("resize", () => closeAdminMenus_());
  }
  const menu = btn.parentNode, open = !menu.classList.contains("open");
  closeAdminMenus_(menu);
  menu.classList.toggle("open", open);
  btn.setAttribute("aria-expanded", open ? "true" : "false");
  if (!open) return;
  const list = menu.querySelector(".admin-menu-list"), r = btn.getBoundingClientRect();
  const w = list.offsetWidth, h = list.offsetHeight, vw = window.innerWidth, vh = window.innerHeight;
  let left = r.left, top = r.bottom + 4;
  if (left + w > vw - 8) left = Math.max(8, r.right - w);
  if (top + h > vh - 8 && r.top - h - 4 >= 8) top = r.top - h - 4;
  list.style.left = left + "px"; list.style.top = top + "px";
}
function adminMenuKey_(e){
  const menu = e.target.closest(".admin-menu");
  if (!menu) return;
  const btn = menu.querySelector(":scope > button"), items = [...menu.querySelectorAll(".admin-menu-item")];
  if (e.key === "Escape" && menu.classList.contains("open")) { e.preventDefault(); e.stopPropagation(); closeAdminMenus_(); btn.focus(); return; }
  if (e.key !== "ArrowDown" && e.key !== "ArrowUp") return;
  e.preventDefault();
  if (!menu.classList.contains("open")) toggleAdminMenu_(btn);
  const i = items.indexOf(document.activeElement);
  const next = e.key === "ArrowDown" ? (i + 1) % items.length : (i <= 0 ? items.length - 1 : i - 1);
  if (items[next]) items[next].focus();
}

function toggleNavDropdown(btn){
  const group = btn.parentNode, wasOpen = group.classList.contains("open");
  closeNavDropdowns();
  if(!wasOpen) group.classList.add("open");
}
function closeNavDropdowns(){
  document.querySelectorAll("#adminNav .admin-nav-group.open").forEach(g => g.classList.remove("open"));
}
function navGo(hash){ closeNavDropdowns(); location.hash = "#" + hash; }
function renderAdminNav(){
  let nav = document.getElementById("adminNav");
  if(!adminOrgs || !adminKey || adminPending){ if(nav) nav.remove(); return; }
  const app = document.getElementById("app");
  if(!app) return;
  if(!nav){
    nav = document.createElement("nav");
    nav.id = "adminNav";
    nav.setAttribute("aria-label", "Admin");
    app.parentNode.insertBefore(nav, app);
    if(!window._navDropdownCloserInstalled){
      window._navDropdownCloserInstalled = true;
      document.addEventListener("click", (e) => { if(!e.target.closest(".admin-nav-group")) closeNavDropdowns(); });
    }
  }
  const active = adminNavActive_();
  const groupHtml = (g) => {
    const groupActive = g.items.some(it => Array.isArray(it) && it[0] === active);
    const itemHtml = (it) => Array.isArray(it)
      ? `<button type="button" class="admin-nav-btn${active === it[0] ? " active" : ""}" data-h="${escapeHtml(it[0])}" onclick="navGo(this.dataset.h)">${escapeHtml(it[1])}</button>`
      : `<button type="button" class="admin-nav-btn" onclick="closeNavDropdowns();${it.action}">${escapeHtml(it.label)}</button>`;
    return `<div class="admin-nav-group">
      <button type="button" class="admin-nav-btn admin-nav-drop${groupActive ? " active" : ""}" onclick="toggleNavDropdown(this)">${escapeHtml(g.label)}</button>
      <div class="admin-nav-menu">${g.items.map(itemHtml).join("")}</div>
    </div>`;
  };
  // Phones get a "☰ Menu" bar instead of the button row (CSS swaps them below 760px): the sheet lists
  // every page, grouped, so nothing hides inside a dropdown that can run off the screen.
  const navGroups = adminNavGroups_();   // pages of switched-off features are left out, here and in the sheet
  // The same top-level pages as the desktop row (Run Transfer Sheets was missing from the phone menu).
  const top = [["orders", "Orders"], ["runorder", "Run Order"], ["runtransfer", "Run Transfer Sheets"], ["catalog", "Manage catalog"]].filter(it => adminPageOn_(it[0]));
  const current = top.concat(...ADMIN_NAV_GROUPS.map(g => g.items.filter(Array.isArray))).find(it => it[0] === active);
  const currentLabel = current ? current[1] : "";
  const sheetItem = (it) => Array.isArray(it)
    ? `<button type="button" class="admin-nav-btn${active === it[0] ? " active" : ""}" data-h="${escapeHtml(it[0])}" onclick="navGo(this.dataset.h)">${escapeHtml(it[1])}</button>`
    : `<button type="button" class="admin-nav-btn" onclick="closeNavDropdowns();${it.action}">${escapeHtml(it.label)}</button>`;
  nav.innerHTML = `
    <div class="admin-nav-row">
      <button type="button" class="admin-nav-btn${active === "orders" ? " active" : ""}" onclick="navGo('orders')">Orders</button>
      ${adminPageOn_("runorder") ? `<button type="button" class="admin-nav-btn${active === "runorder" ? " active" : ""}" onclick="navGo('runorder')">Run Order</button>` : ""}
      <button type="button" class="admin-nav-btn${active === "runtransfer" ? " active" : ""}" onclick="navGo('runtransfer')">Run Transfer Sheets</button>
      <button type="button" class="admin-nav-btn${active === "catalog" ? " active" : ""}" onclick="navGo('catalog')">Manage catalog</button>
      ${navGroups.map(groupHtml).join("")}
    </div>
    <div class="admin-nav-mobile admin-nav-group">
      <button type="button" class="admin-nav-btn admin-nav-menu-btn" aria-label="Menu" onclick="toggleNavDropdown(this)">☰ Menu</button>
      <span class="admin-nav-current">${escapeHtml(currentLabel)}</span>
      <div class="admin-nav-menu admin-nav-sheet">
        <div class="admin-nav-sheet-top">${top.map(sheetItem).join("")}</div>
        ${navGroups.map(g => `<div class="admin-nav-sheet-group"><div class="admin-nav-label">${escapeHtml(g.label)}</div>${g.items.map(sheetItem).join("")}</div>`).join("")}
      </div>
    </div>`;
  drawShopBar_();
}

// ---- The shop bar (2026-10) ----
// Every catalog screen gets the same black bar under the menu: ← Manage catalog, the shop picker, the shop's
// Shop setup (or Resume shop setup) / Products / Designs / Graphics, and Publish — and the page itself sits in
// one max-width, light column (body.shop-mgmt). drawShopBar_ runs with the menu (renderAdminNav), so every
// route change and adminSetHash redraws it; the page renders below it in #app and never touches it.
const SHOP_BAR_TOPS_ = ["catalog", "wizard", "setup", "designs", "graphics", "categories", "locations", "brandrules", "packages"];
function shopBarContext_(){
  const raw = location.hash.replace(/^#\/?/, "");
  const parts = raw.split("/").map(x => { try { return decodeURIComponent(x); } catch (e) { return x; } });
  const top = parts[0];
  if (!SHOP_BAR_TOPS_.includes(top)) return null;
  if (top === "catalog") {
    if (parts[1] === "settings") return null;   // Global settings' old address
    if (parts[1] === "orgs" && parts[2]) return { shop: parts[2], page: parts[3] === "edit" ? "edit" : "products" };
    if (parts[1] === "new-org") return { shop: null, page: "setup" };
    return { shop: null, page: "catalog" };
  }
  if (top === "wizard" || top === "setup") return { shop: parts[1] && parts[1] !== "new" ? parts[1] : null, page: "setup" };
  if (top === "designs" || top === "graphics") return { shop: parts[1] || adminLastShop_() || null, page: top };
  return { shop: null, page: top };   // a catalog-wide list (categories, decoration locations, brand rules, package sizes)
}
// The address of one of a shop's pages.
function shopBarHash_(page, orgId){
  const o = encodeURIComponent(orgId);
  return { setup: "wizard/" + o, products: "catalog/orgs/" + o + "/products", edit: "catalog/orgs/" + o + "/edit",
    designs: "designs/" + o, graphics: "graphics/" + o }[page] || ("catalog/orgs/" + o + "/products");
}
window._shopBarData = window._shopBarData || { at: 0, wizards: null, publish: null };
async function loadShopBarData_(force){
  const d = window._shopBarData;
  if (!force && d.loading) return d.loading;
  if (!force && Date.now() - d.at < 15000) return;
  d.loading = (async () => {
    const [w, p, o] = await Promise.all([
      hoopApi_({ action: "listShopWizards" }).catch(() => null),
      hoopApi_({ action: "getPublishState" }).catch(() => null),
      hoopApi_({ action: "listOrgsAdmin" }).catch(() => null)]);
    if (w && w.wizards) d.wizards = w.wizards;
    if (o && o.orgs) window._adminOrgRegistry = o.orgs;   // each shop's open / coming-soon state for the toggle
    if (p && p.publishState) { d.publish = p.publishState; window._publishState = p.publishState; }
    d.at = Date.now();
  })();
  try { await d.loading; } finally { d.loading = null; }
}
// Each link is drawn for whoever may open that page (its role and feature switch): in OpenDecoDesk a worker manages
// products, designs and graphics; Shop setup and Publish are a manager's.
function shopBarHtml_(ctx){
  const manager = adminCan_("manager");
  const orgs = adminOrgs || [];
  const shop = ctx.shop && orgs.some(o => o.orgId === ctx.shop) ? ctx.shop : null;
  const d = window._shopBarData;
  const link = (page, label) => `<a class="shop-bar-link${ctx.page === page ? " active" : ""}" href="#${escapeHtml(shopBarHash_(page, shop))}"${ctx.page === page ? ' aria-current="page"' : ""}>${escapeHtml(label)}</a>`;
  const wiz = shop && (d.wizards || []).find(x => x.orgId === shop);
  const pub = shop && d.publish ? d.publish[shop] : null;
  const pubBtn = !shop || !manager ? "" : pub && pub.state === "current"
    ? `<button type="button" class="shop-bar-pub done" disabled title="Shoppers see this shop as it is now">✓ Published</button>`
    : `<button type="button" class="shop-bar-pub" data-org="${escapeHtml(shop)}" onclick="shopBarPublish_(this.dataset.org)" title="${pub && pub.state === "never" ? "Shoppers see this shop's current products and settings (until it's published once, changes show at once)" : "Shoppers see this shop's current products and settings"}">${pub && pub.state === "changed" ? "Publish changes" : "Publish"}</button>`;
  // Unpublished changes can be thrown away: back to what was last published (shopBarDiscard_).
  const discardBtn = shop && manager && pub && pub.state === "changed" ? `<button type="button" class="shop-bar-discard" data-org="${escapeHtml(shop)}" onclick="shopBarDiscard_(this.dataset.org)" title="Put this shop back the way it was last published">Discard changes&hellip;</button>` : "";
  // Open for orders, or "Coming soon" — a switch beside Publish (setOrgReady, asked first).
  const reg = shop && (window._adminOrgRegistry || []).find(o => o.orgId === shop);
  const liveBtn = !shop || !manager || !reg ? "" : `<button type="button" class="shop-bar-live${reg.ready ? " on" : ""}" role="switch" aria-checked="${reg.ready ? "true" : "false"}"
      data-org="${escapeHtml(shop)}" onclick="shopBarLive_(this.dataset.org, this.getAttribute('aria-checked') !== 'true')"
      title="${reg.ready ? "Open for orders — click to show “Coming soon” instead" : "Shoppers see “Coming soon” — click to open the shop for orders"}"><span class="shop-bar-knob"></span>${reg.ready ? "Live" : "Coming soon"}</button>`;
  return `
    ${adminCanOpen_("catalog") ? (ctx.page === "catalog" ? `<span class="shop-bar-title">Manage catalog</span>` : `<a class="shop-bar-back" href="#catalog">&larr; Manage catalog</a>`) : ""}
    <label class="shop-bar-pick"><span class="sr-only">Shop</span>
      <select aria-label="Shop" onchange="shopBarPick_(this.value)">
        ${shop ? "" : `<option value="" selected>Choose a shop&hellip;</option>`}
        ${orgs.map(o => `<option value="${escapeHtml(o.orgId)}"${o.orgId === shop ? " selected" : ""}>${escapeHtml(o.name || o.orgId)}</option>`).join("")}
      </select></label>
    ${shop ? `<span class="shop-bar-links">
      ${adminCanOpen_(shopBarHash_("setup", shop)) ? link("setup", wiz && !wiz.done ? "Resume shop setup" : "Shop setup") : ""}
      ${adminCanOpen_(shopBarHash_("edit", shop)) ? link("edit", "Shop settings") : ""}
      ${adminCanOpen_(shopBarHash_("products", shop)) ? link("products", "Products") : ""}
      ${adminCanOpen_(shopBarHash_("designs", shop)) ? link("designs", "Designs") : ""}
      ${adminCanOpen_(shopBarHash_("graphics", shop)) ? link("graphics", "Graphics") : ""}
    </span><span class="shop-bar-end">${adminDesktop_() ? "" : liveBtn + discardBtn + pubBtn}</span>` : ""}`;
}
// The Live / Coming soon switch: asks, then opens or closes the shop for orders (nothing is published by it).
async function shopBarLive_(orgId, ready){
  const name = ((adminOrgs || []).find(o => o.orgId === orgId) || {}).name || orgId;
  const ok = await askConfirm_(ready
    ? `Open ${name} for orders?\n\nShoppers can order from it straight away. They see what was last published — publish first if you've made changes.`
    : `Show “Coming soon” for ${name}?\n\nShoppers can't order until you open it again. Orders already placed aren't affected.`,
    { confirmLabel: ready ? "Go live" : "Show coming soon" });
  if (!ok) return;
  try {
    await hoopApi_({ action: "setOrgReady", orgId, ready });
    const reg = (window._adminOrgRegistry || []).find(o => o.orgId === orgId); if (reg) reg.ready = ready;
    if (typeof _wiz !== "undefined" && _wiz && _wiz.orgId === orgId && _wiz.org) _wiz.org.ready = ready;
    showToast(ready ? `${name} is open for orders.` : `${name} now shows “Coming soon”.`);
  } catch (e) { showToast(e.message || "Couldn't change it.", true); }
  drawShopBar_();
}
function drawShopBar_(){
  const app = document.getElementById("app");
  // No bar on a page whose feature is switched off (OpenDecoDesk): it shows the turned-off panel and asks the server nothing.
  const ctx = (adminOrgs && adminKey && !adminPending && adminPageOn_(location.hash)) ? shopBarContext_() : null;
  document.body.classList.toggle("shop-mgmt", !!ctx);
  let bar = document.getElementById("shopBar");
  if (!ctx) { if (bar) bar.remove(); return; }
  if (!bar && app) {
    bar = document.createElement("nav");
    bar.id = "shopBar";
    bar.setAttribute("aria-label", "Shop");
    app.parentNode.insertBefore(bar, app);
  }
  if (!bar) return;
  window._shopBarCtx = ctx;
  bar.innerHTML = shopBarHtml_(ctx);
  if (ctx.shop && adminCan_("manager")) loadShopBarData_().then(() => {
    const now = document.getElementById("shopBar");
    if (now && window._shopBarCtx === ctx) now.innerHTML = shopBarHtml_(ctx);
  });
}
// Picking a shop opens the same page for it (a catalog-wide list opens the shop's products).
function shopBarPick_(orgId){
  if (!orgId) return;
  const ctx = window._shopBarCtx || { page: "products" };
  const page = ["setup", "products", "edit", "designs", "graphics"].includes(ctx.page) ? ctx.page : (adminCan_("manager") ? "products" : "designs");
  location.hash = "#" + shopBarHash_(page, orgId);
}
async function shopBarPublish_(orgId){
  const name = ((adminOrgs || []).find(o => o.orgId === orgId) || {}).name || orgId;
  if (!(await askConfirm_(`Publish ${name}?\n\nShoppers see the shop's current products and settings, and new orders are priced from them.`, { confirmLabel: "Publish" }))) return;
  try {
    const r = await hoopApi_({ action: "publish", org: orgId });
    window._publishState = r.publishState || window._publishState;
    if (r.publishState) window._shopBarData.publish = r.publishState;
    showToast(`Published — shoppers see ${name} as it is now.`);
    if (typeof drawPublishStates_ === "function") drawPublishStates_();
  } catch (e) { showToast(e.message || "Could not publish.", true); }
  await loadShopBarData_(true);
  drawShopBar_();
}

// Discard unpublished changes: shows what goes back to the published version (and which products added since are
// deleted, or hidden when an order already uses them), asks, then does it and reopens the page.
async function shopBarDiscard_(orgId){
  const name = ((adminOrgs || []).find(o => o.orgId === orgId) || {}).name || orgId;
  let plan;
  try { plan = (await hoopApi_({ action: "previewDiscardShopChanges", org: orgId })).plan; } catch (e) { showToast(e.message, true); return; }
  if (!plan.anything) { showToast("Nothing to discard — the shop is as it was published."); return; }
  const when = plan.publishedAt ? new Date(plan.publishedAt).toLocaleString() : "";
  const li = (x) => `<li>${x}</li>`;
  const fields = (f) => f.length ? ` <span style="color:#666;">(${escapeHtml(f.slice(0, 6).join(", "))}${f.length > 6 ? ` +${f.length - 6}` : ""})</span>` : "";
  const parts = [];
  if (plan.shopChanged) parts.push(li(`<b>Shop settings</b> go back${fields(plan.shopFields)}`));
  plan.restore.forEach(r => parts.push(li(`<b>${escapeHtml(r.name)}</b> goes back as published${fields(r.fields)}`)));
  plan.missing.forEach(r => parts.push(li(`<b>${escapeHtml(r.name)}</b> is put back`)));
  plan.added.forEach(a => parts.push(li(a.history ? `<b>${escapeHtml(a.name)}</b> was added since — it's already on an order, so it's <b>hidden</b>, not deleted`
    : `<b>${escapeHtml(a.name)}</b> was added since and is <b>deleted</b> (with its blank links, designs and mockups)`)));
  const { ov, close } = inventoryModal_(`Discard unpublished changes — ${escapeHtml(name)}`, `
    <div style="font-size:13px;line-height:1.5;">
      <p style="margin:0 0 8px;">Puts the shop back the way it was last published${when ? ` (${escapeHtml(when)})` : ""} — what shoppers see now. This can't be undone.</p>
      <ul class="discard-list" style="margin:0 0 8px 18px;padding:0;">${parts.join("")}</ul>
      <p style="margin:0;color:#666;font-size:12px;">Graphics, transfers, decoration locations, blank links, designs and option prices aren't part of a publish (they're always live), so they're left as they are.</p>
    </div>
    <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:14px;">
      <button type="button" class="admin-btn" id="dcKeep" style="background:#fff;color:var(--ink,#222);border:1px solid #ccc;">Keep my changes</button>
      <button type="button" class="admin-btn admin-btn-danger admin-btn-danger-solid" id="dcGo">Discard changes</button></div>`, 640);
  ov.querySelector("#dcKeep").onclick = close;
  ov.querySelector("#dcGo").onclick = async () => {
    const btn = ov.querySelector("#dcGo"); btn.disabled = true;
    try {
      const r = await hoopApi_({ action: "discardShopChanges", org: orgId });
      close();
      if (r.publishState) { window._publishState = r.publishState; window._shopBarData.publish = r.publishState; }
      showToast(`${name} is back to its published version` + (r.deleted.length ? ` — ${r.deleted.length} new product${r.deleted.length === 1 ? "" : "s"} deleted` : "") + (r.hidden.length ? `, ${r.hidden.length} hidden` : "") + ".");
      window._prodFormDirty = false;
      const gone = r.deleted.find(d => location.hash.includes("/products/" + encodeURIComponent(d.productId)));
      if (gone) location.hash = "#catalog/orgs/" + encodeURIComponent(orgId) + "/products"; else adminRoute();
    } catch (e) { btn.disabled = false; showToast(e.message, true); }
  };
}

// The orders screen hides completed orders (delivered + paid in full, then closed out) and
// cancelled orders (voided, or every item cancelled) unless their "Include …" box is ticked;
// every total, count and export follows what's in the view.
window._orderView = window._orderView || { includeCompleted: false, includeCancelled: false };
function isCancelledOrder_(o){
  return !!o.voidedAt || !(o.items || []).some(it => !it.cancelDate);
}
function orderViewFilter_(orders){
  return orders.filter(o => (window._orderView.includeCompleted || !o.completedAt) &&
    (window._orderView.includeCancelled || !isCancelledOrder_(o)));
}
function toggleIncludeCompleted(orgId, on){
  window._orderView.includeCompleted = !!on;
  selectAdminOrg(orgId);
}
function toggleIncludeCancelled(orgId, on){
  window._orderView.includeCancelled = !!on;
  selectAdminOrg(orgId);
}
// Delivered, paid in full, not voided, something still active, not already completed.
function canCompleteOrder(o){
  return !!o && !o.voidedAt && !o.completedAt && !!o.deliveredAt && !!o.paid && (o.items || []).some(it => !it.cancelDate);
}
// Close out (or reopen) orders, then repaint the list — completed ones drop out of the default view.
async function completeOrders(orgId, orderIds, completed){
  if(!adminKey) adminKey = (await adminLogin()) || "";
  if(!adminKey) return false;
  try{
    const res = await fetch("/api/orders", { method: "POST", headers: {"Content-Type": "application/json"},
      body: JSON.stringify({ action: "setOrderCompleted", org: orgId, orderIds, completed, key: adminKey }) });
    const d = await res.json();
    if(!res.ok || d.status === "error"){
      if(d && d.message === "Unauthorized") clearAdminAuth();
      showToast("Could not update: " + ((d && d.message) || "unknown error"), true);
      return false;
    }
    const word = completed ? "Completed" : "Reopened";
    const skipped = (d.skipped || []).map(x => x.orderId + " (" + x.reason + ")");
    showToast(`${word} ${d.updated} order${d.updated === 1 ? "" : "s"}` + (skipped.length ? ` — skipped ${skipped.join(", ")}` : "") + ".", !d.updated && skipped.length > 0);
    const orgObj = (adminOrgs || []).find(x => x.orgId === orgId);
    if(orgObj) refreshOrdersInPlace_(orgObj);
    return true;
  }catch(e){ showToast("Could not reach the server.", true); return false; }
}
// After orders are set to delivered: offer to complete the ones that can be (paid in full).
async function offerToComplete(orgId, orderIds){
  const cache = (window._ordersCache && window._ordersCache[orgId]) || [];
  const delivered = orderIds.map(id => cache.find(o => o.orderId === id)).filter(o => o && o.deliveredAt && !o.completedAt && !o.voidedAt);
  const ready = delivered.filter(canCompleteOrder);
  const waiting = delivered.filter(o => !canCompleteOrder(o));
  if(ready.length){
    const names = ready.slice(0, 6).map(o => o.orderId).join(", ") + (ready.length > 6 ? ", +" + (ready.length - 6) + " more" : "");
    if(await askConfirm_(`Mark ${ready.length} delivered order${ready.length === 1 ? "" : "s"} as completed?\n\n${names}\n\nPaid in full. Completed orders are hidden from this list unless "Include completed" is ticked (you can reopen them).`)){
      await completeOrders(orgId, ready.map(o => o.orderId), true);
      return;
    }
  }
  if(waiting.length) showToast(`${waiting.length} delivered order${waiting.length === 1 ? "" : "s"} can't be completed yet — a balance is still due.`);
}

