// Bulk selection helpers — called by the checkbox column in the orders table.
function toggleSelectAllOrders(cb){
  const checkboxes = document.querySelectorAll(".order-select");
  const orgId = checkboxes.length ? checkboxes[0].dataset.org : null;
  checkboxes.forEach(c => { c.checked = cb.checked; });
  if(orgId) updateBulkBar(orgId);
}

function updateBulkBar(orgId){
  const bar = document.getElementById("bulkBar");
  if(!bar) return;
  const checked = Array.from(document.querySelectorAll(".order-select:checked"));
  const all     = document.querySelectorAll(".order-select");
  const selectAll = document.getElementById("selectAllOrders");
  if(selectAll){
    selectAll.indeterminate = checked.length > 0 && checked.length < all.length;
    selectAll.checked = all.length > 0 && checked.length === all.length;
  }
  if(checked.length === 0){ bar.style.display = "none"; return; }
  bar.style.display = "";
  const countEl = document.getElementById("bulkBarCount");
  if(countEl) countEl.textContent = checked.length + " order" + (checked.length === 1 ? "" : "s") + " selected";
}

function clearBulkSelection(){
  document.querySelectorAll(".order-select").forEach(c => { c.checked = false; });
  const selectAll = document.getElementById("selectAllOrders");
  if(selectAll){ selectAll.checked = false; selectAll.indeterminate = false; }
  const bar = document.getElementById("bulkBar");
  if(bar) bar.style.display = "none";
}

async function bulkSetFulfillmentStage(orgId, stage){
  const checked = Array.from(document.querySelectorAll(".order-select:checked"));
  if(!checked.length){ showToast("No orders selected.", true); return; }
  const orderIds = checked.map(c => c.dataset.order);
  const stageLabels = { blankOrdered:"blank ordered", blankShipped:"blank shipped", blankReceived:"blank received", manufactured:"manufactured", digitizingComplete:"digitizing complete", designApproved:"design approved", qaPacked:"QA and packed", shipped:"shipped", delivered:"delivered" };
  const label = stageLabels[stage] || stage;

  let extraFields = {};
  if(stage === "blankOrdered"){
    const details = await showBlankOrderModal("Mark " + orderIds.length + " order" + (orderIds.length === 1 ? "" : "s") + " as blank ordered");
    if(!details) return;
    extraFields = details;
  } else if(stage === "blankShipped"){
    const cache = (window._ordersCache && window._ordersCache[orgId]) || [];
    const ordersForModal = orderIds.map(id => cache.find(o => o.orderId === id)).filter(Boolean);
    await blankShippedFlow_(orgId, ordersForModal);
    return;
  } else if(stage === "blankReceived"){
    const cache = (window._ordersCache && window._ordersCache[orgId]) || [];
    const ordersForModal = orderIds.map(id => cache.find(o => o.orderId === id)).filter(Boolean);
    const details = await showBlankReceiveModal("Receiving blanks for " + orderIds.length + " order" + (orderIds.length === 1 ? "" : "s"), ordersForModal);
    if(!details) return;
    extraFields = details;
  } else if(stage === "shipped"){
    const tn = await showTrackingModal("Mark " + orderIds.length + " order" + (orderIds.length === 1 ? "" : "s") + " as shipped", { required: false, submitLabel: "Mark shipped" });
    if(tn === undefined) return; // cancelled
    if(tn) extraFields = { trackingNumber: tn };
  } else {
    if(!await askConfirm_("Mark " + orderIds.length + " order" + (orderIds.length === 1 ? "" : "s") + " as " + label + "?")) return;
  }

  if(!adminKey) adminKey = (await adminLogin()) || "";
  if(!adminKey) return;
  try{
    const res = await fetch("/api/orders", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({action: "bulkSetFulfillmentStage", org: orgId, orderIds, stage, ...extraFields, key: adminKey})
    });
    const data = await res.json();
    if(!res.ok || data.status === "error"){
      if(data && data.message === "Unauthorized") clearAdminAuth();
      showToast("Bulk update failed: " + ((data && data.message) || "unknown error"), true);
      return;
    }
    let msg = "Updated " + data.updated;
    if(data.skipped) msg += ", " + data.skipped + " already set";
    if(data.errors && data.errors.length) msg += ", " + data.errors.length + " error" + (data.errors.length === 1 ? "" : "s");
    showToast(msg + ".");
    const orgObj = (adminOrgs || []).find(x => x.orgId === orgId);
    // Blank stages are per-line-item now (migrations/0039) + roll up to order summaries, so re-fetch
    // rather than patching cells in place (a partial receive mustn't flip the whole-order cell).
    if(/^blank/.test(stage)){ if(orgObj) refreshOrdersInPlace_(orgObj); return; }
    if(orgObj){
      const errorIds = new Set((data.errors || []).map(e => e.orderId));
      const byRow = {};
      if(stage === "blankReceived" && Array.isArray(extraFields.itemConditions)){
        extraFields.itemConditions.forEach(ic => { byRow[ic.sheetRow] = ic; });
      }
      let anyMiss = false;
      for(const id of orderIds){
        if(errorIds.has(id)) continue;
        const updates = { [FULFILLMENT_FIELD[stage]]: data.timestamp || new Date().toISOString() };
        if(stage === "shipped" && extraFields.trackingNumber) updates.trackingNumber = extraFields.trackingNumber;
        if(stage === "blankReceived"){
          updates.blankCondition = extraFields.condition || "Good";
          updates.blankConditionNote = extraFields.blankConditionNote || "";
          if(Object.keys(byRow).length){
            const o = (window._ordersCache && window._ordersCache[orgId] || []).find(x => x.orderId === id);
            if(o) (o.items || []).forEach(it => {
              const ic = byRow[it.sheetRow];
              if(ic){ it.blankCondition = ic.condition; it.blankConditionNote = ic.note || ""; }
            });
          }
        }
        if(!applyOrderUpdate(orgId, id, updates, orgObj)) anyMiss = true;
      }
      if(anyMiss) refreshOrdersInPlace_(orgObj);
      if(stage === "delivered") await offerToComplete(orgId, orderIds.filter(id => !errorIds.has(id)));
    }
  }catch(e){
    showToast("Could not reach the server.", true);
  }
}

// Cancel all non-cancelled, non-late-cancel items across the selected orders
// in one request, with a single shared reason. Sends one cancellation email
// per affected order (handled server-side by the bulkCancelLineItems action).
async function bulkCancelLineItems(orgId){
  const checked = Array.from(document.querySelectorAll(".order-select:checked"));
  if(!checked.length){ showToast("No orders selected.", true); return; }
  const orderIds = checked.map(c => c.dataset.order);
  const orders = (window._ordersCache && window._ordersCache[orgId]) || [];
  const sheetRows = [];
  orderIds.forEach(orderId => {
    const o = orders.find(o => o.orderId === orderId);
    if(o) o.items.forEach(it => { if(!it.cancelDate && !o.blankOrderedAt) sheetRows.push(Number(it.sheetRow)); });
  });
  if(!sheetRows.length){ showToast("No cancellable items in selection (blank already ordered or all already cancelled).", true); return; }
  const ans = await confirmModal_({ title: "Cancel " + sheetRows.length + " item" + (sheetRows.length === 1 ? "" : "s") + "?",
    text: "Across " + orderIds.length + " order" + (orderIds.length === 1 ? "" : "s") + ". Customers are told by email. This can't be undone.",
    reason: "optional", reasonLabel: "Reason (applies to all, optional)", confirmLabel: "Cancel items", cancelLabel: "Keep them", danger: true });
  if(!ans.ok) return;
  const reason = ans.reason;
  if(!adminKey) adminKey = (await adminLogin()) || "";
  if(!adminKey) return;
  try{
    const res = await fetch("/api/orders", {
      method: "POST",
      headers: {"Content-Type":"application/json"},
      body: JSON.stringify({action:"bulkCancelLineItems", org:orgId, sheetRows, reason: reason||"", key:adminKey})
    });
    const data = await res.json();
    if(!res.ok || data.status === "error"){
      if(data && data.message === "Unauthorized") clearAdminAuth();
      showToast("Bulk cancel failed: " + ((data && data.message) || "unknown error"), true);
      return;
    }
    const results = data.results || [];
    const cancelled = results.filter(r => r.status === "ok" && !r.alreadyCanceled).length;
    const lateCancels = results.filter(r => r.lateCancel).length;
    let msg = "Cancelled " + cancelled + " item(s).";
    if(lateCancels) msg += " ⚠ " + lateCancels + " late cancel(s) — manual reconciliation needed.";
    showToast(msg, lateCancels > 0);
    const org = (adminOrgs || []).find(o => o.orgId === orgId);
    if(org) refreshOrdersInPlace_(org);
  }catch(e){
    showToast("Could not reach the server.", true);
  }
}

// Adds a tracking number to all selected orders in bulk.
// Shows the design verification compose modal.
// Returns {message, imageUrls} or null on cancel.
function showDesignVerifModal(){
  return new Promise(function(resolve){
    // The desktop program: the pictures are attached to the email and the customer replies to it (no
    // page to open); marking the order Design approved records their approval.
    const desktop = adminDesktop_();
    const { ov, close } = inventoryModal_("Send design verification", `
          ${desktop ? `<div class="admin-note" style="margin:0 0 10px;">The pictures are attached to the email, and the customer replies to approve or ask for changes. When they approve, mark the order <strong>Design approved</strong>.</div>` : ""}
          <label style="display:block;margin-bottom:4px;font-size:13px;font-weight:600;color:#1a1a1a;">Message to customer <span style="color:#b03a2e">*</span></label>
          <textarea id="dvMessage" rows="5" placeholder="Please review the design below and let us know if you approve or have any changes." style="width:100%;box-sizing:border-box;padding:8px;border:1px solid #ccc;border-radius:4px;font-size:14px;font-family:inherit;color:#1a1a1a;resize:vertical;"></textarea>
          <div style="margin-top:14px;font-size:13px;font-weight:600;color:#1a1a1a;margin-bottom:6px;">${desktop ? "Design images (upload them; at most 15 MB in all)" : "Design images (optional — paste https:// URLs or upload)"}</div>
          ${[1,2,3].map(i => `
            <div style="display:flex;align-items:center;gap:6px;margin-bottom:6px;">
              <input type="text" id="dvImg${i}" placeholder="https://..." style="flex:1;padding:6px 8px;border:1px solid #ccc;border-radius:4px;font-size:13px;color:#1a1a1a;">
              <label style="cursor:pointer;font-size:12px;padding:5px 10px;background:#e5e7eb;border-radius:4px;white-space:nowrap;color:#1a1a1a;">
                Upload <input type="file" accept="image/jpeg,image/png,image/webp,image/gif,image/heic,image/heif,.heic,.heif" style="display:none;" data-target="dvImg${i}" onchange="handleDvImageUpload(this)">
              </label>
              <span id="dvImg${i}Status" style="font-size:11px;color:#555;min-width:60px;"></span>
            </div>`).join("")}
          <div id="dvError" style="color:#b03a2e;font-size:13px;min-height:18px;margin-top:4px;"></div>
          <div style="display:flex;gap:10px;justify-content:flex-end;margin-top:18px;">
            <button type="button" id="dvCancel" class="admin-btn admin-btn-secondary">Cancel</button>
            <button type="button" id="dvSend" class="admin-btn">Send</button>
          </div>`, 540, { onClose: () => resolve(null) });
    const cancel = () => { close(); resolve(null); };
    ov.querySelector("#dvCancel").onclick = cancel;
    ov.querySelector("#dvSend").onclick = function(){
      const message = ov.querySelector("#dvMessage").value.trim();
      if(!message){ ov.querySelector("#dvError").textContent = "Message is required."; return; }
      const imageUrls = [1,2,3].map(i => ov.querySelector("#dvImg"+i).value.trim()).filter(Boolean);
      if(!imageUrls.length){ ov.querySelector("#dvError").textContent = "At least one design image is required."; return; }
      close();
      resolve({message, imageUrls});
    };
    ov.querySelector("#dvMessage").focus();
  });
}

window.handleDvImageUpload = async function(input){
  const targetId = input.dataset.target;
  const statusEl = document.getElementById(targetId + "Status");
  const file = input.files && input.files[0];
  if(!file) return;
  statusEl.textContent = "Uploading…";
  try{
    const url = await uploadImage(file, "verify");
    document.getElementById(targetId).value = url;
    statusEl.textContent = "✓";
  }catch(e){
    statusEl.textContent = "Failed";
  }
};

async function bulkSendDesignVerification(orgId){
  const checked = Array.from(document.querySelectorAll(".order-select:checked"));
  if(!checked.length){ showToast("No orders selected.", true); return; }
  const orderIds = checked.map(c => c.dataset.order);

  const modal = await showDesignVerifModal();
  if(!modal) return;

  const errEl = document.createElement("div");
  try{
    const res = await fetch("/api/orders", {
      method: "POST", headers: {"Content-Type":"application/json"},
      body: JSON.stringify({
        action: "sendDesignVerification",
        key: adminKey,
        org: orgId,
        orderIds,
        message: modal.message,
        imageUrls: modal.imageUrls,
      })
    });
    const data = await res.json();
    if(!res.ok || data.status === "error"){
      showToast("Error: " + ((data && data.message) || "Unknown error"), true);
      return;
    }
    const reasons = (data.skippedReasons || []).join("; ");
    const skippedNote = data.skipped ? ` (${data.skipped} skipped — ${reasons || "no email address on file"})` : "";
    showToast(`✓ Verification email sent to ${data.sent} order${data.sent===1?"":"s"}${skippedNote}.`, !!data.skipped && !data.sent);
    clearBulkSelection();
  }catch(e){
    showToast("Network error — could not send verification emails.", true);
  }
}

