// ---- Revenue Report ----------------------------------------------------------
async function renderRevenueReport(app) {
  adminSetHash("revenue");
  document.title = adminTitle_("Revenue report");

  const thisYear  = new Date().getFullYear();
  const defaultFrom = thisYear + "-01-01";
  const defaultTo   = new Date().toISOString().slice(0, 10);

  app.innerHTML = `
    <div class="org-hero admin-hero" style="--org-accent:var(--accent);">
            <h1 class="org-name">Revenue Report</h1>
    </div>
    <div class="admin-panel" style="--org-accent:var(--accent);max-width:900px;margin:8px auto 60px;">
      <form id="revFilters" style="display:flex;flex-wrap:wrap;gap:10px;align-items:flex-end;background:var(--surface-alt,#f6f6f6);padding:14px 16px;border-radius:8px;margin-bottom:20px;">
        <div>
          <label style="font-size:12px;font-weight:600;display:block;margin-bottom:3px;">From</label>
          <input type="date" id="revFrom" value="${defaultFrom}"
                 style="font-size:13px;padding:5px 8px;border:1px solid #ccc;border-radius:4px;background:var(--surface,#fff);color:var(--ink,#111);">
        </div>
        <div>
          <label style="font-size:12px;font-weight:600;display:block;margin-bottom:3px;">To</label>
          <input type="date" id="revTo" value="${defaultTo}"
                 style="font-size:13px;padding:5px 8px;border:1px solid #ccc;border-radius:4px;background:var(--surface,#fff);color:var(--ink,#111);">
        </div>
        <div>
          <label style="font-size:12px;font-weight:600;display:block;margin-bottom:3px;">Basis</label>
          <select id="revBasis" style="font-size:13px;padding:5px 8px;border:1px solid #ccc;border-radius:4px;background:var(--surface,#fff);color:var(--ink,#111);"
                  title="Accrual: sales by the date the order was placed. Cash: money actually received / refunded by the date it moved.">
            <option value="accrual">Accrual (orders placed)</option>
            <option value="cash">Cash (money received)</option>
          </select>
        </div>
        <div style="display:flex;gap:6px;align-self:flex-end;">
          <button type="submit" class="admin-pass-submit" style="padding:6px 18px;font-size:13px;">Generate</button>
          ${[thisYear, thisYear-1].map(y =>
            `<button type="button" style="padding:6px 12px;font-size:12px;border:1px solid #ccc;border-radius:4px;cursor:pointer;background:var(--surface,#fff);"
              onclick="document.getElementById('revFrom').value='${y}-01-01';document.getElementById('revTo').value='${y}-12-31';document.getElementById('revFilters').dispatchEvent(new Event('submit'));">${y}</button>`
          ).join("")}
        </div>
      </form>

      <div id="revResults"></div>
    </div>
  `;

  function fmt(n) { return "$" + Number(n).toFixed(2); }

  // Cash basis: what actually came in / went back out, by the date it moved.
  function renderCashTable(d) {
    const th = "padding:9px 14px;text-align:right;background:#f0f0f0;color:#333;font-size:12px;font-weight:700;border-bottom:2px solid #ccc;";
    const td = "padding:10px 14px;text-align:right;border-bottom:1px solid #ddd;color:#111;background:#fff;";
    const ft = "padding:10px 14px;text-align:right;background:#f0f0f0;color:#111;font-weight:700;border-top:2px solid #aaa;";
    const LABEL = { card: "Card (Stripe)", venmo: "Venmo", zelle: "Zelle", check: "Check", cash: "Cash", other: "Other" };
    const t = d.total;
    return `
      <div style="font-size:13px;color:#555;margin-bottom:10px;">Money received and refunded between ${escapeHtml(new Date(d.dateFrom + "T12:00:00").toLocaleDateString())} and ${escapeHtml(new Date(d.dateTo + "T12:00:00").toLocaleDateString())}, by the date it moved. Voided entries and test orders excluded.</div>
      <div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;margin-bottom:16px;"><table style="width:100%;border-collapse:collapse;font-size:14px;">
        <thead><tr><th style="${th}text-align:left;">Shop</th><th style="${th}">Payments</th><th style="${th}">Received</th><th style="${th}">Refunded</th><th style="${th}">Stripe fees</th><th style="${th}">Net received</th></tr></thead>
        <tbody>${d.orgs.map(o => `<tr><td style="${td}text-align:left;font-weight:600;">${escapeHtml(o.name)}</td><td style="${td}">${o.payments}</td><td style="${td}">${fmt(o.received)}</td><td style="${td}">${o.refunded > 0 ? "−" + fmt(o.refunded) : "—"}</td><td style="${td}">${o.fees > 0 ? fmt(o.fees) : "—"}</td><td style="${td}font-weight:600;">${fmt(o.net)}</td></tr>`).join("")
          || `<tr><td colspan="6" style="${td}text-align:left;color:#888;">No money moved in this period.</td></tr>`}</tbody>
        <tfoot><tr><td style="${ft}text-align:left;" colspan="2">Total</td><td style="${ft}">${fmt(t.received)}</td><td style="${ft}">${t.refunded > 0 ? "−" + fmt(t.refunded) : "—"}</td><td style="${ft}">${fmt(t.fees)}</td><td style="${ft}">${fmt(t.net)}</td></tr></tfoot>
      </table></div>
      <h3 style="margin:0 0 8px;font-size:15px;">By payment method</h3>
      <div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;"><table style="width:100%;border-collapse:collapse;font-size:14px;">
        <thead><tr><th style="${th}text-align:left;">Method</th><th style="${th}">Received</th><th style="${th}">Refunded</th><th style="${th}">Net</th></tr></thead>
        <tbody>${d.methods.map(m => `<tr><td style="${td}text-align:left;">${escapeHtml(LABEL[m.method] || m.method)}</td><td style="${td}">${fmt(m.received)}</td><td style="${td}">${m.refunded > 0 ? "−" + fmt(m.refunded) : "—"}</td><td style="${td}">${fmt(m.net)}</td></tr>`).join("")}</tbody>
      </table></div>
      ${d.otherIncome && (d.otherIncome.service || d.otherIncome.other || d.otherIncome.interest) ? `<h3 style="margin:18px 0 8px;font-size:15px;">Other income (Accounts &amp; money)</h3>
      <div style="font-size:14px;">Services (Schedule C line 1): <strong>${fmt(d.otherIncome.service)}</strong> · Other business income (line 6): <strong>${fmt(d.otherIncome.other)}</strong> · Interest (Schedule B): <strong>${fmt(d.otherIncome.interest)}</strong></div>` : ""}
      ${d.testCardCharges > 0 ? `<div style="font-size:13px;color:#555;margin-top:10px;">Also charged on Stripe but excluded above: <strong>${fmt(d.testCardCharges)}</strong> in test transactions. They appear on the Stripe 1099-K, so include them when reconciling it.</div>` : ""}`;
  }

  function renderTable(data) {
    const { orgs, total, dateFrom, dateTo } = data;
    const cell  = "padding:10px 14px;text-align:right;border-bottom:1px solid #ddd;color:#111;background:#fff;";
    const cellL = "padding:10px 14px;text-align:left;border-bottom:1px solid #ddd;color:#111;background:#fff;";
    const th    = "padding:9px 14px;text-align:right;background:#f0f0f0;color:#333;font-size:12px;font-weight:700;white-space:nowrap;border-bottom:2px solid #ccc;";
    const thL   = "padding:9px 14px;text-align:left;background:#f0f0f0;color:#333;font-size:12px;font-weight:700;border-bottom:2px solid #ccc;";
    const foot  = "padding:10px 14px;text-align:right;background:#f0f0f0;color:#111;font-weight:700;border-top:2px solid #aaa;";
    const footL = "padding:10px 14px;text-align:left;background:#f0f0f0;color:#111;font-weight:700;border-top:2px solid #aaa;font-size:15px;";
    const dLabel = `${new Date(dateFrom + "T12:00:00").toLocaleDateString()} – ${new Date(dateTo + "T12:00:00").toLocaleDateString()}`;
    return `
      <div style="font-size:13px;color:#555;margin-bottom:10px;">${dLabel}</div>
      <div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;">
        <table style="width:100%;border-collapse:collapse;font-size:14px;">
          <thead>
            <tr>
              <th style="${thL}">Shop</th>
              <th style="${th}">Orders</th>
              <th style="${th}">Subtotal</th>
              <th style="${th}">Discounts</th>
              <th style="${th}">Shipping</th>
              <th style="${th}">Total</th>
              <th style="${th}" title="Money received for these orders, less anything refunded">Received (net of refunds)</th>
              <th style="${th}">Balance Due</th>
            </tr>
          </thead>
          <tbody>
            ${orgs.map(o => `<tr style="${o.orderCount===0?"opacity:0.5;":""}">
                <td style="${cellL}font-weight:${o.orderCount>0?"600":"400"};">${escapeHtml(o.name)}</td>
                <td style="${cell}">${o.orderCount || "—"}</td>
                <td style="${cell}">${o.subtotal > 0 ? fmt(o.subtotal) : "—"}</td>
                <td style="${cell}">${o.discounts > 0 ? "−"+fmt(o.discounts) : "—"}</td>
                <td style="${cell}">${o.shipping > 0 ? fmt(o.shipping) : "—"}</td>
                <td style="${cell}font-weight:600;">${o.effectiveTotal > 0 ? fmt(o.effectiveTotal) : "—"}</td>
                <td style="${cell}">${o.received > 0 ? fmt(o.received) : "—"}</td>
                <td style="${cell}font-weight:600;color:${o.balance>0.005?"#b03a2e":"#111"};">${o.balance > 0.005 ? fmt(o.balance) : "—"}</td>
              </tr>`).join("")}
          </tbody>
          <tfoot>
            <tr>
              <td style="${footL}">Total</td>
              <td style="${foot}">${total.orderCount}</td>
              <td style="${foot}">${fmt(total.subtotal)}</td>
              <td style="${foot}">${total.discounts > 0 ? "−"+fmt(total.discounts) : "—"}</td>
              <td style="${foot}">${total.shipping > 0 ? fmt(total.shipping) : "—"}</td>
              <td style="${foot}font-size:15px;">${fmt(total.effectiveTotal)}</td>
              <td style="${foot}">${fmt(total.received)}</td>
              <td style="${foot}color:${total.balance>0.005?"#b03a2e":"#111"};">${total.balance > 0.005 ? fmt(total.balance) : "—"}</td>
            </tr>
          </tfoot>
        </table>
      </div>
    `;
  }

  async function loadReport() {
    const resultsEl = document.getElementById("revResults");
    if (!resultsEl) return;
    resultsEl.innerHTML = `<div style="color:#888;font-size:14px;padding:20px 0;">Loading…</div>`;

    if (!adminKey) adminKey = (await adminLogin()) || "";
    if (!adminKey) return;

    const dateFrom = document.getElementById("revFrom")?.value;
    const dateTo   = document.getElementById("revTo")?.value;
    if (!dateFrom || !dateTo) return;

    try {
      const r = await fetch("/api/orders", {
        method: "POST", headers: {"Content-Type":"application/json"},
        body: JSON.stringify({ action: "getRevenueReport", key: adminKey, dateFrom, dateTo,
          basis: (document.getElementById("revBasis") || {}).value || "accrual" }),
      });
      const d = await r.json();
      if (!r.ok || d.status === "error") {
        resultsEl.innerHTML = `<div style="color:#b03a2e;font-size:14px;padding:20px 0;">${escapeHtml((d && d.message) || "Error loading report.")}</div>`;
        return;
      }
      resultsEl.innerHTML = d.basis === "cash" ? renderCashTable(d) : renderTable(d);
    } catch (err) {
      resultsEl.innerHTML = `<div style="color:#b03a2e;font-size:14px;padding:20px 0;">Network error.</div>`;
    }
  }

  document.getElementById("revFilters").addEventListener("submit", (e) => { e.preventDefault(); loadReport(); });
  loadReport();
}

