  "order.marked_paid":        "Marked paid",
  "order.date_changed":       "Date changed",
  "order.deleted":            "Order deleted",
  "order.voided":             "Order voided",
  "payment.voided":           "Payment voided",
  "payment.refunded":         "Refund recorded",
  "period.closed":            "Month closed",
  "period.reopened":          "Month reopened",
  "inventory.received":       "Blanks received",
  "inventory.written_off":    "Blanks written off",
  "inventory.movement_voided":   "Stock entry voided",
  "inventory.movement_restored": "Stock entry restored (void undone)",
  "transfer.movement_voided":    "Transfer entry voided",
  "transfer.movement_restored":  "Transfer entry restored (void undone)",
  "settings.sales_tax_set":   "Sales tax rate set",
  "org.tax_exemption_set":    "Tax exemption set",
  "report.accountant_export": "Accountant export",
  "payments.stripe_fees_backfilled": "Stripe fees backfilled",
  "order.discount_set":       "Discount set",
  "order.customer_updated":   "Customer info updated",
  "order.created_local_sale": "Local sale created",
  "order.fulfillment_stage":  "Fulfillment stage",
  "order.bulk_fulfillment_stage": "Bulk fulfillment stage",
  "order.edited":             "Order edited",
  "order.tracking_set":       "Tracking set",
  "order.bulk_tracking_set":  "Bulk tracking set",
  "order.shipping_set":       "Shipping set",
  "payment.added":            "Payment added",
  "payment.deleted":          "Payment deleted",
  "item.cancelled":           "Item cancelled",
  "item.bulk_cancelled":      "Bulk items cancelled",
  "item.refund_set":          "Refund set",
  "org.created":              "Shop created",
  "org.updated":              "Shop edited",
  "product.created":          "Product created",
  "product.updated":          "Product edited",
  "product.hidden":           "Product hidden",
  "product.shown":            "Product shown",
