// ---- Free shipping per vendor + "Get me to free shipping" (2026-10) ----
// A vendor ships free over a dollar amount (SanMar, S&S: $200) or at a piece count — kept per vendor
// NAME (the blank's Vendor field), so it works with or without a vendor connection (setVendorShipping in db.js).
const fsDollars_ = (cents) => "$" + (Number(cents) % 100 ? (Number(cents) / 100).toFixed(2) : String(Number(cents) / 100));
function freeShipText_(fs){
  if (!fs) return "";
  return [fs.overCents ? `at ${fsDollars_(fs.overCents)}` : "", fs.minQty ? `at ${fs.minQty} pieces` : ""].filter(Boolean).join(" or ");
}
// How far an order (cents at the supplier's price, pieces) is from free shipping: {met, toGoCents, toGoPieces, label}.
function freeShipProgress_(fs, cents, pieces){
  if (!fs) return null;
  if ((fs.overCents && cents >= fs.overCents) || (fs.minQty && pieces >= fs.minQty)) return { met: true, toGoCents: 0, toGoPieces: 0, label: "free shipping" };
  const toGoCents = fs.overCents ? fs.overCents - cents : null, toGoPieces = fs.minQty ? fs.minQty - pieces : null;
  const label = [toGoCents != null ? "$" + (toGoCents / 100).toFixed(2) + " to go" : "", toGoPieces != null ? `${toGoPieces} piece${toGoPieces === 1 ? "" : "s"} to go` : ""].filter(Boolean).join(" or ");
  return { met: false, toGoCents, toGoPieces, label };
}
// A Blanks to Order supplier block's header: its free shipping (✎ to change it) and, when short, the button.
function freeShipHeaderHtml_(s, si){
  const fs = s.freeShipping;
  if (!fs) return `<button type="button" class="bto-fs-edit" data-si="${si}" style="background:none;border:none;color:#2563eb;cursor:pointer;font-size:12px;padding:0;">Set free shipping…</button>`;
  const pr = freeShipProgress_(fs, s.orderCents, s.qty);
  return `<span class="bto-fs" style="font-size:12px;color:${pr.met ? "#166534" : "#92400e"};display:inline-flex;gap:6px;align-items:baseline;flex-wrap:wrap;">
    ${pr.met ? "✓ Free shipping" : `Free shipping ${escapeHtml(freeShipText_(fs))} — ${escapeHtml(pr.label)}`}
    <button type="button" class="bto-fs-edit" data-si="${si}" title="Change ${escapeHtml(s.vendor)}'s free shipping" style="background:none;border:none;color:#2563eb;cursor:pointer;font-size:12px;padding:0;">✎</button>
    ${pr.met ? "" : `<button type="button" class="admin-btn bto-free" data-si="${si}" style="padding:3px 10px;font-size:12px;" title="Add restock and best sellers until this order ships free">Get me to free shipping</button>`}</span>`;
}
// Sets a vendor's free shipping: over $ and/or at N pieces (blank = not that kind); Use default / no free shipping.
function showVendorShippingForm_(vendor, current, onSaved){
  const fs = current || {};
  const { ov, close } = inventoryModal_(`Free shipping — ${escapeHtml(vendor)}`, `
    <div style="font-size:13px;color:#555;margin-bottom:12px;">When an order from ${escapeHtml(vendor)} reaches either amount it ships free. Leave one empty if the vendor doesn't use it (some vendors count pieces, SanMar and S&amp;S dollars).</div>
    <div style="display:flex;gap:16px;flex-wrap:wrap;font-size:13px;">
      <label style="display:flex;flex-direction:column;gap:4px;">Free at ($ or more)<input type="number" id="vsOver" min="0" step="0.01" value="${fs.overCents ? (fs.overCents / 100).toFixed(2) : ""}" placeholder="—" style="width:120px;"></label>
      <label style="display:flex;flex-direction:column;gap:4px;">…or at (pieces)<input type="number" id="vsQty" min="0" step="1" value="${fs.minQty || ""}" placeholder="—" style="width:100px;"></label>
    </div>
    ${fs.isDefault ? `<div style="font-size:12px;color:#888;margin-top:8px;">This is the built-in default for ${escapeHtml(vendor)}.</div>` : ""}
    <div style="display:flex;justify-content:space-between;gap:8px;margin-top:16px;flex-wrap:wrap;">
      <button type="button" class="admin-btn" id="vsReset" style="background:#fff;color:var(--ink,#222);border:1px solid #ccc;" title="Go back to the built-in default (SanMar / S&amp;S $200; none for other vendors)">Use default</button>
      <span style="display:flex;gap:8px;"><button type="button" class="admin-btn" id="vsCancel" style="background:#fff;color:var(--ink,#222);border:1px solid #ccc;">Cancel</button><button type="button" class="admin-btn" id="vsSave">Save</button></span>
    </div>`, 460);
  const save = async (body) => {
    try { const r = await hoopApi_({ action: "setVendorShipping", vendor, ...body }); close(); showToast(r.freeShipping ? `${vendor} ships free ${freeShipText_(r.freeShipping)}.` : `${vendor}: no free shipping.`); onSaved && onSaved(); }
    catch (e) { showToast(e.message || "Couldn't save", true); }
  };
  ov.querySelector("#vsCancel").onclick = close;
  ov.querySelector("#vsReset").onclick = () => save({ reset: true });
  ov.querySelector("#vsSave").onclick = () => save({ over: ov.querySelector("#vsOver").value, minQty: ov.querySelector("#vsQty").value });
}
// Restock orders placed by hand and recorded here (migrations/0074), with Cancel for one that never got ordered.
function restockOrdersHtml_(list){
  if (!list || !list.length) return "";
  const td = "padding:5px 8px;border-top:1px solid #eee;font-size:13px;vertical-align:top;";
  return `<div id="btoRestockOrders" style="margin-top:22px;"><h2 style="margin:0 0 4px;font-size:16px;">Restock ordered by hand</h2>
    <div style="font-size:12px;color:#666;margin-bottom:6px;">Recorded from “Get me to free shipping”, so these blanks aren't suggested again while they're on their way. A line stops counting once that blank is received (or after 45 days).</div>
    <div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;"><table style="width:100%;border-collapse:collapse;"><tbody>
    ${list.map(o => `<tr><td style="${td}white-space:nowrap;">${escapeHtml(String(o.createdAt || "").slice(0, 10))}</td><td style="${td}">${escapeHtml(o.vendor)}${o.reference ? ` · <span style="font-family:'IBM Plex Mono',monospace;font-size:12px;">${escapeHtml(o.reference)}</span>` : ""}</td>
      <td style="${td}">${o.lines.length} line${o.lines.length === 1 ? "" : "s"}, ${o.pieces} piece${o.pieces === 1 ? "" : "s"}${o.waiting ? "" : ` <span style="color:#166534;">· received</span>`}</td>
      <td style="${td}text-align:right;"><button type="button" class="admin-btn bto-rso-cancel admin-btn-danger" data-id="${o.id}" style="padding:2px 8px;font-size:12px;">Cancel</button></td></tr>`).join("")}
    </tbody></table></div></div>`;
}

// What to add to reach free shipping — pure. base = lines already in the order [{blankId, color, size, qty, price}];
// candidates = the vendor's blank sizes (freeShippingSuggestions: price, onHand, reserved, needed, onOrder,
// reorderPoint, used90, used365); fs = {overCents, minQty}. Order of picking:
//   1. sizes below their reorder point: the shortfall;
//   2. still short (or no reorder points set): one piece at a time to the size that sells fastest against what's
//      free — use in the last 90 days (as a yearly rate), else the last year — at most about a year's use per size;
//   3. stop as soon as the order reaches the dollar amount or the piece count.
// Returns {lines: [{...candidate, qty, reason}], cents, pieces, met, noHistory}.
function fillToFreeShipping_(base, candidates, fs){
  const key = (l) => [l.blankId, l.color || "", l.size || ""].join("\u0001");
  const baseQty = new Map();
  for (const l of base || []) baseQty.set(key(l), (baseQty.get(key(l)) || 0) + (Number(l.qty) || 0));
  let cents = (base || []).reduce((t, l) => t + Math.round((Number(l.price) || 0) * 100) * (Number(l.qty) || 0), 0);
  let pieces = (base || []).reduce((n, l) => n + (Number(l.qty) || 0), 0);
  const met = () => !!fs && ((fs.overCents && cents >= fs.overCents) || (fs.minQty && pieces >= fs.minQty));
  const out = new Map();
  const add = (c, n, reason) => {
    const k = key(c), cur = out.get(k);
    if (cur) cur.qty += n; else out.set(k, { ...c, qty: n, reason });
    cents += Math.round((Number(c.price) || 0) * 100) * n; pieces += n;
  };
  // Free after this order: what's on the shelf and not promised, plus what's coming and what's already in the order.
  const freeAfter = (c) => (Number(c.onHand) || 0) - (Number(c.reserved) || 0) - (Number(c.needed) || 0) + (Number(c.onOrder) || 0) + (baseQty.get(key(c)) || 0);
  for (const c of candidates || []) {
    if (c.reorderPoint == null) continue;
    const free = freeAfter(c), short = Number(c.reorderPoint) - free;
    if (short > 0) add(c, short, `Below its reorder point — keep ${c.reorderPoint}, ${Math.max(0, free)} free`);
  }
  // Pieces a year, from the last 90 days when it has sales, else the last year.
  const rate = (c) => (Number(c.used90) || 0) > 0 ? Number(c.used90) * 365 / 90 : (Number(c.used365) || 0);
  const pool = (candidates || []).filter(c => !c.forTesting && rate(c) > 0 && !(fs && fs.overCents && !fs.minQty && !(Number(c.price) > 0)));
  const noHistory = !pool.length;
  for (let guard = 0; guard < 5000 && fs && !met(); guard++) {
    let best = null, bestScore = 0;
    for (const c of pool) {
      const have = Math.max(0, freeAfter(c)) + ((out.get(key(c)) || {}).qty || 0);
      if (have >= Math.ceil(rate(c))) continue;   // about a year's use is enough
      const score = rate(c) / (have + 1);
      if (score > bestScore) { best = c; bestScore = score; }
    }
    if (!best) break;
    const used = (Number(best.used90) || 0) > 0 ? `${best.used90} used in the last 90 days` : `${best.used365} used in the last year`;
    add(best, 1, `${used} · ${Math.max(0, freeAfter(best))} free`);
  }
  return { lines: [...out.values()], cents, pieces, met: met(), noHistory };
}

// "Get me to free shipping" for one vendor: the lines already in the order (`baseRows`, Blanks to Order rows), the
// suggestions from fillToFreeShipping_, a live tally against the vendor's free shipping, + Add item (blanks on file —
// and, for a vendor with a connection, a live look-up of a style # not on file), then Continue to order (a Purchase
// Order connection, admin), Copy order list / Download CSV, and Mark as ordered… (recorded so the restock isn't
// suggested again). Works for any vendor name on a blank, connected or not.
async function showFreeShipping_(vendor, baseRows, ctx = {}){
  const { ov, close } = inventoryModal_(`Get me to free shipping — ${escapeHtml(vendor)}`, `<div id="fsBody"><div class="admin-summary">Loading&hellip;</div></div>`, 1000);
  const $ = (id) => ov.querySelector("#" + id);
  let data;
  try { data = await hoopApi_({ action: "freeShippingSuggestions", vendor }); }
  catch (e) { $("fsBody").innerHTML = `<div class="admin-empty">${escapeHtml(e.message || "Couldn't load the suggestions.")}</div>`; return; }
  const fs = data.freeShipping, cands = data.candidates || [];
  const money = (n) => "$" + (Number(n) || 0).toFixed(2);
  const priceOf = (r) => Number(r.vendorPrice != null ? r.vendorPrice : r.price) || 0;
  const base = (baseRows || []).filter(r => r.toOrder > 0).map(r => ({ kind: "base", r, blankId: r.blankId, blank: r.blank, sku: r.sku, color: r.color || "", size: r.size || "",
    qty: r.toOrder, price: priceOf(r), on: true, reason: r.needed ? `For ${r.orders && r.orders.length ? r.orders.length + " order" + (r.orders.length === 1 ? "" : "s") : "orders"}${r.restock ? ` + ${r.restock} restock` : ""}` : r.restock ? `Restock (keep ${r.reorderPoint})` : "" }));
  const pick = fillToFreeShipping_(base.map(l => ({ ...l, qty: l.qty })), cands, fs);
  let n = 0;
  const lines = base.map(l => ({ ...l, id: n++ })).concat(pick.lines.map(c => ({ kind: "suggest", r: null, blankId: c.blankId, blank: c.blank, sku: c.sku, color: c.color, size: c.size,
    qty: c.qty, price: Number(c.price) || 0, on: true, reason: c.reason, vendorConnectionId: c.vendorConnectionId, id: n++ })));
  const connIds = [...new Set(cands.map(c => c.vendorConnectionId).filter(Boolean))];
  const sup = ctx.supplier;
  $("fsBody").innerHTML = `
    <div style="font-size:13px;color:#555;margin-bottom:10px;">${fs ? `${escapeHtml(vendor)} ships free ${escapeHtml(freeShipText_(fs))}.` : `${escapeHtml(vendor)} has no free shipping set — set it on Blanks to Order (Set free shipping…), or use this window to build an order list.`}
      Suggestions: sizes below their reorder point first, then your best sellers from this vendor against what's free. Change any quantity or untick a line.</div>
    <div id="fsLines" style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;max-height:44vh;overflow-y:auto;"></div>
    <div id="fsNote" style="font-size:12px;color:#92400e;margin-top:6px;"></div>
    <div style="border:1px solid #e5e7eb;border-radius:6px;padding:10px;margin-top:10px;">
      <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;font-size:13px;">
        <strong style="font-size:13px;">+ Add item</strong>
        <input type="text" id="fsQ" placeholder="SKU / style #, name or color" style="flex:1;min-width:200px;">
        ${connIds.length && adminCan_("manager") ? `<button type="button" class="admin-btn" id="fsLookup" style="padding:4px 10px;font-size:12px;" title="Look the style # up live at ${escapeHtml(vendor)} — for a style that isn't a blank yet">Look up on ${escapeHtml(vendor)}</button>` : ""}
      </div>
      <div id="fsFound" style="margin-top:6px;"></div>
    </div>
    <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:12px;flex-wrap:wrap;">
      <strong id="fsTally" style="font-size:15px;"></strong>
      <span style="display:flex;gap:8px;flex-wrap:wrap;">
        <button type="button" class="admin-btn" id="fsCopy" style="background:#fff;color:var(--ink,#222);border:1px solid #ccc;" title="Copy the ticked lines to paste into the vendor's site, an email or a spreadsheet">Copy order list</button>
        <button type="button" class="admin-btn" id="fsCsv" style="background:#fff;color:var(--ink,#222);border:1px solid #ccc;">Download CSV</button>
        <button type="button" class="admin-btn" id="fsMark" style="background:#fff;color:var(--ink,#222);border:1px solid #ccc;" title="You placed this order yourself (vendor site, phone, email): record it so the restock isn't suggested again while it's on its way">Mark as ordered…</button>
        <button type="button" class="admin-btn" id="fsOrder" style="display:none;">Continue to order</button>
      </span>
    </div>`;
  const on = () => lines.filter(l => l.on && l.qty > 0);
  const drawTally = () => {
    const list = on(), cents = list.reduce((t, l) => t + Math.round(l.price * 100) * l.qty, 0), pieces = list.reduce((k, l) => k + l.qty, 0);
    const pr = freeShipProgress_(fs, cents, pieces);
    const goal = fs ? [fs.overCents ? `${money(cents / 100)} of ${fsDollars_(fs.overCents)}` : money(cents / 100), fs.minQty ? `${pieces} of ${fs.minQty} pieces` : `${pieces} piece${pieces === 1 ? "" : "s"}`].join(" · ") : `${money(cents / 100)} · ${pieces} piece${pieces === 1 ? "" : "s"}`;
    $("fsTally").innerHTML = `Order ${escapeHtml(goal)}${pr ? (pr.met ? ` — <span style="color:#166534;">Free shipping ✓</span>` : ` — <span style="color:#92400e;">${escapeHtml(pr.label)}</span>`) : ""}`;
  };
  const drawLines = () => {
    const th = "padding:6px 8px;text-align:left;font-size:11px;color:#555;background:#f0f0f0;white-space:nowrap;position:sticky;top:0;", td = "padding:5px 8px;border-top:1px solid #eee;font-size:13px;vertical-align:top;";
    $("fsLines").innerHTML = lines.length ? `<table style="width:100%;border-collapse:collapse;"><thead><tr><th style="${th}"></th><th style="${th}">Blank</th><th style="${th}">SKU</th><th style="${th}">Color</th><th style="${th}">Size</th>
      <th style="${th}text-align:right;">Qty</th><th style="${th}text-align:right;">Price</th><th style="${th}text-align:right;">Total</th><th style="${th}">Why</th></tr></thead><tbody>
      ${lines.map(l => `<tr data-fs-line="${l.id}" style="${l.on ? "" : "opacity:.5;"}">
        <td style="${td}">${l.kind === "base" ? "" : `<input type="checkbox" class="fs-on" data-id="${l.id}" ${l.on ? "checked" : ""} aria-label="Include">`}</td>
        <td style="${td}">${escapeHtml(l.blank)}${l.newBlank ? ` <span style="font-size:11px;background:#dbeafe;color:#1e40af;padding:1px 5px;border-radius:3px;">New blank</span>` : ""}</td>
        <td style="${td}font-family:'IBM Plex Mono',monospace;font-size:12px;">${escapeHtml(l.sku || "")}</td><td style="${td}">${escapeHtml(l.color || "—")}</td><td style="${td}">${escapeHtml(l.size || "—")}</td>
        <td style="${td}text-align:right;">${l.kind === "base" ? l.qty : `<input type="number" class="fs-qty" data-id="${l.id}" min="1" max="5000" step="1" value="${l.qty}" style="width:64px;text-align:right;" ${l.on ? "" : "disabled"}>`}</td>
        <td style="${td}text-align:right;">${l.price ? money(l.price) : `<span style="color:#b03a2e;">no price</span>`}</td>
        <td style="${td}text-align:right;" data-fs-total>${money(l.price * l.qty)}</td>
        <td style="${td}font-size:12px;color:#555;">${l.kind === "base" ? `<span style="color:#888;">Already in the order</span>${l.reason ? " · " + escapeHtml(l.reason) : ""}` : escapeHtml(l.reason || "")}</td></tr>`).join("")}</tbody></table>`
      : `<div class="admin-empty" style="padding:14px;">Nothing yet — add items below.</div>`;
    // A tick or a quantity updates that row and the tally — no redraw, so the list doesn't jump.
    $("fsLines").querySelectorAll(".fs-on").forEach(cb => cb.onchange = () => {
      const l = lines.find(x => x.id === Number(cb.dataset.id)); l.on = cb.checked;
      const tr = cb.closest("tr"); tr.style.opacity = l.on ? "" : ".5"; const q = tr.querySelector(".fs-qty"); if (q) q.disabled = !l.on;
      drawTally();
    });
    $("fsLines").querySelectorAll(".fs-qty").forEach(inp => inp.oninput = () => {
      const l = lines.find(x => x.id === Number(inp.dataset.id)); const v = Math.floor(Number(inp.value)); l.qty = v > 0 ? Math.min(5000, v) : 0;
      inp.closest("tr").querySelector("[data-fs-total]").textContent = money(l.price * l.qty);
      drawTally();
    });
  };
  const notes = [];
  if (pick.noHistory && !pick.lines.length) notes.push(`No sales history for ${vendor}'s blanks yet${cands.some(c => c.reorderPoint != null) ? "" : " and no reorder points set"}, so there's nothing more to suggest — add items below.`);
  else if (fs && !pick.met) notes.push("The suggestions stop at about a year's use per size, so they don't reach free shipping on their own — add items below or raise a quantity.");
  $("fsNote").textContent = notes.join(" ");
  drawLines(); drawTally();

  // ---- + Add item: blanks on file (this vendor's first — all blanks when it has none matching) ----
  let allBlanks = null;
  const addLine = (c, qty, extra = {}) => {
    const k = [c.blankId, c.color, c.size].join("\u0001");
    const have = lines.find(l => l.kind !== "base" && !l.newBlank && [l.blankId, l.color, l.size].join("\u0001") === k && l.blankId);
    if (have) { have.qty += qty; have.on = true; }
    else lines.push({ kind: "added", r: null, blankId: c.blankId, blank: c.blank, sku: c.sku, color: c.color, size: c.size, qty, price: Number(c.price) || 0, on: true,
      reason: extra.reason || "Added", vendorConnectionId: c.vendorConnectionId || null, id: n++, ...extra });
    drawLines(); drawTally();
    const row = $("fsLines").querySelector(`[data-fs-line="${have ? have.id : n - 1}"]`); if (row && row.scrollIntoView) row.scrollIntoView({ block: "nearest" });
  };
  const foundRow = (c, i, other) => `<tr><td style="padding:4px 6px;font-size:13px;">${escapeHtml(c.blank)}${other ? ` <span style="font-size:11px;color:#888;">(${escapeHtml(c.vendor || "no vendor")})</span>` : ""}</td>
    <td style="padding:4px 6px;font-family:'IBM Plex Mono',monospace;font-size:12px;">${escapeHtml(c.sku || "")}</td><td style="padding:4px 6px;font-size:13px;">${escapeHtml(c.color || "—")}</td><td style="padding:4px 6px;font-size:13px;">${escapeHtml(c.size || "—")}</td>
    <td style="padding:4px 6px;font-size:13px;text-align:right;">${Number(c.price) > 0 ? money(c.price) : "—"}</td>
    <td style="padding:4px 6px;font-size:12px;color:#666;text-align:right;">${c.onHand != null ? `${c.onHand} on hand` : ""}</td>
    <td style="padding:4px 6px;"><input type="number" class="fs-add-qty" data-i="${i}" min="1" max="5000" value="1" style="width:56px;text-align:right;" aria-label="Quantity"> <button type="button" class="admin-btn fs-add" data-i="${i}" style="padding:2px 8px;font-size:12px;">Add</button></td></tr>`;
  const search = async () => {
    const q = $("fsQ").value.trim().toLowerCase();
    if (!q) { $("fsFound").innerHTML = ""; return; }
    const words = q.split(/\s+/);
    const match = (c) => words.every(w => [c.blank, c.sku, c.brand, c.color, c.size].some(v => String(v || "").toLowerCase().includes(w)));
    let found = cands.filter(match), other = false;
    if (!found.length) {
      // Nothing from this vendor: any blank in the system (sizes as the Blanks screen has them).
      if (!allBlanks) {
        try {
          const r = await hoopApi_({ action: "getBlanks" });
          allBlanks = [];
          for (const b of r.blanks || []) for (const z of b.sizes || []) allBlanks.push({ blankId: b.id, blank: b.name, sku: b.sku, brand: b.brand, vendor: b.vendor, color: z.color || "", size: z.size,
            price: z.vendorPrice != null ? z.vendorPrice : z.purchasePrice, onHand: z.quantity, vendorConnectionId: b.vendorConnectionId || null });
        } catch (e) { allBlanks = []; }
      }
      found = allBlanks.filter(match); other = true;
    }
    found = found.slice(0, 40);
    $("fsFound").innerHTML = found.length ? `<div style="max-height:200px;overflow-y:auto;"><table style="width:100%;border-collapse:collapse;"><tbody>${found.map((c, i) => foundRow(c, i, other)).join("")}</tbody></table></div>`
      : `<div style="font-size:12px;color:#888;">No blank on file matches${connIds.length ? ` — try Look up on ${escapeHtml(vendor)} for a style # that isn't a blank yet` : ""}.</div>`;
    $("fsFound").querySelectorAll(".fs-add").forEach(b => b.onclick = () => {
      const c = found[Number(b.dataset.i)], q2 = Math.floor(Number($("fsFound").querySelector(`.fs-add-qty[data-i="${b.dataset.i}"]`).value)) || 1;
      addLine(c, Math.max(1, Math.min(5000, q2)));
    });
  };
  let timer = null;
  $("fsQ").oninput = () => { clearTimeout(timer); timer = setTimeout(search, 200); };
  $("fsQ").onkeydown = (e) => { if (e.key === "Enter") { e.preventDefault(); clearTimeout(timer); search(); } };

  // ---- Look up a style # live at a connected vendor (a style that isn't a blank yet) ----
  if ($("fsLookup")) $("fsLookup").onclick = async () => {
    const style = $("fsQ").value.trim();
    if (!style) { showToast("Type the style # to look up.", true); return; }
    $("fsFound").innerHTML = `<div class="admin-summary">Asking ${escapeHtml(vendor)}&hellip;</div>`;
    const { products, problems } = await fetchFromVendors_([{ connectionId: connIds[0], style }]);
    const p = products[0];
    if (!p) { $("fsFound").innerHTML = `<div style="font-size:12px;color:#b03a2e;">${escapeHtml(problems[0] || `${vendor} has no style ${style}.`)}</div>`; return; }
    const colors = (p.colors || []).map(c => c.color);
    const priceFor = (color, size) => { const pc = (p.prices || {})[color] || (p.prices || {})["*"] || {}; return Number(pc[size]) || 0; };
    $("fsFound").innerHTML = `<div style="font-size:13px;margin-bottom:6px;"><strong>${escapeHtml(p.brand ? p.brand + " " : "")}${escapeHtml(p.style)}</strong> — ${escapeHtml(p.name || "")}</div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;font-size:13px;">
        <select id="fsLkColor" aria-label="Color">${colors.map(c => `<option>${escapeHtml(c)}</option>`).join("")}</select>
        <select id="fsLkSize" aria-label="Size">${(p.sizes || []).map(z => `<option>${escapeHtml(z)}</option>`).join("")}</select>
        <input type="number" id="fsLkQty" min="1" max="5000" value="1" style="width:60px;text-align:right;" aria-label="Quantity">
        <span id="fsLkPrice" style="color:#555;"></span>
        <button type="button" class="admin-btn" id="fsLkAdd" style="padding:3px 10px;font-size:12px;">Add</button></div>
      <div style="font-size:12px;color:#888;margin-top:4px;">It becomes a blank (that color, linked to ${escapeHtml(vendor)}) when you continue.</div>`;
    const showPrice = () => { const v = priceFor($("fsLkColor").value, $("fsLkSize").value); $("fsLkPrice").textContent = v ? money(v) : "no price"; };
    $("fsLkColor").onchange = showPrice; $("fsLkSize").onchange = showPrice; showPrice();
    $("fsLkAdd").onclick = () => {
      const color = $("fsLkColor").value, size = $("fsLkSize").value, qty = Math.max(1, Math.min(5000, Math.floor(Number($("fsLkQty").value)) || 1));
      // Already a blank with that color + size? Use it.
      const on_ = cands.find(c => String(c.sku || "").toLowerCase() === String(p.style).toLowerCase() && String(c.color).toLowerCase() === color.toLowerCase() && String(c.size).toLowerCase() === size.toLowerCase());
      if (on_) { addLine(on_, qty); return; }
      addLine({ blankId: 0, blank: p.name || p.style, sku: p.style, color, size, price: priceFor(color, size), vendorConnectionId: connIds[0] }, qty, { newBlank: { product: p, color }, reason: `Looked up at ${vendor}` });
    };
  };

  // Lines with a blank that isn't on file yet become blanks first (only the colors picked, linked to the connection).
  const makeNewBlanks = async () => {
    const pending = on().filter(l => l.newBlank);
    const byStyle = new Map();
    for (const l of pending) (byStyle.get(l.newBlank.product.style) || byStyle.set(l.newBlank.product.style, { product: l.newBlank.product, colors: new Set(), lines: [] }).get(l.newBlank.product.style)).lines.push(l);
    for (const g of byStyle.values()) {
      for (const l of g.lines) g.colors.add(l.newBlank.color);
      const pv = await hoopApi_({ action: "previewVendorBlanks", products: [g.product] });
      const plan = (pv.plans || [])[0];
      if (!plan) throw new Error(`Couldn't add style ${g.product.style} as a blank.`);
      const vcolors = plan.colors.filter(x => g.colors.has(x.vendorColor) || g.colors.has(x.color)).map(x => x.vendorColor);
      const ap = await hoopApi_({ action: "applyVendorBlanks", products: [g.product], source: "Connected vendor",
        selections: [{ key: plan.key, blankId: plan.blankId || undefined, colors: vcolors, newSizes: true, create: {} }] });
      const res = (ap.results || [])[0];
      if (!res || !res.blankId) throw new Error(`Couldn't add style ${g.product.style} as a blank.`);
      for (const l of g.lines) {
        const pc = plan.colors.find(x => x.vendorColor === l.newBlank.color || x.color === l.newBlank.color);
        l.blankId = res.blankId; l.color = plan.action === "create" ? l.newBlank.color : ((pc && pc.color) || l.newBlank.color); l.newBlank = null;
      }
    }
  };
  const tsv = () => [["Style", "Description", "Color", "Size", "Qty", "Unit", "Total"].join("\t")]
    .concat(on().map(l => [l.sku, l.blank, l.color, l.size].map(v => csvSafe(String(v || "")).replace(/[\t\r\n]+/g, " ")).concat([l.qty, l.price.toFixed(2), (l.price * l.qty).toFixed(2)]).join("\t")));
  $("fsCopy").onclick = async () => {
    if (!on().length) { showToast("Nothing ticked.", true); return; }
    try { await navigator.clipboard.writeText(tsv().join("\n")); showToast(`Copied ${on().length} line${on().length === 1 ? "" : "s"} for ${vendor}.`); }
    catch (e) { showToast("Couldn't copy — use Download CSV instead.", true); }
  };
  $("fsCsv").onclick = () => {
    if (!on().length) { showToast("Nothing ticked.", true); return; }
    downloadCsv_(`order-${vendorFileName_(vendor)}-${new Date().toISOString().slice(0, 10)}.csv`, on().map(l => ({ style: l.sku, description: l.blank, color: l.color, size: l.size, qty: l.qty, unit: Number(l.price.toFixed(2)), total: Number((l.price * l.qty).toFixed(2)) })),
      [["style", "Style"], ["description", "Description"], ["color", "Color"], ["size", "Size"], ["qty", "Qty"], ["unit", "Unit"], ["total", "Total"]]);
  };
  // Restock in this order: the added / suggested lines whole, and a base line's own restock part.
  const restockLines = () => on().map(l => ({ blankId: l.blankId, color: l.color, size: l.size, qty: l.kind === "base" ? Math.max(0, Number((l.r && l.r.restock) || 0)) : l.qty })).filter(l => l.qty > 0);
  $("fsMark").onclick = async () => {
    if (!on().length) { showToast("Nothing ticked.", true); return; }
    const ref = prompt(`Record this ${vendor} order as placed (on ${vendor}'s site, by phone or email)?\n\nThe restock in it won't be suggested again until it's received. Order lines on Blanks to Order still need “Mark blank ordered” on the order.\n\nVendor order # (optional):`, "");
    if (ref === null) return;
    try {
      await makeNewBlanks();
      const lines_ = restockLines();
      if (!lines_.length) { showToast("Nothing to record — every ticked line is for an order (mark those orders blank ordered)."); close(); ctx.onDone && ctx.onDone(); return; }
      await hoopApi_({ action: "recordRestockOrder", vendor, reference: ref, lines: lines_ });
      showToast(`Recorded — ${lines_.reduce((k, l) => k + l.qty, 0)} pieces of restock on order from ${vendor}.`);
      close(); ctx.onDone && ctx.onDone();
    } catch (e) { showToast(e.message || "Couldn't record it", true); }
  };
  // Continue to order: a vendor whose blanks link to a connection that takes orders (admin).
  const orderBtn = $("fsOrder");
  const canOrder = sup && sup.connections && sup.connections.length && connIds.some(id => supplierOrderableRows_([{ vendorConnectionId: id }], sup).length);
  if (canOrder) {
    orderBtn.style.display = "";
    orderBtn.onclick = async () => {
      if (!on().length) { showToast("Nothing ticked.", true); return; }
      orderBtn.disabled = true;
      try { await makeNewBlanks(); } catch (e) { orderBtn.disabled = false; showToast(e.message, true); return; }
      const rows = on().map(l => l.kind === "base" ? { ...l.r } : { blankId: l.blankId, blank: l.blank, sku: l.sku, color: l.color, size: l.size, needed: 0, reserved: 0, onHand: 0,
        price: l.price, vendorPrice: l.price, vendorConnectionId: l.vendorConnectionId || connIds[0], orders: [], items: [], toOrder: l.qty, restock: l.qty });
      close();
      showSupplierOrder_(vendor, supplierOrderableRows_(rows, sup), sup, ctx.onDone, { freeShipping: fs });
    };
  }
}
// "S&S" → "s-s" for a file name.
const vendorFileName_ = (v) => String(v || "vendor").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "vendor";

// ---- Brand rules (migrations/0075): restricted brands and the supplier's logo approvals ----
// An order's large quantities of a restricted brand (order.brandReview, from the loaders): a pill per style.
function brandReviewPills_(o){
  return (o.brandReview || []).map(b => b.approved
    ? ` <span title="The supplier's logo approval is on file for ${escapeHtml(b.brand)}" style="font-size:10px;font-weight:700;padding:1px 5px;border-radius:3px;background:#f3f4f6;color:#555;white-space:nowrap;">✓ ${escapeHtml(b.brand)} approved</span>`
    : ` <span class="brand-review" title="${b.pieces} pieces of ${escapeHtml(b.blank)} — ${escapeHtml(b.brand)} needs the supplier's logo approval for ${b.threshold}+ (add it on the product)" style="font-size:10px;font-weight:700;padding:1px 5px;border-radius:3px;background:#fee2e2;color:#b03a2e;white-space:nowrap;">⚠ Supplier review: ${escapeHtml(b.brand)} ${escapeHtml(b.style)} ×${b.pieces}</span>`).join("");
}
// Under a supplier's table on Blanks to Order: styles whose to-order pieces reach their brand's large quantity
// without an approval for every product they're for.
function brandApprovalNeededHtml_(rows){
  const styles = new Map();
  for (const r of rows || []) {
    if (!r.brandRule || r.brandRule.largeNeedsApproval === false) continue;
    const e = styles.get(r.blankId) || styles.set(r.blankId, { brand: r.brandRule.brand, blank: r.blank, sku: r.sku, threshold: r.brandRule.threshold, pieces: 0, approvals: {} }).get(r.blankId);
    e.pieces += Number(r.toOrder) || 0;
    Object.assign(e.approvals, r.approvals || {});
  }
  const need = [...styles.values()].filter(e => e.pieces >= e.threshold && Object.values(e.approvals).some(a => a === false || (a != null && a < e.pieces)));
  if (!need.length) return "";
  return `<div class="bto-brand-approval" style="font-size:12px;color:#b03a2e;margin-bottom:4px;">Needs the supplier's logo approval before ordering: ${need.map(e => `${escapeHtml(e.brand)} ${escapeHtml(e.sku || e.blank)} ×${e.pieces} (large is ${e.threshold}+)`).join("; ")} — add it on the product (Manage catalog → the product → Supplier logo approval).</div>`;
}
// The product form's supplier approval box: approvals for this product's restricted brands, Add / Revoke.
async function loadBrandApprovalBox_(orgId, product, brands){
  const box = document.getElementById("prodFormBrandApprovals");
  if (!box) return;
  const load = async () => { try { return (await hoopApi_({ action: "listBrandApprovals", org: orgId, productId: product.productId })).approvals || []; } catch (e) { return []; } };
  let approvals = await load();
  const canEdit = adminCan_("manager");
  const draw = () => {
    box.innerHTML = `<div style="border:1px solid #e5e7eb;border-radius:6px;padding:8px 12px;margin-top:8px;background:#fff;color:#111;font-size:13px;">
      <b>Supplier logo approval</b> <span style="color:#666;">(${brands.map(escapeHtml).join(", ")})</span>
      ${approvals.length ? `<ul style="margin:6px 0 0 18px;">${approvals.map(a => `<li class="ba-item"><span style="${a.revokedAt ? "color:#888;text-decoration:line-through;" : ""}">${escapeHtml(a.brand)} — approved ${escapeHtml(a.approvedOn)}${a.maxQty != null ? `, up to ${a.maxQty}` : ", any quantity"}${a.note ? ` · ${escapeHtml(a.note)}` : ""}</span>
        <button type="button" class="admin-btn ba-view" data-key="${escapeHtml(a.fileKey)}" style="padding:1px 7px;font-size:11px;">📎 View</button>
        ${a.revokedAt ? `<span style="color:#888;"> revoked ${escapeHtml(String(a.revokedAt).slice(0, 10))}${a.revokeNote ? ": " + escapeHtml(a.revokeNote) : ""}</span>` : canEdit ? `<button type="button" class="admin-btn ba-revoke admin-btn-danger" data-id="${a.id}" style="padding:1px 7px;font-size:11px;">Revoke…</button>` : ""}</li>`).join("")}</ul>`
        : `<div style="color:#b03a2e;margin-top:4px;">None on file — a large order of this product can't be ordered from the supplier here until it's added (verify the logo with the supplier).</div>`}
      ${canEdit ? `<button type="button" class="admin-btn" id="baAdd" style="margin-top:6px;padding:3px 10px;font-size:12px;">+ Add approval…</button>` : ""}</div>`;
    box.querySelectorAll(".ba-view").forEach(b => b.onclick = () => expViewReceipt_(b.dataset.key));
    box.querySelectorAll(".ba-revoke").forEach(b => b.onclick = async () => {
      const ans = await confirmModal_({ title: "Revoke this approval?", text: "Supplier ordering for this brand will need a new approval.", reason: "optional", reasonLabel: "Why (optional)", confirmLabel: "Revoke", danger: true });
      if (!ans.ok) return;
      const note = ans.reason;
      try { await hoopApi_({ action: "revokeBrandApproval", id: Number(b.dataset.id), note }); approvals = await load(); draw(); showToast("Approval revoked."); }
      catch (e) { showToast(e.message, true); }
    });
    const add = box.querySelector("#baAdd");
    if (add) add.onclick = () => showBrandApprovalModal_(orgId, product, brands, async () => { approvals = await load(); draw(); });
  };
  draw();
}
async function showBrandApprovalModal_(orgId, product, brands, onDone){
  let others = [];
  try { others = ((await hoopApi_({ action: "listProducts", org: orgId })).products || []).filter(p => p.productId !== product.productId); } catch (e) {}
  const today = new Date().toISOString().slice(0, 10);
  const { ov, close } = inventoryModal_("Add the supplier's logo approval", `<div style="font-size:13px;">
    <label style="display:block;margin-bottom:8px;">Brand <select id="baBrand">${brands.map(b => `<option>${escapeHtml(b)}</option>`).join("")}</select></label>
    <label style="display:block;margin-bottom:8px;">The supplier's approval (required — a PDF of the email, or a picture of it)<br><input type="file" id="baFile" accept="application/pdf,image/jpeg,image/png,image/webp,image/heic,image/heif,.heic,.heif"></label>
    <label style="display:block;margin-bottom:8px;">Approved on <input type="date" id="baDate" value="${today}" max="${today}"></label>
    <label style="display:block;margin-bottom:8px;">Approved up to <input type="number" id="baMax" min="1" step="1" style="width:90px;"> pieces <span style="color:#888;">(blank = any quantity)</span></label>
    <label style="display:block;margin-bottom:8px;">Note <input id="baNote" maxlength="500" style="width:100%;box-sizing:border-box;" placeholder="e.g. which supplier, who there, which logo"></label>
    ${others.length ? `<details style="margin-bottom:8px;"><summary>Same logo on other products of this shop? (${others.length})</summary>
      <div style="max-height:160px;overflow:auto;margin-top:4px;">${others.map(p => `<label class="pick-row" style="display:block;"><input type="checkbox" class="baOther" value="${escapeHtml(p.productId)}"> ${escapeHtml(p.name)}</label>`).join("")}</div></details>` : ""}
    <div id="baErr" style="color:#b03a2e;min-height:18px;"></div>
    <div style="display:flex;justify-content:flex-end;gap:8px;"><button type="button" id="baCancel" style="padding:6px 12px;border:1px solid #ccc;border-radius:5px;background:#fff;cursor:pointer;">Cancel</button><button type="button" class="admin-btn" id="baSave">Save approval</button></div></div>`, 560);
  ov.querySelector("#baCancel").onclick = close;
  ov.querySelector("#baSave").onclick = async () => {
    const err = ov.querySelector("#baErr"), btn = ov.querySelector("#baSave");
    const f = ov.querySelector("#baFile").files[0];
    if (!f) { err.textContent = "Attach the supplier's approval."; return; }
    btn.disabled = true; err.textContent = "Uploading…";
    try {
      const up = await uploadReceipt_(f);
      const productIds = [product.productId, ...[...ov.querySelectorAll(".baOther:checked")].map(x => x.value)];
      await hoopApi_({ action: "addBrandApproval", org: orgId, productIds, brand: ov.querySelector("#baBrand").value, approvedOn: ov.querySelector("#baDate").value,
        maxQty: ov.querySelector("#baMax").value === "" ? "" : Number(ov.querySelector("#baMax").value), note: ov.querySelector("#baNote").value, fileKey: up.key, fileName: up.name });
      close(); showToast(`Approval saved for ${productIds.length} product${productIds.length === 1 ? "" : "s"}.`);
      if (onDone) await onDone();
    } catch (e) { btn.disabled = false; err.textContent = e.message || "Couldn't save it"; }
  };
}
// Tools → Brand rules: the default large quantity, the logo concerns, and the restricted brands (admins edit).
// Price impact (Brand rules): every product size, in every shop, linked to a blank with a MAP — its price now (Before)
// and MAP + the price rule (After). The rules can be tweaked in the window (the After column follows) and saved from it,
// and the ticked After prices applied to the products (applyRulePrices; drafts until each shop is published).
async function showPriceImpact_(rules, opts){
  opts = opts || {};
  const edit = { priceRule: rules.priceRule ? { ...rules.priceRule } : null, brandPrices: (rules.brandPrices || []).map(b => ({ ...b })) };
  const { ov, close } = inventoryModal_("Price impact of the price rule", `<div id="piBody" style="font-size:13px;color:#666;">Working out every shop's prices&hellip;</div>`, 1000);
  const body = ov.querySelector("#piBody");
  const shopName = (id) => ((adminOrgs || []).find(o => o.orgId === id) || {}).name || id;
  let rows = [], noMap = 0;
  const unticked = new Set();   // rows that would change but were unticked (by key)
  const keyOf = (r) => [r.org, r.productId, r.group, r.size].join("|");
  const load = async () => {
    const products = (await hoopApi_({ action: "analyzePricing" })).products || [];
    rows = []; noMap = 0;
    for (const p of products) for (const r of p.rows || []) {
      if (r.map == null) { noMap++; continue; }
      rows.push({ org: p.orgId, productId: p.productId, group: r.group || "", size: r.size || "", blank: r.mapBlank || r.mapOf || "Blank", brand: r.mapBrand || "", shop: shopName(p.orgId),
        product: p.name + (p.visible ? "" : " (hidden)"), what: [r.group, r.size].filter(Boolean).join(" · ") || "One price", before: r.price, map: r.map });
    }
    rows.sort((a, b) => a.blank.localeCompare(b.blank) || a.shop.localeCompare(b.shop) || a.product.localeCompare(b.product));
  };
  try { await load(); } catch (e) { body.textContent = e.message; return; }
  const canApply = adminCan_("manager");
  let rounding = "none";
  const brands = [...new Set([...rows.map(r => r.brand).filter(Boolean), ...edit.brandPrices.map(b => b.brand)])].sort((a, b) => a.localeCompare(b));
  const money = (v) => v == null ? "—" : "$" + Number(v).toFixed(2);
  // MAP + the rule, rounded up as chosen (rounding only ever goes up, so it never lands under the rule).
  const after = (r) => {
    const rule = priceRuleFor_(edit, r.brand); if (!rule) return null;
    let cents = Math.round((rule.unit === "pct" ? r.map * (1 + rule.add / 100) : r.map + Number(rule.add)) * 100);
    if (rounding === "whole") cents = Math.ceil(cents / 100) * 100; else if (rounding === "99") cents = Math.ceil((cents + 1) / 100) * 100 - 1;
    return cents / 100;
  };
  const changing = (r) => { const a = after(r); return a != null && Math.abs(a - r.before) >= 0.005; };
  const picked = () => rows.filter(r => changing(r) && !unticked.has(keyOf(r)));
  const brandRule = (b) => edit.brandPrices.find(x => x.brand === b) || null;
  const drawTable = () => {
    const only = body.querySelector("#piOnly").checked;
    let up = 0, down = 0, html = "", last = null;
    for (const r of rows) {
      const a = after(r), changes = changing(r);
      if (changes) (a > r.before ? up++ : down++);
      if (only && !changes) continue;
      if (r.blank !== last) { last = r.blank; html += `<tr class="pi-blank"><th colspan="${canApply ? 7 : 6}" style="text-align:left;padding:8px 6px 3px;background:#f8fafc;">${escapeHtml(r.blank)}${r.brand ? ` <span style="color:#666;font-weight:400;">· ${escapeHtml(r.brand)}</span>` : ""}</th></tr>`; }
      html += `<tr class="pi-row">${canApply ? `<td style="padding:3px 6px;width:22px;">${changes ? `<input type="checkbox" class="pi-pick" data-k="${escapeHtml(keyOf(r))}"${unticked.has(keyOf(r)) ? "" : " checked"} aria-label="Apply this price">` : ""}</td>` : ""}<td style="padding:3px 6px;">${escapeHtml(r.shop)}</td><td style="padding:3px 6px;">${escapeHtml(r.product)}</td><td style="padding:3px 6px;">${escapeHtml(r.what)} <span style="color:#888;font-size:11px;">MAP ${money(r.map)}</span></td>
        <td class="pi-before" style="padding:3px 6px;text-align:right;">${money(r.before)}</td><td class="pi-after" style="padding:3px 6px;text-align:right;${changes ? `font-weight:700;color:${a > r.before ? "#166534" : "#b03a2e"};` : ""}">${money(a)}</td><td class="pi-change" style="padding:3px 6px;text-align:right;${changes ? `color:${a > r.before ? "#166534" : "#b03a2e"};` : "color:#888;"}">${a == null ? "—" : changes ? (a > r.before ? "+" : "−") + "$" + Math.abs(a - r.before).toFixed(2) : "$0.00"}</td></tr>`;
    }
    body.querySelector("#piSummary").textContent = rows.length ? `${rows.length} price${rows.length === 1 ? "" : "s"} on blanks with a MAP: ${up} would go up, ${down} would go down.` : "";
    const apply = body.querySelector("#piApply");
    if (apply) { const n = picked().length; apply.disabled = !n; apply.textContent = n ? `Apply ${n} price${n === 1 ? "" : "s"}…` : "Apply these prices"; }
    body.querySelector("#piTable").innerHTML = html || `<tr><td colspan="${canApply ? 7 : 6}" class="admin-empty" style="padding:10px;">${rows.length ? "No price would change." : "No product is linked to a blank with a MAP."}</td></tr>`;
  };
  body.style.color = "var(--ink,#111)";
  body.innerHTML = `
    <div class="pi-rules" style="padding:8px 10px;border:1px solid #e5e7eb;border-radius:6px;margin-bottom:10px;">
      <div style="font-size:12px;color:#666;margin-bottom:6px;">Change the rule here to see the effect — After is MAP + the rule (a brand's own rule, else the general one). Prices aren't changed by this window.</div>
      <label class="pi-gen" style="display:block;margin-bottom:6px;">General: MAP + ${unitPick_("piGen", edit.priceRule, "")}</label>
      ${brands.length ? `<div style="display:flex;flex-wrap:wrap;gap:6px 18px;">${brands.map(b => `<label class="pi-brand" data-brand="${escapeHtml(b)}" style="white-space:nowrap;">${escapeHtml(b)}: MAP + ${unitPick_("", brandRule(b) || { add: null }, "")}</label>`).join("")}</div>
        <div style="font-size:11px;color:#888;margin-top:4px;">A brand left blank uses the general rule.</div>` : ""}
    </div>
    <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:6px;">
      <span id="piSummary" style="font-size:12px;color:#555;"></span>
      <span style="display:flex;gap:12px;align-items:center;flex-wrap:wrap;">
        <label style="font-size:12px;">Round After <select id="piRound" style="font-size:12px;width:auto;min-width:0;padding:3px 6px;">${WIZ_ROUNDING_.map(([v, l]) => `<option value="${v}">${l}</option>`).join("")}</select></label>
        <label class="pick-row" style="font-size:12px;"><input type="checkbox" id="piOnly"> Only prices that would change</label></span></div>
    <div style="max-height:52vh;overflow:auto;border:1px solid #ddd;border-radius:6px;"><table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="position:sticky;top:0;background:#f0f0f0;">${canApply ? `<th style="padding:5px 6px;"><input type="checkbox" id="piAll" checked aria-label="Tick every price that would change"></th>` : ""}<th style="text-align:left;padding:5px 6px;">Shop</th><th style="text-align:left;padding:5px 6px;">Product</th><th style="text-align:left;padding:5px 6px;">Size</th><th style="text-align:right;padding:5px 6px;">Before</th><th style="text-align:right;padding:5px 6px;">After</th><th style="text-align:right;padding:5px 6px;">Change</th></tr></thead>
      <tbody id="piTable"></tbody></table></div>
    ${noMap ? `<div style="font-size:11px;color:#888;margin-top:4px;">${noMap} price${noMap === 1 ? "" : "s"} on blanks with no MAP aren't listed — the rule doesn't apply to them.</div>` : ""}
    <div id="piDone" style="font-size:12px;margin-top:8px;"></div>
    <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:12px;flex-wrap:wrap;">
      <button type="button" class="admin-btn" id="piClose" style="background:#fff;color:var(--ink,#222);border:1px solid #ccc;">Close</button>
      ${opts.canEdit ? `<button type="button" class="admin-btn" id="piSave" style="background:#fff;color:var(--ink,#222);border:1px solid #ccc;">Save this rule</button>` : ""}
      ${canApply ? `<button type="button" class="admin-btn" id="piApply" disabled>Apply these prices</button>` : ""}</div>`;
  const readRules = () => {
    edit.priceRule = readUnit_(body.querySelector(".pi-gen"));
    const keep = edit.brandPrices.filter(b => !brands.includes(b.brand));
    edit.brandPrices = keep.concat([...body.querySelectorAll(".pi-brand")].map(el => { const u = readUnit_(el); return u ? { brand: el.dataset.brand, ...u } : null; }).filter(Boolean));
  };
  body.querySelector(".pi-rules").addEventListener("input", () => { readRules(); drawTable(); });
  body.querySelector(".pi-rules").addEventListener("change", () => { readRules(); drawTable(); });
  body.querySelector("#piOnly").onchange = drawTable;
  body.querySelector("#piRound").onchange = (e) => { rounding = e.target.value; drawTable(); };
  body.querySelector("#piTable").addEventListener("change", (e) => {
    if (!e.target.classList.contains("pi-pick")) return;
    e.target.checked ? unticked.delete(e.target.dataset.k) : unticked.add(e.target.dataset.k); drawTable();
  });
  const all = body.querySelector("#piAll");
  if (all) all.onchange = () => { rows.filter(changing).forEach(r => all.checked ? unticked.delete(keyOf(r)) : unticked.add(keyOf(r))); drawTable(); };
  const applyBtn = body.querySelector("#piApply");
  if (applyBtn) applyBtn.onclick = async () => {
    const list = picked();
    if (!list.length) return;
    const shops = [...new Set(list.map(r => r.org))];
    if (!(await askConfirm_(`Apply ${list.length} new price${list.length === 1 ? "" : "s"} in ${shops.length} shop${shops.length === 1 ? "" : "s"}?\n\nEach product's price is set to its After price. Shoppers see the new prices when each shop is published.`, { confirmLabel: "Apply prices" }))) return;
    applyBtn.disabled = true;
    try {
      const r = await hoopApi_({ action: "applyRulePrices", changes: list.map(x => ({ org: x.org, productId: x.productId, group: x.group, size: x.size, price: after(x) })) });
      unticked.clear();
      await load(); drawTable();
      const touched = [...new Set(r.products.map(p => p.org))];
      body.querySelector("#piDone").innerHTML = `<span style="color:#166534;">Applied ${r.prices} price${r.prices === 1 ? "" : "s"} in ${touched.length} shop${touched.length === 1 ? "" : "s"}.</span>
        ${touched.length ? ` They're drafts until published: ${touched.map(o => `<button type="button" class="admin-btn pi-publish" data-org="${escapeHtml(o)}" style="padding:2px 8px;font-size:12px;">Publish ${escapeHtml(shopName(o))}</button>`).join(" ")}` : ""}
        ${r.skipped.length ? `<div style="color:#b03a2e;">Not applied: ${r.skipped.map(escapeHtml).join("; ")}</div>` : ""}`;
      body.querySelectorAll(".pi-publish").forEach(b => b.onclick = async () => {
        b.disabled = true;
        try { const pr = await hoopApi_({ action: "publish", org: b.dataset.org }); if (pr.publishState && window._shopBarData) window._shopBarData.publish = pr.publishState; b.textContent = `✓ ${shopName(b.dataset.org)} published`; }
        catch (e) { b.disabled = false; showToast(e.message, true); }
      });
      if (typeof drawPublishStates_ === "function") try { drawPublishStates_(); } catch (e) {}
    } catch (e) { showToast(e.message, true); drawTable(); }
  };
  body.querySelector("#piClose").onclick = close;
  const save = body.querySelector("#piSave");
  if (save) save.onclick = async () => {
    save.disabled = true; readRules();
    try {
      const r = await hoopApi_({ action: "updateBrandRules", rules: Object.assign({}, rules, { priceRule: edit.priceRule, brandPrices: edit.brandPrices }) });
      showToast("Price rule saved."); close(); if (opts.onSaved) opts.onSaved(r.rules);
    } catch (e) { save.disabled = false; showToast(e.message, true); }
  };
  drawTable();
}

// An amount + dollars / percent pair (the price rule). Blank amount = no rule.
function unitPick_(id, r, dis){
  r = r || {};
  return `<input type="number" class="br-padd"${id ? ` id="${id}Add"` : ""} min="0" step="0.5" value="${r.add == null ? "" : r.add}" placeholder="none" aria-label="Amount over MAP" style="width:80px;" ${dis}>
    <select class="br-punit"${id ? ` id="${id}Unit"` : ""} aria-label="Dollars or percent" ${dis}><option value="amount"${r.unit === "pct" ? "" : " selected"}>dollars</option><option value="pct"${r.unit === "pct" ? " selected" : ""}>percent</option></select>`;
}
const readUnit_ = (el) => { const a = el.querySelector(".br-padd").value.trim(); return a === "" ? null : { add: Number(a), unit: el.querySelector(".br-punit").value }; };
async function renderBrandRules(app){
  adminSetHash("brandrules");
  document.title = adminTitle_("Brand rules");
  app.innerHTML = `${adminPageHead_("Brand rules")}
    <div class="admin-panel" style="--org-accent:var(--accent);max-width:1040px;margin:8px auto 60px;">
      <div style="font-size:13px;color:#666;margin-bottom:12px;">Your price rule over MAP, and the brands suppliers restrict — <b>verify each with the supplier you buy it from</b>. Most can only be sold decorated, and a large order needs the supplier's logo approval. A product linked to one of these blanks is flagged; an order — or an order placed with a supplier from Blanks to Order — with a <b>large</b> number of one style needs the supplier's logo approval on the product. Ordering from the supplier here is blocked until it's on file; an admin can override that, with a reason.</div>
      <div id="brBody">Loading…</div></div>`;
  const body = document.getElementById("brBody");
  let rules, cats = [];
  try { rules = (await hoopApi_({ action: "getBrandRules" })).rules; } catch (e) { body.textContent = e.message; return; }
  try { cats = (await hoopApi_({ action: "listProductCategories" })).categories || []; } catch (e) {}
  const canEdit = adminCan_("admin");
  const dis = canEdit ? "" : "disabled";
  const draw = () => {
    body.innerHTML = `
      <label style="display:block;margin-bottom:10px;">Large quantity (default): <input type="number" id="brQty" min="1" step="1" value="${rules.largeQty}" style="width:90px;" ${dis}> pieces of one style on one order</label>
      <div style="margin-bottom:12px;"><label for="brConcerns" style="display:block;margin-bottom:4px;">Logo concerns shown with every flag (one per line)</label>
        <textarea id="brConcerns" rows="5" style="display:block;width:100%;max-width:520px;box-sizing:border-box;" ${dis}>${escapeHtml(rules.concerns.join("\n"))}</textarea></div>
      <div class="br-price" style="margin:4px 0 18px;padding:10px 12px;border:1px solid #e5e7eb;border-radius:6px;">
        <div style="font-weight:700;margin-bottom:4px;">Price rule</div>
        <div style="font-size:12px;color:#666;margin-bottom:8px;">What to charge over a blank's MAP (minimum advertised price). The shop setup wizard and the product form's price calculator start from it, and a price under it is flagged as a warning — softer than a price below MAP itself. A brand's own rule wins over the general one; leave the amount blank for no rule.</div>
        <label style="display:block;margin-bottom:8px;">General: MAP + ${unitPick_("brPrice", rules.priceRule, dis)}</label>
        <table style="border-collapse:collapse;font-size:13px;"><tbody>${(rules.brandPrices || []).map((b, i) => `<tr class="br-prow" data-i="${i}">
          <td style="padding:3px 6px 3px 0;"><input class="br-pbrand" value="${escapeHtml(b.brand)}" placeholder="Brand" aria-label="Brand" style="width:150px;" ${dis}></td>
          <td style="padding:3px 6px;">MAP + ${unitPick_("", b, dis)}</td>
          <td style="padding:3px 6px;">${canEdit ? `<button type="button" class="admin-btn br-pdel admin-btn-danger" data-i="${i}" style="padding:2px 8px;font-size:12px;">Remove</button>` : ""}</td></tr>`).join("")}</tbody></table>
        <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:6px;">
          ${canEdit ? `<button type="button" class="admin-btn" id="brPAdd" style="padding:3px 10px;font-size:12px;background:#fff;color:var(--ink,#222);border:1px solid #ccc;">+ Add a brand's price rule</button>` : ""}
          <button type="button" class="admin-btn" id="brImpact" style="padding:3px 10px;font-size:12px;">Show price impact&hellip;</button></div>
      </div>
      <div style="font-weight:700;margin-bottom:4px;">Restricted brands</div>
      <div style="overflow-x:auto;"><table class="stack-mobile" style="width:100%;border-collapse:collapse;font-size:13px;">
        <thead><tr><th style="text-align:left;padding:4px;">Brand</th><th style="text-align:left;padding:4px;">Large quantity</th><th style="text-align:left;padding:4px;">Decorated only</th><th style="text-align:left;padding:4px;">Large orders need approval</th><th style="text-align:left;padding:4px;">May be sold plain (categories)</th><th style="text-align:left;padding:4px;">Note</th><th></th></tr></thead>
        <tbody>${rules.brands.map((b, i) => `<tr class="br-row" data-i="${i}">
          <td data-label="Brand" style="padding:4px;"><input class="br-brand" value="${escapeHtml(b.brand)}" style="width:150px;" ${dis}></td>
          <td data-label="Large quantity" style="padding:4px;"><input class="br-qty" type="number" min="1" step="1" value="${b.largeQty == null ? "" : b.largeQty}" placeholder="${rules.largeQty}" style="width:80px;" ${dis}></td>
          <td data-label="Decorated only" style="padding:4px;"><input class="br-dec" type="checkbox" ${b.mustDecorate ? "checked" : ""} ${dis}></td>
          <td data-label="Large orders need approval" style="padding:4px;"><input class="br-appr" type="checkbox" ${b.largeNeedsApproval !== false ? "checked" : ""} ${dis}></td>
          <td data-label="May be sold plain" style="padding:4px;">${cats.map(c => `<label class="pick-row" style="display:inline-block;margin-right:6px;font-size:12px;"><input type="checkbox" class="br-cat" value="${escapeHtml(c.key)}" ${(b.exceptCategories || []).includes(c.key) ? "checked" : ""} ${dis}> ${escapeHtml(c.name)}</label>`).join("")}</td>
          <td data-label="Note" style="padding:4px;"><input class="br-note" value="${escapeHtml(b.note || "")}" style="width:100%;min-width:180px;" ${dis}></td>
          <td style="padding:4px;">${canEdit ? `<button type="button" class="admin-btn br-del admin-btn-danger" data-i="${i}" style="padding:2px 8px;font-size:12px;">Remove</button>` : ""}</td></tr>`).join("")}</tbody></table></div>
      ${canEdit ? `<div style="display:flex;gap:8px;margin-top:12px;"><button type="button" class="admin-btn" id="brAdd" style="background:#fff;color:var(--ink,#222);border:1px solid #ccc;">+ Add brand</button><button type="button" class="admin-btn" id="brSave">Save</button></div>` : `<div style="color:#666;margin-top:10px;font-size:12px;">Only an admin can change these.</div>`}`;
    body.querySelector("#brImpact").onclick = () => showPriceImpact_(canEdit ? read() : rules, { canEdit, onSaved: (saved) => { rules = saved; draw(); } });
    if (!canEdit) return;
    const read = () => ({ largeQty: Number(body.querySelector("#brQty").value), concerns: body.querySelector("#brConcerns").value.split("\n").map(x => x.trim()).filter(Boolean),
      brands: [...body.querySelectorAll(".br-row")].map(tr => ({ brand: tr.querySelector(".br-brand").value.trim(), largeQty: tr.querySelector(".br-qty").value === "" ? null : Number(tr.querySelector(".br-qty").value),
        mustDecorate: tr.querySelector(".br-dec").checked, largeNeedsApproval: tr.querySelector(".br-appr").checked, exceptCategories: [...tr.querySelectorAll(".br-cat:checked")].map(x => x.value), note: tr.querySelector(".br-note").value.trim() })),
      priceRule: readUnit_(body.querySelector(".br-price > label")),
      brandPrices: [...body.querySelectorAll(".br-prow")].map(tr => Object.assign({ brand: tr.querySelector(".br-pbrand").value.trim() }, readUnit_(tr) || { add: "" })) });
    body.querySelectorAll(".br-pdel").forEach(b => b.onclick = () => { rules = read(); rules.brandPrices.splice(Number(b.dataset.i), 1); draw(); });
    body.querySelector("#brPAdd").onclick = () => { rules = read(); rules.brandPrices.push({ brand: "", add: "", unit: "amount" }); draw(); };
    body.querySelectorAll(".br-del").forEach(b => b.onclick = () => { rules = read(); rules.brands.splice(Number(b.dataset.i), 1); draw(); });
    body.querySelector("#brAdd").onclick = () => { rules = read(); rules.brands.push({ brand: "", largeQty: null, mustDecorate: true, largeNeedsApproval: true, exceptCategories: [], note: "" }); draw(); };
    body.querySelector("#brSave").onclick = async () => {
      const btn = body.querySelector("#brSave"); btn.disabled = true;
      try { rules = (await hoopApi_({ action: "updateBrandRules", rules: read() })).rules; draw(); showToast("Brand rules saved."); }
      catch (e) { btn.disabled = false; showToast(e.message, true); }
    };
  };
  draw();
}

// ---- Ordering blanks from a supplier (migrations/0072) — admin only, the server refuses anyone else ----
// Rows whose blank links to a connection of a company that has a connection taking orders (production, or the
// supplier's test service).
function supplierOrderableRows_(rows, ctx){
  if (!ctx || !ctx.connections || !ctx.connections.length) return [];
  const canOrder = new Set(ctx.connections.map(c => c.companyCode));
  return (rows || []).filter(r => r.vendorConnectionId && canOrder.has((ctx.companies || {})[r.vendorConnectionId]));
}
// Under a supplier's table (admin, when ordering through a connection is set up for it): the lines that can't be
// ordered from here, and why — so a missing button or a short order explains itself.
function supplierNotOrderableHtml_(block, ctx){
  if (!ctx || !ctx.connections || !ctx.connections.length) return "";
  const can = new Set(supplierOrderableRows_(block.rows, ctx));
  const left = block.rows.filter(r => !can.has(r));
  if (!left.length) return "";
  const forSupplier = can.size || ctx.connections.some(c => sameVendorName_(block.vendor, c.name));
  if (!forSupplier) return "";
  const companies = ctx.companies || {};
  const unlinked = left.filter(r => !r.vendorConnectionId || !companies[r.vendorConnectionId]);
  const noOrders = left.filter(r => !unlinked.includes(r));
  const names = (rows) => [...new Set(rows.map(r => r.blank + (r.sku ? " (" + r.sku + ")" : "")))];
  const list = (rows) => { const n = names(rows); return n.slice(0, 4).map(escapeHtml).join(", ") + (n.length > 4 ? ` and ${n.length - 4} more` : ""); };
  const parts = [];
  if (unlinked.length) parts.push(`${unlinked.length} line${unlinked.length === 1 ? "" : "s"} — ${list(unlinked)} — ${unlinked.length === 1 ? "isn't" : "aren't"} linked to a vendor connection (Tools → Vendor integrations → Link blanks…).`);
  if (noOrders.length) parts.push(`${noOrders.length} line${noOrders.length === 1 ? "" : "s"} — ${list(noOrders)} — ${noOrders.length === 1 ? "is" : "are"} linked to a connection that can't place orders.`);
  return `<div class="bto-not-orderable" style="font-size:12px;color:#92400e;margin-bottom:4px;">Can't be ordered from here, order by hand: ${parts.join(" ")}</div>`;
}
const SUPPLIER_ORDER_STATUS_ = { sending: "Sending…", placed: "Placed", failed: "Refused", unknown: "No answer — check the supplier's site" };
// The "Orders placed with suppliers" list under Blanks to Order.
function supplierOrdersHtml_(orders){
  const th = "padding:6px 8px;text-align:left;font-size:11px;color:#555;background:#f0f0f0;white-space:nowrap;", td = "padding:6px 8px;border-top:1px solid #eee;font-size:13px;vertical-align:top;";
  const rows = (orders || []).map(o => {
    const pieces = (o.lines || []).reduce((n, l) => n + (Number(l.qty) || 0), 0);
    const ships = (o.shipments || []).map(s => `${escapeHtml(s.carrier)} ${escapeHtml(s.trackingNumber)}${s.deliveredAt ? " · delivered" : s.status ? " · " + escapeHtml(s.status.toLowerCase().replace(/_/g, " ")) : ""}`).join("<br>");
    const color = o.cancelledAt ? "#555" : o.status === "placed" ? "#166534" : o.status === "sending" ? "#555" : "#b03a2e";
    const statusText = o.cancelledAt ? `Cancelled at the supplier ${String(o.cancelledAt).slice(0, 10)}` : (SUPPLIER_ORDER_STATUS_[o.status] || o.status);
    return `<tr class="so-row" data-id="${o.id}">
      <td style="${td}font-family:'IBM Plex Mono',monospace;font-size:12px;">${escapeHtml(o.poNumber)}${o.environment === "test" ? ` <span style="font-size:10px;background:#fef3c7;color:#92400e;padding:1px 5px;border-radius:3px;">TEST</span>` : ""}</td>
      <td style="${td}">${escapeHtml(String(o.placedAt || o.createdAt || "").slice(0, 10))}</td>
      <td style="${td}">${escapeHtml(o.vendor)}</td>
      <td style="${td}">${(o.lines || []).length} line${(o.lines || []).length === 1 ? "" : "s"} · ${pieces} pc</td>
      <td style="${td}text-align:right;">$${Number(o.total || 0).toFixed(2)}</td>
      <td style="${td}color:${color};">${escapeHtml(statusText)}${o.cancelledAt && o.cancelNote ? `<div style="font-size:11px;color:#555;">${escapeHtml(o.cancelNote)}</div>` : ""}${o.error && !o.cancelledAt ? `<div style="font-size:11px;color:#7f1d1d;">${escapeHtml(o.error)}</div>` : ""}</td>
      <td style="${td}font-size:12px;">${ships || (o.status === "placed" && !o.cancelledAt ? `<span style="color:#888;">none yet</span>` : "")}</td>
      <td style="${td}white-space:nowrap;">
        ${o.status === "placed" && !o.cancelledAt ? `<button type="button" class="admin-btn so-check" data-id="${o.id}" style="padding:2px 8px;font-size:12px;">Check shipments</button>
          <button type="button" class="admin-btn so-receive" data-id="${o.id}" style="padding:2px 8px;font-size:12px;">Receive…</button>` : ""}
        ${(o.status === "failed" || o.status === "unknown") && !o.cancelledAt ? `<button type="button" class="admin-btn so-retry" data-id="${o.id}" style="padding:2px 8px;font-size:12px;">Send again</button>` : ""}
        ${(o.status === "placed" || o.status === "unknown") && !o.cancelledAt ? `<button type="button" class="admin-btn so-cancel admin-btn-danger" data-id="${o.id}" style="padding:2px 8px;font-size:12px;" title="You cancelled this order with the supplier: take its PO number off the order lines">Mark cancelled…</button>` : ""}
      </td></tr>`;
  }).join("");
  return `<div id="btoSupplierOrders" style="margin-top:26px;">
    <div style="display:flex;justify-content:space-between;align-items:baseline;gap:12px;flex-wrap:wrap;margin-bottom:4px;">
      <h2 style="margin:0;font-size:17px;">Orders placed with suppliers</h2>
      ${(orders || []).some(o => o.status === "placed") ? `<button type="button" class="admin-btn so-check-all" style="padding:3px 10px;font-size:12px;">Check all for shipments</button>` : ""}
    </div>
    <div style="font-size:12px;color:#666;margin-bottom:6px;">Placed from this screen. Tracking numbers the supplier reports are added to the blank shipments each morning (or with Check shipments), and followed to delivery.</div>
    ${rows ? `<div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;"><table style="width:100%;border-collapse:collapse;">
      <thead><tr><th style="${th}">PO</th><th style="${th}">Date</th><th style="${th}">Supplier</th><th style="${th}">Lines</th><th style="${th}text-align:right;">Total</th><th style="${th}">Status</th><th style="${th}">Shipments</th><th style="${th}"></th></tr></thead>
      <tbody>${rows}</tbody></table></div>` : `<div class="admin-empty">No orders placed from here yet.</div>`}
  </div>`;
}
// Receive order, filled in from a placed supplier order: one box per blank, each line at what it cost.
function supplierOrderReceivePrefill_(o){
  const groups = new Map();
  for (const l of o.lines || []) {
    if (!groups.has(l.blankId)) groups.set(l.blankId, { blankId: l.blankId, lines: [] });
    groups.get(l.blankId).lines.push({ color: l.color || "", size: l.size || "", qty: Number(l.qty) || 0, total: Math.round((Number(l.unitCents) || 0) * (Number(l.qty) || 0)) / 100 });
  }
  return { groups: [...groups.values()], vendor: o.vendor || "", vendorRef: o.poNumber || "", receivedAt: new Date().toISOString().slice(0, 10) };
}
function wireSupplierOrders_(root, ctx, reload){
  if (!ctx) return;
  const find = (id) => (ctx.orders || []).find(o => String(o.id) === String(id));
  const check = async (btn, id) => {
    btn.disabled = true;
    try {
      const r = await hoopApi_({ action: "checkSupplierOrderShipments", ...(id ? { id: Number(id) } : {}) });
      const errs = (r.errors || []).map(e => `${e.poNumber}: ${e.message}`);
      showToast(r.added ? `Found ${r.added} new shipment${r.added === 1 ? "" : "s"}.` : errs.length ? "Couldn't check: " + errs[0] : "No new shipments yet.", !!errs.length && !r.added);
      reload();
    } catch (e) { btn.disabled = false; showToast(e.message || "Couldn't check", true); }
  };
  root.querySelectorAll(".so-check").forEach(b => b.onclick = () => check(b, b.dataset.id));
  const all = root.querySelector(".so-check-all");
  if (all) all.onclick = () => check(all, null);
  root.querySelectorAll(".so-receive").forEach(b => b.onclick = () => { const o = find(b.dataset.id); if (o) showReceiveOrderModal(reload, supplierOrderReceivePrefill_(o)); });
  // Cancelled with the supplier (by phone, on its site…): recorded here, and the lines go back on Blanks to Order.
  root.querySelectorAll(".so-cancel").forEach(b => b.onclick = async () => {
    const o = find(b.dataset.id);
    if (!o) return;
    const ans = await confirmModal_({ title: `Mark order ${o.poNumber} as cancelled?`, text: `This doesn't contact ${o.vendor} — cancel it with them first. The order lines it was for (those not shipped or received yet) lose its PO number and go back on Blanks to order.`,
      reason: "optional", reasonLabel: "Why (optional)", confirmLabel: "Mark cancelled", cancelLabel: "Keep it", danger: true });
    if (!ans.ok) return;
    const note = ans.reason;
    b.disabled = true;
    try {
      const r = await hoopApi_({ action: "cancelSupplierOrder", id: o.id, note });
      showToast(`Order ${o.poNumber} marked cancelled — ${r.unmarked} order line${r.unmarked === 1 ? "" : "s"} back on the list.`);
      reload();
    } catch (e) { b.disabled = false; showToast(e.message || "Couldn't mark it cancelled", true); }
  });
  root.querySelectorAll(".so-retry").forEach(b => b.onclick = async () => {
    const o = find(b.dataset.id);
    if (!o) return;
    if (o.status === "unknown" && !await askConfirm_(`Send order ${o.poNumber} to ${o.vendor} again?\n\nIt got no answer, so it may already be there — check your orders on the supplier's site first. It goes again with the same PO number, which a supplier ignores if it already has it.`)) return;
    if (o.status === "failed" && !await askConfirm_(`Send order ${o.poNumber} to ${o.vendor} again, unchanged?`)) return;
    b.disabled = true;
    const r = await supplierOrderCall_({ action: "placeSupplierOrder", retryId: o.id });
    showToast(r.ok ? `Order ${o.poNumber} placed with ${o.vendor}.` : (r.d.message || "Failed"), !r.ok);
    reload();
  });
}
// Like hoopApi_, but keeps the answer when it's an error (the plan's per-line problems, the saved order).
async function supplierOrderCall_(body){
  if (!adminKey) adminKey = (await adminLogin()) || "";
  if (!adminKey) return { ok: false, d: { message: "Sign-in required" } };
  try {
    const r = await fetch("/api/orders", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ ...body, key: adminKey }) });
    const d = await r.json().catch(() => ({ status: "error", message: "Server error (" + r.status + ")" }));
    return { ok: r.ok && d.status !== "error", d };
  } catch (e) { return { ok: false, d: { status: "error", message: "The request didn't get through — check your connection." } }; }
}
// The order window: which connection, each line's quantity / the supplier's stock / price, ship method, PO number,
// then Place order. `rows` are Blanks to Order rows (to order = the default quantity; `items` = the order lines).
function showSupplierOrder_(vendor, rows, ctx, onDone, opts = {}){
  const companies = new Set(rows.map(r => (ctx.companies || {})[r.vendorConnectionId]).filter(Boolean));
  const conns = ctx.connections.filter(c => companies.has(c.companyCode)).sort((a, b) => (a.environment === "test") - (b.environment === "test"));
  if (!conns.length) { showToast("No connection for this supplier can place orders.", true); return; }
  const lines = rows.map((r, i) => ({ i, r, qty: r.toOrder, on: true, plan: null }));
  const { ov, close } = inventoryModal_(`Order from ${escapeHtml(vendor || conns[0].name)}`, `
    <style>#soPlace:disabled,#soCheck:disabled{opacity:.45;cursor:not-allowed;}</style>
    <div style="display:flex;gap:14px;flex-wrap:wrap;align-items:center;font-size:13px;margin-bottom:10px;">
      <label>Send to <select id="soConn">${conns.map(c => `<option value="${c.id}">${escapeHtml(c.name)}${c.environment === "test" ? " (TEST service)" : ""}</option>`).join("")}</select></label>
      <span id="soEnv"></span>
    </div>
    <div id="soLines" style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;max-height:46vh;overflow-y:auto;"></div>
    <div style="display:flex;gap:14px;flex-wrap:wrap;align-items:flex-end;font-size:13px;margin-top:12px;">
      <label>Ship method<br><select id="soShip"></select></label>
      <label>PO number<br><input id="soPo" maxlength="28" style="width:180px;font-family:'IBM Plex Mono',monospace;"></label>
      <div id="soShipTo" style="font-size:12px;color:#555;flex:1;min-width:200px;"></div>
    </div>
    <div id="soBrand" style="font-size:13px;margin-top:10px;"></div>
    <div id="soMsg" style="font-size:13px;margin-top:10px;"></div>
    <div id="soFree" style="font-size:13px;margin-top:8px;"></div>
    <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:14px;flex-wrap:wrap;">
      <strong id="soTotal"></strong>
      <span style="display:flex;gap:8px;"><button type="button" class="admin-btn" id="soCheck" style="background:#fff;color:var(--ink,#222);border:1px solid #ccc;">Check stock &amp; prices</button>
        <button type="button" class="admin-btn" id="soPlace" disabled>Place order</button></span>
    </div>`, 940);
  const $ = (id) => ov.querySelector("#" + id);
  let plan = null, stale = true, busy = false;
  const conn = () => conns.find(c => String(c.id) === $("soConn").value) || conns[0];
  const money = (c) => "$" + ((Number(c) || 0) / 100).toFixed(2);
  const keyOf = (o) => o.blankId + "|" + o.color + "|" + o.size;
  // This line's entry in the checked plan, at the quantity it was checked for (else null).
  const planFor = (l) => { const p = plan && (plan.lines || []).find(x => keyOf(x) === keyOf({ blankId: l.r.blankId, color: l.r.color || "", size: l.r.size || "" })); return p && p.qty === l.qty ? p : null; };
  const drawShip = () => {
    const c = conn(), keep = $("soShip").value;   // redrawn after each check: keep the method picked
    $("soShip").innerHTML = (c.shipMethods || []).map((m, i) => `<option value="${i}">${escapeHtml(m.label || m.carrier + " " + m.service)}</option>`).join("");
    if (keep && Number(keep) < (c.shipMethods || []).length) $("soShip").value = keep;
    // Never promise a test order is harmless: S&S's test address placed a real order (2026-10). The PO number starts
    // TEST- and the order carries "TEST ORDER — DO NOT PROCESS OR SHIP", but an automatic system may ignore both.
    $("soEnv").innerHTML = (c.environment === "test" ? `<span style="font-size:12px;background:#fef3c7;color:#92400e;padding:2px 7px;border-radius:4px;">The supplier's TEST service — some suppliers still process these as real orders. Confirm with ${escapeHtml(c.name)} before using it.</span>`
      : `<span style="font-size:12px;color:#7f1d1d;">This places a real order, charged to the payment method ${escapeHtml(c.name)} has on file.</span>`)
      + (plan && plan.orderHelp ? `<div style="font-size:12px;color:#555;margin-top:4px;">${escapeHtml(plan.orderHelp)}</div>` : "");
  };
  const drawLines = () => {
    const th = "padding:6px 8px;text-align:left;font-size:11px;color:#555;background:#f0f0f0;white-space:nowrap;position:sticky;top:0;", td = "padding:5px 8px;border-top:1px solid #eee;font-size:13px;vertical-align:top;";
    const byKey = new Map(((plan && plan.lines) || []).map(p => [keyOf(p), p]));
    $("soLines").innerHTML = `<table style="width:100%;border-collapse:collapse;"><thead><tr><th style="${th}"></th><th style="${th}">Blank</th><th style="${th}">Style</th><th style="${th}">Color</th><th style="${th}">Size</th>
      <th style="${th}text-align:right;">Qty</th><th style="${th}text-align:right;">In stock</th><th style="${th}text-align:right;">Price</th><th style="${th}text-align:right;">Cost</th><th style="${th}">Notes</th></tr></thead><tbody>
      ${lines.map(l => {
        const p = stale ? null : byKey.get(keyOf({ blankId: l.r.blankId, color: l.r.color || "", size: l.r.size || "" }));
        const unit = p ? p.unitCents : Math.round((Number(l.r.vendorPrice != null ? l.r.vendorPrice : l.r.price) || 0) * 100);
        return `<tr style="${l.on ? "" : "opacity:.5;"}">
          <td style="${td}"><input type="checkbox" class="so-on" data-i="${l.i}" ${l.on ? "checked" : ""}></td>
          <td style="${td}">${escapeHtml(l.r.blank)}</td><td style="${td}font-family:'IBM Plex Mono',monospace;font-size:12px;">${escapeHtml(l.r.sku)}</td>
          <td style="${td}">${escapeHtml(l.r.color || "—")}</td><td style="${td}">${escapeHtml(l.r.size || "—")}</td>
          <td style="${td}text-align:right;"><input type="number" class="so-qty" data-i="${l.i}" min="1" max="5000" step="1" value="${l.qty}" style="width:64px;text-align:right;" ${l.on ? "" : "disabled"}></td>
          <td style="${td}text-align:right;">${p && p.available != null ? p.available : "—"}</td>
          <td style="${td}text-align:right;">${unit ? money(unit) : "—"}</td><td style="${td}text-align:right;">${unit ? money(unit * l.qty) : "—"}</td>
          <td style="${td}font-size:12px;">${p && p.problem ? `<span class="so-problem" style="color:#b03a2e;">${escapeHtml(p.problem)}</span>` : ""}${p && p.note ? `<span style="color:#92400e;">${escapeHtml(p.note)}</span>` : ""}${p && !p.problem && p.partId ? `<span style="color:#166534;">✓</span>` : ""}</td></tr>`;
      }).join("")}</tbody></table>`;
    // (Un)ticking a line already checked needs no new check; ticking one that wasn't sent does.
    $("soLines").querySelectorAll(".so-on").forEach(cb => cb.onchange = () => { const l = lines[Number(cb.dataset.i)]; l.on = cb.checked; if (l.on && !planFor(l)) stale = true; drawLines(); drawFoot(); });
    $("soLines").querySelectorAll(".so-qty").forEach(inp => inp.oninput = () => {
      const v = Math.floor(Number(inp.value));
      lines[Number(inp.dataset.i)].qty = v > 0 ? v : 0; stale = true; drawFoot();
    });
  };
  const drawFoot = () => {
    drawFree();
    const on = lines.filter(l => l.on && l.qty > 0);
    const c = conn();
    // What would be sent: the checked plan's lines that are still ticked.
    const active = plan && !stale ? on.map(planFor).filter(Boolean) : [];
    const totalCents = active.reduce((t, p) => t + p.unitCents * p.qty, 0);
    const problems = active.filter(p => p.problem).length;
    if (stale || !plan || !active.length) {
      $("soTotal").textContent = on.length ? `${on.length} line${on.length === 1 ? "" : "s"} · ${on.reduce((n, l) => n + l.qty, 0)} pieces` : "Nothing ticked";
      $("soPlace").disabled = true; $("soPlace").textContent = "Place order";
      if (!busy) $("soMsg").innerHTML = on.length ? `<span style="color:#555;">${plan ? "Changed — " : ""}check stock &amp; prices to place the order.</span>` : "";
      return;
    }
    $("soTotal").textContent = `${active.length} line${active.length === 1 ? "" : "s"} · ${money(totalCents)} at our prices`;
    const blockers = [];
    if (problems && !plan.lookupError) blockers.push(`${problems} line${problems === 1 ? " can't" : "s can't"} be ordered — lower the quantity, untick ${problems === 1 ? "it" : "them"}, or order ${problems === 1 ? "it" : "them"} by hand.`);
    // Restricted brands (migrations/0075): a large quantity needs the supplier's logo approval — or an admin override with a reason.
    const needs = (plan.brandCheck && plan.brandCheck.needsApproval) || [];
    drawBrandCheck_();
    if (needs.length && !(ov.querySelector("#soOverride") && ov.querySelector("#soOverride").checked && ov.querySelector("#soOverrideWhy").value.trim().length >= 5))
      blockers.push("The supplier's logo approval isn't on file — add it on the product, or tick the admin override and say why.");
    if (plan.lookupError) blockers.unshift(`${c.name} couldn't be asked: ${plan.lookupError} Check stock & prices again in a moment.`);
    if (plan.shipToMissing && plan.shipToMissing.length) blockers.push(`Fill in the shop's ship-from address first (Global settings): ${plan.shipToMissing.join(", ")}.`);
    if (!plan.stockChecked) blockers.length || ($("soMsg").innerHTML = `<span style="color:#92400e;">${escapeHtml(c.name)} has no Inventory service set up, so stock wasn't checked.</span>`);
    if (blockers.length) $("soMsg").innerHTML = `<span style="color:#b03a2e;">${blockers.map(escapeHtml).join(" ")}</span>`;
    else if (plan.stockChecked) $("soMsg").innerHTML = `<span style="color:#166534;">Everything ticked is in stock. Prices shown are ours — the supplier charges its own.</span>${unticked ? ` <span style="color:#92400e;">${unticked} line${unticked === 1 ? "" : "s"} the supplier can't supply ${unticked === 1 ? "was" : "were"} unticked — order ${unticked === 1 ? "it" : "them"} by hand.</span>` : ""}`;
    $("soPlace").disabled = !!blockers.length;
    $("soPlace").textContent = `Place order — ${money(totalCents)}`;
  };
  // Free shipping (the vendor's threshold, by vendor name): how far the ticked lines are from it, at our prices, with
  // "Get me to free shipping" when short — it takes the ticked lines over as the starting point.
  const drawFree = () => {
    const fs = opts.freeShipping, el = $("soFree");
    if (!el) return;
    if (!fs) { el.innerHTML = ""; return; }
    const on = lines.filter(l => l.on && l.qty > 0);
    const cents = on.reduce((t, l) => t + Math.round((Number(l.r.vendorPrice != null ? l.r.vendorPrice : l.r.price) || 0) * 100) * l.qty, 0);
    const pr = freeShipProgress_(fs, cents, on.reduce((n, l) => n + l.qty, 0));
    el.innerHTML = pr.met ? `<span style="color:#166534;">✓ Free shipping — ${escapeHtml(vendor)} ships free ${escapeHtml(freeShipText_(fs))}.</span>`
      : `<span style="color:#92400e;">Free shipping ${escapeHtml(freeShipText_(fs))}: ${escapeHtml(pr.label)}.</span>${opts.onFreeShipping ? ` <button type="button" class="admin-btn" id="soGetFree" style="padding:3px 10px;font-size:12px;">Get me to free shipping</button>` : ""}`;
    const b = $("soGetFree");
    if (b) b.onclick = () => { close(); opts.onFreeShipping(on.map(l => ({ ...l.r, toOrder: l.qty, restock: Math.max(0, l.qty - ((l.r.toOrder || 0) - (l.r.restock || 0))) }))); };
  };
  let unticked = 0;
  // restockQty: what a line buys beyond the order lines it's for (its reorder-point top-up, or an added line) — kept on
  // the supplier order so the restock isn't suggested again while it's on its way.
  const sendLines = () => lines.filter(l => l.on && l.qty > 0).map(l => ({ blankId: l.r.blankId, color: l.r.color || "", size: l.r.size || "", qty: l.qty,
    restockQty: Math.max(0, l.qty - Math.max(0, (Number(l.r.toOrder) || 0) - (Number(l.r.restock) || 0))) }));
  // The brand-rule block: styles over their large quantity without an approval, with links to the products.
  let brandDrawnFor = null;
  const drawBrandCheck_ = () => {
    const box = ov.querySelector("#soBrand");
    const bc = plan && !stale ? plan.brandCheck : null;
    if (brandDrawnFor === bc) return;   // keep the override tick / reason while the window redraws
    brandDrawnFor = bc;
    const needs = (bc && bc.needsApproval) || [], restock = (bc && bc.restockOnly) || [];
    if (!needs.length && !restock.length) { box.innerHTML = ""; return; }
    box.innerHTML = `<div style="border:1px solid #fca5a5;background:#fef2f2;border-radius:6px;padding:8px 12px;color:#7f1d1d;">
      ${needs.map(n => `<div style="margin-bottom:4px;"><b>${escapeHtml(n.brand)} ${escapeHtml(n.style)} ×${n.pieces}</b> (large is ${n.threshold}+): the supplier's logo approval isn't on file for
        ${n.missing.map(m => `<a href="#catalog/orgs/${encodeURIComponent(m.orgId)}/products/${encodeURIComponent(m.productId)}/edit" target="_blank">${escapeHtml(m.name)}</a>`).join(", ")}.${n.note ? ` <i>${escapeHtml(n.note)}</i>` : ""}</div>`).join("")}
      ${restock.map(n => `<div style="color:#92400e;margin-bottom:4px;">${escapeHtml(n.brand)} ${escapeHtml(n.style)} ×${n.pieces} is a large quantity with no order behind it — the supplier may want to review it.</div>`).join("")}
      ${needs.length ? `<label style="display:flex;gap:6px;align-items:center;margin-top:6px;"><input type="checkbox" id="soOverride"> Order anyway (admin override)</label>
        <input id="soOverrideWhy" placeholder="Why (required, recorded in the audit log)" maxlength="300" style="width:100%;box-sizing:border-box;margin-top:4px;padding:4px 6px;display:none;">` : ""}
    </div>`;
    const tick = box.querySelector("#soOverride"), why = box.querySelector("#soOverrideWhy");
    if (tick) { tick.onchange = () => { why.style.display = tick.checked ? "" : "none"; drawFoot(); }; why.oninput = () => drawFoot(); }
  };
  const check = async () => {
    const want = sendLines();
    if (!want.length) { showToast("Tick at least one line.", true); return; }
    busy = true; $("soCheck").disabled = true; $("soPlace").disabled = true;
    $("soMsg").innerHTML = `<span style="color:#555;">Asking ${escapeHtml(conn().name)}&hellip;</span>`;
    const r = await supplierOrderCall_({ action: "previewSupplierOrder", connectionId: conn().id, lines: want, itemIds: [...new Set(lines.filter(l => l.on && l.qty > 0).flatMap(l => l.r.items || []))] });
    busy = false; $("soCheck").disabled = false;
    if (!r.ok) { plan = null; stale = true; drawLines(); drawFoot(); $("soMsg").innerHTML = `<span style="color:#b03a2e;">${escapeHtml(r.d.message || "Couldn't ask the supplier")}</span>`; return; }
    plan = r.d; stale = false;
    drawShip();
    // A line the supplier can't supply at all (not a color / size it has, blank not linked…) is unticked so the rest
    // can go; one that's only short on stock stays ticked, to lower its quantity.
    unticked = 0;
    for (const l of lines) { const p = planFor(l); if (l.on && p && (p.problemKind === "part" || p.problemKind === "blank")) { l.on = false; unticked++; } }
    if (!$("soPo").value) $("soPo").value = plan.poNumber || "";
    const a = plan.shipTo || {};
    $("soShipTo").innerHTML = `Ships to <strong>${escapeHtml(a.company || "")}</strong>, ${escapeHtml([a.street1, a.city, a.state, a.zip].filter(Boolean).join(", "))} <span style="color:#888;">(Global settings → Ship-from address)</span>`;
    drawLines(); drawFoot();
  };
  const place = async () => {
    if (!plan || stale) return;
    const c = conn(), m = (c.shipMethods || [])[Number($("soShip").value)] || {};
    const po = $("soPo").value.trim();
    if (!/^[A-Za-z0-9-]{1,28}$/.test(po)) { showToast("A PO number is 1–28 letters, digits or dashes.", true); return; }
    const on = lines.filter(l => l.on && l.qty > 0);
    const cents = on.map(planFor).filter(Boolean).reduce((t, p) => t + p.unitCents * p.qty, 0);
    if (!await askConfirm_(`Place order ${po} with ${c.name}?\n\n${on.length} line${on.length === 1 ? "" : "s"}, ${on.reduce((n, l) => n + l.qty, 0)} pieces, about ${money(cents)} at our prices, ${m.label || "UPS Ground"}.\n\n${c.environment === "test"
      ? "This goes to " + c.name + "'s TEST service, marked as a test order — but some suppliers still process test orders as real ones. If " + c.name + " does, it's charged to your account's payment method and you'd have to cancel it with them."
      : "This is a real order, charged to the payment method on your " + c.name + " account."}`)) return;
    busy = true; $("soPlace").disabled = true; $("soCheck").disabled = true;
    $("soMsg").innerHTML = `<span style="color:#555;">Placing the order&hellip;</span>`;
    const r = await supplierOrderCall_({ action: "placeSupplierOrder", connectionId: c.id, lines: sendLines(), itemIds: [...new Set(on.flatMap(l => l.r.items || []))],
      carrier: m.carrier, service: m.service, poNumber: po,
      ...(ov.querySelector("#soOverride") && ov.querySelector("#soOverride").checked ? { overrideApproval: { reason: ov.querySelector("#soOverrideWhy").value.trim() } } : {}) });
    busy = false;
    if (r.ok) {
      ov.querySelector("div").innerHTML = `<h3 style="margin:0 0 10px;font-size:16px;">Order ${escapeHtml(r.d.order.poNumber)} placed with ${escapeHtml(c.name)}</h3>
        <p style="font-size:13px;">${r.d.order.lines.length} line${r.d.order.lines.length === 1 ? "" : "s"}, ${money(Math.round(r.d.order.total * 100))} at our prices${r.d.order.transactionId ? ` · confirmation ${escapeHtml(r.d.order.transactionId)}` : ""}.
          ${r.d.marked} order line${r.d.marked === 1 ? " is" : "s are"} now marked blanks ordered with this PO number.</p>
        <p style="font-size:12px;color:#666;">Tracking numbers are picked up each morning once ${escapeHtml(c.name)} ships. When the box arrives, use Receive… on this order.</p>
        <div style="text-align:right;"><button type="button" class="admin-btn" id="soDone">Done</button></div>`;
      ov.querySelector("#soDone").onclick = () => { close(); onDone && onDone(); };
      return;
    }
    if (r.d.code === "needsApproval") { plan = { ...plan, brandCheck: r.d.brandCheck }; brandDrawnFor = null; stale = false; drawLines(); drawFoot(); $("soCheck").disabled = false; return; }
    if (r.d.code === "problems" && Array.isArray(r.d.lines)) { plan = { ...plan, ...r.d }; stale = false; drawLines(); drawFoot(); $("soCheck").disabled = false; return; }
    if (r.d.order) {   // saved: refused or no answer
      ov.querySelector("div").innerHTML = `<h3 style="margin:0 0 10px;font-size:16px;color:#b03a2e;">Order ${escapeHtml(r.d.order.poNumber)} ${r.d.code === "unknown" ? "— no answer" : "was refused"}</h3>
        <p style="font-size:13px;">${escapeHtml(r.d.message || "")}</p>
        <p style="font-size:12px;color:#666;">It's listed under “Orders placed with suppliers”, with Send again. Nothing was marked ordered.</p>
        <div style="text-align:right;"><button type="button" class="admin-btn" id="soDone">Close</button></div>`;
      ov.querySelector("#soDone").onclick = () => { close(); onDone && onDone(); };
      return;
    }
    $("soCheck").disabled = false; drawFoot();
    $("soMsg").innerHTML = `<span style="color:#b03a2e;">${escapeHtml(r.d.message || "The order wasn't placed")}</span>`;
  };
  // Another connection (production ↔ test): a fresh PO number, since a test one starts TEST-.
  $("soConn").onchange = () => { plan = null; stale = true; $("soPo").value = ""; drawShip(); drawLines(); drawFoot(); check(); };
  $("soCheck").onclick = check;
  $("soPlace").onclick = place;
  drawShip(); drawLines(); drawFoot();
  check();
}

async function renderInventoryReport(app){
  adminSetHash("cogs");
  document.title = adminTitle_("Inventory & COGS");
  const y = new Date().getFullYear();
  app.innerHTML = `
    ${adminPageHead_("Inventory & COGS")}
    <div class="admin-panel" style="--org-accent:var(--accent);max-width:980px;margin:8px auto 60px;">
      <form id="cogsFilters" style="display:flex;flex-wrap:wrap;gap:10px;align-items:flex-end;background:var(--surface-alt,#f6f6f6);padding:14px 16px;border-radius:8px;margin-bottom:20px;">
        <div><label style="font-size:12px;font-weight:600;display:block;margin-bottom:3px;">From</label><input type="date" id="cogsFrom" value="${y}-01-01" style="font-size:13px;padding:5px 8px;border:1px solid #ccc;border-radius:4px;"></div>
        <div><label style="font-size:12px;font-weight:600;display:block;margin-bottom:3px;">To</label><input type="date" id="cogsTo" value="${new Date().toISOString().slice(0, 10)}" style="font-size:13px;padding:5px 8px;border:1px solid #ccc;border-radius:4px;"></div>
        <div style="display:flex;gap:6px;"><button type="submit" class="admin-pass-submit" style="padding:6px 18px;font-size:13px;">Generate</button>
          ${[y, y-1].map(yy => `<button type="button" class="cogsQuick" data-from="${yy}-01-01" data-to="${yy}-12-31" style="padding:6px 10px;font-size:12px;border:1px solid #ccc;border-radius:4px;cursor:pointer;background:var(--surface,#fff);">${yy}</button>`).join("")}</div>
      </form>
      <div style="margin:-6px 0 18px;display:flex;gap:10px;align-items:center;flex-wrap:wrap;">
        <button type="button" class="admin-btn" id="cogsCatchUp" style="font-size:13px;padding:6px 14px;">Use blanks for past orders…</button>
        <span style="font-size:12px;color:#666;">Orders made before stock was tracked (or before you entered their receipts) get their blanks taken out of stock, priced as of the day they were made.</span>
      </div>
      <div id="cogsResults"></div>
    </div>`;
  const fmt = (n) => "$" + Number(n).toFixed(2);
  const monthLabel = (m) => new Date(m + "-15T12:00:00").toLocaleDateString(undefined, { month: "short", year: "numeric" });
  const card = (k, v, sub) => `<div style="border:1px solid #ddd;border-radius:6px;padding:10px 14px;min-width:170px;background:#fff;"><div style="font-size:12px;color:#555;">${k}</div><div style="font-size:20px;font-weight:700;color:#111;">${v}</div>${sub ? `<div style="font-size:11px;color:#777;">${sub}</div>` : ""}</div>`;
  const th = "padding:8px 10px;text-align:right;background:#f0f0f0;color:#333;font-size:12px;font-weight:700;border-bottom:2px solid #ccc;";
  const td = "padding:8px 10px;text-align:right;border-bottom:1px solid #ddd;color:#111;background:#fff;";
  async function load(){
    const el = document.getElementById("cogsResults");
    // A reload keeps the current results on screen (dimmed) instead of swapping them for "Loading…", so the page
    // doesn't jump back to the top; the first load shows "Loading…".
    if (el.children.length) el.style.opacity = ".5";
    else el.innerHTML = `<div style="color:#888;font-size:14px;padding:20px 0;">Loading…</div>`;
    if (!adminKey) adminKey = (await adminLogin()) || "";
    if (!adminKey) return;
    try {
      const r = await fetch("/api/orders", { method: "POST", headers: {"Content-Type":"application/json"},
        body: JSON.stringify({ action: "getInventoryReport", key: adminKey, dateFrom: document.getElementById("cogsFrom").value, dateTo: document.getElementById("cogsTo").value }) });
      const d = await r.json();
      if (!r.ok || d.status === "error") { el.innerHTML = `<div style="color:#b03a2e;padding:20px 0;">${escapeHtml((d && d.message) || "Error loading report.")}</div>`; return; }
      const t = d.totals, g = d.groups || null, rf = d.rollForward || null;
      // Three inventory groups (migrations/0060): blanks for sale, blanks for testing / shop use, and
      // finished stock (decorated pieces on a shop's site). Their roll-forward is Schedule C Part III.
      const unitsVal = (x) => x ? `${fmt(x.value)} <span style="color:#777;font-size:12px;">· ${x.units} units</span>` : "—";
      const orgName = (id) => ((adminOrgs || []).find(o => o.orgId === id) || {}).name || id;
      const line = (label, v, opts = {}) => `<tr${opts.sub ? ' class="cogs-sub"' : ""}><td style="${td}text-align:left;${opts.sub ? "padding-left:28px;color:#555;font-size:13px;" : ""}${opts.bold ? "font-weight:700;" : ""}">${label}</td><td style="${td}${opts.bold ? "font-weight:700;" : ""}${opts.sub ? "color:#555;font-size:13px;" : ""}">${v}</td></tr>`;
      const stockTable = (title, rows, cls) => `<h3 style="margin:18px 0 8px;font-size:15px;">${title}</h3>
        <div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;"><table class="${cls}" style="width:100%;border-collapse:collapse;font-size:13px;">
          <thead><tr><th style="${th}text-align:left;">Blank</th><th style="${th}text-align:left;">Color</th><th style="${th}text-align:left;">Size</th><th style="${th}">On hand</th><th style="${th}">Avg cost</th><th style="${th}">Value</th></tr></thead>
          <tbody>${rows.map(r => `<tr><td style="${td}text-align:left;">${escapeHtml(r.name)}</td><td style="${td}text-align:left;">${escapeHtml(r.color || "—")}</td><td style="${td}text-align:left;">${escapeHtml(r.size || "—")}</td><td style="${td}${r.qty < 0 ? "color:#b03a2e;" : ""}">${r.qty}</td><td style="${td}">${fmt(r.avgCost)}</td><td style="${td}">${fmt(r.value)}</td></tr>`).join("") || `<tr><td colspan="6" style="${td}text-align:left;color:#888;">None.</td></tr>`}</tbody>
        </table></div>`;
      const finishedRows = (d.finished && d.finished.ending && d.finished.ending.rows) || [];
      const checkOff = rf && Math.abs(rf.check) >= 0.05;
      el.innerHTML = `
        <div style="font-size:13px;color:#555;margin-bottom:10px;">At weighted-average cost. Blanks come out of stock when pieces are made (or decorated for stock); finished stock leaves when an order is made. Stock history starts when inventory tracking was switched on; costs for orders made before then are estimates from their linked blanks.</div>
        ${g ? `<h3 style="margin:0 0 8px;font-size:15px;">Inventory by group</h3>
        <div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;margin-bottom:16px;"><table class="cogs-groups" style="width:100%;border-collapse:collapse;font-size:14px;">
          <thead><tr><th style="${th}text-align:left;">Group</th><th style="${th}">Beginning</th><th style="${th}">Ending</th></tr></thead>
          <tbody>
            <tr><td style="${td}text-align:left;">Blanks for sale</td><td style="${td}">${unitsVal(g.forSale.beginning)}</td><td style="${td}">${unitsVal(g.forSale.ending)}</td></tr>
            <tr><td style="${td}text-align:left;">Blanks for testing / shop use <div style="font-size:11px;color:#777;">Could still be sold — marked on the blank (Blanks → Edit)</div></td><td style="${td}">${unitsVal(g.testing.beginning)}</td><td style="${td}">${unitsVal(g.testing.ending)}</td></tr>
            <tr><td style="${td}text-align:left;">Finished stock <div style="font-size:11px;color:#777;">Decorated for a shop, listed as in stock on its site (Products → Stock)</div></td><td style="${td}">${unitsVal(g.finished.beginning)}</td><td style="${td}">${unitsVal(g.finished.ending)}</td></tr>
            <tr><td style="${td}text-align:left;font-weight:700;">All inventory</td><td style="${td}font-weight:700;">${fmt(rf ? rf.beginning : d.beginning.value)}</td><td style="${td}font-weight:700;">${fmt(rf ? rf.ending : d.ending.value)}</td></tr>
          </tbody></table></div>` : ""}
        <h3 style="margin:0 0 8px;font-size:15px;">Roll-forward <span style="font-weight:400;color:#777;font-size:12px;">(Schedule C Part III)</span></h3>
        <div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;margin-bottom:6px;max-width:560px;"><table class="cogs-rollforward" style="width:100%;border-collapse:collapse;font-size:14px;"><tbody>
          ${line("Beginning inventory", fmt(rf ? rf.beginning : d.beginning.value), { bold: true })}
          ${line("+ Purchases", fmt(t.purchases))}
          ${t.corrections ? line("± Count corrections and opening balances", fmt(t.corrections)) : ""}
          ${line("− Cost of goods sold", fmt(t.cogs))}
          ${line("blanks used on orders", fmt(t.cogsBlanks || 0), { sub: true })}
          ${line("finished stock sold", fmt(t.cogsFinished || 0), { sub: true })}
          ${t.estimatedPart > 0 ? line("estimated, orders made before tracking", fmt(t.estimatedPart), { sub: true }) : ""}
          ${line("− Write-offs", fmt(t.writeoffs))}
          ${line("used for testing / shop use", fmt(t.writeoffsTesting || 0), { sub: true })}
          ${line("damaged or lost", fmt(t.writeoffsDamagedLost || 0), { sub: true })}
          ${(t.writeoffsOther || 0) > 0 ? line("other", fmt(t.writeoffsOther), { sub: true }) : ""}
          ${(t.toFinished || 0) > 0 ? line("Blanks → finished stock <span style='color:#777;font-size:12px;'>(moved between groups — nets to $0)</span>", fmt(t.toFinished)) : ""}
          ${line("Ending inventory", fmt(rf ? rf.ending : d.ending.value), { bold: true })}
        </tbody></table></div>
        ${rf ? `<div class="cogs-check" style="font-size:12px;margin-bottom:16px;color:${checkOff ? "#b03a2e" : "#166534"};">${checkOff
          ? `Doesn't add up by ${fmt(rf.check)} — usually stock that went below zero (made or written off before its receipt was entered) or an order whose blanks were never taken out. ${t.estimatedPart > 0 ? "Estimated costs are left out of this check (they never left recorded stock). " : ""}`
          : `Adds up${t.estimatedPart > 0 ? " (estimated costs are left out — they never left recorded stock)" : ""}.`}</div>` : ""}
        <div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;margin-bottom:18px;"><table class="cogs-months" style="width:100%;border-collapse:collapse;font-size:13px;">
          <thead><tr><th style="${th}text-align:left;">Month</th><th style="${th}">Units used</th><th style="${th}">COGS</th><th style="${th}">…from finished stock</th><th style="${th}">…estimated</th><th style="${th}">Purchases</th><th style="${th}">Blanks → finished</th><th style="${th}">Write-offs: testing</th><th style="${th}">Write-offs: other</th></tr></thead>
          <tbody>${d.cogs.rows.length ? d.cogs.rows.map(r => `<tr><td style="${td}text-align:left;">${escapeHtml(monthLabel(r.month))}</td><td style="${td}">${r.unitsUsed}</td><td style="${td}font-weight:600;">${fmt(r.cogs)}</td><td style="${td}">${r.cogsFinished > 0 ? fmt(r.cogsFinished) : "—"}</td><td style="${td}">${r.estimatedPart > 0 ? fmt(r.estimatedPart) : "—"}</td><td style="${td}">${r.purchases > 0 ? fmt(r.purchases) : "—"}</td><td style="${td}">${r.toFinished > 0 ? fmt(r.toFinished) : "—"}</td><td style="${td}">${r.writeoffsTesting > 0 ? fmt(r.writeoffsTesting) : "—"}</td><td style="${td}">${(r.writeoffs - (r.writeoffsTesting || 0)) > 0.004 ? fmt(r.writeoffs - (r.writeoffsTesting || 0)) : "—"}</td></tr>`).join("")
            : `<tr><td colspan="9" style="${td}text-align:left;color:#888;">No inventory activity in this period.</td></tr>`}</tbody>
        </table></div>
        ${(d.taxedResale || []).length ? `<div style="border:1px solid #fcd34d;background:#fffbeb;border-radius:6px;padding:10px 14px;font-size:13px;color:#78350f;margin-bottom:18px;">
          <strong>Sales tax was paid on ${d.taxedResale.length} blank purchase${d.taxedResale.length === 1 ? "" : "s"}</strong> — blanks you resell should be bought tax-free with a resale certificate. Give the vendor your certificate and ask about a refund:
          <ul style="margin:6px 0 0 18px;">${d.taxedResale.slice(0, 20).map(t => `<li>${escapeHtml(String(t.date).slice(0, 10))} — ${escapeHtml(t.vendor || "vendor?")}${t.invoice ? " #" + escapeHtml(t.invoice) : ""}: ${escapeHtml(t.blank)}${t.size ? " (" + escapeHtml(t.size) + ")" : ""} × ${t.qty}, $${Number(t.cost).toFixed(2)}</li>`).join("")}</ul></div>` : ""}
        ${missingCostHtml_(d.cogs.missingCost)}
        <div style="font-size:13px;color:#555;margin:18px 0 0;">Ending inventory — ${escapeHtml(new Date(d.dateTo + "T12:00:00").toLocaleDateString())}</div>
        ${stockTable("Blanks for sale", d.ending.rows.filter(r => !r.forTesting), "cogs-end-sale")}
        ${stockTable("Blanks for testing / shop use", d.ending.rows.filter(r => r.forTesting), "cogs-end-testing")}
        <h3 style="margin:18px 0 8px;font-size:15px;">Finished stock</h3>
        <div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;"><table class="cogs-end-finished" style="width:100%;border-collapse:collapse;font-size:13px;">
          <thead><tr><th style="${th}text-align:left;">Product</th><th style="${th}text-align:left;">Shop</th><th style="${th}text-align:left;">Size</th><th style="${th}">On hand</th><th style="${th}">Avg cost</th><th style="${th}">Value</th></tr></thead>
          <tbody>${finishedRows.map(r => `<tr><td style="${td}text-align:left;">${escapeHtml(r.name || r.productId)}</td><td style="${td}text-align:left;">${escapeHtml(orgName(r.orgId))}</td><td style="${td}text-align:left;">${escapeHtml(r.size || "—")}</td><td style="${td}${r.qty < 0 ? "color:#b03a2e;" : ""}">${r.qty}</td><td style="${td}">${fmt(r.avgCost)}</td><td style="${td}">${fmt(r.value)}</td></tr>`).join("") || `<tr><td colspan="6" style="${td}text-align:left;color:#888;">None.</td></tr>`}</tbody>
        </table></div>
        ${d.transfers ? `<h3 style="margin:22px 0 8px;font-size:15px;">Transfer sheets</h3>
        <div style="display:flex;flex-wrap:wrap;gap:12px;margin-bottom:12px;">
          ${card("Beginning", fmt(d.transfers.beginning.value), d.transfers.beginning.units + " on hand")}
          ${card("+ Purchases", fmt(d.transfers.totals.purchases))}
          ${card("− COGS", fmt(d.transfers.totals.cogs))}
          ${card("− Write-offs", fmt(d.transfers.totals.writeoffs))}
          ${card("Ending", fmt(d.transfers.ending.value), d.transfers.ending.units + " on hand")}
        </div>
        <div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;"><table style="width:100%;border-collapse:collapse;font-size:13px;">
          <thead><tr><th style="${th}text-align:left;">Transfer</th><th style="${th}">On hand</th><th style="${th}">Avg cost</th><th style="${th}">Value</th></tr></thead>
          <tbody>${d.transfers.ending.rows.map(r => `<tr><td style="${td}text-align:left;">${escapeHtml(r.name)}</td><td style="${td}${r.qty < 0 ? "color:#b03a2e;" : ""}">${r.qty}</td><td style="${td}">${fmt(r.avgCost)}</td><td style="${td}">${fmt(r.value)}</td></tr>`).join("") || `<tr><td colspan="4" style="${td}text-align:left;color:#888;">No transfer stock.</td></tr>`}</tbody>
        </table></div>` : ""}`;
    } catch (e) { el.innerHTML = `<div style="color:#b03a2e;padding:20px 0;">Network error.</div>`; }
    finally { el.style.opacity = ""; }
  }
  document.getElementById("cogsFilters").addEventListener("submit", (e) => { e.preventDefault(); load(); });
  document.getElementById("cogsCatchUp").addEventListener("click", () => showBlankCatchUp_(load));
  // The "Use blanks for past orders…" button inside the linked-now notice opens the same window.
  document.getElementById("cogsResults").addEventListener("click", (e) => { if (e.target.closest(".cogs-catchup-inline")) showBlankCatchUp_(load); });
  document.querySelectorAll(".cogsQuick").forEach(b => b.addEventListener("click", () => {
    document.getElementById("cogsFrom").value = b.dataset.from; document.getElementById("cogsTo").value = b.dataset.to; load(); }));
  load();
}

// ---- Accounts & money (migrations/0014) ---------------------------------------
// Accounts list shared by the expense form, Receive blanks and the payments
// modal. Refreshed whenever the Accounts screen saves.
let _accountsCache = null;
async function loadAccounts_(force){
  // Accounts belong to Bookkeeping: with it off there are none to choose from (the forms that offer
  // a "paid from" hide it), and nothing is asked of the server.
  if (!adminFeatureOn_("bookkeeping")) return { accounts: [], otherIncomeTypes: {}, defaults: {} };
  if (_accountsCache && !force) return _accountsCache;
  if (!adminKey) adminKey = (await adminLogin()) || "";
  const r = await fetch("/api/orders", { method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify({ action: "listAccounts", key: adminKey }) });
  const d = await r.json().catch(() => ({ status: "error" }));
  if (!r.ok || d.status === "error") throw new Error((d && d.message) || "Could not load accounts");
  _accountsCache = d;
  return d;
}
// <option>s for active accounts (plus an optional "Personal funds" choice).
function accountOptions_(accounts, selected, { personal = false, blank = false } = {}){
  return (blank ? `<option value="">Choose…</option>` : "") +
    accounts.filter(a => a.active || String(a.id) === String(selected)).map(a => `<option value="${a.id}"${String(a.id) === String(selected) ? " selected" : ""}>${escapeHtml(a.name)}</option>`).join("") +
    (personal ? `<option value="personal"${selected === "personal" ? " selected" : ""}>Personal funds (owner paid)</option>` : "");
}
const METHOD_ACCOUNT_TYPE = { card: "stripe", venmo: "venmo", cash: "cash", zelle: "checking", check: "checking", other: "checking" };
function accountForMethod_(accounts, method){
  const a = accounts.find(x => x.active && x.type === (METHOD_ACCOUNT_TYPE[method] || "checking"));
  return a ? a.id : (accounts[0] && accounts[0].id);
}

async function renderMoney(app){
  adminSetHash("money");
  document.title = adminTitle_("Accounts & money");
  const y = new Date().getFullYear();
  const inp = "font-size:13px;padding:5px 7px;border:1px solid #ccc;border-radius:4px;box-sizing:border-box;";
  const lbl = "display:block;font-size:12px;font-weight:600;margin-bottom:3px;";
  app.innerHTML = `
    ${adminPageHead_("Accounts & money")}
    <div class="admin-panel" style="--org-accent:var(--accent);max-width:1040px;margin:8px auto 60px;">
      <div style="display:flex;gap:10px;align-items:flex-end;flex-wrap:wrap;margin-bottom:16px;">
        <div><label style="${lbl}" for="mnYear">Year</label><select id="mnYear" style="${inp}">${[y, y - 1, y - 2].map(v => `<option>${v}</option>`).join("")}</select></div>
      </div>
      <div id="mnBody" style="font-size:14px;color:#888;">Loading…</div>
    </div>`;
  document.getElementById("mnYear").onchange = () => mnLoad_();
  await mnLoad_();
}

async function mnApi_(body){
  if (!adminKey) adminKey = (await adminLogin()) || "";
  const r = await fetch("/api/orders", { method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify(Object.assign({ key: adminKey }, body)) });
  const d = await r.json().catch(() => ({ status: "error", message: "Server error (" + r.status + ")" }));
  if (!r.ok || d.status === "error") throw new Error((d && d.message) || "Request failed");
  return d;
}

async function mnLoad_(){
  const el = document.getElementById("mnBody");
  const yr = document.getElementById("mnYear").value;
  let acc, d;
  try {
    acc = await loadAccounts_(true);
    d = await mnApi_({ action: "listMoney", dateFrom: `${yr}-01-01`, dateTo: `${yr}-12-31` });
  } catch (e) { el.textContent = e.message; return; }
  const accounts = acc.accounts, types = acc.accountTypes, incomeTypes = d.otherIncomeTypes;
  const name = (id) => (accounts.find(a => a.id === Number(id)) || {}).name || "—";
  const fmt = (n) => (n < 0 ? "−$" : "$") + Math.abs(Number(n || 0)).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const inp = "font-size:13px;padding:5px 7px;border:1px solid #ccc;border-radius:4px;box-sizing:border-box;";
  const lbl = "display:block;font-size:12px;font-weight:600;margin-bottom:3px;";
  const th = "padding:7px 10px;text-align:left;background:#f0f0f0;color:#333;font-size:12px;font-weight:700;border-bottom:2px solid #ccc;";
  const td = "padding:7px 10px;border-bottom:1px solid #e5e7eb;vertical-align:middle;color:#111;background:#fff;";
  const today = new Date().toLocaleDateString("en-CA");
  const s = d.summary;
  const del = (kind, id) => `<button type="button" data-kind="${kind}" data-id="${id}" class="mn-del admin-btn-danger" style="padding:2px 8px;font-size:12px;border-radius:4px;cursor:pointer;">Delete</button>`;
  const table = (heads, rows, empty) => `<div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;"><table style="width:100%;border-collapse:collapse;font-size:14px;">
      <thead><tr>${heads.map(h => `<th style="${th}${/Amount|Balance/.test(h) ? "text-align:right;" : ""}">${h}</th>`).join("")}</tr></thead>
      <tbody>${rows.length ? rows.join("") : `<tr><td colspan="${heads.length}" style="${td}color:#888;">${empty}</td></tr>`}</tbody></table></div>`;

  // Blanks & transfers bought this year (listStockPurchases): inventory, not expenses — each becomes cost
  // of goods sold as it's used. One row per receive, with its receipt. Edited and voided where it was
  // received (Blanks → History, Transfers → History), not here.
  const stock = d.stockPurchases || [];
  const stockTotal = (k) => stock.filter(x => !k || x.kind === k).reduce((t, x) => t + Number(x.total || 0), 0);
  const stockSection = `
    <h2 style="font-size:17px;margin:0 0 6px;">Blanks &amp; transfers bought</h2>
    <p style="font-size:13px;color:#555;margin:0 0 8px;">Stock bought for orders — garment blanks and transfer sheets. It isn't an expense: it's inventory, and becomes cost of goods sold as it's used (see <a href="#cogs">Inventory &amp; COGS</a>). Amounts include shipping spread into the cost; an R&amp;D or personal part of the same order is listed under Expenses or Owner draws. If the wrong account was chosen, <strong>Change account…</strong> fixes the whole receipt at once (every blank on it, plus its R&amp;D expense and personal draw). To void one, use the history on <a href="#inventory">Blanks</a> or <a href="#transfers">Transfers</a>.</p>
    ${stock.length ? `<div style="font-size:13px;color:#555;margin:0 0 8px;">${stock.length} purchase${stock.length === 1 ? "" : "s"} · ${fmt(stockTotal())} (blanks ${fmt(stockTotal("blanks"))}, transfers ${fmt(stockTotal("transfers"))})</div>` : ""}
    <div id="mnStock" style="margin-bottom:24px;">${table(["Date", "Bought", "Vendor", "Paid from", "Amount", ""], stock.map(x => `<tr>
        <td style="${td}white-space:nowrap;">${escapeHtml(x.date)}</td>
        <td style="${td}"><span style="font-size:11px;font-weight:700;color:#555;text-transform:uppercase;letter-spacing:.04em;">${x.kind === "transfers" ? "Transfers" : "Blanks"}</span><br>${x.items.map(escapeHtml).join("<br>")}${(x.extras || []).map(e => `<div style="font-size:12px;color:#555;">+ ${escapeHtml(e.label)} ${fmt(e.amount)}</div>`).join("")}</td>
        <td style="${td}">${escapeHtml(x.vendor || "—")}${x.vendorRef ? `<div style="font-size:12px;color:#666;">#${escapeHtml(x.vendorRef)}</div>` : ""}${x.vendorChargedTax ? `<div style="font-size:11px;color:#b45309;">sales tax charged</div>` : ""}</td>
        <td style="${td}">${x.paidPersonally ? "Personal funds" : x.accountId ? escapeHtml(x.accountName || name(x.accountId)) : `<span style="color:#b45309;">not set</span>`}</td>
        <td style="${td}text-align:right;white-space:nowrap;">${fmt(x.total)}</td>
        <td style="${td}">${x.receiptKey ? `<button type="button" class="admin-btn" style="padding:3px 8px;font-size:12px;" title="${escapeHtml(x.receiptName || "Receipt")}" data-key="${escapeHtml(x.receiptKey)}" onclick="expViewReceipt_(this.dataset.key)">📎 Receipt</button>` : `<span style="font-size:12px;color:#999;">no receipt</span>`}
          <div style="margin-top:4px;"><button type="button" class="admin-btn mn-stock-acct" style="padding:3px 8px;font-size:12px;" data-kind="${escapeHtml(x.kind)}" data-id="${Number(x.ids[0])}">Change account…</button></div></td></tr>`),
      "No blanks or transfers bought in " + escapeHtml(yr) + ".")}</div>`;

  el.style.color = "var(--ink,#111)";
  el.innerHTML = `
    ${s.unassigned ? `<div style="border:1px solid #fcd34d;background:#fffbeb;border-radius:6px;padding:8px 12px;margin-bottom:14px;font-size:13px;color:#78350f;">${s.unassigned} payment/expense/stock purchase${s.unassigned === 1 ? " has" : "s have"} no account yet — edit ${s.unassigned === 1 ? "it" : "them"} and choose where the money went, or the balances below won't match your statements.</div>` : ""}
    <h2 style="font-size:17px;margin:0 0 6px;">Accounts</h2>
    <p style="font-size:13px;color:#555;margin:0 0 8px;">Set each account's balance on its opening date once (from that day's statement); the balance shown is computed from everything recorded since. A credit card shows what's owed as a negative balance.</p>
    ${table(["Name", "Type", "Opening date", "Opening balance", "Balance today", "Active", ""], accounts.map(a => `<tr data-acc="${a.id}">
        <td style="${td}"><input data-f="name" value="${escapeHtml(a.name)}" maxlength="60" style="${inp}width:170px;"></td>
        <td style="${td}"><select data-f="type" style="${inp}">${Object.entries(types).map(([k, v]) => `<option value="${k}"${k === a.type ? " selected" : ""}>${escapeHtml(v)}</option>`).join("")}</select></td>
        <td style="${td}"><input data-f="openingDate" type="date" value="${escapeHtml(a.openingDate)}" style="${inp}"></td>
        <td style="${td}"><input data-f="openingBalance" type="number" step="0.01" value="${Number(a.openingBalance).toFixed(2)}" style="${inp}width:110px;"></td>
        <td style="${td}text-align:right;font-weight:600;">${fmt(a.balance)}</td>
        <td style="${td}text-align:center;"><input data-f="active" type="checkbox" ${a.active ? "checked" : ""}></td>
        <td style="${td}"><button type="button" class="admin-btn mn-acc-save" style="padding:3px 10px;font-size:12px;">Save</button></td></tr>`).concat([`<tr data-acc="new">
        <td style="${td}"><input data-f="name" placeholder="New account" maxlength="60" style="${inp}width:170px;"></td>
        <td style="${td}"><select data-f="type" style="${inp}">${Object.entries(types).map(([k, v]) => `<option value="${k}">${escapeHtml(v)}</option>`).join("")}</select></td>
        <td style="${td}"><input data-f="openingDate" type="date" value="${yearStartOrToday_()}" style="${inp}"></td>
        <td style="${td}"><input data-f="openingBalance" type="number" step="0.01" value="0.00" style="${inp}width:110px;"></td>
        <td style="${td}"></td><td style="${td}text-align:center;"><input data-f="active" type="checkbox" checked></td>
        <td style="${td}"><button type="button" class="admin-btn mn-acc-save" style="padding:3px 10px;font-size:12px;">Add</button></td></tr>`]), "")}
    <div style="display:flex;gap:10px;align-items:flex-end;flex-wrap:wrap;margin:10px 0 24px;font-size:13px;">
      <label>Shippo postage is charged to<br><select id="mnPostage" style="${inp}">${accountOptions_(accounts, acc.defaults.postageAccountId)}</select></label>
      <label>Stripe pays out to<br><select id="mnPayout" style="${inp}">${accountOptions_(accounts, acc.defaults.payoutAccountId)}</select></label>
      <button type="button" class="admin-btn" id="mnDefaultsSave" style="padding:5px 12px;font-size:12px;">Save defaults</button>
      <span style="font-size:12px;color:#666;">Payouts are recorded automatically once <code>payout.paid</code> is ticked on your Stripe webhook.</span>
    </div>

    <h2 style="font-size:17px;margin:0 0 8px;">${escapeHtml(document.getElementById("mnYear").value)} summary</h2>
    <div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:24px;">
      ${[["Services income (line 1)", s.otherIncome.service], ["Other income (line 6)", s.otherIncome.other], ["Interest (Schedule B)", s.otherIncome.interest],
         ["Owner put in", s.owner.totalIn, s.owner.paidPersonally ? `incl. ${fmt(s.owner.paidPersonally)} of expenses and stock paid personally` : ""], ["Owner took out", s.owner.draws]]
        .map(([k, v, note]) => `<div style="flex:1;min-width:150px;border:1px solid #ddd;border-radius:6px;padding:10px 12px;background:#fff;"><div style="font-size:12px;color:#666;">${k}</div><div style="font-size:19px;font-weight:700;">${fmt(v)}</div>${note ? `<div style="font-size:11px;color:#777;">${note}</div>` : ""}</div>`).join("")}
    </div>

    ${stockSection}

    <h2 style="font-size:17px;margin:0 0 6px;">Other income</h2>
    <p style="font-size:13px;color:#555;margin:0 0 8px;">Money earned outside storefront orders. Goods you sell in person belong in <strong>Local sale</strong> (so sales tax applies); use this for services (e.g. digitizing for others), other business income, and bank interest.</p>
    <div class="mn-form" data-kind="income" style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end;margin-bottom:8px;">
      <div><label style="${lbl}">Date</label><input data-f="date" type="date" max="${today}" value="${today}" style="${inp}"></div>
      <div style="flex:1;min-width:180px;"><label style="${lbl}">Description</label><input data-f="description" maxlength="300" style="${inp}width:100%;"></div>
      <div><label style="${lbl}">Type</label><select data-f="type" style="${inp}">${Object.entries(incomeTypes).map(([k, v]) => `<option value="${k}">${escapeHtml(v)}</option>`).join("")}</select></div>
      <div><label style="${lbl}">Amount ($)</label><input data-f="amount" type="number" min="0.01" step="0.01" style="${inp}width:100px;"></div>
      <div><label style="${lbl}">Into</label><select data-f="accountId" style="${inp}">${accountOptions_(accounts, accounts[0] && accounts[0].id)}</select></div>
      <div><label style="${lbl}">Reference</label><input data-f="reference" maxlength="100" style="${inp}width:110px;"></div>
      <button type="button" class="admin-pass-submit mn-save" style="padding:6px 14px;font-size:13px;">Add</button>
    </div>
    ${table(["Date", "Description", "Type", "Into", "Amount", ""], d.income.map(i => `<tr><td style="${td}">${escapeHtml(i.date)}</td><td style="${td}">${escapeHtml(i.description)}${i.reference ? `<br><span style="font-size:12px;color:#666;">${escapeHtml(i.reference)}</span>` : ""}</td>
      <td style="${td}">${escapeHtml(incomeTypes[i.type] || i.type)}</td><td style="${td}">${escapeHtml(name(i.accountId))}</td><td style="${td}text-align:right;">${fmt(i.amount)}</td><td style="${td}">${del("income", i.id)}</td></tr>`), "None this year.")}

    <h2 style="font-size:17px;margin:24px 0 6px;">Owner contributions &amp; draws</h2>
    <p style="font-size:13px;color:#555;margin:0 0 8px;">Money you put into the business or take out for yourself — not income or expenses, but your CPA needs them. Expenses marked “Personal funds” count as money put in automatically.</p>
    <div class="mn-form" data-kind="owner" style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end;margin-bottom:8px;">
      <div><label style="${lbl}">Date</label><input data-f="date" type="date" max="${today}" value="${today}" style="${inp}"></div>
      <div><label style="${lbl}">Type</label><select data-f="kind" style="${inp}"><option value="contribution">Put money in</option><option value="draw">Took money out</option></select></div>
      <div><label style="${lbl}">Amount ($)</label><input data-f="amount" type="number" min="0.01" step="0.01" style="${inp}width:100px;"></div>
      <div><label style="${lbl}">Account</label><select data-f="accountId" style="${inp}">${accountOptions_(accounts, accounts[0] && accounts[0].id)}</select></div>
      <div style="flex:1;min-width:160px;"><label style="${lbl}">Note</label><input data-f="note" maxlength="300" style="${inp}width:100%;"></div>
      <button type="button" class="admin-pass-submit mn-save" style="padding:6px 14px;font-size:13px;">Add</button>
    </div>
    ${table(["Date", "Type", "Account", "Note", "Amount", ""], d.owner.map(o => `<tr><td style="${td}">${escapeHtml(o.date)}</td><td style="${td}">${o.kind === "contribution" ? "Put in" : "Took out"}</td>
      <td style="${td}">${escapeHtml(name(o.accountId))}</td><td style="${td}">${escapeHtml(o.note)}</td><td style="${td}text-align:right;">${fmt(o.amount)}</td><td style="${td}">${del("owner", o.id)}</td></tr>`), "None this year.")}

    <h2 style="font-size:17px;margin:24px 0 6px;">Transfers between accounts</h2>
    <p style="font-size:13px;color:#555;margin:0 0 8px;">Venmo to the bank, depositing cash, paying the credit card. Stripe payouts appear here automatically.</p>
    <div class="mn-form" data-kind="transfer" style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end;margin-bottom:8px;">
      <div><label style="${lbl}">Date</label><input data-f="date" type="date" max="${today}" value="${today}" style="${inp}"></div>
      <div><label style="${lbl}">From</label><select data-f="fromAccountId" style="${inp}">${accountOptions_(accounts, (accounts.find(a => a.type === "venmo") || accounts[0] || {}).id)}</select></div>
      <div><label style="${lbl}">To</label><select data-f="toAccountId" style="${inp}">${accountOptions_(accounts, (accounts.find(a => a.type === "checking") || accounts[0] || {}).id)}</select></div>
      <div><label style="${lbl}">Amount ($)</label><input data-f="amount" type="number" min="0.01" step="0.01" style="${inp}width:100px;"></div>
      <div style="flex:1;min-width:160px;"><label style="${lbl}">Note</label><input data-f="note" maxlength="300" style="${inp}width:100%;"></div>
      <button type="button" class="admin-pass-submit mn-save" style="padding:6px 14px;font-size:13px;">Add</button>
    </div>
    ${table(["Date", "From", "To", "Note", "Amount", ""], d.transfers.map(t => `<tr><td style="${td}">${escapeHtml(t.date)}</td><td style="${td}">${escapeHtml(name(t.fromAccountId))}</td>
      <td style="${td}">${escapeHtml(name(t.toAccountId))}</td><td style="${td}">${escapeHtml(t.note)}${t.externalRef ? ` <span style="font-size:11px;color:#666;">(automatic)</span>` : ""}</td>
      <td style="${td}text-align:right;">${fmt(t.amount)}</td><td style="${td}">${t.externalRef ? "" : del("transfer", t.id)}</td></tr>`), "None this year.")}
    <div id="mnErr" style="color:#b03a2e;font-size:13px;min-height:18px;margin-top:10px;"></div>`;

  const err = el.querySelector("#mnErr");
  el.querySelectorAll(".mn-acc-save").forEach(b => b.onclick = async () => {
    const tr = b.closest("tr"), f = (k) => tr.querySelector(`[data-f="${k}"]`);
    err.textContent = "";
    try {
      await mnApi_({ action: "saveAccount", account: { id: tr.dataset.acc === "new" ? undefined : Number(tr.dataset.acc), name: f("name").value.trim(),
        type: f("type").value, openingDate: f("openingDate").value, openingBalance: parseFloat(f("openingBalance").value) || 0, active: f("active").checked } });
      showToast("Account saved."); await keepView_(mnLoad_);
    } catch (e) { err.textContent = e.message; }
  });
  el.querySelector("#mnDefaultsSave").onclick = async () => {
    err.textContent = "";
    try { await mnApi_({ action: "saveMoneyDefaults", defaults: { postageAccountId: Number(el.querySelector("#mnPostage").value), payoutAccountId: Number(el.querySelector("#mnPayout").value) } });
      showToast("Defaults saved."); _accountsCache = null; }
    catch (e) { err.textContent = e.message; }
  };
  el.querySelectorAll(".mn-save").forEach(b => b.onclick = async () => {
    const form = b.closest(".mn-form"), entry = {};
    form.querySelectorAll("[data-f]").forEach(x => { entry[x.dataset.f] = x.value; });
    entry.amount = parseFloat(entry.amount);
    err.textContent = "";
    try { await mnApi_({ action: "saveMoneyEntry", kind: form.dataset.kind, entry }); showToast("Saved."); await keepView_(mnLoad_); }
    catch (e) { err.textContent = e.message; }
  });
  el.querySelectorAll(".mn-stock-acct").forEach(b => b.onclick = () => mnChangeReceiptAccount_(b.dataset.kind, Number(b.dataset.id)));
  el.querySelectorAll(".mn-del").forEach(b => b.onclick = async () => {
    if (!await askConfirm_("Delete this entry? It's removed from all totals (kept in the audit log).")) return;
    err.textContent = "";
    try { await mnApi_({ action: "deleteMoneyEntry", kind: b.dataset.kind, id: Number(b.dataset.id) }); showToast("Deleted."); await keepView_(mnLoad_); }
    catch (e) { err.textContent = e.message; }
  });
}
// Change the paying account of a whole received receipt. The server finds every record the receipt wrote (the stock rows
// for every blank on it, its R&D / written-off expense, its personal-use draw), the window lists them, and one Save moves
// them all. Anything that would make the move wrong (a statement match, a reconciled month, a closed month) is said up front.
async function mnChangeReceiptAccount_(kind, movementId){
  const { ov, close } = inventoryModal_("Change account — whole receipt", `<div id="rcaBody" style="font-size:13px;color:#777;">Loading…</div>`, 560);
  const body = ov.querySelector("#rcaBody");
  const fmt = (n) => "$" + Math.abs(Number(n || 0)).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  let acc, pv;
  try { acc = await loadAccounts_(true); pv = await mnApi_({ action: "previewReceiptAccountChange", kind, movementId }); }
  catch (e) { body.textContent = e.message; return; }
  const r = pv.receipt;
  const current = r.paidPersonally ? "personal" : (r.accountId ? String(r.accountId) : "");
  body.style.color = "#1a1a1a";
  body.innerHTML = `
    <div style="margin-bottom:8px;"><strong>${escapeHtml(r.vendor || "Receipt")}</strong>${r.vendorRef ? " #" + escapeHtml(r.vendorRef) : ""} · ${escapeHtml(r.date)}</div>
    <div style="font-size:12px;color:#555;margin-bottom:6px;">Everything below moves to the account you choose:</div>
    <ul id="rcaList" style="margin:0 0 10px 18px;padding:0;font-size:13px;">
      <li>${r.stock.length} stock line${r.stock.length === 1 ? "" : "s"} · ${fmt(r.stockTotal)}<div style="font-size:12px;color:#666;">${r.stock.slice(0, 8).map(x => escapeHtml(x.label) + " ×" + x.qty).join("<br>")}${r.stock.length > 8 ? "<br>… and " + (r.stock.length - 8) + " more" : ""}</div></li>
      ${r.expense ? `<li>Expense: ${escapeHtml(r.expense.description)} · ${fmt(r.expense.amount)}</li>` : ""}
      ${r.draw ? `<li>Owner draw: ${escapeHtml(r.draw.note)} · ${fmt(r.draw.amount)}</li>` : ""}
    </ul>
    ${r.via === "match" ? `<div style="font-size:12px;color:#92400e;margin-bottom:8px;">This receipt was recorded before records were linked, so these were found by matching the date, vendor, invoice and account. Check the list above is the whole receipt.</div>` : ""}
    <label style="font-size:12px;font-weight:600;">Paid from<br><select id="rcaAccount" style="font-size:13px;padding:5px 7px;border:1px solid #ccc;border-radius:4px;min-width:240px;">${accountOptions_(acc.accounts, current, { personal: true, blank: !current })}</select></label>
    <div id="rcaProblem" style="font-size:13px;color:#b03a2e;margin:8px 0;min-height:18px;"></div>
    <div style="display:flex;gap:8px;justify-content:flex-end;">
      <button type="button" id="rcaCancel" style="padding:6px 14px;border:1px solid #ccc;border-radius:5px;background:#fff;cursor:pointer;">Cancel</button>
      <button type="button" id="rcaSave" class="admin-pass-submit" style="padding:6px 14px;font-size:13px;" disabled>Move whole receipt</button>
    </div>`;
  const sel = body.querySelector("#rcaAccount"), save = body.querySelector("#rcaSave"), problem = body.querySelector("#rcaProblem");
  body.querySelector("#rcaCancel").onclick = close;
  const targetOf = () => sel.value === "personal" ? { paidPersonally: true } : sel.value ? { accountId: Number(sel.value) } : null;
  const check = async () => {
    const t = targetOf(); save.disabled = true; problem.textContent = "";
    if (!t || sel.value === current) return;
    try {
      const d = await mnApi_(Object.assign({ action: "previewReceiptAccountChange", kind, movementId }, t));
      problem.textContent = d.blockers.join(" ");
      save.disabled = d.blockers.length > 0;
    } catch (e) { problem.textContent = e.message; }
  };
  sel.onchange = check;
  save.onclick = async () => {
    const t = targetOf(); if (!t) return;
    save.disabled = true;
    try {
      await mnApi_(Object.assign({ action: "setReceiptAccount", kind, movementId, expectStockIds: r.stock.map(x => x.id) }, t));
      showToast("Moved the whole receipt."); close(); await keepView_(mnLoad_);
    } catch (e) { problem.textContent = e.message; save.disabled = false; }
  };
}
function yearStartOrToday_(){ return new Date().getFullYear() + "-01-01"; }

// ---- Reconcile: statement CSV import + monthly reconciliation (migrations/0015) --
// Minimal RFC-4180 CSV parser (quotes, doubled quotes, commas/newlines in quotes).
function parseCsv_(text){
  const rows = []; let row = [], cell = "", q = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (q) { if (ch === '"') { if (text[i + 1] === '"') { cell += '"'; i++; } else q = false; } else cell += ch; continue; }
    if (ch === '"') q = true;
    else if (ch === ",") { row.push(cell); cell = ""; }
    else if (ch === "\n" || ch === "\r") { if (ch === "\r" && text[i + 1] === "\n") i++; row.push(cell); cell = ""; if (row.some(c => c.trim() !== "")) rows.push(row); row = []; }
    else cell += ch;
  }
  row.push(cell); if (row.some(c => c.trim() !== "")) rows.push(row);
  return rows;
}
// "2026-03-05", "03/05/2026", "3/5/26", "03-05-2026" → "2026-03-05" (US month-first); "" if unreadable.
function parseStatementDate_(v){
  const t = String(v || "").trim();
  let m = t.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return `${m[1]}-${m[2].padStart(2, "0")}-${m[3].padStart(2, "0")}`;
  m = t.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{2}|\d{4})$/);
  if (m) { const y = m[3].length === 2 ? "20" + m[3] : m[3]; return `${y}-${m[1].padStart(2, "0")}-${m[2].padStart(2, "0")}`; }
  return "";
}
// "$1,234.56", "(12.34)", "-12.34", "12.34-" → number; NaN if unreadable. Blank → 0.
function parseStatementAmount_(v){
  let t = String(v == null ? "" : v).trim();
  if (!t) return 0;
  let neg = false;
  if (/^\(.*\)$/.test(t)) { neg = true; t = t.slice(1, -1); }
  if (/-$/.test(t)) { neg = true; t = t.slice(0, -1); }
  t = t.replace(/[$,\s]/g, "");
  const n = Number(t);
  return Number.isFinite(n) ? (neg ? -Math.abs(n) : n) : NaN;
}
// Rows → statement lines using a mapping {date, desc, mode: "one"|"split", amount, debit, credit, flip}.
function mapStatementRows_(rows, mp){
  const out = [], errors = [];
  rows.forEach((r, i) => {
    const date = parseStatementDate_(r[mp.date]);
    let amt = mp.mode === "split" ? parseStatementAmount_(r[mp.credit]) - Math.abs(parseStatementAmount_(r[mp.debit])) : parseStatementAmount_(r[mp.amount]);
    if (mp.flip) amt = -amt;
    if (!date || !Number.isFinite(amt)) { errors.push(i + 1); return; }
    if (Math.round(amt * 100) === 0) return;
    out.push({ date, description: String(r[mp.desc] || "").trim(), amount: Math.round(amt * 100) / 100 });
  });
  return { lines: out, errors };
}

// ---- Account viewer (Finance → Account viewer) --------------------------------------------------
// One account's register: every movement in the date range, newest first, with the running balance. Nothing
// loads when a control changes — only Search (the screen loads once when opened). Each row has a receipt
// button: view the file, or add / replace it (uploaded through the existing receipt upload).
async function renderAccountViewer(app){
  adminSetHash("accountviewer");
  document.title = adminTitle_("Account viewer");
  const inp = "font-size:13px;padding:5px 7px;border:1px solid #ccc;border-radius:4px;box-sizing:border-box;";
  const today = new Date().toLocaleDateString("en-CA");
  const fromDefault = (() => { const d = new Date(); d.setDate(d.getDate() - 31); return d.toLocaleDateString("en-CA"); })();   // today + the 31 days before = 32 days
  app.innerHTML = `
    ${adminPageHead_("Account viewer")}
    <div class="admin-panel" style="--org-accent:var(--accent);max-width:1080px;margin:8px auto 60px;">
      <div style="display:flex;gap:10px;align-items:flex-end;flex-wrap:wrap;margin-bottom:10px;">
        <label style="font-size:12px;font-weight:600;">Account<br><select id="avAccount" style="${inp}min-width:190px;"></select></label>
        <label style="font-size:12px;font-weight:600;">From<br><input id="avFrom" type="date" value="${fromDefault}" max="${today}" style="${inp}"></label>
        <label style="font-size:12px;font-weight:600;">To<br><input id="avTo" type="date" value="${today}" style="${inp}"></label>
        <button type="button" id="avSearch" class="admin-pass-submit" style="padding:6px 16px;font-size:13px;">Search</button>
        <span id="avHint" style="font-size:12px;color:#b45309;"></span>
      </div>
      <div id="avSummary" style="font-size:13px;color:#444;margin-bottom:8px;"></div>
      <div id="avList" style="max-height:62vh;overflow-y:auto;overflow-x:auto;border:1px solid #ddd;border-radius:6px;background:#fff;color:#111;font-size:14px;"><div style="padding:14px;color:#888;">Loading…</div></div>
      <input id="avFile" type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif,.heic,.heif,application/pdf" hidden>
    </div>`;
  let acc;
  try { acc = await loadAccounts_(true); } catch (e) { document.getElementById("avList").textContent = e.message; return; }
  const sel = document.getElementById("avAccount");
  sel.innerHTML = acc.accounts.map(a => `<option value="${a.id}">${escapeHtml(a.name)}${a.active ? "" : " (inactive)"}</option>`).join("");
  if (acc.accounts[0]) sel.value = String(acc.accounts[0].id);          // defaults to the first account
  const hint = document.getElementById("avHint");
  const changed = () => { hint.textContent = "Changed — click Search"; };
  for (const id of ["avAccount", "avFrom", "avTo"]) document.getElementById(id).onchange = changed;
  document.getElementById("avSearch").onclick = () => avSearch_();
  document.getElementById("avFile").onchange = () => avUploadPicked_();
  window._av = { last: null, target: null };
  await avSearch_();
}

// Runs the search the controls currently describe. `again` re-runs the LAST search instead (used after a receipt
// is added so the list refreshes without picking up controls the user has edited but not searched).
async function avSearch_(again){
  const list = document.getElementById("avList"), sum = document.getElementById("avSummary");
  if (!list) return;
  const av = window._av || (window._av = { last: null, target: null });
  const q = again && av.last ? av.last : { accountId: Number(document.getElementById("avAccount").value),
    dateFrom: document.getElementById("avFrom").value, dateTo: document.getElementById("avTo").value };
  if (!q.accountId) { list.innerHTML = `<div style="padding:14px;color:#888;">No accounts yet.</div>`; return; }
  if (!q.dateFrom || !q.dateTo || q.dateFrom > q.dateTo) { showToast("Choose a start date on or before the end date.", true); return; }
  const keepScroll = again ? list.scrollTop : 0;
  let d;
  try { d = await mnApi_(Object.assign({ action: "getAccountRegister" }, q)); }
  catch (e) { list.innerHTML = `<div style="padding:14px;color:#b03a2e;">${escapeHtml(e.message)}</div>`; return; }
  av.last = q;
  document.getElementById("avHint").textContent = "";
  const fmt = (n) => (n < 0 ? "−$" : "$") + Math.abs(Number(n || 0)).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  sum.innerHTML = `<strong>${escapeHtml(d.account.name)}</strong> · ${escapeHtml(d.dateFrom)} to ${escapeHtml(d.dateTo)} · started at ${fmt(d.startBalance)} · in ${fmt(d.totalIn)} · out ${fmt(d.totalOut)} · ended at <strong>${fmt(d.endBalance)}</strong> · ${d.count} transaction${d.count === 1 ? "" : "s"}${d.truncated ? " (showing the newest 3,000)" : ""}`;
  const th = "padding:6px 9px;text-align:left;background:#f0f0f0;color:#333;font-size:12px;font-weight:700;border-bottom:2px solid #ccc;position:sticky;top:0;z-index:1;";
  const td = "padding:6px 9px;border-bottom:1px solid #e5e7eb;vertical-align:top;color:#111;background:#fff;";
  const btn = "padding:2px 8px;font-size:12px;border:1px solid #ccc;border-radius:4px;background:#fff;cursor:pointer;";
  list.innerHTML = d.rows.length ? `<table style="width:100%;border-collapse:collapse;">
      <thead><tr><th style="${th}">Date</th><th style="${th}">Category</th><th style="${th}">Description</th><th style="${th}text-align:right;">Amount</th><th style="${th}text-align:right;">Balance</th><th style="${th}">Receipt</th></tr></thead>
      <tbody>${d.rows.map(r => `<tr>
        <td style="${td}white-space:nowrap;">${escapeHtml(r.date)}</td>
        <td style="${td}white-space:nowrap;">${escapeHtml(r.category)}</td>
        <td style="${td}">${receiptLineHtml_(r.description, r.parts, fmt)}</td>
        <td style="${td}text-align:right;white-space:nowrap;color:${r.amount < 0 ? "#b03a2e" : "#166534"};">${r.amount < 0 ? "−" : "+"}${fmt(Math.abs(r.amount))}</td>
        <td style="${td}text-align:right;white-space:nowrap;font-weight:600;">${fmt(r.balance)}</td>
        <td style="${td}white-space:nowrap;">${r.receiptKey
          ? `<button type="button" class="av-view" style="${btn}" title="${escapeHtml(r.receiptName || "Receipt")}" data-key="${escapeHtml(r.receiptKey)}">📎 View</button> <button type="button" class="av-add" style="${btn}color:#555;" data-src="${escapeHtml(r.src)}" data-id="${r.srcId}" title="Replace this receipt">Replace</button>`
          : `<button type="button" class="av-add" style="${btn}" data-src="${escapeHtml(r.src)}" data-id="${r.srcId}">＋ Receipt</button>`}</td>
      </tr>`).join("")}</tbody></table>` : `<div style="padding:14px;color:#888;">No transactions in this range.</div>`;
  list.scrollTop = keepScroll;
  list.querySelectorAll(".av-view").forEach(b => b.onclick = () => expViewReceipt_(b.dataset.key));
  list.querySelectorAll(".av-add").forEach(b => b.onclick = () => {
    av.target = { src: b.dataset.src, srcId: Number(b.dataset.id) };
    const f = document.getElementById("avFile"); f.value = ""; f.click();
  });
}

// One stock receipt shown as ONE line — the charge on the card or bank statement — with its parts behind an
// expander (each blank / size, any R&D or personal part): the Account viewer and Reconcile both use it.
// `parts` = [{description|label, amount}]; a line without parts is just its label.
function receiptLineHtml_(label, parts, fmt){
  if (!parts || parts.length < 2) return escapeHtml(label);
  // Plain lines, not a nested table — the screens (and their tests) read their own table's rows.
  return `<details class="receipt-parts"><summary style="cursor:pointer;">${escapeHtml(label)}</summary>
    <div style="margin:4px 0 2px 14px;font-size:12px;color:#555;">${parts.map(p => `<div class="receipt-part" style="display:flex;gap:12px;justify-content:space-between;max-width:420px;">
      <span>${escapeHtml(p.description || p.label || "")}</span><span style="white-space:nowrap;">${fmt(p.amount)}</span></div>`).join("")}</div></details>`;
}

// The file picked for "＋ Receipt" / "Replace": upload it, attach it to the row's record, refresh the list in place.
async function avUploadPicked_(){
  const f = document.getElementById("avFile"), file = f && f.files && f.files[0], target = window._av && window._av.target;
  if (!file || !target) return;
  try {
    showToast("Uploading receipt…");
    const up = await uploadReceipt_(file);
    const res = await mnApi_({ action: "setRecordReceipt", src: target.src, srcId: target.srcId, receiptKey: up.key, receiptName: up.name });
    showToast(res.records > 1 ? `Receipt saved on all ${res.records} records of that purchase.` : "Receipt saved.");
    await avSearch_(true);
  } catch (e) { showToast(e.message, true); }
  finally { f.value = ""; window._av.target = null; }
}

async function renderReconcile(app){
  adminSetHash("reconcile");
  document.title = adminTitle_("Reconcile");
  const inp = "font-size:13px;padding:5px 7px;border:1px solid #ccc;border-radius:4px;box-sizing:border-box;";
  const lastMonth = (() => { const d = new Date(); d.setDate(1); d.setMonth(d.getMonth() - 1); return d.toLocaleDateString("en-CA").slice(0, 7); })();
  app.innerHTML = `
    ${adminPageHead_("Reconcile")}
    <div class="admin-panel" style="--org-accent:var(--accent);max-width:1080px;margin:8px auto 60px;">
      <div style="display:flex;gap:10px;align-items:flex-end;flex-wrap:wrap;margin-bottom:14px;">
        <label style="font-size:12px;font-weight:600;">Account<br><select id="rcAccount" style="${inp}min-width:170px;"></select></label>
        <label style="font-size:12px;font-weight:600;">Month<br><input id="rcMonth" type="month" value="${lastMonth}" style="${inp}"></label>
      </div>
      <p style="font-size:13px;color:#555;margin:0 0 14px;">Each month: import the statement CSV for an account, fix anything unmatched (usually a missing expense), then enter the statement's ending balance and mark the month reconciled. Import every statement from the account's opening date so the balances line up.</p>
      <div id="rcBody" style="font-size:14px;color:#888;">Loading…</div>
    </div>`;
  let acc;
  try { acc = await loadAccounts_(true); } catch (e) { document.getElementById("rcBody").textContent = e.message; return; }
  const sel = document.getElementById("rcAccount");
  sel.innerHTML = accountOptions_(acc.accounts, (acc.accounts.find(a => a.type === "checking") || acc.accounts[0] || {}).id);
  sel.onchange = () => rcLoad_();
  document.getElementById("rcMonth").onchange = () => rcLoad_();
  await rcLoad_();
}

async function rcLoad_(data){
  const el = document.getElementById("rcBody");
  const accountId = Number(document.getElementById("rcAccount").value), month = document.getElementById("rcMonth").value;
  if (!accountId || !month) return;
  let d = data;
  if (!d) { try { d = await mnApi_({ action: "getReconciliation", accountId, month }); } catch (e) { el.textContent = e.message; return; } }
  const fmt = (n) => (n < 0 ? "−$" : "$") + Math.abs(Number(n || 0)).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const isCard = d.account.type === "credit_card";
  const inp = "font-size:13px;padding:5px 7px;border:1px solid #ccc;border-radius:4px;box-sizing:border-box;";
  const th = "padding:6px 9px;text-align:left;background:#f0f0f0;color:#333;font-size:12px;font-weight:700;border-bottom:2px solid #ccc;";
  const td = "padding:6px 9px;border-bottom:1px solid #e5e7eb;vertical-align:top;color:#111;background:#fff;";
  const btn = (cls, id, label, extra = "") => `<button type="button" class="${cls}" data-id="${id}" style="padding:2px 8px;font-size:12px;border:1px solid #ccc;border-radius:4px;background:#fff;cursor:pointer;${extra}">${label}</button>`;
  const unmatched = d.lines.filter(l => l.status === "unmatched" || l.status === "broken");
  const matched = d.lines.filter(l => l.status === "matched"), ignored = d.lines.filter(l => l.status === "ignored");
  const locked = !!d.reconciled;
  el.style.color = "var(--ink,#111)";
  el.innerHTML = `
    <div style="border:1px solid #ddd;border-radius:8px;padding:12px 14px;margin-bottom:18px;background:var(--surface,#fff);">
      <div style="font-weight:700;margin-bottom:6px;">Import statement CSV — ${escapeHtml(d.account.name)}</div>
      <input type="file" id="rcFile" accept=".csv,text/csv" style="font-size:13px;" ${locked ? "disabled" : ""}>
      <div id="rcMap" style="margin-top:10px;"></div>
    </div>

    <div style="border:1px solid #ddd;border-radius:8px;padding:12px 14px;margin-bottom:18px;background:var(--surface,#fff);">
      <div style="display:flex;gap:18px;flex-wrap:wrap;align-items:flex-end;">
        <label style="font-size:12px;font-weight:600;">${isCard ? "Amount owed on the statement" : "Statement ending balance"} (${escapeHtml(d.to)})<br>
          <input id="rcStmtBal" type="number" step="0.01" value="${d.reconciled ? (isCard ? -d.reconciled.statementBalance : d.reconciled.statementBalance).toFixed(2) : ""}" style="${inp}width:130px;" ${locked ? "disabled" : ""}></label>
        <div style="font-size:13px;">Book balance: <strong>${fmt(d.bookBalance)}</strong><br>
          <span style="color:#555;">− not yet on a statement ${fmt(d.uncleared)} + ignored lines ${fmt(d.ignored)} = expected <strong>${fmt(isCard ? -d.expectedStatementBalance : d.expectedStatementBalance)}</strong>${isCard ? " owed" : ""}</span></div>
        <div id="rcDiff" style="font-size:14px;font-weight:700;"></div>
        ${locked ? `<div style="font-size:13px;color:#15803d;font-weight:600;">✓ Reconciled ${escapeHtml(new Date(d.reconciled.at).toLocaleDateString())}</div>
            <button type="button" id="rcReopen" class="admin-btn" style="padding:4px 10px;font-size:12px;">Reopen month</button>`
          : `<button type="button" id="rcReconcile" class="admin-pass-submit" style="padding:6px 14px;font-size:13px;">Mark reconciled</button>`}
      </div>
      <div id="rcErr" style="color:#b03a2e;font-size:13px;min-height:16px;margin-top:6px;"></div>
    </div>

    <h3 style="font-size:15px;margin:0 0 6px;">On the statement, not in the books — ${unmatched.length}</h3>
    ${unmatched.length ? `<div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;margin-bottom:18px;"><table style="width:100%;border-collapse:collapse;font-size:14px;">
      <thead><tr><th style="${th}">Date</th><th style="${th}">Description</th><th style="${th}text-align:right;">Amount</th><th style="${th}"></th></tr></thead>
      <tbody>${unmatched.map(l => `<tr><td style="${td}white-space:nowrap;">${escapeHtml(l.date)}</td>
        <td style="${td}">${escapeHtml(l.description)}${l.status === "broken" ? `<br><span style="font-size:12px;color:#b45309;">Its matched entry was voided or deleted — match it again</span>` : ""}</td>
        <td style="${td}text-align:right;white-space:nowrap;color:${l.amount < 0 ? "#b03a2e" : "#15803d"};">${fmt(l.amount)}</td>
        <td style="${td}white-space:nowrap;text-align:right;">${locked ? "" : btn("rc-match", l.id, "Match…") + " " + btn("rc-create", l.id, "Create…") + " " + btn("rc-ignore", l.id, "Ignore")}</td></tr>`).join("")}</tbody></table></div>`
      : `<div style="color:#888;margin-bottom:18px;">${d.lines.length ? "Everything on this statement is matched. ✓" : "No statement lines for this month yet — import the CSV above."}</div>`}

    <h3 style="font-size:15px;margin:0 0 6px;">In the books, not on this statement — ${d.unmatchedBook.length}</h3>
    <p style="font-size:12px;color:#666;margin:0 0 6px;">Not cleared yet (e.g. a check not deposited), dated wrong, or put in the wrong account.</p>
    ${d.unmatchedBook.length ? `<div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;margin-bottom:10px;"><table style="width:100%;border-collapse:collapse;font-size:14px;">
      <thead><tr><th style="${th}">Date</th><th style="${th}">Entry</th><th style="${th}text-align:right;">Amount</th></tr></thead>
      <tbody>${d.unmatchedBook.map(m => `<tr><td style="${td}">${escapeHtml(m.date)}</td><td style="${td}">${receiptLineHtml_(m.label, m.parts, fmt)}</td><td style="${td}text-align:right;">${fmt(m.amount)}</td></tr>`).join("")}</tbody></table></div>` : `<div style="color:#888;margin-bottom:10px;">None.</div>`}
    ${d.unclearedEarlier.length ? `<details data-keep-open="rc-uncleared" style="margin-bottom:18px;"><summary style="cursor:pointer;font-size:13px;">${d.unclearedEarlier.length} earlier entr${d.unclearedEarlier.length === 1 ? "y" : "ies"} still not on any statement (${fmt(d.unclearedEarlier.reduce((a, m) => a + m.amount, 0))})</summary>
      <ul style="font-size:13px;margin:6px 0 0 18px;">${d.unclearedEarlier.map(m => `<li>${escapeHtml(m.date)} — ${m.parts && m.parts.length > 1 ? receiptLineHtml_(m.label + " — " + fmt(m.amount), m.parts, fmt) : escapeHtml(m.label) + " — " + fmt(m.amount)}</li>`).join("")}</ul></details>` : ""}

    <details data-keep-open="rc-matched" style="margin-bottom:8px;"><summary style="cursor:pointer;font-size:14px;font-weight:600;">Matched — ${matched.length}</summary>
      <div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;margin-top:8px;"><table style="width:100%;border-collapse:collapse;font-size:13px;">
      <tbody>${matched.map(l => `<tr><td style="${td}white-space:nowrap;">${escapeHtml(l.date)}</td><td style="${td}">${escapeHtml(l.description)}<br><span style="color:#666;">↔ ${l.matched.map(m => m.parts && m.parts.length > 1 ? receiptLineHtml_(m.label + " " + fmt(m.amount), m.parts, fmt) : escapeHtml(m.label) + " " + fmt(m.amount)).join(" + ")}</span></td>
        <td style="${td}text-align:right;">${fmt(l.amount)}</td><td style="${td}text-align:right;">${locked ? "" : btn("rc-unmatch", l.id, "Unmatch")}</td></tr>`).join("") || `<tr><td style="${td}color:#888;">None.</td></tr>`}</tbody></table></div></details>
    ${ignored.length ? `<details data-keep-open="rc-ignored"><summary style="cursor:pointer;font-size:14px;font-weight:600;">Ignored — ${ignored.length}</summary>
      <ul style="font-size:13px;margin:6px 0 0 18px;">${ignored.map(l => `<li>${escapeHtml(l.date)} — ${escapeHtml(l.description)} — ${fmt(l.amount)} <span style="color:#666;">(${escapeHtml(l.ignoreReason)})</span> ${locked ? "" : btn("rc-unignore", l.id, "Undo")}</li>`).join("")}</ul></details>` : ""}`;

  const err = el.querySelector("#rcErr");
  const act = async (body) => { err.textContent = ""; try { const r = await mnApi_(body); await keepView_(() => rcLoad_(r.lines ? r : undefined)); return r; } catch (e) { err.textContent = e.message; showToast(e.message, true); } };
  const diffEl = el.querySelector("#rcDiff"), balEl = el.querySelector("#rcStmtBal");
  const showDiff = () => {
    const v = parseFloat(balEl.value);
    if (!Number.isFinite(v)) { diffEl.textContent = ""; return; }
    const diff = Math.round(((isCard ? -v : v) - d.expectedStatementBalance) * 100) / 100;
    diffEl.innerHTML = diff === 0 ? `<span style="color:#15803d;">Difference $0.00 ✓</span>` : `<span style="color:#b03a2e;">Difference ${fmt(isCard ? -diff : diff)}</span>`;
  };
  balEl.addEventListener("input", showDiff); showDiff();
  const recBtn = el.querySelector("#rcReconcile");
  if (recBtn) recBtn.onclick = () => act({ action: "reconcileMonth", accountId: d.account.id, month: d.month, statementBalance: parseFloat(balEl.value) });
  const reopen = el.querySelector("#rcReopen");
  if (reopen) reopen.onclick = async () => { if (await askConfirm_("Reopen this month? You can change matches again, then re-reconcile.")) act({ action: "unreconcileMonth", accountId: d.account.id, month: d.month }); };
  el.querySelectorAll(".rc-unmatch").forEach(b => b.onclick = () => act({ action: "unmatchStatementLine", lineId: Number(b.dataset.id) }));
  el.querySelectorAll(".rc-unignore").forEach(b => b.onclick = () => act({ action: "ignoreStatementLine", lineId: Number(b.dataset.id), reason: null }));
  el.querySelectorAll(".rc-ignore").forEach(b => b.onclick = async () => {
    const ans = await confirmModal_({ title: "Ignore this statement line?", reason: "required", reasonLabel: "Why can it be ignored? (e.g. “duplicate on statement”, “pending charge that dropped off”)", confirmLabel: "Ignore line" });
    if (ans.ok) act({ action: "ignoreStatementLine", lineId: Number(b.dataset.id), reason: ans.reason });
  });
  el.querySelectorAll(".rc-match").forEach(b => b.onclick = () => rcMatchModal_(d, d.lines.find(l => l.id === Number(b.dataset.id)), act));
  el.querySelectorAll(".rc-create").forEach(b => b.onclick = () => rcCreateModal_(d, d.lines.find(l => l.id === Number(b.dataset.id)), act));
  const file = el.querySelector("#rcFile");
  if (file) file.onchange = () => rcImportPreview_(d, file.files[0]);
}

function rcMatchModal_(d, line, act){
  const fmt = (n) => (n < 0 ? "−$" : "$") + Math.abs(Number(n || 0)).toFixed(2);
  const near = d.candidates.slice().sort((a, b) => Math.abs(Date.parse(a.date) - Date.parse(line.date)) - Math.abs(Date.parse(b.date) - Date.parse(line.date)));
  const { ov, close } = inventoryModal_("Match statement line", `
    <div style="font-size:14px;margin-bottom:8px;"><strong>${escapeHtml(line.date)}</strong> — ${escapeHtml(line.description)} — <strong>${fmt(line.amount)}</strong></div>
    <div style="font-size:12px;color:#555;margin-bottom:8px;">Tick the recorded entries this line is (several if it's a combined deposit). They must add up to the line's amount.</div>
    <div style="max-height:320px;overflow-y:auto;border:1px solid #e5e7eb;border-radius:6px;">${near.length ? near.map(m => `<label style="display:flex;gap:8px;padding:5px 8px;border-bottom:1px solid #f0f0f0;font-size:13px;align-items:center;">
      <input type="checkbox" value="${escapeHtml((m.keys || [m.key]).join(","))}" data-amt="${m.amount}"><span style="width:84px;">${escapeHtml(m.date)}</span><span style="flex:1;">${receiptLineHtml_(m.label, m.parts, fmt)}</span><span>${fmt(m.amount)}</span></label>`).join("")
      : `<div style="padding:10px;color:#888;font-size:13px;">No unmatched entries in this account around this date — use Create… instead.</div>`}</div>
    <div style="display:flex;justify-content:space-between;align-items:center;margin-top:10px;">
      <span id="rcmSum" style="font-size:13px;">Selected: $0.00</span>
      <span><button type="button" id="rcmCancel" style="padding:6px 12px;border:1px solid #ccc;border-radius:5px;background:#fff;cursor:pointer;">Cancel</button>
      <button type="button" id="rcmOk" class="admin-btn" style="padding:6px 12px;">Match</button></span></div>`, 620);
  const boxes = () => [...ov.querySelectorAll('input[type="checkbox"]')];
  const upd = () => { const sum = boxes().filter(x => x.checked).reduce((a, x) => a + Number(x.dataset.amt), 0);
    const ok = Math.round(sum * 100) === Math.round(line.amount * 100);
    ov.querySelector("#rcmSum").innerHTML = `Selected: <strong style="color:${ok ? "#15803d" : "#b03a2e"};">${fmt(sum)}</strong>${ok ? " ✓" : " (need " + fmt(line.amount) + ")"}`; };
  boxes().forEach(x => x.addEventListener("change", upd));
  ov.querySelector("#rcmCancel").onclick = close;
  // A purchase's line carries all its records' keys (one charge = every size, R&D and personal part).
  ov.querySelector("#rcmOk").onclick = async () => { const keys = boxes().filter(x => x.checked).flatMap(x => x.value.split(",")).filter(Boolean); if (!keys.length) return; close(); await act({ action: "matchStatementLine", lineId: line.id, keys }); };
}

// Mirrors spreadCents in db.js: extra split by weight, whole cents, exact total.
function spreadCents_(weights, extra){
  const w = weights.map(x => Math.max(0, Number(x) || 0)), tw = w.reduce((a, x) => a + x, 0);
  const sh = w.map(x => tw ? extra * x / tw : 0), al = sh.map(Math.floor);
  let left = tw ? extra - al.reduce((a, x) => a + x, 0) : 0;
  sh.map((x, i) => [x - Math.floor(x), i]).sort((a, b) => b[0] - a[0]).forEach(([, i]) => { if (left > 0) { al[i]++; left--; } });
  return al;
}

// The blank-order form: one box per blank type (sizes, qty, total cost), vendor,
// shipping & other costs, an optional R&D / personal part and a live total —
// shared by Reconcile → Create… → Blank purchase and Blanks → Receive order.
// opts.target() returns the cents it must add up to (or null for no target);
// opts.onChange(ok) fires as it's edited. collect() gives the request fields.
// A size string matches a blank's own size record loosely — vendors spell "one size"
// several ways ("Adjustable", "One Size", "OSFA", "O/S") and blanks here are recorded
// as "OSFA"; anything else is compared letters/digits-only, case-insensitive.
const sizeKey_ = (s) => { const k = String(s || "").toLowerCase().replace(/[^a-z0-9]/g, ""); return ["osfa", "onesize", "os", "adjustable", "adjust"].includes(k) ? "osfa" : k; };

function blankOrderForm_(el, opts){
  const { blanks, cats } = opts;
  const inp = "font-size:13px;padding:5px 7px;border:1px solid #ccc;border-radius:4px;box-sizing:border-box;";
  const blankName = (b) => b.name || [b.brand, b.color].filter(Boolean).join(" ") || "Blank #" + b.id;
  el.innerHTML = `<div id="rccGroups"></div>
          <div id="rccUnmatched" style="font-size:12px;color:#b03a2e;margin-bottom:6px;"></div>
          <button type="button" id="rccAddBlank" style="padding:4px 10px;border:1px dashed #999;border-radius:5px;background:#fff;cursor:pointer;font-size:12px;margin-bottom:6px;">+ Add another blank</button>
          <div style="display:flex;gap:8px;flex-wrap:wrap;margin:6px 0;">
            <label style="font-size:12px;font-weight:600;">Vendor<br><input id="rccVendor" maxlength="100" style="${inp}width:150px;"></label>
            <label style="font-size:12px;font-weight:600;">Invoice / order #<br><input id="rccRef" maxlength="100" style="${inp}width:130px;"></label></div>
          <label style="display:block;font-size:12px;font-weight:600;margin-bottom:6px;">Shipping &amp; other costs<br>$<input type="number" min="0" step="0.01" id="rccShip" placeholder="0.00" style="${inp}width:90px;"></label>
          <details id="rccMixed" style="margin:4px 0 8px;font-size:12px;"><summary style="cursor:pointer;font-weight:600;">Not all of it is for inventory? (R&amp;D / testing, personal)</summary>
            <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end;margin-top:6px;">
              <label style="font-weight:600;">R&amp;D / testing<br>$<input type="number" min="0" step="0.01" id="rccRd" placeholder="0.00" style="${inp}width:86px;"></label>
              <label style="font-weight:600;">as<br><select id="rccRdCat" style="${inp}">${cats.map(c => `<option value="${c.id}"${/^supplies/i.test(c.name) ? " selected" : ""}>${escapeHtml(c.name)}</option>`).join("")}</select></label>
              <label style="font-weight:600;">Personal<br>$<input type="number" min="0" step="0.01" id="rccPers" placeholder="0.00" style="${inp}width:86px;"></label></div>
            <div style="color:#555;margin-top:4px;">Enter those items' prices before shipping. Test pieces and samples become an expense; personal items an owner draw (not deductible). No blank needs to be chosen if none of the order is inventory.</div></details>
          <label style="display:flex;gap:6px;align-items:center;font-size:12px;margin-bottom:6px;"><input type="checkbox" id="rccTaxed"> The vendor charged sales tax (blanks for resale should be tax-free with your resale certificate)</label>
          <div id="rccTotal" style="font-size:13px;font-weight:600;margin:4px 0;"></div>
          <div style="font-size:12px;color:#555;">Enter the invoice's blank prices per size and any shipping (or tax you couldn't avoid) above — it's added to the blanks' cost (landed cost), spread over the blanks and sizes by value, and becomes cost of goods sold as they're used. ${opts.hint || ""}</div>`;
  const collect = () => ({
    groups: [...el.querySelectorAll(".rcc-group")].map(g => ({ blankId: Number(g.querySelector(".rcc-blank").value) || 0,
      lines: [...g.querySelectorAll(".rcc-qty")].map(q => ({ color: q.dataset.color || "", size: q.dataset.size, qty: parseInt(q.value, 10) || 0,
        total: parseFloat(g.querySelector(`.rcc-cost[data-i="${q.dataset.i}"]`).value) || 0 })).filter(x => x.qty > 0) })).filter(g => g.lines.length),
    rdAmount: parseFloat(el.querySelector("#rccRd").value) || 0,
    rdCategoryId: Number(el.querySelector("#rccRdCat").value) || 0,
    personalAmount: parseFloat(el.querySelector("#rccPers").value) || 0,
    vendor: el.querySelector("#rccVendor").value.trim(), vendorRef: el.querySelector("#rccRef").value.trim(),
    vendorChargedTax: el.querySelector("#rccTaxed").checked,
    extraCost: parseFloat(el.querySelector("#rccShip").value) || 0,
  });
  const groupsEl = el.querySelector("#rccGroups");
  const $ = (x) => "$" + (x / 100).toFixed(2);
  // One box per blank type on the invoice: its sizes, qty and total cost.
  const groupStats = () => [...groupsEl.querySelectorAll(".rcc-group")].map(g => {
    const b = blanks.find(x => String(x.id) === g.querySelector(".rcc-blank").value);
    let cents = 0, qty = 0;
    g.querySelectorAll(".rcc-qty").forEach(q => { const n = parseInt(q.value, 10) || 0;
      if (n > 0) { qty += n; cents += Math.round((parseFloat(g.querySelector(`.rcc-cost[data-i="${q.dataset.i}"]`).value) || 0) * 100); } });
    return { name: b ? blankName(b) : "Blank", cents, qty };
  });
  const total = () => {
    const gs = groupStats().filter(g => g.qty > 0), cents = gs.reduce((a, g) => a + g.cents, 0);
    const c = (id) => Math.max(0, Math.round((parseFloat(el.querySelector(id).value) || 0) * 100));
    const extraC = c("#rccShip"), rdC = c("#rccRd"), persC = c("#rccPers");
    const all = cents + rdC + persC + extraC, target = opts.target(), some = gs.length > 0 || rdC > 0 || persC > 0;
    const ok = some && (target == null || all === target);
    // Same split the server makes (spreadCents in db.js): by value, whole cents.
    const w = cents || rdC || persC ? [...gs.map(g => g.cents), rdC, persC] : [...gs.map(g => g.qty), 0, 0];
    const al = spreadCents_(w, extraC), n = gs.length;
    const mixed = rdC > 0 || persC > 0;
    el.querySelector("#rccTotal").innerHTML = `${mixed ? `Inventory ${$(cents)}${rdC ? ` + R&amp;D ${$(rdC)}` : ""}${persC ? ` + personal ${$(persC)}` : ""}` : `Blanks ${$(cents)}`}${extraC ? ` + shipping &amp; other ${$(extraC)}` : ""} = <span style="color:${ok ? "#15803d" : "#b03a2e"};">${$(all)}</span>${target == null ? "" : ` of ${$(target)}`}${ok && target != null ? " ✓" : ""}` +
      (mixed || n > 1 ? `<div style="font-weight:400;font-size:12px;color:#555;">Records: ${[...gs.map((g, i) => `${escapeHtml(g.name)} ${$(g.cents + al[i])}`), rdC ? `R&amp;D expense ${$(rdC + al[n])}` : "", persC ? `owner draw ${$(persC + al[n + 1])}` : ""].filter(Boolean).join(" · ")}${extraC ? " (shipping spread by value)" : ""}</div>` : "");
    opts.onChange(ok);
  };
  // `preset` (from a PDF import): { blankId, lines: [{size, qty, total}] } — pre-fills
  // this group's blank and per-size qty/cost. A preset line whose size isn't on file
  // for that blank yet can't be placed in this per-size table at all (it's driven by
  // the blank's own recorded sizes) — it's returned as "unmatched" so the caller can
  // warn about it rather than silently drop the money.
  const addGroup = (preset) => {
    const g = document.createElement("div");
    g.className = "rcc-group";
    g.style.cssText = "border:1px solid #e5e7eb;border-radius:6px;padding:8px;margin-bottom:8px;";
    const first = !groupsEl.children.length;
    g.innerHTML = `<div style="display:flex;gap:8px;align-items:flex-end;justify-content:space-between;">
        <label style="font-size:12px;font-weight:600;">Blank<br><select class="rcc-blank" style="${inp}"><option value="">Choose…</option>${blanks.map(b => `<option value="${b.id}"${preset && preset.blankId === b.id ? " selected" : ""}>${escapeHtml(blankName(b))}</option>`).join("")}</select></label>
        ${first ? "" : `<button type="button" class="rcc-rm admin-btn-danger" style="padding:3px 8px;border-radius:4px;cursor:pointer;font-size:12px;">Remove</button>`}</div>
      <div class="rcc-sizes"></div>`;
    groupsEl.appendChild(g);
    const sizes = () => {
      const b = blanks.find(x => String(x.id) === g.querySelector(".rcc-blank").value);
      g.querySelector(".rcc-sizes").innerHTML = b ? `<table style="border-collapse:collapse;font-size:13px;margin-top:6px;">
        <tr style="text-align:left;"><th style="padding:3px 6px;">Color / size</th><th style="padding:3px 6px;">Qty</th><th style="padding:3px 6px;">Total cost</th><th style="padding:3px 6px;">Each</th></tr>
        ${(b.sizes || []).map((z, i) => `<tr><td style="padding:3px 6px;">${z.color ? escapeHtml(z.color) + " · " : ""}${escapeHtml(z.size || "—")}</td>
          <td style="padding:3px 6px;"><input type="number" min="0" step="1" class="rcc-qty" data-i="${i}" data-color="${escapeHtml(z.color || "")}" data-size="${escapeHtml(z.size || "")}" data-avg="${Number(z.vendorPrice != null ? z.vendorPrice : (z.purchasePrice || 0))}" placeholder="0" style="${inp}width:64px;"></td>
          <td style="padding:3px 6px;">$<input type="number" min="0" step="0.01" class="rcc-cost" data-i="${i}" placeholder="0.00" style="${inp}width:86px;"></td>
          <td style="padding:3px 6px;font-size:12px;color:#666;" class="rcc-each" data-i="${i}"></td></tr>`).join("")}</table>` : "";
      if (b && b.vendor && !el.querySelector("#rccVendor").value) el.querySelector("#rccVendor").value = b.vendor;
      const each = (i) => {
        const q = parseInt(g.querySelector(`.rcc-qty[data-i="${i}"]`).value, 10) || 0, t = parseFloat(g.querySelector(`.rcc-cost[data-i="${i}"]`).value) || 0;
        g.querySelector(`.rcc-each[data-i="${i}"]`).textContent = q > 0 && t > 0 ? "$" + (t / q).toFixed(Math.round(t * 100) % q ? 3 : 2) + " each" : "";
      };
      // Typing a quantity fills its total from the vendor price (migrations/0062), else the current
      // average cost, until the total is edited by hand; "Each" shows the per-blank cost.
      g.querySelectorAll(".rcc-qty").forEach(q => q.addEventListener("input", () => {
        const c = g.querySelector(`.rcc-cost[data-i="${q.dataset.i}"]`);
        if (!c.dataset.touched) c.value = (parseInt(q.value, 10) || 0) > 0 ? ((parseInt(q.value, 10) || 0) * Number(q.dataset.avg)).toFixed(2) : "";
        each(q.dataset.i); total();
      }));
      g.querySelectorAll(".rcc-cost").forEach(c => c.addEventListener("input", () => { c.dataset.touched = "1"; each(c.dataset.i); total(); }));
      if (b && preset) {
        (preset.lines || []).forEach(line => {
          // By color AND size when the line names its color (several colors of one blank share a size, e.g.
          // OSFA caps in Black, Navy and White); a line without one (older callers) matches by size alone.
          const inputs = [...g.querySelectorAll(".rcc-qty")];
          const norm = (c) => String(c || "").toLowerCase().replace(/[^a-z0-9]/g, "");
          const input = line.color != null
            ? inputs.find(x => norm(x.dataset.color) === norm(line.color) && sizeKey_(x.dataset.size) === sizeKey_(line.size))
            : inputs.find(x => sizeKey_(x.dataset.size) === sizeKey_(line.size));
          if (!input) { g._unmatched = (g._unmatched || []).concat(line); return; }
          input.value = line.qty;
          const cost = g.querySelector(`.rcc-cost[data-i="${input.dataset.i}"]`);
          cost.value = Number(line.total).toFixed(2); cost.dataset.touched = "1";
          each(input.dataset.i);
        });
      }
      total();
    };
    g.querySelector(".rcc-blank").onchange = sizes;
    const rm = g.querySelector(".rcc-rm"); if (rm) rm.onclick = () => { g.remove(); total(); };
    sizes();
    return g;
  };
  el.querySelector("#rccAddBlank").onclick = () => addGroup();
  if (opts.prefill && opts.prefill.groups && opts.prefill.groups.length) {
    el.querySelector("#rccVendor").value = opts.prefill.vendor || "";
    el.querySelector("#rccRef").value = opts.prefill.vendorRef || "";
    if (opts.prefill.extraCost) el.querySelector("#rccShip").value = Number(opts.prefill.extraCost).toFixed(2);
    const unmatched = [];
    opts.prefill.groups.forEach(pg => { const g = addGroup(pg); if (g._unmatched) unmatched.push(...g._unmatched.map(l => `${pg.blankId ? "" : "(unmatched blank) "}${l.color ? l.color + " " : ""}${l.size || "size"} × ${l.qty}`)); });
    if (unmatched.length) el.querySelector("#rccUnmatched").textContent = `Not entered — this blank has no "${unmatched.join('", "')}" on file yet. Add it to the blank first, or enter these manually.`;
  } else {
    addGroup();
  }
  ["#rccShip", "#rccRd", "#rccPers"].forEach(id => el.querySelector(id).addEventListener("input", total));
  return { total, collect };

}

// Reconcile → Create… → Refund of an expense: money back for something you bought (a returned item,
// a reversed bank fee). Recorded as a NEGATIVE expense in the original purchase's category, so it
// reduces that Schedule C line instead of being counted as income. Optionally linked to the purchase.
function rcRefundForm_(el, { cats, line, onChange }){
  const inp = "font-size:13px;padding:5px 7px;border:1px solid #ccc;border-radius:4px;box-sizing:border-box;";
  const lbl = "font-size:12px;font-weight:600;display:block;margin-bottom:8px;";
  const refundCents = Math.round(Math.abs(line.amount) * 100);
  el.innerHTML = `
    <label style="${lbl}">Which purchase is this a refund of? <span style="font-weight:400;color:#666;">(links it and copies its category)</span><br>
      <select id="rfOrig" style="${inp}width:100%;"><option value="">Loading purchases…</option></select></label>
    <label style="${lbl}">Category<br><select id="rfCat" style="${inp}"><option value="">Choose…</option>${cats.map(c => `<option value="${c.id}">${escapeHtml(c.name)}</option>`).join("")}</select></label>
    <div id="rfNote" style="font-size:12px;color:#555;margin-bottom:6px;"></div>`;
  const origEl = el.querySelector("#rfOrig"), catEl = el.querySelector("#rfCat"), noteEl = el.querySelector("#rfNote");
  let list = [];
  const changed = () => {
    const o = list.find(x => String(x.id) === origEl.value);
    let note = "";
    if(o){
      if(o.categoryId) catEl.value = String(o.categoryId);
      const left = Math.round(o.amount * 100) - Math.round(o.refunded * 100);
      note = `Original: ${escapeHtml(o.date)}, $${o.amount.toFixed(2)}${o.refunded ? ` ($${o.refunded.toFixed(2)} already refunded)` : ""}.` +
        (refundCents > left ? ` <strong style="color:#b03a2e;">This refund is more than what's left ($${(left / 100).toFixed(2)}).</strong>` : "");
      if(o.date.slice(0, 4) !== String(line.date).slice(0, 4)){
        note += ` <strong style="color:#92400e;">That purchase was in ${escapeHtml(o.date.slice(0, 4))}. A refund in a later tax year is normally reported as other income (you're recovering an earlier deduction) — ask your CPA, or record it as Other income instead.</strong>`;
      }
    }
    noteEl.innerHTML = note;
    onChange(!!catEl.value);
  };
  origEl.onchange = changed; catEl.onchange = () => onChange(!!catEl.value);
  onChange(false);
  // Purchases from the last two years, best guesses first (shared words with the bank's description, same amount).
  (async () => {
    try{
      const to = new Date().toISOString().slice(0, 10), fromD = new Date(); fromD.setFullYear(fromD.getFullYear() - 2);
      const d = await mnApi_({ action: "listExpenses", dateFrom: fromD.toISOString().slice(0, 10), dateTo: to });
      const refunded = {};
      (d.expenses || []).filter(x => x.isRefund && x.refundOfId).forEach(x => { refunded[x.refundOfId] = (refunded[x.refundOfId] || 0) + Math.abs(x.amount); });
      const words = (t) => String(t || "").toLowerCase().replace(/[^a-z0-9 ]/g, " ").split(/\s+/).filter(w => w.length >= 4);
      const lw = new Set(words(line.description));
      list = (d.expenses || []).filter(x => !x.isRefund && Math.round(x.amount * 100) >= refundCents - 0).map(x => {
        const shared = words(x.description + " " + x.vendor).filter(w => lw.has(w)).length;
        return { ...x, refunded: refunded[x.id] || 0, score: shared * 10 + (Math.round(x.amount * 100) === refundCents ? 5 : 0) };
      }).sort((a, b) => b.score - a.score || b.date.localeCompare(a.date)).slice(0, 60);
      origEl.innerHTML = `<option value="">— Not sure / not listed (just pick the category) —</option>` + list.map(x =>
        `<option value="${x.id}">${escapeHtml(x.date)} · ${escapeHtml(x.description)}${x.vendor ? " · " + escapeHtml(x.vendor) : ""} — $${x.amount.toFixed(2)} (${escapeHtml(x.category)})</option>`).join("");
      if(list[0] && list[0].score >= 10){ origEl.value = String(list[0].id); changed(); }   // a strong match is preselected — easy to change
    }catch(e){ origEl.innerHTML = `<option value="">— Couldn't load purchases; pick the category —</option>`; }
  })();
  return { collect: () => ({ refundOfId: Number(origEl.value) || 0, categoryId: Number(catEl.value) || 0 }) };
}

// Reconcile → Create… → Deposit: a bank deposit mapped to the orders' payments it covers — a Venmo
// cash-out, cash, checks, or a mix (cash + checks on one slip). Each ticked payment has a "covers $…"
// amount: cash and Venmo (recorded in another account) can be deposited in PARTS — what's left stays on
// the list — while a payment already in this account (checks) is matched whole. If the deposit is less
// than what's covered (Venmo's fee, cash kept, a deposit fee) the difference is recorded as an expense.
function rcDepositForm_(el, { cats, line, accountId, onChange }){
  const inp = "font-size:13px;padding:5px 7px;border:1px solid #ccc;border-radius:4px;box-sizing:border-box;";
  const depositCents = Math.round(Math.abs(line.amount) * 100);
  const $ = (c) => (c < 0 ? "−$" : "$") + (Math.abs(c) / 100).toFixed(2);
  const cents = (v) => Math.round((parseFloat(v) || 0) * 100);
  const METHOD = { venmo: "Venmo", cash: "Cash", check: "Check", zelle: "Zelle", card: "Stripe" };
  const feeGuess = cats.find(c => /bank|fee/i.test(c.name) && c.deductionType === "deductible") || cats.find(c => c.deductionType === "deductible");
  const startFilter = /venmo/i.test(line.description || "") ? "venmo" : /stripe/i.test(line.description || "") ? "card" : "";
  el.innerHTML = `<div style="font-size:12px;margin-bottom:6px;">Tick the payments this <strong>${$(depositCents)}</strong> deposit covers — Venmo, cash, checks or a Stripe payout (cash and checks can be mixed on one slip). Cash and Venmo can be deposited in parts
      (change <em>covers</em>; the rest stays for the next deposit); a check or Zelle payment already in this account, or a card payment in a Stripe payout, is matched whole.</div>
    <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:6px;font-size:12px;">
      <label>Show <select id="vmFilter" style="${inp}"><option value="">All</option><option value="venmo"${startFilter === "venmo" ? " selected" : ""}>Venmo</option><option value="cash">Cash</option><option value="check">Checks</option><option value="zelle">Zelle</option><option value="card"${startFilter === "card" ? " selected" : ""}>Stripe (cards)</option></select></label>
      <button type="button" id="vmOldest" style="padding:2px 8px;border:1px solid #ccc;border-radius:4px;background:#fff;cursor:pointer;font-size:12px;">Tick oldest first until it covers the deposit</button></div>
    <div id="vmList" style="max-height:250px;overflow-y:auto;border:1px solid #e5e7eb;border-radius:6px;font-size:13px;">Loading…</div>
    <div id="vmSum" style="font-size:13px;font-weight:600;margin:8px 0 4px;"></div>
    <div id="vmFeeRow" style="display:none;margin-bottom:6px;"><label style="font-size:12px;font-weight:600;"><span id="vmFeeLabel">Record the difference as</span><br>
      <select id="vmCat" style="${inp}">${cats.map(c => `<option value="${c.id}"${feeGuess && c.id === feeGuess.id ? " selected" : ""}>${escapeHtml(c.name)}</option>`).join("")}</select></label></div>`;
  const listEl = el.querySelector("#vmList"), sumEl = el.querySelector("#vmSum"), feeRow = el.querySelector("#vmFeeRow"), filterEl = el.querySelector("#vmFilter");
  let pays = [];
  const box = (p) => listEl.querySelector(`input[data-pid="${p.id}"]`), cov = (p) => listEl.querySelector(`input[data-cov="${p.id}"]`);
  // What part of a covered amount reaches the bank: a fee already recorded on a moved payment comes out proportionally; a payment already here counts whole.
  const netOf = (p, c) => p.direct ? c : (p.fee > 0 ? Math.round(c * (p.amount - p.fee) / p.amount) : c);
  const rows = () => pays.filter(p => box(p) && box(p).checked).map(p => ({ p, c: cents(cov(p).value), maxC: Math.round(p.remaining * 100) }));
  const shortfall = () => depositCents - rows().reduce((t, r) => t + netOf(r.p, r.c), 0);
  const recalc = () => {
    const sel = rows(), net = sel.reduce((t, r) => t + netOf(r.p, r.c), 0), diff = net - depositCents, pct = net > 0 ? diff / net * 100 : 0;
    const bad = sel.filter(r => r.c <= 0 || r.c > r.maxC);
    sel.forEach(r => { cov(r.p).style.borderColor = (r.c <= 0 || r.c > r.maxC) ? "#b03a2e" : "#ccc"; });
    const moved = sel.filter(r => !r.p.direct), hasVenmo = moved.some(r => r.p.method === "venmo");
    const cards = sel.filter(r => r.p.method === "card"), mixedCard = cards.length > 0 && cards.length < sel.length;
    // Stripe's fee goes ON the card payments that don't have one yet (no category to pick) — unless every one already has a fee.
    const feeOnPayments = cards.length > 0 && !mixedCard && cards.some(r => r.p.fee === 0);
    const noRoom = diff > 0 && !moved.length;   // only payments already in this account: they must equal the deposit
    const ok = sel.length > 0 && !bad.length && diff >= 0 && !noRoom && !mixedCard;
    const noun = hasVenmo ? "Venmo fees" : cards.length ? "Stripe fees" : "difference";
    sumEl.innerHTML = !sel.length ? `<span style="color:#b03a2e;">Nothing ticked yet.</span>`
      : mixedCard ? `<span style="color:#b03a2e;">A Stripe payout is its own deposit — untick the card payments or the others.</span>`
      : bad.length ? `<span style="color:#b03a2e;">Each ticked payment needs an amount from $0.01 up to what it has left.</span>`
      : diff < 0 ? `${sel.length} payment${sel.length === 1 ? "" : "s"} cover ${$(net)} — <span style="color:#b03a2e;">${$(-diff)} short of the deposit; tick more or raise an amount.</span>`
      : noRoom ? `${sel.length} payment${sel.length === 1 ? "" : "s"} = ${$(net)} — <span style="color:#b03a2e;">already in this account, so they must equal the deposit exactly (${$(depositCents)}).</span>`
      : `${sel.length} payment${sel.length === 1 ? "" : "s"} cover ${$(net)} − deposit ${$(depositCents)} = <span style="color:${diff === 0 ? "#15803d" : "#92400e"};">${diff === 0 ? "matches exactly ✓" : noun + " " + $(diff) + " (" + pct.toFixed(1) + "%)"}</span>` +
        ((hasVenmo || cards.length) && pct > 5 ? ` <span style="font-weight:400;color:#92400e;">— that's high (${hasVenmo ? "Venmo's business fee is about 1.9% + 10¢" : "Stripe's fee is about 2.9% + 30¢"}); check the amounts.</span>` : "");
    feeRow.style.display = ok && diff > 0 && !feeOnPayments ? "" : "none";
    el.querySelector("#vmFeeLabel").textContent = hasVenmo ? "Record the missing amount (Venmo's fee) as"
      : cards.length ? "Record the difference (a refund or adjustment netted out of the payout) as" : "Record the difference (fees, cash kept, short deposit) as";
    if(ok && diff > 0 && feeOnPayments) sumEl.innerHTML += `<div style="font-weight:400;font-size:12px;color:#555;margin-top:3px;">Stripe's fee will be recorded on the card payments that don't have one yet (as <em>Sync Stripe fees</em> would).</div>`;
    onChange(ok);
  };
  // Ticking starts "covers" at the smaller of what the payment has left and what the deposit still needs; a payment already here is always whole.
  const tickRow = (p, on) => {
    box(p).checked = on; cov(p).disabled = !on || p.whole;
    if(!on){ cov(p).value = ""; return; }
    const rem = Math.round(p.remaining * 100), need = Math.max(shortfall(), 0);
    cov(p).value = ((p.whole ? rem : (need > 0 && need < rem ? need : rem)) / 100).toFixed(2);
  };
  // The filter only HIDES rows, so ticks and amounts survive switching between Venmo / cash / checks.
  const applyFilter = () => {
    const f = filterEl.value; let n = 0;
    listEl.querySelectorAll("tr[data-method]").forEach(tr => { const show = !f || tr.dataset.method === f; tr.style.display = show ? "" : "none"; if(show) n++; });
    const empty = listEl.querySelector("#vmEmpty");
    if(empty){ empty.style.display = n ? "none" : ""; empty.textContent = `No ${f ? METHOD[f].toLowerCase() + " " : ""}payments waiting to be deposited. (Record an order's payment first, under Orders → Payments.)`; }
  };
  const paint = () => {
    const shown = pays;
    listEl.innerHTML = shown.length ? `<div id="vmEmpty" style="display:none;padding:10px;color:#888;"></div><table style="border-collapse:collapse;width:100%;">${shown.map(p => `<tr data-method="${escapeHtml(p.method)}" style="border-bottom:1px solid #f0f0f0;">
        <td style="padding:4px 8px;width:24px;"><input type="checkbox" data-pid="${p.id}"></td>
        <td style="padding:4px 4px;white-space:nowrap;">${escapeHtml(String(p.receivedAt).slice(0, 10))}</td>
        <td style="padding:4px 8px;"><span style="font-size:10px;font-weight:700;padding:1px 6px;border-radius:3px;background:#e0e7ff;color:#3730a3;">${escapeHtml((METHOD[p.method] || p.method).toUpperCase())}</span> ${escapeHtml(p.orderId)}
          <div style="font-size:11px;color:#777;">${escapeHtml(p.customerName)} · in ${escapeHtml(p.accountName)}${p.direct ? " (matched whole)" : ""}</div></td>
        <td style="padding:4px 8px;font-size:12px;color:#555;">${p.cashedOut > 0 ? `${$(Math.round(p.remaining * 100))} left of ${$(Math.round(p.amount * 100))}<div style="font-size:11px;color:#777;">${$(Math.round(p.cashedOut * 100))} already deposited</div>` : `${$(Math.round(p.amount * 100))}`}</td>
        <td style="padding:4px 8px;text-align:right;white-space:nowrap;">covers $<input type="number" min="0.01" step="0.01" max="${p.remaining.toFixed(2)}" data-cov="${p.id}" disabled style="${inp}width:84px;"></td></tr>`).join("")}</table>`
      : `<div style="padding:10px;color:#888;">No Venmo, cash or check payments waiting to be deposited. (Record an order's payment first, under Orders → Payments.)</div>`;
    shown.forEach(p => { box(p).onchange = () => { tickRow(p, box(p).checked); recalc(); }; cov(p).oninput = recalc; });
    applyFilter(); recalc();
  };
  onChange(false);
  mnApi_({ action: "listCashoutPayments", accountId }).then(d => { pays = d.payments || []; paint(); }).catch(e => { listEl.textContent = e.message; });
  filterEl.onchange = applyFilter;
  el.querySelector("#vmOldest").onclick = () => {
    const f = filterEl.value;
    pays.forEach(p => { if(box(p)) tickRow(p, false); });
    [...pays].reverse().forEach(p => { if(box(p) && (!f || p.method === f) && shortfall() > 0) tickRow(p, true); });
    recalc();
  };
  return { collect: () => ({ allocations: rows().map(r => ({ paymentId: r.p.id, amount: r.c / 100 })), feeCategoryId: Number(el.querySelector("#vmCat").value) || 0 }) };
}

async function rcCreateModal_(d, line, act){
  const into = line.amount > 0;
  let cats = [], incomeTypes = {};
  try { const c = await mnApi_({ action: "listExpenseCategories" }); cats = c.categories; } catch (_) {}
  try { incomeTypes = (await loadAccounts_()).otherIncomeTypes || {}; } catch (_) {}
  const accounts = ((await loadAccounts_().catch(() => ({ accounts: [] }))).accounts || []).filter(a => a.id !== d.account.id);
  let blanks = [];
  if (!into) { try { blanks = (await mnApi_({ action: "getBlanks" })).blanks || []; } catch (_) {} }
  const blankName = (b) => b.name || [b.brand, b.color].filter(Boolean).join(" ") || "Blank #" + b.id;
  const inp = "font-size:13px;padding:5px 7px;border:1px solid #ccc;border-radius:4px;box-sizing:border-box;";
  const kinds = into ? [["income", "Other income (bank bonus, interest, services)"], ["expense_refund", "Refund of an expense (returned item, reversed fee)"],
                        ["deposit", "Deposit — Stripe payout, Venmo, Zelle, cash or checks (map to orders)"], ["owner", "Owner put money in"], ["transfer", "Transfer from another account"]]
                     : [["expense", "Business expense"], ["blanks", "Blank purchase (inventory, R&D, personal)"], ["owner", "Owner took money out"], ["transfer", "Transfer to another account"]];
  const { ov, close } = inventoryModal_("Record this statement line", `
    <div style="font-size:14px;margin-bottom:10px;"><strong>${escapeHtml(line.date)}</strong> — ${escapeHtml(line.description)} — <strong>${line.amount < 0 ? "−" : ""}$${Math.abs(line.amount).toFixed(2)}</strong></div>
    <label style="font-size:12px;font-weight:600;display:block;margin-bottom:8px;">It's a<br><select id="rccKind" style="${inp}">${kinds.map(([k, v]) => `<option value="${k}">${v}</option>`).join("")}</select></label>
    <div id="rccHint" style="font-size:12px;color:#555;margin:-2px 0 10px;"></div>
    <label id="rccDescWrap" style="font-size:12px;font-weight:600;display:block;margin-bottom:8px;">Description<br><input id="rccDesc" value="${escapeHtml(line.description)}" maxlength="300" style="${inp}width:100%;"></label>
    <div id="rccExtra"></div>
    <div id="rccNote" style="font-size:12px;color:#555;margin:6px 0 10px;">Dated ${escapeHtml(line.date)}, $${Math.abs(line.amount).toFixed(2)}, in ${escapeHtml(d.account.name)} — and matched to this line. Edit details (receipt, vendor, business-use %) afterwards on the Expenses or Accounts &amp; money screen.</div>
    <div style="display:flex;justify-content:flex-end;gap:8px;"><button type="button" id="rccCancel" style="padding:6px 12px;border:1px solid #ccc;border-radius:5px;background:#fff;cursor:pointer;">Cancel</button>
      <button type="button" id="rccOk" class="admin-btn" style="padding:6px 12px;">Create &amp; match</button></div>`, 620);
  const extra = ov.querySelector("#rccExtra"), kindEl = ov.querySelector("#rccKind");
  let blankForm = null, refundForm = null, venmoForm = null;
  const HINTS = {
    expense_refund: "Money back for something you bought. It's recorded as a negative expense in the original category, so it reduces that line of Schedule C — it is not income.",
    deposit: "A deposit that pays off orders: a Venmo cash-out, cash, checks, Zelle (or a mix on one slip), or a Stripe payout. Map it to the orders' payments it covers. Cash and Venmo can be deposited in parts; a check already in this account, or a card payment in a Stripe payout, is matched whole. If the deposit is short of what you ticked, the difference is recorded: Stripe's fee goes on the card payments; Venmo's fee, cash you kept or a deposit fee become an expense.",
    income: "Money you earned that isn't an order payment: a bank bonus or promotion, interest, or service work. A bonus/promotion is Other business income. (If the bank is just giving back a fee it charged you, use Refund of an expense.)",
    owner: "You put your own money into the business.",
    transfer: "Moving money between your own accounts.",
  };
  // A sensible starting choice from the bank's wording.
  if(into){
    const t = String(line.description || "");
    if(/refund|return|revers|credit adj|chargeback|rebate/i.test(t)) kindEl.value = "expense_refund";
    else if(/venmo|stripe|zelle|deposit|check|cheque|cash/i.test(t)) kindEl.value = "deposit";
  }
  const draw = () => {
    const k = kindEl.value;
    ov.querySelector("#rccHint").textContent = HINTS[k] || "";
    ov.querySelector("#rccDescWrap").style.display = k === "blanks" || k === "deposit" ? "none" : "";
    ov.querySelector("#rccNote").style.display = k === "blanks" || k === "deposit" ? "none" : "";
    extra.innerHTML = k === "expense" ? `<label style="font-size:12px;font-weight:600;display:block;margin-bottom:8px;">Category<br><select id="rccCat" style="${inp}"><option value="">Choose…</option>${cats.map(c => `<option value="${c.id}">${escapeHtml(c.name)}</option>`).join("")}</select></label>`
      : k === "income" ? `<label style="font-size:12px;font-weight:600;display:block;margin-bottom:8px;">Type<br><select id="rccType" style="${inp}">${Object.entries(incomeTypes).map(([t, v]) => `<option value="${t}">${escapeHtml(v)}</option>`).join("")}</select></label>`
      : k === "transfer" ? `<label style="font-size:12px;font-weight:600;display:block;margin-bottom:8px;">${into ? "From" : "To"} account<br><select id="rccOther" style="${inp}">${accountOptions_(accounts, (accounts[0] || {}).id)}</select></label>`
      : k === "expense_refund" ? `<div id="rccRefundForm"></div>`
      : k === "deposit" ? `<div id="rccVenmoForm"></div>`
      : k === "blanks" ? (blanks.length ? `<div id="rccBlankForm"></div>`
        : `<div style="font-size:13px;color:#888;">No blanks set up yet — add them under Blanks first.</div>`) : "";
    const gate = (ok) => { const b = ov.querySelector("#rccOk"); if(b){ b.disabled = !ok; b.style.opacity = ok ? "" : ".5"; } };
    if (k === "expense_refund") {
      refundForm = rcRefundForm_(ov.querySelector("#rccRefundForm"), { cats, line, onChange: gate });
    } else if (k === "deposit") {
      venmoForm = rcDepositForm_(ov.querySelector("#rccVenmoForm"), { cats, line, accountId: d.account.id, onChange: gate });
    } else if (k === "blanks" && blanks.length) {
      const okBtn = ov.querySelector("#rccOk");
      blankForm = blankOrderForm_(ov.querySelector("#rccBlankForm"), { blanks, cats, target: () => Math.round(Math.abs(line.amount) * 100),
        hint: `Everything must add up to exactly $${Math.abs(line.amount).toFixed(2)}.`,
        onChange: (ok) => { okBtn.disabled = !ok; okBtn.style.opacity = ok ? "" : ".5"; } });
    } else { const okBtn = ov.querySelector("#rccOk"); if (okBtn) { okBtn.disabled = false; okBtn.style.opacity = ""; } }
  };
  kindEl.onchange = draw; draw();
  ov.querySelector("#rccCancel").onclick = close;
  ov.querySelector("#rccOk").onclick = async () => {
    const k = kindEl.value, body = { action: "createFromStatementLine", lineId: line.id, kind: k, description: ov.querySelector("#rccDesc").value.trim() };
    if (k === "expense") { body.categoryId = Number((ov.querySelector("#rccCat") || {}).value); if (!body.categoryId) return; }
    if (k === "income") body.incomeType = ov.querySelector("#rccType").value;
    if (k === "transfer") body.otherAccountId = Number(ov.querySelector("#rccOther").value);
    if (k === "blanks") { if (!blankForm) return; Object.assign(body, blankForm.collect()); }
    if (k === "expense_refund") { if (!refundForm) return; Object.assign(body, refundForm.collect()); if (!body.categoryId) return; }
    if (k === "deposit") { if (!venmoForm) return; Object.assign(body, venmoForm.collect()); if (!body.allocations.length) return; }
    close(); await act(body);
  };
}

function rcImportPreview_(d, file){
  const mapEl = document.getElementById("rcMap");
  if (!file) return;
  const inp = "font-size:12px;padding:4px 6px;border:1px solid #ccc;border-radius:4px;";
  const reader = new FileReader();
  reader.onload = () => {
    const rows = parseCsv_(String(reader.result || ""));
    if (rows.length < 2) { mapEl.textContent = "That file has no rows."; return; }
    const header = rows[0].map(h => h.trim()), body = rows.slice(1);
    let saved = {}; try { saved = d.account.csvMapping ? JSON.parse(d.account.csvMapping) : {}; } catch (_) {}
    const find = (re) => { const i = header.findIndex(h => re.test(h)); return i < 0 ? 0 : i; };
    const byName = (name, fallback) => { const i = header.indexOf(name); return i >= 0 ? i : fallback; };
    // A column named e.g. "Debit/Credit" matches both /debit/ and /credit/ on
    // its own — that's one signed amount column, not split debit/credit
    // columns. Only treat it as split when a debit-only header and a
    // credit-only header are two DIFFERENT columns; otherwise it's "one" and
    // the amount regex below picks up the combined column instead.
    const debitIdx = header.findIndex(h => /debit|withdraw/i.test(h) && !/credit|deposit/i.test(h));
    const creditIdx = header.findIndex(h => /credit|deposit/i.test(h) && !/debit|withdraw/i.test(h));
    const isSplit = debitIdx >= 0 && creditIdx >= 0 && debitIdx !== creditIdx;
    const mp = {
      date: byName(saved.date, find(/date/i)), desc: byName(saved.desc, find(/desc|memo|payee|name|detail/i)),
      mode: saved.mode || (isSplit ? "split" : "one"),
      amount: byName(saved.amount, find(/amount|net|debit.*credit|credit.*debit|withdraw.*deposit|deposit.*withdraw/i)),
      debit: byName(saved.debit, debitIdx >= 0 ? debitIdx : 0), credit: byName(saved.credit, creditIdx >= 0 ? creditIdx : 0),
      flip: saved.flip != null ? !!saved.flip : d.account.type === "credit_card",
    };
    const opts = (sel) => header.map((h, i) => `<option value="${i}"${i === sel ? " selected" : ""}>${escapeHtml(h || "Column " + (i + 1))}</option>`).join("");
    const draw = () => {
      const { lines, errors } = mapStatementRows_(body, mp);
      const inMonth = lines.filter(l => l.date.slice(0, 7) === d.month).length;
      mapEl.innerHTML = `
        <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end;font-size:12px;">
          <label>Date<br><select data-k="date" style="${inp}">${opts(mp.date)}</select></label>
          <label>Description<br><select data-k="desc" style="${inp}">${opts(mp.desc)}</select></label>
          <label>Amounts are in<br><select data-k="mode" style="${inp}"><option value="one"${mp.mode === "one" ? " selected" : ""}>one column</option><option value="split"${mp.mode === "split" ? " selected" : ""}>debit &amp; credit columns</option></select></label>
          ${mp.mode === "one" ? `<label>Amount<br><select data-k="amount" style="${inp}">${opts(mp.amount)}</select></label>`
            : `<label>Debit (money out)<br><select data-k="debit" style="${inp}">${opts(mp.debit)}</select></label><label>Credit (money in)<br><select data-k="credit" style="${inp}">${opts(mp.credit)}</select></label>`}
          <label style="display:flex;gap:4px;align-items:center;"><input type="checkbox" data-k="flip" ${mp.flip ? "checked" : ""}> Flip signs</label>
        </div>
        <div style="font-size:12px;color:#555;margin:8px 0 4px;">Preview — money <strong>into</strong> ${escapeHtml(d.account.name)} should be positive, money out negative${d.account.type === "credit_card" ? " (a card charge is money out)" : ""}. ${lines.length} line${lines.length === 1 ? "" : "s"} (${inMonth} in ${escapeHtml(d.month)})${errors.length ? `, <span style="color:#b03a2e;">${errors.length} unreadable (rows ${errors.slice(0, 5).join(", ")}${errors.length > 5 ? "…" : ""})</span>` : ""}.</div>
        <table style="border-collapse:collapse;font-size:12px;margin-bottom:8px;">${lines.slice(0, 5).map(l => `<tr><td style="padding:2px 8px;">${escapeHtml(l.date)}</td><td style="padding:2px 8px;">${escapeHtml(l.description)}</td><td style="padding:2px 8px;text-align:right;color:${l.amount < 0 ? "#b03a2e" : "#15803d"};">${l.amount < 0 ? "−" : ""}$${Math.abs(l.amount).toFixed(2)}</td></tr>`).join("")}</table>
        <button type="button" id="rcImport" class="admin-btn" style="padding:5px 12px;font-size:12px;" ${lines.length ? "" : "disabled"}>Import ${lines.length} line${lines.length === 1 ? "" : "s"}</button>`;
      mapEl.querySelectorAll("[data-k]").forEach(x => x.onchange = () => { const k = x.dataset.k; mp[k] = k === "flip" ? x.checked : k === "mode" ? x.value : Number(x.value); draw(); });
      mapEl.querySelector("#rcImport").onclick = async () => {
        const saveMap = { date: header[mp.date], desc: header[mp.desc], mode: mp.mode, amount: header[mp.amount], debit: header[mp.debit], credit: header[mp.credit], flip: mp.flip };
        try {
          const r = await mnApi_({ action: "importStatement", accountId: d.account.id, lines, mapping: saveMap });
          showToast(`Imported ${r.inserted} new line${r.inserted === 1 ? "" : "s"}${r.duplicates ? ` (${r.duplicates} already imported)` : ""}; ${r.matched} matched automatically.`);
          _accountsCache = null; await keepView_(() => rcLoad_());
        } catch (e) { showToast(e.message, true); }
      };
    };
    draw();
  };
  reader.readAsText(file);
}

// ---- Expenses (migrations/0012): Schedule C Part II + Form 4562 facts ---------
const _exp = { categories: [], lines: {}, methods: {}, editing: null, receipt: null };

async function expApi_(body){
  if (!adminKey) adminKey = (await adminLogin()) || "";
  const r = await fetch("/api/orders", { method: "POST", headers: {"Content-Type": "application/json"},
    body: JSON.stringify(Object.assign({ key: adminKey }, body)) });
  const d = await r.json().catch(() => ({ status: "error", message: "Server error (" + r.status + ")" }));
  if (!r.ok || d.status === "error") throw new Error((d && d.message) || "Request failed");
  return d;
}
const expMoney_ = (n) => (Number(n) < 0 ? "−$" : "$") + Math.abs(Number(n || 0)).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const expToday_ = () => new Date().toLocaleDateString("en-CA");
const EXP_TYPE_LABEL = { depreciation: "Depreciation", deductible: "Deductible", none: "None" };

async function renderExpenses(app){
  adminSetHash("expenses");
  document.title = adminTitle_("Expenses");
  const y = new Date().getFullYear();
  const inp = "font-size:13px;padding:6px 8px;border:1px solid #ccc;border-radius:4px;box-sizing:border-box;";
  const lbl = "display:block;font-size:12px;font-weight:600;margin-bottom:3px;";
  app.innerHTML = `
    ${adminPageHead_("Expenses")}
    <div class="admin-panel" style="--org-accent:var(--accent);max-width:1040px;margin:8px auto 60px;">
      <div id="expForm" style="border:1px solid #ddd;border-radius:8px;padding:14px 16px;margin-bottom:22px;background:var(--surface,#fff);">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;">
          <div id="expFormTitle" style="font-size:15px;font-weight:700;">Add expense</div>
          <button type="button" class="admin-btn" id="expImportBtn" style="padding:4px 12px;font-size:12px;" title="Import expenses from a card/bank statement or spreadsheet CSV">Import CSV</button>
        </div>
        <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end;">
          <div><label style="${lbl}" for="expDate">Date</label><input id="expDate" type="date" max="${expToday_()}" value="${expToday_()}" style="${inp}"></div>
          <div style="flex:2;min-width:200px;"><label style="${lbl}" for="expDesc">Description</label><input id="expDesc" type="text" maxlength="300" placeholder="e.g. Embroidery machine" style="${inp}width:100%;"></div>
          <div><label style="${lbl}" for="expCat">Category</label>
            <div style="display:flex;gap:4px;"><select id="expCat" style="${inp}max-width:260px;"></select>
              ${adminCan_("manager") ? `<button type="button" class="admin-btn" id="expCatManage" title="Manage categories" aria-label="Manage categories" style="padding:4px 9px;font-size:14px;">⚙</button>` : ""}</div></div>
          <div><label style="${lbl}" for="expAmount">Amount ($)</label><input id="expAmount" type="number" min="0.01" step="0.01" placeholder="0.00" style="${inp}width:110px;">
            <label style="display:flex;gap:4px;align-items:center;font-size:11px;color:#555;margin-top:3px;" title="Money back for an earlier purchase (a returned item, a reversed fee). It reduces this category instead of counting as income."><input type="checkbox" id="expRefund"> This is a refund</label></div>
        </div>
        <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end;margin-top:10px;">
          <div style="flex:1;min-width:160px;"><label style="${lbl}" for="expVendor">Vendor <span style="font-weight:400;color:#777;">(optional)</span></label><input id="expVendor" type="text" maxlength="120" placeholder="e.g. Amazon" style="${inp}width:100%;"></div>
          <div><label style="${lbl}" for="expPaidFrom">Paid from</label><select id="expPaidFrom" style="${inp}"></select></div>
          <div><label style="${lbl}" for="expBiz">Business use %</label><input id="expBiz" type="number" min="1" max="100" step="1" value="100" style="${inp}width:80px;"></div>
          <div><label style="${lbl}" for="expReceipt">Receipt <span style="font-weight:400;color:#777;">(image or PDF, optional)</span></label>
            <input id="expReceipt" type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif,.heic,.heif,application/pdf" style="font-size:12px;">
            <div id="expReceiptCurrent" style="font-size:12px;color:#555;margin-top:3px;"></div></div>
        </div>
        <div id="expUseTaxRow" style="display:none;margin-top:10px;font-size:13px;">
          <label style="display:inline-flex;align-items:center;gap:6px;"><input type="checkbox" id="expVendorTax" checked> Sales tax was charged by the vendor</label>
          <div style="font-size:12px;color:#555;margin-top:2px;">Uncheck if you paid no sales tax (e.g. an out-of-state online seller) — use tax is then due on it and shows in the Sales Tax Report.</div>
        </div>
        <div id="expDepFields" style="display:none;margin-top:12px;padding:10px 12px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;">
          <div style="font-size:13px;font-weight:600;margin-bottom:6px;">Capital equipment — details for Form 4562</div>
          <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end;">
            <div><label style="${lbl}" for="expPIS">Placed in service</label><input id="expPIS" type="date" style="${inp}"></div>
            <div><label style="${lbl}" for="expMethod">Method</label><select id="expMethod" style="${inp}"></select></div>
          </div>
          <div style="font-size:12px;color:#555;margin-top:6px;">Your CPA makes the election and works out the deduction; this records the facts. Section 179 or 100% bonus (for equipment acquired after Jan 19, 2025) writes it off in the first year; MACRS spreads it over 5–7 years. Items of <strong>$2,500 or less</strong> can usually just be expensed (de minimis safe harbor) — use a Deductible category for those.</div>
        </div>
        <div style="display:flex;gap:8px;align-items:center;margin-top:12px;">
          <button type="button" class="admin-pass-submit" id="expSave" style="padding:7px 18px;font-size:13px;">Save expense</button>
          <button type="button" class="admin-btn" id="expCancel" style="display:none;font-size:13px;">Cancel edit</button>
          <span id="expFormErr" style="color:#b03a2e;font-size:13px;"></span>
        </div>
        <div style="font-size:12px;color:#777;margin-top:10px;">Don't enter Stripe fees, Shippo postage, or blanks bought through Blanks → Receive — those are already recorded automatically.</div>
      </div>

      <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end;margin-bottom:12px;">
        <div><label style="${lbl}" for="expYear">Year</label><select id="expYear" style="${inp}">${[y, y - 1, y - 2].map(v => `<option value="${v}">${v}</option>`).join("")}</select></div>
        <div><label style="${lbl}" for="expMonth">Month</label><select id="expMonth" style="${inp}"><option value="">All months</option>${
          Array.from({ length: 12 }, (_, i) => `<option value="${String(i + 1).padStart(2, "0")}">${new Date(2000, i, 1).toLocaleString("en-US", { month: "long" })}</option>`).join("")}</select></div>
      </div>
      <div id="expSummary"></div>
      <div id="expList" style="font-size:14px;color:#888;">Loading…</div>
    </div>`;

  { const m = document.getElementById("expCatManage"); if (m) m.onclick = showExpenseCategoriesModal_; }
  document.getElementById("expImportBtn").onclick = showExpenseImportModal_;
  document.getElementById("expCat").onchange = expOnCategoryChange_;
  document.getElementById("expSave").onclick = expSave_;
  document.getElementById("expCancel").onclick = () => expResetForm_();
  document.getElementById("expYear").onchange = expLoad_;
  document.getElementById("expMonth").onchange = expLoad_;
  try {
    const d = await expApi_({ action: "listExpenseCategories" });
    _exp.categories = d.categories; _exp.lines = d.scheduleCLines; _exp.methods = d.depreciationMethods;
  } catch (e) { document.getElementById("expList").textContent = e.message; return; }
  document.getElementById("expMethod").innerHTML = Object.entries(_exp.methods).map(([k, v]) => `<option value="${escapeHtml(k)}">${escapeHtml(v)}</option>`).join("");
  try { _exp.accounts = (await loadAccounts_()).accounts; } catch (_) { _exp.accounts = []; }
  expFillCategorySelect_();
  expResetForm_();
  await expLoad_();
}

function expFillCategorySelect_(selectedId){
  const sel = document.getElementById("expCat");
  if (!sel) return;
  const keep = selectedId || sel.value;
  sel.innerHTML = `<option value="">Choose…</option>` + _exp.categories.map(c =>
    `<option value="${c.id}">${escapeHtml(c.name)}${c.deductionType === "depreciation" ? " (depreciation)" : c.deductionType === "none" ? " (not deductible)" : ""}</option>`).join("");
  if (keep && _exp.categories.some(c => String(c.id) === String(keep))) sel.value = String(keep);
  expOnCategoryChange_();
}
function expOnCategoryChange_(){
  const cat = _exp.categories.find(c => String(c.id) === document.getElementById("expCat").value);
  const dep = !!cat && cat.deductionType === "depreciation";
  document.getElementById("expDepFields").style.display = dep ? "block" : "none";
  document.getElementById("expUseTaxRow").style.display = cat && cat.useTaxable ? "block" : "none";
  const pis = document.getElementById("expPIS");
  if (dep && !pis.value) pis.value = document.getElementById("expDate").value;
}
function expResetForm_(){
  _exp.editing = null; _exp.receipt = null;
  document.getElementById("expFormTitle").textContent = "Add expense";
  document.getElementById("expSave").textContent = "Save expense";
  document.getElementById("expCancel").style.display = "none";
  document.getElementById("expDate").value = expToday_();
  ["expDesc", "expAmount", "expVendor", "expPIS"].forEach(id => { document.getElementById(id).value = ""; });
  document.getElementById("expBiz").value = "100";
  document.getElementById("expVendorTax").checked = true;
  document.getElementById("expRefund").checked = false; _exp.refundOfId = null;
  let lastPaidFrom = ""; try { lastPaidFrom = localStorage.getItem("oddExpPaidFrom") || ""; } catch (_) {}
  const cc = (_exp.accounts || []).find(a => a.type === "credit_card" && a.active);
  document.getElementById("expPaidFrom").innerHTML = accountOptions_(_exp.accounts || [], lastPaidFrom || (cc && cc.id) || "", { personal: true });
  document.getElementById("expReceipt").value = "";
  document.getElementById("expReceiptCurrent").innerHTML = "";
  document.getElementById("expMethod").value = "ask_cpa";
  document.getElementById("expCat").value = "";
  document.getElementById("expFormErr").textContent = "";
  expOnCategoryChange_();
}
function expEdit_(id){
  const x = (_exp.list || []).find(e => e.id === Number(id));
  if (!x) return;
  _exp.editing = x.id; _exp.receipt = x.receiptKey ? { key: x.receiptKey, name: x.receiptName } : null;
  document.getElementById("expFormTitle").textContent = "Edit expense";
  document.getElementById("expSave").textContent = "Save changes";
  document.getElementById("expCancel").style.display = "";
  document.getElementById("expDate").value = x.date;
  document.getElementById("expDesc").value = x.description;
  document.getElementById("expCat").value = String(x.categoryId);
  document.getElementById("expAmount").value = Math.abs(Number(x.amount)).toFixed(2);   // a refund is shown as a positive amount with the box ticked
  document.getElementById("expRefund").checked = x.amount < 0; _exp.refundOfId = x.refundOfId || null;
  document.getElementById("expVendor").value = x.vendor;
  document.getElementById("expBiz").value = String(x.businessUsePct);
  document.getElementById("expVendorTax").checked = x.vendorChargedTax !== false;
  document.getElementById("expPaidFrom").innerHTML = accountOptions_(_exp.accounts || [], x.paidPersonally ? "personal" : (x.accountId || ""), { personal: true, blank: !x.paidPersonally && !x.accountId });
  document.getElementById("expPIS").value = x.placedInService || "";
  document.getElementById("expMethod").value = x.depMethod || "ask_cpa";
  document.getElementById("expReceipt").value = "";
  document.getElementById("expReceiptCurrent").innerHTML = x.receiptKey
    ? `Current: ${escapeHtml(x.receiptName || "receipt")} <button type="button" id="expReceiptRemove" style="font-size:11px;padding:1px 6px;cursor:pointer;">Remove</button> <span style="color:#777;">(choose a file to replace it)</span>` : "";
  const rm = document.getElementById("expReceiptRemove");
  if (rm) rm.onclick = () => { _exp.receipt = null; document.getElementById("expReceiptCurrent").textContent = "Receipt will be removed when you save."; };
  expOnCategoryChange_();
  document.getElementById("expForm").scrollIntoView({ behavior: "smooth", block: "start" });
}

// Uploads a receipt to the private RECEIPTS bucket. Images are downscaled
// (existing resizeImageFile); PDFs go up as-is.
async function uploadReceipt_(file){
  file = await heicToJpeg_(file);   // a receipt photographed on an iPhone / iPad (HEIC) → JPEG
  const ok = ["image/jpeg", "image/png", "image/webp", "application/pdf"];
  if (!ok.includes(file.type)) throw new Error("Receipts must be a JPEG, PNG or WebP image, or a PDF.");
  const body = file.type === "application/pdf" ? file : await resizeImageFile(file, 1600);
  const r = await fetch("/api/receipt?name=" + encodeURIComponent(file.name || ""), {
    method: "POST", headers: { "X-Admin-Key": adminKey || "", "Content-Type": body.type || file.type }, body });
  const d = await r.json().catch(() => ({ status: "error", message: "Server error (" + r.status + ")" }));
  if (!r.ok || d.status === "error") throw new Error((d && d.message) || "Receipt upload failed");
  return { key: d.key, name: d.name };
}
// Opens a receipt: asks for a 60-second signed link (logged-in POST), then
// points a tab opened up front (so pop-up blockers allow it) at that link.
async function expViewReceipt_(key){
  const w = window.open("about:blank", "_blank");
  try {
    const r = await fetch("/api/receipt", { method: "POST", headers: { "Content-Type": "application/json", "X-Admin-Key": adminKey || "" },
      body: JSON.stringify({ key }) });
    const d = await r.json().catch(() => ({ status: "error", message: "Server error (" + r.status + ")" }));
    if (!r.ok || d.status === "error") throw new Error((d && d.message) || "Could not open receipt");
    if (w) { w.opener = null; w.location.href = d.url; } else location.href = d.url;
  } catch (e) { if (w) w.close(); showToast(e.message, true); }
}

async function expSave_(){
  const err = document.getElementById("expFormErr");
  err.textContent = "";
  const btn = document.getElementById("expSave");
  const cat = _exp.categories.find(c => String(c.id) === document.getElementById("expCat").value);
  const expense = {
    id: _exp.editing || undefined,
    date: document.getElementById("expDate").value,
    description: document.getElementById("expDesc").value.trim(),
    categoryId: cat ? cat.id : 0,
    amount: parseFloat(document.getElementById("expAmount").value),
    vendor: document.getElementById("expVendor").value.trim(),
    businessUsePct: parseInt(document.getElementById("expBiz").value, 10) || 100,
    vendorChargedTax: !(cat && cat.useTaxable) || document.getElementById("expVendorTax").checked,
  };
  if (document.getElementById("expRefund").checked) { expense.refund = true; if (_exp.refundOfId) expense.refundOfId = _exp.refundOfId; }
  const paidFrom = document.getElementById("expPaidFrom").value;
  if (!paidFrom) { err.textContent = "Choose which account paid it (or Personal funds)."; return; }
  if (paidFrom === "personal") expense.paidPersonally = true; else expense.accountId = Number(paidFrom);
  try { localStorage.setItem("oddExpPaidFrom", paidFrom); } catch (_) {}
  if (!expense.date) { err.textContent = "Enter the date."; return; }
  if (!expense.description) { err.textContent = "Enter a description."; return; }
  if (!cat) { err.textContent = "Choose a category."; return; }
  if (!(expense.amount > 0)) { err.textContent = "Enter an amount."; return; }
  if (cat.deductionType === "depreciation") {
    expense.placedInService = document.getElementById("expPIS").value || expense.date;
    expense.depMethod = document.getElementById("expMethod").value || "ask_cpa";
  }
  btn.disabled = true;
  try {
    const file = document.getElementById("expReceipt").files[0];
    if (file) { btn.textContent = "Uploading receipt…"; _exp.receipt = await uploadReceipt_(file); }
    expense.receiptKey = _exp.receipt ? _exp.receipt.key : "";
    expense.receiptName = _exp.receipt ? _exp.receipt.name : "";
    await expApi_({ action: "saveExpense", expense });
    showToast(_exp.editing ? "Expense updated." : "Expense saved.");
    expResetForm_();
    await expRefresh_();
  } catch (e) { err.textContent = e.message; }
  finally { btn.disabled = false; btn.textContent = _exp.editing ? "Save changes" : "Save expense"; }
}

async function expDelete_(id){
  const x = (_exp.list || []).find(e => e.id === Number(id));
  if (!x || !await askConfirm_(`Delete "${x.description}" (${expMoney_(x.amount)})? It's removed from all totals (kept in the audit log).`)) return;
  try { await expApi_({ action: "deleteExpense", expenseId: x.id }); showToast("Expense deleted."); if (_exp.editing === x.id) expResetForm_(); await expRefresh_(); }
  catch (e) { showToast(e.message, true); }
}

// After an expense is saved / deleted / imported: reload in place — the list's scroll and the open sections stay —
// and flash the expenses that are new or changed.
async function expRefresh_(){
  const snap = () => new Map((_exp.list || []).map(x => [x.id, JSON.stringify(x)]));
  const before = snap();
  await keepView_(expLoad_);
  const after = snap();
  flashRows_([...after.keys()].filter(id => before.get(id) !== after.get(id)).map(id => `tr[data-expense-row="${id}"]`));
}
async function expLoad_(){
  const y = document.getElementById("expYear").value, m = document.getElementById("expMonth").value;
  const from = m ? `${y}-${m}-01` : `${y}-01-01`;
  const to = m ? `${y}-${m}-${String(new Date(Number(y), Number(m), 0).getDate()).padStart(2, "0")}` : `${y}-12-31`;
  const listEl = document.getElementById("expList"), sumEl = document.getElementById("expSummary");
  let d;
  try { d = await expApi_({ action: "listExpenses", dateFrom: from, dateTo: to }); }
  catch (e) { listEl.textContent = e.message; return; }
  _exp.list = d.expenses;
  const s = d.summary;
  const th = "padding:7px 10px;text-align:left;background:#f0f0f0;color:#333;font-size:12px;font-weight:700;border-bottom:2px solid #ccc;";
  const td = "padding:8px 10px;border-bottom:1px solid #e5e7eb;vertical-align:top;color:#111;background:#fff;";
  const card = (label, v, note) => `<div style="flex:1;min-width:150px;border:1px solid #ddd;border-radius:6px;padding:10px 12px;background:var(--surface,#fff);">
      <div style="font-size:12px;color:#666;">${label}</div><div style="font-size:20px;font-weight:700;">${expMoney_(v)}</div>${note ? `<div style="font-size:11px;color:#777;">${note}</div>` : ""}</div>`;
  sumEl.innerHTML = `
    <div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:14px;">
      ${card("Total spent", s.totals.amount)}
      ${card("Deductible", s.totals.deductible, "Schedule C Part II, after meal and business-use %")}
      ${card("Capital equipment", s.totals.capital, "Depreciation — Form 4562 / line 13")}
      ${card("Not deductible", s.totals.nonDeductible)}
    </div>
    ${s.byLine.length ? `<details data-keep-open="exp-lines" style="margin-bottom:14px;"><summary style="cursor:pointer;font-size:14px;font-weight:600;">By Schedule C line</summary>
      <div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;margin-top:8px;"><table style="width:100%;border-collapse:collapse;font-size:14px;">
        <thead><tr><th style="${th}">Line</th><th style="${th}">Description</th><th style="${th}text-align:right;">Spent</th><th style="${th}text-align:right;">Deductible</th></tr></thead>
        <tbody>${s.byLine.map(l => `<tr><td style="${td}">${escapeHtml(l.line)}</td><td style="${td}">${escapeHtml(l.label)}</td><td style="${td}text-align:right;">${expMoney_(l.amount)}</td><td style="${td}text-align:right;font-weight:600;">${expMoney_(l.deductible)}</td></tr>`).join("")}</tbody>
      </table></div></details>` : ""}
    ${s.assets.length ? `<details data-keep-open="exp-assets" style="margin-bottom:14px;"><summary style="cursor:pointer;font-size:14px;font-weight:600;">Capital equipment (Form 4562)</summary>
      <div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;margin-top:8px;"><table style="width:100%;border-collapse:collapse;font-size:14px;">
        <thead><tr><th style="${th}">Placed in service</th><th style="${th}">Asset</th><th style="${th}text-align:right;">Cost</th><th style="${th}text-align:right;">Business use</th><th style="${th}text-align:right;">Business basis</th><th style="${th}">Method</th></tr></thead>
        <tbody>${s.assets.map(a => `<tr><td style="${td}">${escapeHtml(a.placedInService)}</td><td style="${td}">${escapeHtml(a.description)}${a.vendor ? `<br><span style="font-size:12px;color:#666;">${escapeHtml(a.vendor)}</span>` : ""}</td><td style="${td}text-align:right;">${expMoney_(a.cost)}</td><td style="${td}text-align:right;">${a.businessUsePct}%</td><td style="${td}text-align:right;">${expMoney_(a.businessBasis)}</td><td style="${td}">${escapeHtml(a.method)}</td></tr>`).join("")}</tbody>
      </table></div></details>` : ""}`;
  listEl.style.color = "var(--ink,#111)";
  listEl.innerHTML = d.expenses.length ? `<div data-keep-scroll="expenses" style="overflow:auto;max-height:60vh;border:1px solid #ddd;border-radius:6px;"><table class="stack-mobile" style="width:100%;border-collapse:collapse;font-size:14px;">
      <thead><tr><th style="${th}">Date</th><th style="${th}">Description</th><th style="${th}">Category</th><th style="${th}text-align:right;">Amount</th><th style="${th}text-align:right;">Deductible</th><th style="${th}"></th></tr></thead>
      <tbody>${d.expenses.map(x => `<tr data-expense-row="${x.id}">
        <td style="${td}white-space:nowrap;">${escapeHtml(x.date)}</td>
        <td style="${td}">${x.isRefund ? `<span style="font-size:10px;font-weight:700;padding:1px 6px;border-radius:3px;background:#dcfce7;color:#166534;margin-right:5px;" title="Money back for an earlier purchase — reduces this category">REFUND</span>` : ""}${escapeHtml(x.description)}${x.vendor ? `<br><span style="font-size:12px;color:#666;">${escapeHtml(x.vendor)}</span>` : ""}${x.businessUsePct < 100 ? `<br><span style="font-size:12px;color:#666;">${x.businessUsePct}% business use</span>` : ""}${x.useTaxDue ? `<br><span style="font-size:12px;color:#b45309;font-weight:600;">Use tax due — no sales tax charged</span>` : ""}<br><span style="font-size:12px;color:${x.paidPersonally || x.accountId ? "#666" : "#b45309"};">${x.paidPersonally ? "Paid personally" : x.accountId ? "Paid from " + escapeHtml(((_exp.accounts || []).find(a => a.id === x.accountId) || {}).name || "account") : "Paid from: not set"}</span></td>
        <td style="${td}">${escapeHtml(x.category)}<br><span style="font-size:12px;color:#666;">${escapeHtml(EXP_TYPE_LABEL[x.deductionType] || "")}${x.scheduleCLine ? " · line " + escapeHtml(x.scheduleCLine) : ""}${x.deductionType === "depreciation" && x.depMethod ? " · " + escapeHtml(_exp.methods[x.depMethod] || "") : ""}</span></td>
        <td style="${td}text-align:right;white-space:nowrap;">${expMoney_(x.amount)}</td>
        <td style="${td}text-align:right;white-space:nowrap;">${x.deductionType === "deductible" ? expMoney_(x.deductible) : x.deductionType === "depreciation" ? `<span style="font-size:12px;color:#666;">capital</span>` : "—"}</td>
        <td style="${td}white-space:nowrap;text-align:right;">
          ${x.receiptKey ? `<button type="button" class="admin-btn" style="padding:3px 8px;font-size:12px;" title="${escapeHtml(x.receiptName || "Receipt")}" data-key="${escapeHtml(x.receiptKey)}" onclick="expViewReceipt_(this.dataset.key)">📎 Receipt</button>` : ""}
          <button type="button" class="admin-btn" style="padding:3px 8px;font-size:12px;" data-id="${x.id}" onclick="expEdit_(this.dataset.id)">Edit</button>
          <button class="admin-btn-danger" type="button" style="padding:3px 8px;font-size:12px;border-radius:4px;cursor:pointer;" data-id="${x.id}" onclick="expDelete_(this.dataset.id)">Delete</button>
        </td></tr>`).join("")}</tbody></table></div>`
    : `<div style="color:#888;">No expenses recorded for this period.</div>`;
}

// Import expenses from a CSV (card/bank statement or a spreadsheet): same parser
// and column mapping as Reconcile, plus optional vendor / category columns.
// Money-out rows become expenses; rows already recorded (same date + amount)
// start unticked; categories come from a category column or your past
// expenses with the same description.
function showExpenseImportModal_(){
  const inp = "font-size:12px;padding:4px 6px;border:1px solid #ccc;border-radius:4px;";
  const accounts = _exp.accounts || [];
  let lastPaidFrom = ""; try { lastPaidFrom = localStorage.getItem("oddExpPaidFrom") || ""; } catch (_) {}
  const cc = accounts.find(a => a.type === "credit_card" && a.active);
  const { ov, close } = inventoryModal_("Import expenses from CSV", `
    <div style="display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end;font-size:12px;margin-bottom:10px;">
      <label style="font-weight:600;">Paid from<br><select id="eiPaidFrom" style="${inp}">${accountOptions_(accounts, lastPaidFrom || (cc && cc.id) || "", { personal: true })}</select></label>
      <label style="font-weight:600;">CSV file<br><input type="file" id="eiFile" accept=".csv,text/csv" style="font-size:12px;"></label>
    </div>
    <div style="font-size:12px;color:#555;margin-bottom:8px;">Tip: import a card or bank statement here, then reconcile the same statement later — its lines will match these expenses automatically. Card payments and refunds (money in) are skipped.</div>
    <div id="eiMap"></div><div id="eiReview"></div>
    <div id="eiErr" style="color:#b03a2e;font-size:13px;min-height:16px;margin-top:8px;"></div>`, 980);
  const err = ov.querySelector("#eiErr");
  const fileEl = ov.querySelector("#eiFile"), paidEl = ov.querySelector("#eiPaidFrom");
  let header = [], body = [], mp = null;
  const mapFor = () => {
    const acct = accounts.find(a => String(a.id) === paidEl.value);
    let saved = {}; try { saved = acct && acct.csvMapping ? JSON.parse(acct.csvMapping) : {}; } catch (_) {}
    const find = (re, dflt = 0) => { const i = header.findIndex(h => re.test(h)); return i < 0 ? dflt : i; };
    const byName = (name, fallback) => { const i = name ? header.indexOf(name) : -1; return i >= 0 ? i : fallback; };
    return { date: byName(saved.date, find(/date/i)), desc: byName(saved.desc, find(/desc|memo|payee|name|detail/i)),
      mode: saved.mode || (header.some(h => /debit/i.test(h)) && header.some(h => /credit/i.test(h)) ? "split" : "one"),
      amount: byName(saved.amount, find(/amount|total|cost/i)), debit: byName(saved.debit, find(/debit|withdraw/i)), credit: byName(saved.credit, find(/credit|deposit/i)),
      flip: saved.flip != null ? !!saved.flip : (acct ? acct.type === "credit_card" : true),
      vendor: byName(saved.vendor, find(/vendor|merchant|payee/i, -1)), category: byName(saved.category, find(/categ/i, -1)) };
  };
  const opts = (sel, none) => (none ? `<option value="-1"${sel === -1 ? " selected" : ""}>(none)</option>` : "") +
    header.map((h, i) => `<option value="${i}"${i === sel ? " selected" : ""}>${escapeHtml(h || "Column " + (i + 1))}</option>`).join("");
  const drawMap = () => {
    const mapEl = ov.querySelector("#eiMap");
    const { lines } = mapStatementRows_(body, mp);
    const out = lines.filter(l => l.amount < 0).length, inn = lines.length - out;
    mapEl.innerHTML = `
      <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end;font-size:12px;">
        <label>Date<br><select data-k="date" style="${inp}">${opts(mp.date)}</select></label>
        <label>Description<br><select data-k="desc" style="${inp}">${opts(mp.desc)}</select></label>
        <label>Vendor<br><select data-k="vendor" style="${inp}">${opts(mp.vendor, true)}</select></label>
        <label>Category<br><select data-k="category" style="${inp}">${opts(mp.category, true)}</select></label>
        <label>Amounts in<br><select data-k="mode" style="${inp}"><option value="one"${mp.mode === "one" ? " selected" : ""}>one column</option><option value="split"${mp.mode === "split" ? " selected" : ""}>debit &amp; credit</option></select></label>
        ${mp.mode === "one" ? `<label>Amount<br><select data-k="amount" style="${inp}">${opts(mp.amount)}</select></label>`
          : `<label>Debit (out)<br><select data-k="debit" style="${inp}">${opts(mp.debit)}</select></label><label>Credit (in)<br><select data-k="credit" style="${inp}">${opts(mp.credit)}</select></label>`}
        <label style="display:flex;gap:4px;align-items:center;"><input type="checkbox" data-k="flip" ${mp.flip ? "checked" : ""}> Flip signs</label>
        <button type="button" id="eiReviewBtn" class="admin-btn" style="padding:4px 12px;font-size:12px;">Review ${out} expense${out === 1 ? "" : "s"}</button>
      </div>
      <div style="font-size:12px;color:#555;margin-top:4px;">${out} money-out row${out === 1 ? "" : "s"} → expenses${inn ? `; ${inn} money-in row${inn === 1 ? "" : "s"} skipped (refunds, payments)` : ""}. If purchases show as money in, tick <em>Flip signs</em>.</div>`;
    mapEl.querySelectorAll("[data-k]").forEach(x => x.onchange = () => { const k = x.dataset.k; mp[k] = k === "flip" ? x.checked : k === "mode" ? x.value : Number(x.value); ov.querySelector("#eiReview").innerHTML = ""; drawMap(); });
    mapEl.querySelector("#eiReviewBtn").onclick = review;
  };
  const review = async () => {
    err.textContent = "";
    const reviewEl = ov.querySelector("#eiReview");
    // Keep each row's extra columns (vendor / category) alongside the mapped line.
    const rows = [];
    body.forEach(r => {
      const { lines } = mapStatementRows_([r], mp);
      if (!lines.length || lines[0].amount >= 0) return;
      rows.push({ date: lines[0].date, description: lines[0].description, amount: Math.round(-lines[0].amount * 100) / 100,
        vendor: mp.vendor >= 0 ? String(r[mp.vendor] || "").trim() : "", categoryName: mp.category >= 0 ? String(r[mp.category] || "").trim() : "" });
    });
    if (!rows.length) { reviewEl.innerHTML = `<div style="font-size:13px;color:#888;margin-top:8px;">No money-out rows to import.</div>`; return; }
    let pv;
    try { pv = await expApi_({ action: "previewExpenseImport", rows: rows.map(r => ({ date: r.date, description: r.description || "x", amount: r.amount })) }); }
    catch (e) { err.textContent = e.message; return; }
    // A category column matches a category's exact name, else the start of one ("Software" → "Software & subscriptions").
    const catFromName = (n) => { const t = n.trim().toLowerCase(); if (t.length < 3) return null;
      const exact = _exp.categories.find(c => c.name.toLowerCase() === t); if (exact) return exact.id;
      const start = _exp.categories.find(c => c.name.toLowerCase().startsWith(t)); return start ? start.id : null; };
    rows.forEach((r, i) => { r.duplicate = pv.rows[i].duplicate; r.categoryId = catFromName(r.categoryName) || pv.rows[i].suggestedCategoryId || ""; });
    const catOpts = (sel) => `<option value="">Choose…</option>` + _exp.categories.map(c => `<option value="${c.id}"${String(c.id) === String(sel) ? " selected" : ""}>${escapeHtml(c.name)}</option>`).join("");
    const td = "padding:4px 6px;border-bottom:1px solid #eee;vertical-align:middle;";
    reviewEl.innerHTML = `
      <div style="max-height:360px;overflow:auto;border:1px solid #ddd;border-radius:6px;margin-top:10px;"><table style="width:100%;border-collapse:collapse;font-size:12px;">
        <thead><tr style="background:#f3f4f6;text-align:left;"><th style="${td}"><input type="checkbox" id="eiAll" checked title="Tick all / none"></th><th style="${td}">Date</th><th style="${td}">Description</th><th style="${td}">Vendor</th><th style="${td}text-align:right;">Amount</th><th style="${td}">Category</th><th style="${td}"></th></tr></thead>
        <tbody>${rows.map((r, i) => `<tr data-i="${i}">
          <td style="${td}"><input type="checkbox" class="ei-on" ${r.duplicate ? "" : "checked"}></td>
          <td style="${td}white-space:nowrap;">${escapeHtml(r.date)}</td>
          <td style="${td}"><input class="ei-desc" value="${escapeHtml(r.description)}" maxlength="300" style="${inp}width:100%;min-width:180px;"></td>
          <td style="${td}"><input class="ei-vendor" value="${escapeHtml(r.vendor)}" maxlength="120" style="${inp}width:110px;"></td>
          <td style="${td}text-align:right;white-space:nowrap;">$${r.amount.toFixed(2)}</td>
          <td style="${td}"><select class="ei-cat" style="${inp}max-width:190px;">${catOpts(r.categoryId)}</select></td>
          <td style="${td}font-size:11px;color:#b45309;">${r.duplicate ? "Looks already recorded" : ""}</td></tr>`).join("")}</tbody></table></div>
      <div style="display:flex;justify-content:space-between;align-items:center;margin-top:10px;">
        <span id="eiCount" style="font-size:13px;"></span>
        <span><button type="button" id="eiCancel" style="padding:6px 12px;border:1px solid #ccc;border-radius:5px;background:#fff;cursor:pointer;">Cancel</button>
        <button type="button" id="eiGo" class="admin-pass-submit" style="padding:6px 14px;font-size:13px;">Import</button></span></div>`;
    const trs = () => [...reviewEl.querySelectorAll("tbody tr")];
    const count = () => { const on = trs().filter(tr => tr.querySelector(".ei-on").checked);
      const total = on.reduce((a, tr) => a + rows[Number(tr.dataset.i)].amount, 0);
      reviewEl.querySelector("#eiCount").textContent = `${on.length} expense${on.length === 1 ? "" : "s"}, $${total.toFixed(2)}`;
      reviewEl.querySelector("#eiGo").textContent = `Import ${on.length}`; };
    reviewEl.querySelectorAll(".ei-on").forEach(x => x.onchange = count);
    reviewEl.querySelector("#eiAll").onchange = (e) => { trs().forEach(tr => { tr.querySelector(".ei-on").checked = e.target.checked; }); count(); };
    count();
    reviewEl.querySelector("#eiCancel").onclick = close;
    reviewEl.querySelector("#eiGo").onclick = async () => {
      err.textContent = "";
      const chosen = trs().filter(tr => tr.querySelector(".ei-on").checked).map(tr => { const r = rows[Number(tr.dataset.i)];
        return { date: r.date, amount: r.amount, description: tr.querySelector(".ei-desc").value.trim(), vendor: tr.querySelector(".ei-vendor").value.trim(),
          categoryId: Number(tr.querySelector(".ei-cat").value) || 0 }; });
      if (!chosen.length) { err.textContent = "Tick at least one row."; return; }
      const missing = chosen.findIndex(r => !r.categoryId || !r.description);
      if (missing >= 0) { err.textContent = `Every ticked row needs a description and a category (row dated ${chosen[missing].date}, $${chosen[missing].amount.toFixed(2)}).`; return; }
      const paid = paidEl.value;
      const payload = { action: "importExpenses", rows: chosen,
        mapping: { date: header[mp.date], desc: header[mp.desc], mode: mp.mode, amount: header[mp.amount], debit: header[mp.debit], credit: header[mp.credit],
          flip: mp.flip, vendor: mp.vendor >= 0 ? header[mp.vendor] : "", category: mp.category >= 0 ? header[mp.category] : "" },
        ...(paid === "personal" ? { paidPersonally: true } : { accountId: Number(paid) }) };
      const btn = reviewEl.querySelector("#eiGo"); btn.disabled = true;
      try { const r = await expApi_(payload); close(); showToast(`Imported ${r.imported} expense${r.imported === 1 ? "" : "s"}.`); _accountsCache = null; await expRefresh_(); }
      catch (e) { err.textContent = e.message; btn.disabled = false; }
    };
  };
  const load = () => {
    const f = fileEl.files[0]; if (!f) return;
    const reader = new FileReader();
    reader.onload = () => {
      const rows = parseCsv_(String(reader.result || ""));
      if (rows.length < 2) { err.textContent = "That file has no rows."; return; }
      header = rows[0].map(h => h.trim()); body = rows.slice(1); mp = mapFor();
      ov.querySelector("#eiReview").innerHTML = ""; drawMap();
    };
    reader.readAsText(f);
  };
  fileEl.onchange = load;
  paidEl.onchange = () => { if (header.length) { mp = mapFor(); ov.querySelector("#eiReview").innerHTML = ""; drawMap(); } };
}

// ⚙ Manage categories: name, deduction type, Schedule C line, deductible %.
// Delete is only offered for categories no expense uses (server enforces too).
function showExpenseCategoriesModal_(){
  const inp = "font-size:13px;padding:4px 6px;border:1px solid #ccc;border-radius:4px;box-sizing:border-box;";
  const lineOpts = (sel) => `<option value="">—</option>` + Object.entries(_exp.lines).map(([k, v]) =>
    `<option value="${escapeHtml(k)}"${k === sel ? " selected" : ""}>${escapeHtml(k)} · ${escapeHtml(v)}</option>`).join("");
  const typeOpts = (sel) => Object.entries(EXP_TYPE_LABEL).map(([k, v]) => `<option value="${k}"${k === sel ? " selected" : ""}>${v}</option>`).join("");
  const row = (c) => `<tr data-cat-row="${c ? c.id : "new"}" style="border-top:1px solid #e5e7eb;">
      <td style="padding:5px 4px;"><input data-f="name" value="${escapeHtml(c ? c.name : "")}" placeholder="${c ? "" : "New category name"}" maxlength="80" style="${inp}width:100%;"></td>
      <td style="padding:5px 4px;"><select data-f="deductionType" style="${inp}">${typeOpts(c ? c.deductionType : "deductible")}</select></td>
      <td style="padding:5px 4px;"><select data-f="scheduleCLine" style="${inp}max-width:190px;">${lineOpts(c ? c.scheduleCLine : "")}</select></td>
      <td style="padding:5px 4px;"><input data-f="deductiblePct" type="number" min="0" max="100" step="1" value="${c ? c.deductiblePct : 100}" style="${inp}width:62px;"></td>
      <td style="padding:5px 4px;text-align:center;"><input data-f="useTaxable" type="checkbox" ${c && c.useTaxable ? "checked" : ""} title="Goods the business buys and uses: use tax is owed when the vendor doesn't charge sales tax"></td>
      <td style="padding:5px 4px;text-align:center;font-size:12px;color:#666;">${c ? c.expenseCount : ""}</td>
      <td style="padding:5px 4px;white-space:nowrap;">
        <button type="button" class="admin-btn" data-save="${c ? c.id : "new"}" style="padding:3px 8px;font-size:12px;">${c ? "Save" : "Add"}</button>
        ${c ? `<button type="button" data-del="${c.id}" ${c.expenseCount > 0 ? `disabled title="Used by ${c.expenseCount} expense(s) — can't delete"` : `title="Delete category"`} style="padding:3px 8px;font-size:12px;border-radius:4px;border:1px solid #fca5a5;background:#fee2e2;color:#b03a2e;cursor:${c.expenseCount > 0 ? "not-allowed" : "pointer"};opacity:${c.expenseCount > 0 ? ".45" : "1"};">Delete</button>` : ""}
      </td></tr>`;
  const { ov } = inventoryModal_("Expense categories", `
    <div style="font-size:12px;color:#555;margin-bottom:10px;"><strong>Deductible</strong>: ordinary expenses (Schedule C Part II). <strong>Depreciation</strong>: capital equipment such as machines (Form 4562). <strong>None</strong>: not deductible. Deductible % is for items only partly deductible — business meals are 50%. <strong>Use tax</strong>: goods you buy and use (equipment, supplies) — use tax is owed when the seller didn't charge sales tax. A category can only be deleted when no expense uses it.</div>
    <div style="overflow-x:auto;"><table style="border-collapse:collapse;width:100%;font-size:13px;">
      <thead><tr style="text-align:left;background:#f3f4f6;"><th style="padding:5px 4px;">Name</th><th style="padding:5px 4px;">Deduction</th><th style="padding:5px 4px;">Sched. C line</th><th style="padding:5px 4px;">Ded. %</th><th style="padding:5px 4px;" title="Use tax applies when no sales tax was charged">Use tax</th><th style="padding:5px 4px;"># used</th><th></th></tr></thead>
      <tbody id="expCatRows">${_exp.categories.map(row).join("")}${row(null)}</tbody>
    </table></div>
    <div id="expCatErr" style="color:#b03a2e;font-size:13px;min-height:18px;margin-top:8px;"></div>`, 900);
  const redraw = (cats) => {
    _exp.categories = cats;
    ov.querySelector("#expCatRows").innerHTML = cats.map(row).join("") + row(null);
    expFillCategorySelect_();
  };
  ov.addEventListener("change", (e) => {
    if (e.target.dataset.f !== "deductionType") return;
    const tr = e.target.closest("tr");
    if (e.target.value === "none") tr.querySelector('[data-f="deductiblePct"]').value = "0";
    if (e.target.value === "depreciation") tr.querySelector('[data-f="scheduleCLine"]').value = "13";
  });
  ov.addEventListener("click", async (e) => {
    const errEl = ov.querySelector("#expCatErr");
    const saveId = e.target.dataset.save, delId = e.target.dataset.del;
    if (!saveId && !delId) return;
    errEl.textContent = "";
    try {
      if (saveId) {
        const tr = e.target.closest("tr");
        const f = (k) => tr.querySelector(`[data-f="${k}"]`).value;
        if (!f("name").trim()) { errEl.textContent = "Enter a category name."; return; }
        const d = await expApi_({ action: "saveExpenseCategory", category: { id: saveId === "new" ? undefined : Number(saveId),
          name: f("name").trim(), deductionType: f("deductionType"), scheduleCLine: f("scheduleCLine"), deductiblePct: f("deductiblePct"),
          useTaxable: tr.querySelector('[data-f="useTaxable"]').checked } });
        redraw(d.categories);
        showToast(saveId === "new" ? "Category added." : "Category saved.");
      } else {
        const c = _exp.categories.find(x => String(x.id) === delId);
        if (!c || !await askConfirm_(`Delete the category "${c.name}"?`)) return;
        const d = await expApi_({ action: "deleteExpenseCategory", categoryId: c.id });
        redraw(d.categories);
        showToast("Category deleted.");
      }
      await expRefresh_();
    } catch (err) { errEl.textContent = err.message; }
  });
}

// ---- Communications → Send a test email: one message, and what the provider said ------------
const COMMS_PROVIDER_ = { resend: "Resend", "cloudflare-binding": "Cloudflare Email Service (Worker binding)",
  "cloudflare-api": "Cloudflare Email Service (API)", none: "None set up" };
async function commsSendTest_(){
  const to = (document.getElementById("commsTestTo").value || "").trim();
  const btn = document.getElementById("commsTestBtn"), out = document.getElementById("commsTestResult");
  btn.disabled = true; out.innerHTML = `<span style="color:#888;">Sending…</span>`;
  try {
    const res = await fetch("/api/orders", { method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action: "sendTestEmail", key: adminKey, to }) });
    const d = await res.json().catch(() => ({ status: "error", message: "Server error (" + res.status + ")" }));
    if (!res.ok || d.status !== "ok") { out.innerHTML = `<span style="color:#b03a2e;">${escapeHtml((d && d.message) || "Could not send.")}</span>`; return; }
    const r = d.report, row = (k, v) => v === "" || v == null ? "" : `<tr><td style="padding:3px 10px 3px 0;color:#666;white-space:nowrap;vertical-align:top;">${k}</td><td style="padding:3px 0;word-break:break-word;">${v}</td></tr>`;
    const key = r.key ? `set, ${Number(r.key.length)} characters${r.key.looksLikeResend ? ", starts with re_" : ", <b>doesn't start with re_</b>"}${r.key.spaceInside ? ", <b>has a space or line break inside</b>" : r.key.paddedEnds ? ", <b>extra space or line break at the end</b>" : ""}` : "";
    const sent = r.ok ? `<div style="color:#15803d;font-weight:700;margin-bottom:6px;">✓ Accepted by ${escapeHtml(COMMS_PROVIDER_[r.provider] || r.provider)}</div>`
      : `<div style="color:#b03a2e;font-weight:700;margin-bottom:6px;">✗ Not sent</div>`;
    out.innerHTML = sent + `<table style="border-collapse:collapse;font-size:13px;">
      ${row("Provider", escapeHtml(COMMS_PROVIDER_[r.provider] || r.provider))}
      ${row("API key", key)}
      ${row("From", escapeHtml(r.businessName ? `${r.businessName} <${r.from}>` : r.from))}
      ${row("To", escapeHtml(r.to))}
      ${row("Reply-to", escapeHtml(r.replyTo || ""))}
      ${row("Copy (BCC)", escapeHtml(r.bcc || ""))}
      ${row("Answer", r.httpStatus != null ? "HTTP " + Number(r.httpStatus) : "")}
      ${row("Message", r.providerMessage ? `<code style="font-size:12px;">${escapeHtml(r.providerMessage)}</code>` : "")}
      ${row("Email id", r.providerId ? `<code style="font-size:12px;">${escapeHtml(r.providerId)}</code>` : "")}
    </table>` + ((r.hints || []).length ? `<ul style="margin:8px 0 0;padding-left:18px;color:#333;">${r.hints.map(h => `<li style="margin:3px 0;">${escapeHtml(h)}</li>`).join("")}</ul>` : "");
  } catch (e) { out.innerHTML = `<span style="color:#b03a2e;">Could not reach the server.</span>`; }
  finally { btn.disabled = false; }
}

// ---- Communications: what the next 6 AM roll-up email will contain ------------
// After an action on Communications: refill it in place (no "Loading…", the scroll stays).
function refreshComms_(){ return keepView_(() => renderCommunications(document.getElementById("app"), { soft: true })); }
async function renderCommunications(app, opts){
  adminSetHash("comms");
  document.title = adminTitle_("Communications");
  if (!(opts && opts.soft && document.getElementById("commsBody"))) app.innerHTML = `
    ${adminPageHead_("Communications")}
    <div class="admin-panel" style="--org-accent:var(--accent);max-width:960px;margin:8px auto 60px;">
      <div style="display:flex;gap:8px;margin-bottom:16px;">
        <button class="admin-btn" style="font-size:13px;padding:6px 14px;" onclick="refreshComms_()">Refresh</button>
      </div>
      ${adminCan_("admin") ? `<details id="commsTest" style="margin:0 0 18px;border:1px solid #ddd;border-radius:6px;padding:10px 14px;background:#fafafa;">
        <summary style="cursor:pointer;font-weight:700;font-size:14px;">✉️ Send a test email</summary>
        <div style="font-size:13px;color:#555;margin:8px 0;">Sends one short message the same way order emails go, and shows what the email service answered — for finding out why emails aren't arriving.</div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;">
          <input id="commsTestTo" type="email" placeholder="you@example.com" value="${escapeHtml((adminMe && adminMe.email) || "")}" style="flex:1 1 220px;min-width:0;padding:6px 8px;font-size:14px;border:1px solid #ccc;border-radius:4px;">
          <button id="commsTestBtn" class="admin-btn" style="font-size:13px;padding:6px 14px;" onclick="commsSendTest_()">Send test</button>
        </div>
        <div id="commsTestResult" style="margin-top:10px;font-size:13px;"></div>
      </details>` : ""}
      <div id="commsBody" style="font-size:14px;color:#888;">Loading…</div>
    </div>`;
  if (!adminKey) adminKey = (await adminLogin()) || "";
  if (!adminKey) return;
  const el = document.getElementById("commsBody");
  let d;
  try {
    const r = await fetch("/api/orders", { method: "POST", headers: {"Content-Type": "application/json"},
      body: JSON.stringify({ action: "getPendingCommunications", key: adminKey }) });
    d = await r.json().catch(() => ({ status: "error", message: "Server error (" + r.status + ")" }));
    if (!r.ok || d.status === "error") { el.textContent = (d && d.message) || "Could not load."; return; }
  } catch (e) { el.textContent = "Could not reach the server."; return; }

  const fmt = (n) => "$" + Number(n || 0).toFixed(2);
  const when = (iso) => iso ? new Date(iso).toLocaleString(undefined, { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" }) : "";
  const th = "padding:7px 10px;text-align:left;background:#f0f0f0;color:#333;font-size:12px;font-weight:700;border-bottom:2px solid #ccc;";
  const td = "padding:8px 10px;border-bottom:1px solid #e5e7eb;vertical-align:top;color:#111;background:#fff;";
  const sub = "color:#666;font-size:12px;";
  const KIND = { payment: "Payment", refund: "Refund", dispute: "Dispute", design: "Design response", delivered: "Delivered" };
  const urgent = d.notices.filter(x => x.urgent);
  const delivered = d.notices.filter(x => !x.urgent && x.kind === "delivered");
  const activity = d.notices.filter(x => !x.urgent && x.kind !== "delivered");
  const inTransit = d.inTransit || [];
  const pickedUp = d.pickedUp || [], awaitingPickup = d.awaitingPickup || [];
  const awaitingBlanks = d.awaitingBlanks || [];
  const total = d.orders.reduce((s, o) => s + Math.round(Number(o.total) * 100), 0) / 100;
  const since = d.firstRun ? "No roll-up has been sent yet — the first one covers the last 24 hours."
    : d.lastSentAt ? `Since the last roll-up email, sent ${escapeHtml(when(d.lastSentAt))}.` : "Since the last roll-up (none has needed sending yet).";
  // The last time the roll-up RAN — a run that finds nothing sends no email, so say that it checked.
  const run = d.lastRun;
  const ranHow = run ? (run.trigger === "scheduled" ? "the morning run" : "a manual run") : "";
  const lastRunLine = !run ? "" : `<div id="commsLastRun" style="font-size:13px;margin-top:4px;color:${run.ok ? "#555" : "#b03a2e"};">Last checked ${escapeHtml(when(run.at))} by ${ranHow}: ${
    !run.ok ? `<b>it did not complete</b>${run.message ? " — " + escapeHtml(run.message) : ""}. It will try again at the next run.`
    : run.sent ? `an email was sent${run.orders ? ` (${Number(run.orders)} order${Number(run.orders) === 1 ? "" : "s"})` : ""}.`
    : run.heartbeat === "sent" ? "nothing new — a short “nothing new” email was sent."
    : run.heartbeat === "failed" ? `nothing new, and <b style="color:#b03a2e;">the “nothing new” email could not be sent</b>.`
    : "nothing new, so no email was sent."}</div>`;

  const noticeTable = (rows) => `<div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;"><table style="width:100%;border-collapse:collapse;font-size:14px;">
      <thead><tr><th style="${th}">When</th><th style="${th}">Type</th><th style="${th}">Order</th><th style="${th}">Details</th></tr></thead>
      <tbody>${rows.map(x => `<tr>
        <td style="${td}white-space:nowrap;${sub}">${escapeHtml(when(x.createdAt))}</td>
        <td style="${td}white-space:nowrap;">${escapeHtml(KIND[x.kind] || x.kind)}</td>
        <td style="${td}white-space:nowrap;">${escapeHtml(x.orderId)}<br><span style="${sub}">${escapeHtml(x.orgName || "")}</span></td>
        <td style="${td}">${escapeHtml(x.summary)}${x.detail ? `<br><span style="${sub}">${escapeHtml(x.detail)}</span>` : ""}${(x.imageUrls || []).length
          ? "<br>" + x.imageUrls.filter(u => isValidImageUrl(u)).map((u, i) => `<a href="${escapeHtml(u)}" target="_blank" rel="noopener" style="font-size:12px;">image ${i + 1}</a>`).join(" · ") : ""}</td>
      </tr>`).join("")}</tbody></table></div>`;

  const itemLine = (it) => `${it.qty}× ${it.name}${it.size ? ` (${it.size})` : ""}${it.personalized ? ` [${it.persName}]` : ""}${it.cancelled ? " — cancelled" : ""}`;
  const ordersHtml = d.orders.length ? `<div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;"><table style="width:100%;border-collapse:collapse;font-size:14px;">
      <thead><tr><th style="${th}">Order</th><th style="${th}">Shop</th><th style="${th}">Customer</th><th style="${th}">Items</th><th style="${th}">Payment</th><th style="${th}text-align:right;">Total</th></tr></thead>
      <tbody>${d.orders.map(o => `<tr>
        <td style="${td}white-space:nowrap;">${escapeHtml(o.orderId)}<br><span style="${sub}">${escapeHtml(when(o.placedAt))}</span></td>
        <td style="${td}">${escapeHtml(o.orgName)}</td>
        <td style="${td}">${escapeHtml(o.customerName)}<br><span style="${sub}">${escapeHtml(o.contact || "")}</span></td>
        <td style="${td}font-size:13px;">${o.items.map(it => escapeHtml(itemLine(it))).join("<br>")}</td>
        <td style="${td}white-space:nowrap;">${escapeHtml(o.paymentMethod || "")}<br><span style="font-size:12px;color:${o.paid ? "#15803d" : "#b45309"};">${o.paid ? "Paid" : "Unpaid"}</span></td>
        <td style="${td}text-align:right;white-space:nowrap;">${fmt(o.total)}</td>
      </tr>`).join("")}</tbody></table></div>` : `<div style="color:#888;">No new orders.</div>`;

  const inTransitHtml = inTransit.length ? `<div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;"><table style="width:100%;border-collapse:collapse;font-size:14px;">
      <thead><tr><th style="${th}">Order</th><th style="${th}">Shop</th><th style="${th}">Customer</th><th style="${th}">Carrier / tracking</th><th style="${th}">Shipped</th><th style="${th}">Status</th></tr></thead>
      <tbody>${inTransit.map(x => `<tr>
        <td style="${td}white-space:nowrap;">${escapeHtml(x.orderId)}</td><td style="${td}">${escapeHtml(x.orgName)}</td><td style="${td}">${escapeHtml(x.customerName)}</td>
        <td style="${td}font-family:monospace;font-size:12px;">${escapeHtml(x.carrier)} ${escapeHtml(x.tracking)}</td>
        <td style="${td}white-space:nowrap;${sub}">${escapeHtml(when(x.shippedAt))}</td>
        <td style="${td}">${escapeHtml(x.status || "")}${x.statusDate ? `<br><span style="${sub}">${escapeHtml(x.statusDate)}</span>` : ""}${x.statusDetail ? `<br><span style="color:#666;font-size:11px;">${escapeHtml(x.statusDetail)}</span>` : ""}</td>
        </tr>`).join("")}</tbody></table></div>`
    : `<div style="color:#888;">Nothing is waiting on a delivery (shipped orders need a tracking number to be checked).</div>`;

  // Labels the carrier hasn't scanned yet, and any the check just found scanned (marked shipped now).
  const shipRows = (rows, statusCell) => `<div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;"><table style="width:100%;border-collapse:collapse;font-size:14px;">
      <thead><tr><th style="${th}">Order</th><th style="${th}">Shop</th><th style="${th}">Customer</th><th style="${th}">Carrier / tracking</th><th style="${th}">Status</th></tr></thead>
      <tbody>${rows.map(x => `<tr>
        <td style="${td}white-space:nowrap;">${escapeHtml(x.orderId)}</td><td style="${td}">${escapeHtml(x.orgName)}</td><td style="${td}">${escapeHtml(x.customerName)}</td>
        <td style="${td}font-family:monospace;font-size:12px;">${escapeHtml(x.carrier)} ${escapeHtml(x.tracking)}</td>
        <td style="${td}">${statusCell(x)}</td></tr>`).join("")}</tbody></table></div>`;
  const pickedUpHtml = pickedUp.length ? `<h2 style="font-size:17px;margin:22px 0 8px;">📮 Just picked up by the carrier — ${pickedUp.length}</h2>
    <div style="font-size:13px;color:#555;margin:0 0 8px;">This check found a carrier scan, so these are now marked shipped (dated by the first scan) and each customer was emailed their tracking.</div>
    ${shipRows(pickedUp, x => `Shipped ${escapeHtml(x.shippedAtLabel || "")}${x.customerEmailed === false ? `<br><span style="color:#b45309;font-size:12px;">customer email not sent</span>` : ""}`)}` : "";
  const awaitingHtml = `<h2 style="font-size:17px;margin:22px 0 8px;">🏷 Label created — not shipped yet${awaitingPickup.length ? ` — ${awaitingPickup.length}` : ""}</h2>
    <div style="font-size:13px;color:#555;margin:0 0 8px;">These have a label, but the carrier hasn't scanned them yet. Each is marked shipped automatically (and the customer emailed) once tracking shows a scan — or mark it shipped yourself on the orders screen.</div>
    ${awaitingPickup.length ? shipRows(awaitingPickup, x => `${escapeHtml(x.status || "Awaiting scan")}${x.labelAtLabel ? `<br><span style="${sub}">label ${escapeHtml(x.labelAtLabel)}</span>` : ""}`)
      : `<div style="color:#888;">None — every labeled order has been picked up.</div>`}`;

  // Blanks (garments) ordered from a vendor, not yet received — with each shipment's live carrier
  // status (migrations/0039), mirroring the customer "shipped — waiting on delivery" section.
  const dayShort = (s) => { const m = String(s || "").match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? `${+m[2]}/${+m[3]}/${m[1]}` : ""; };
  const todayStr = new Date().toISOString().slice(0, 10);
  const blanksHtml = awaitingBlanks.length ? `<div style="overflow-x:auto;border:1px solid #ddd;border-radius:6px;"><table style="width:100%;border-collapse:collapse;font-size:14px;">
      <thead><tr><th style="${th}">Order</th><th style="${th}">Shop</th><th style="${th}">Customer</th><th style="${th}">Vendor / ordered</th><th style="${th}">Items</th><th style="${th}">Shipments / status</th></tr></thead>
      <tbody>${awaitingBlanks.map(o => {
        const late = o.blankEstDelivery && String(o.blankEstDelivery).slice(0, 10) < todayStr;
        const vendor = [o.blankVendor, o.blankVendorOrderId].filter(Boolean).map(escapeHtml).join(" · ");
        return `<tr>
          <td style="${td}white-space:nowrap;">${escapeHtml(o.orderId)}</td>
          <td style="${td}">${escapeHtml(o.orgName)}</td>
          <td style="${td}">${escapeHtml(o.customerName)}</td>
          <td style="${td}white-space:nowrap;">${o.blankOrderedAt ? "Ordered " + escapeHtml(dayShort(o.blankOrderedAt)) : ""}${vendor ? `<br><span style="${sub}">${vendor}</span>` : ""}${o.blankEstDelivery ? `<br><span style="font-size:12px;${late ? "color:#b03a2e;font-weight:600;" : "color:#666;"}">${late ? "Overdue — exp. " : "Exp. "}${escapeHtml(dayShort(o.blankEstDelivery))}</span>` : ""}</td>
          <td style="${td}font-size:13px;">${(o.items || []).map(it => `${it.qty} × ${escapeHtml(it.name)}${itemHasSize_(it) ? " · " + escapeHtml(it.size) : ""}${it.shipped ? ` <span style="color:#b45309;font-size:12px;">· shipped</span>` : ""}`).join("<br>")}</td>
          <td style="${td}font-size:13px;">${(o.shipments || []).length ? o.shipments.map(blankShipmentLine_).join("") : `<span style="${sub}">No tracking yet</span>`}</td>
        </tr>`; }).join("")}</tbody></table></div>`
    : `<div style="color:#888;">No blank orders are waiting on a vendor shipment.</div>`;

  el.style.color = "var(--ink,#111)";
  el.innerHTML = `
    <p style="margin:0 0 4px;color:#555;">${since}</p>
    ${lastRunLine}
    <p style="margin:0 0 18px;color:#555;font-size:13px;">This is what the next roll-up email (${adminDesktop_() ? "the first check after 6 AM while the program is open" : "about 6 AM"}) will contain. ${d.orders.length || d.notices.length || pickedUp.length || (d.issues || []).length || (d.security && d.security.count >= 5) ? "" : "<strong>Nothing new — no email will be sent.</strong>"}</p>
    ${d.security && d.security.count ? `<div style="border:2px solid #b45309;border-radius:6px;padding:10px 12px;margin-bottom:20px;background:#fffbeb;">
      <h2 style="margin:0 0 6px;color:#92400e;font-size:16px;">🔒 ${d.security.count} failed admin sign-in${d.security.count === 1 ? "" : "s"}</h2>
      <div style="font-size:14px;">${Number(d.security.passphrase || 0)} wrong password, ${Number(d.security.code || 0)} wrong 2FA code · ${escapeHtml(when(d.security.first))} – ${escapeHtml(when(d.security.last))} · from ${escapeHtml((d.security.ips || []).join(", ") || "unknown")}</div>
      ${Number(d.security.code || 0) > 0 ? `<div style="font-size:13px;margin-top:4px;"><strong>A wrong 2FA code means the password was right</strong> — change it if that wasn't you.</div>` : ""}
      <div style="font-size:12px;color:#555;margin-top:4px;">Reported in the next roll-up (5 or more send one even with no orders), then cleared.</div></div>` : ""}
    ${(d.issues || []).length ? `<div style="border:2px solid #b45309;border-radius:6px;padding:10px 12px;margin-bottom:20px;background:#fffbeb;">
      <h2 style="margin:0 0 6px;color:#92400e;font-size:16px;">⚠️ Problems since the last roll-up</h2>
      <ul style="margin:0;padding-left:18px;font-size:14px;">${d.issues.map(x => `<li><strong>${escapeHtml(x.label)}: ${Number(x.count)}</strong>
        <span style="${sub}">(${escapeHtml(when(x.first))}${x.count > 1 ? " – " + escapeHtml(when(x.last)) : ""})</span>
        ${(x.samples || []).length ? `<br><span style="${sub}">e.g. ${x.samples.map(t => escapeHtml(t)).join(" · ")}</span>` : ""}</li>`).join("")}</ul>
      <div style="font-size:12px;color:#555;margin-top:4px;">Reported in the next roll-up (it's sent even with nothing else new), then cleared. Details are in ${adminDesktop_() ? "the program's log (Help → Open the log)" : "the Cloudflare logs"}.</div></div>` : ""}
    ${urgent.length ? `<div style="border:2px solid #b91c1c;border-radius:6px;padding:10px 12px;margin-bottom:20px;background:#fef2f2;">
      <h2 style="margin:0 0 8px;color:#b91c1c;font-size:16px;">⚠️ Needs attention</h2>${noticeTable(urgent)}</div>` : ""}
    <h2 style="font-size:17px;margin:0 0 8px;">New orders${d.orders.length ? ` — ${d.orders.length}, ${fmt(total)}` : ""}</h2>
    ${ordersHtml}
    <h2 style="font-size:17px;margin:22px 0 8px;">📦 Delivered${delivered.length ? ` — ${delivered.length}` : ""}</h2>
    <div style="font-size:13px;color:#555;margin:0 0 8px;">Found by the daily tracking check: each is already marked delivered. Mark them completed on the orders screen once paid in full.</div>
    ${delivered.length ? noticeTable(delivered) : `<div style="color:#888;">None yet.</div>`}
    <h2 style="font-size:17px;margin:22px 0 8px;">Payments, refunds &amp; customer responses${activity.length ? ` — ${activity.length}` : ""}</h2>
    ${activity.length ? noticeTable(activity) : `<div style="color:#888;">None.</div>`}
    ${pickedUpHtml}
    ${awaitingHtml}
    ${(d.maintenanceDue || []).length ? `<h2 style="font-size:17px;margin:22px 0 8px;" id="commsMaint">🔧 Machine maintenance due — ${d.maintenanceDue.length}</h2>
      <div style="font-size:13px;color:#555;margin:0 0 8px;">Listed in the next roll-up. Mark it done on <a href="#maintenance">Machine maintenance</a>.</div>
      <ul style="margin:0;padding-left:18px;font-size:14px;">${d.maintenanceDue.map(t => `<li><b>${escapeHtml(t.machineName)}</b> — ${escapeHtml(t.name)} <span style="color:#666;">· ${escapeHtml(maintProgressText_(t))}</span></li>`).join("")}</ul>` : ""}
    <div style="display:flex;align-items:center;gap:8px;margin:22px 0 8px;flex-wrap:wrap;">
      <h2 style="font-size:17px;margin:0;">👕 Blanks in transit from the vendor${awaitingBlanks.length ? ` — ${awaitingBlanks.length}` : ""}</h2>
      ${adminFeatureOn_("shipping") ? `<button class="admin-btn" style="font-size:12px;padding:4px 10px;" onclick="checkBlankShipmentsNow(this)">Check now</button>` : ""}</div>
    <div style="font-size:13px;color:#555;margin:0 0 8px;">Each shipment's carrier status is polled in the daily roll-up; Check now refreshes it on demand. Delivered shipments queue a reminder — mark the blanks received on the orders screen once you've counted them.</div>
    ${blanksHtml}
    <h2 style="font-size:17px;margin:22px 0 8px;">🚚 Shipped — waiting on delivery${inTransit.length ? ` — ${inTransit.length}` : ""}</h2>
    <div style="font-size:13px;color:#555;margin:0 0 8px;">Tracking checked live above. Delivered orders are marked delivered and appear under Delivered.
      <button class="admin-btn" id="checkDeliveriesBtn" style="font-size:12px;padding:4px 10px;margin-left:8px;" onclick="refreshComms_()">Refresh</button></div>
    ${inTransitHtml}
    ${priceReminderHtml_(d.priceReminder)}`;
}

// "Refresh all from connected vendors": the reminder's blanks, fetched live into the review window.
async function refreshPriceReminderFromVendors_(){
  if (!window._blanksAll || !window._blanksAll.length) { try { window._blanksAll = (await hoopApi_({ action: "getBlanks" })).blanks || []; } catch (e) { showToast(e.message); return; } }
  const ids = [...document.querySelectorAll(".price-check-blank")].map(el => Number(el.dataset.id)).filter(Boolean);
  await refreshBlanksFromVendors_(ids.length ? ids : null, () => refreshComms_());
}
// The roll-up's 30-day vendor-price reminder (migrations/0062), as it stands today.
function priceReminderHtml_(pr) {
  if (!pr) return "";
  const day = (iso) => iso ? new Date(iso).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }) : "";
  const blanks = pr.blanks || [], products = pr.products || [];
  const when = !blanks.length && !products.length ? "Nothing to check right now."
    : pr.due ? "In the next roll-up." : `Next in the roll-up on ${escapeHtml(day(pr.nextDueAt))}.`;
  const money = (v) => v == null ? "not entered" : "$" + Number(v).toFixed(2);
  return `<h2 style="font-size:17px;margin:22px 0 8px;">💲 Blank prices to check${blanks.length + products.length ? ` — ${blanks.length} blank${blanks.length === 1 ? "" : "s"}, ${products.length} product${products.length === 1 ? "" : "s"} to re-price` : ""}</h2>
    <div style="font-size:13px;color:#555;margin:0 0 8px;">Every 30 days the roll-up lists blanks used by products on sale whose vendor prices haven't been checked in 30 days, and products priced on blank prices that have since changed. ${when}${pr.lastSentAt ? ` Last sent ${escapeHtml(day(pr.lastSentAt))}.` : ""}
      ${blanks.length ? `<button type="button" class="admin-btn" style="font-size:12px;padding:3px 10px;margin-left:6px;" onclick="refreshPriceReminderFromVendors_()">Refresh all from connected vendors</button>` : ""}</div>
    ${blanks.length ? `<div style="font-size:13px;margin-bottom:8px;">${blanks.map(b => `<div class="price-check-blank" data-id="${b.id}" style="padding:3px 0;"><b>${escapeHtml(b.name)}</b> <span style="color:#666;">${escapeHtml(b.vendor || "")} · ${escapeHtml(b.checkedAt ? "checked " + day(b.checkedAt) : "never checked")} · ${Number(b.sizesWithPrice) || 0}/${Number(b.sizes) || 0} sizes priced · used by ${escapeHtml((b.products || []).map(p => p.name + " (" + (p.orgName || p.orgId) + ")").join(", "))}</span></div>`).join("")}
      <a href="#inventory" style="font-size:12px;">Open Blanks →</a></div>` : ""}
    ${products.length ? `<div style="font-size:13px;">${products.map(p => `<div class="price-check-product" style="padding:3px 0;"><a href="#catalog/orgs/${encodeURIComponent(p.orgId)}/products/${encodeURIComponent(p.productId)}/edit"><b>${escapeHtml(p.name)}</b></a> <span style="color:#666;">(${escapeHtml(p.orgName || p.orgId)}) — ${escapeHtml(p.changes.map(c => `${c.blankName}${c.color ? " " + c.color : ""}${c.size ? " " + c.size : ""} ${money(c.from)} → ${money(c.to)}`).join("; "))}</span></div>`).join("")}</div>` : ""}`;
}

// Runs the roll-up's delivery check on demand: delivered orders are marked delivered and queued
// for the next roll-up email, and show up above.
// The desktop version's Orders page: its tracking check now (the same check the program runs every two
// hours, src/worker.js), then the orders again. No email is sent from the desktop version.
async function ordersCheckTracking_(btn){
  btn.disabled = true; const was = btn.textContent; btn.textContent = "Checking…";
  try{
    const r = await fetch("/api/orders", { method: "POST", headers: {"Content-Type": "application/json"},
      body: JSON.stringify({ action: "checkDeliveries", key: adminKey }) });
    const d = await r.json().catch(() => ({ status: "error", message: "Server error (" + r.status + ")" }));
    if(!r.ok || d.status === "error"){ showToast((d && d.message) || "Tracking check failed.", true); return; }
    const n = d.delivered.length, p = (d.pickedUp || []).length;
    const parts = [p ? `${p} picked up by the carrier — marked shipped` : "", n ? `${n} delivered — marked delivered` : ""].filter(Boolean);
    showToast(parts.length ? parts.join("; ") + "."
      : `Checked ${d.checked} order${d.checked === 1 ? "" : "s"} — nothing picked up or delivered yet.` + (d.errors ? ` (${d.errors} lookup${d.errors === 1 ? "" : "s"} failed)` : ""), false);
    const org = (adminOrgs || []).find(o => o.orgId === btn.dataset.org);
    if((p || n) && org) refreshOrdersInPlace_(org);
  }catch(e){ showToast("Could not reach the server.", true); }
  finally{ btn.disabled = false; btn.textContent = was; }
}

async function checkDeliveriesNow(btn){
  btn.disabled = true; btn.textContent = "Checking…";
  try{
    const r = await fetch("/api/orders", { method: "POST", headers: {"Content-Type": "application/json"},
      body: JSON.stringify({ action: "checkDeliveries", key: adminKey }) });
    const d = await r.json().catch(() => ({ status: "error", message: "Server error (" + r.status + ")" }));
    if(!r.ok || d.status === "error"){ showToast((d && d.message) || "Delivery check failed.", true); btn.disabled = false; btn.textContent = "Check now"; return; }
    const n = d.delivered.length, p = (d.pickedUp || []).length;
    const parts = [p ? `${p} picked up by the carrier — marked shipped, customer emailed` : "",
      n ? `${n} delivered — marked delivered and queued for the next roll-up` : ""].filter(Boolean);
    showToast(parts.length ? parts.join("; ") + "."
                : `Checked ${d.checked} order${d.checked === 1 ? "" : "s"} — nothing picked up or delivered yet.` + (d.errors ? ` (${d.errors} lookup${d.errors === 1 ? "" : "s"} failed)` : ""), false);
    await refreshComms_();
  }catch(e){ showToast("Could not reach the server.", true); btn.disabled = false; btn.textContent = "Check now"; }
}

// Polls every active blank (vendor) shipment via the carrier now (migrations/0039), the same check
// the 6 AM roll-up runs: stores each shipment's latest status, and a delivered one queues a reminder.
async function checkBlankShipmentsNow(btn){
  if(!adminKey) adminKey = (await adminLogin()) || "";
  if(!adminKey) return;
  btn.disabled = true; btn.textContent = "Checking…";
  try{
    const r = await fetch("/api/orders", { method: "POST", headers: {"Content-Type": "application/json"},
      body: JSON.stringify({ action: "checkBlankShipments", key: adminKey }) });
    const d = await r.json().catch(() => ({ status: "error", message: "Server error (" + r.status + ")" }));
    if(!r.ok || d.status === "error"){ if(d && d.message === "Unauthorized") clearAdminAuth(); showToast((d && d.message) || "Blank shipment check failed.", true); btn.disabled = false; btn.textContent = "Check now"; return; }
    const n = (d.delivered || []).length;
    showToast(n ? `${n} blank shipment${n === 1 ? "" : "s"} delivered — queued as a reminder to mark received.`
                : `Checked ${d.checked} shipment${d.checked === 1 ? "" : "s"} — none delivered yet.` + (d.errors ? ` (${d.errors} lookup${d.errors === 1 ? "" : "s"} failed)` : ""), false);
    await refreshComms_();
  }catch(e){ showToast("Could not reach the server.", true); btn.disabled = false; btn.textContent = "Check now"; }
}

// ---- Periods & accountant export (migrations/0010) ----------------------------

// One CSV cell: numbers as-is; text quoted when needed and neutralised
// against spreadsheet formula injection (csvSafe).
function csvCell_(v){
  if (v === null || v === undefined) return "";
  if (typeof v === "number") return String(v);
  if (typeof v === "boolean") return v ? "yes" : "";
  const s = csvSafe(String(v));
  return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}
function downloadCsv_(filename, rows, columns){
  const lines = [columns.map(c => csvCell_(c[1])).join(",")]
    .concat(rows.map(r => columns.map(c => csvCell_(r[c[0]])).join(",")));
  const blob = new Blob([lines.join("\r\n") + "\r\n"], { type: "text/csv;charset=utf-8" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
}

