// The product categories list — on its own page and in the popup a Manage… button opens next to every category
// picker or list (showCategoriesModal_). onChange(list) runs after every change.
async function mountCategoryManager_(box, onChange){
  box.innerHTML = `
    <div style="font-size:13px;color:#666;margin-bottom:14px;">What a product or a blank can be filed under, shared by every shop. Each shop's page lists its products in sections, one per category it uses, in this order. Whether a product has sizes is set on the product itself (priced by size, or one flat price) — not by its category.</div>
    <div style="margin-bottom:14px;"><button type="button" class="admin-btn" data-pc-new>+ New category</button></div>
    <div data-pc-body style="color:#888;font-size:14px;max-height:65vh;overflow-y:auto;">Loading…</div>`;
  const body = box.querySelector("[data-pc-body]");
  let cats = [];
  const usedBy = (c) => [c.productCount ? `${c.productCount} product${c.productCount === 1 ? "" : "s"}` : "", c.blankCount ? `${c.blankCount} blank${c.blankCount === 1 ? "" : "s"}` : ""].filter(Boolean).join(", ");
  function draw(){
    if (!cats.length) { body.innerHTML = `<div style="color:#888;padding:16px 0;">No categories yet.</div>`; return; }
    const td = "padding:6px 6px;";
    body.innerHTML = `<table class="stack-mobile" style="width:100%;border-collapse:collapse;font-size:13px;">
      <thead><tr style="text-align:left;background:#f3f4f6;"><th style="${td}">Category</th><th style="${td}">Storefront heading</th><th style="${td}">Packs like</th><th style="${td}">Used by</th><th style="${td}">Order</th><th style="${td}"></th></tr></thead>
      <tbody>${cats.map(c => `<tr style="border-bottom:1px solid #eee;">
        <td class="stack-title" style="${td}font-weight:600;">${escapeHtml(c.name)}</td>
        <td data-label="Storefront heading" style="${td}">${escapeHtml(c.plural)}</td>
        <td data-label="Packs like" style="${td}color:#555;">${escapeHtml(PACK_AS_LABELS_[c.packAs] || c.packAs)}</td>
        <td data-label="Used by" style="${td}color:#666;">${usedBy(c) || `<span style="color:#bbb;">—</span>`}</td>
        <td data-label="Order" style="${td}color:#666;">${c.sortOrder}</td>
        <td class="stack-actions" style="${td}text-align:right;white-space:nowrap;">
          <button type="button" class="admin-btn" style="padding:2px 8px;font-size:11px;" data-pc-edit="${escapeHtml(c.key)}">Edit</button>
          <button type="button" class="admin-btn admin-btn-danger" style="padding:2px 8px;font-size:11px;margin-left:4px;" data-pc-del="${escapeHtml(c.key)}">Delete</button>
        </td>
      </tr>`).join("")}</tbody></table>`;
  }
  const apply = (list) => { cats = list || []; _productCategories = cats.length ? cats : null; draw(); if (onChange) onChange(cats); };
  box.addEventListener("click", async (e) => {
    const t = e.target.closest("button"); if (!t || !box.contains(t)) return;
    if (t.hasAttribute("data-pc-new")) showCategoryFormModal_(null, apply);
    else if (t.dataset.pcEdit) { const c = cats.find(x => x.key === t.dataset.pcEdit); if (c) showCategoryFormModal_(c, apply); }
    else if (t.dataset.pcDel) {
      const c = cats.find(x => x.key === t.dataset.pcDel); if (!c) return;
      if (!await askConfirm_(`Delete the category "${c.name}"?`)) return;
      try { apply((await hoopApi_({ action: "deleteProductCategory", categoryKey: c.key })).categories); showToast("Category deleted."); }
      catch (err) { showToast(err.message, true); }   // the server refuses while a product or blank uses it
    }
  });
  try { apply((await hoopApi_({ action: "listProductCategories" })).categories); }
  catch (e) { body.innerHTML = `<div style="color:#b03a2e;">${escapeHtml(e.message)}</div>`; }
}
function showCategoriesModal_(onChange){
  const { ov } = inventoryModal_("Product categories", `<div data-pc-modal></div>`, 820);
  return mountCategoryManager_(ov.querySelector("[data-pc-modal]"), onChange);
}
// A small "Manage…" button to put next to a category picker or list; it opens the list in a popup.
function manageCategoriesBtn_(extraAttrs){
  return `<button type="button" class="admin-btn admin-btn-secondary manage-list-btn" data-manage-categories ${extraAttrs || ""} title="Add, rename or re-order product categories">Manage&hellip;</button>`;
}
// One page-wide handler for every Manage… button: open the popup, then put the fresh list into the select(s) beside
// it (a select keeps its value; one named by data-select is refreshed) and tell the page (data-after → a function
// name on window, called with the list).
document.addEventListener("click", (e) => {
  const b = e.target.closest && e.target.closest("[data-manage-categories],[data-manage-locations]");
  if (!b) return;
  e.preventDefault();
  const isCat = b.hasAttribute("data-manage-categories");
  const after = b.dataset.after && typeof window[b.dataset.after] === "function" ? window[b.dataset.after] : null;
  const refresh = (list) => {
    if (b.dataset.select) document.querySelectorAll(b.dataset.select).forEach(sel => {
      const v = sel.value;
      sel.innerHTML = isCat ? categoryOptionsHtml_(v) : `<option value="">${escapeHtml(sel.dataset.blank || "— decoration location —")}</option>` + list.map(l => `<option value="${l.id}"${String(l.id) === v ? " selected" : ""}>${escapeHtml(l.name)}</option>`).join("");
    });
    if (after) after(list);
  };
  if (isCat) showCategoriesModal_(refresh); else showLocationsModal_(refresh);
});

function showCategoryFormModal_(category, onSaved){
  const isNew = !category;
  const f = category || { name: "", plural: "", packAs: "other", sortOrder: "" };
  const inp = "font-size:13px;padding:6px 8px;border:1px solid #ccc;border-radius:4px;width:100%;box-sizing:border-box;";
  const { ov, close } = inventoryModal_(isNew ? "New category" : "Edit category", `
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px;">
      <label style="font-size:12px;font-weight:600;">Name <span style="font-weight:400;color:#666;">(one of them)</span><br><input id="pcfName" value="${escapeHtml(f.name)}" placeholder="e.g. Patch" style="${inp}"></label>
      <label style="font-size:12px;font-weight:600;">Storefront heading <span style="font-weight:400;color:#666;">(several)</span><br><input id="pcfPlural" value="${escapeHtml(f.plural)}" placeholder="e.g. Patches" style="${inp}"></label>
      <label style="font-size:12px;font-weight:600;">When choosing a box, it counts as<br><select id="pcfPack" style="${inp}">${Object.keys(PACK_AS_LABELS_).map(k => `<option value="${k}"${f.packAs === k ? " selected" : ""}>${escapeHtml(PACK_AS_LABELS_[k])}</option>`).join("")}</select></label>
      <label style="font-size:12px;font-weight:600;">Order on the shop's page<br><input id="pcfSort" type="number" step="1" value="${f.sortOrder === "" ? "" : Number(f.sortOrder) || 0}" placeholder="${isNew ? "last" : ""}" style="${inp}"></label>
    </div>
    <div style="font-size:12px;color:#666;margin-bottom:8px;">"Counts as" decides which limit in Tools &rarr; Package sizes it uses up (Max shirts, Max sweatshirts, Max caps). With "Nothing", an order containing it gets no automatic shipping rate — the customer is told a quote will follow.</div>
    <div id="pcfErr" style="color:#b03a2e;font-size:13px;min-height:18px;"></div>
    <div style="display:flex;gap:8px;justify-content:flex-end;">
      <button type="button" id="pcfCancel" style="padding:6px 14px;border:1px solid #ccc;border-radius:5px;background:#fff;cursor:pointer;">Cancel</button>
      <button type="button" id="pcfSave" class="admin-btn">${isNew ? "Create category" : "Save changes"}</button>
    </div>`, 520);
  ov.querySelector("#pcfCancel").onclick = close;
  ov.querySelector("#pcfSave").onclick = async () => {
    const err = ov.querySelector("#pcfErr");
    const name = ov.querySelector("#pcfName").value.trim();
    if (!name) { err.textContent = "Give the category a name."; return; }
    const payload = { name, plural: ov.querySelector("#pcfPlural").value.trim(), packAs: ov.querySelector("#pcfPack").value, sortOrder: ov.querySelector("#pcfSort").value };
    if (!isNew) payload.key = category.key;
    try { const r = await hoopApi_({ action: "saveProductCategory", category: payload }); close(); showToast(isNew ? "Category created." : "Category updated."); onSaved && onSaved(r.categories); }
    catch (e) { err.textContent = e.message; }
  };
}

// ---- Run-time report (migrations/0030) — by design, with a per-machine breakdown ---------------
async function renderRunReport(app){
  adminSetHash("runreport");
  document.title = adminTitle_("Run times");
  const y = new Date().getFullYear();
  app.innerHTML = `
    ${adminPageHead_("Run times")}
    <div class="admin-panel" style="--org-accent:var(--accent);max-width:1240px;margin:8px auto 60px;">
      <form id="rrFilters" style="display:flex;flex-wrap:wrap;gap:10px;align-items:flex-end;background:var(--surface-alt,#f6f6f6);padding:14px 16px;border-radius:8px;margin-bottom:20px;">
        <div><label style="font-size:12px;font-weight:600;display:block;margin-bottom:3px;">From</label>
          <input type="date" id="rrFrom" value="${y}-01-01" style="font-size:13px;padding:5px 8px;border:1px solid #ccc;border-radius:4px;"></div>
        <div><label style="font-size:12px;font-weight:600;display:block;margin-bottom:3px;">To</label>
          <input type="date" id="rrTo" value="${new Date().toISOString().slice(0, 10)}" style="font-size:13px;padding:5px 8px;border:1px solid #ccc;border-radius:4px;"></div>
        <button type="submit" class="admin-pass-submit" style="padding:6px 18px;font-size:13px;">Generate</button>
      </form>
      <div id="rrResults"></div>
    </div>`;
  const dur = (ms) => { if (ms == null) return "—"; const s = Math.round(ms / 1000); const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), ss = s % 60; return (h ? h + "h " : "") + (h || m ? m + "m " : "") + ss + "s"; };
  const th = "padding:9px 12px;text-align:right;background:#f0f0f0;color:#333;font-size:12px;font-weight:700;white-space:nowrap;border-bottom:2px solid #ccc;";
  const thL = th.replace("text-align:right", "text-align:left");
  const cell = "padding:8px 12px;text-align:right;border-bottom:1px solid #ddd;color:#111;background:#fff;";
  const cellL = cell.replace("text-align:right", "text-align:left");
  async function load(){
    const el = document.getElementById("rrResults");
    el.innerHTML = `<div style="color:#888;font-size:14px;padding:20px 0;">Loading…</div>`;
    try {
      const r = await runOrderApi_({ action: "getRunReportByDesign", from: document.getElementById("rrFrom").value, to: document.getElementById("rrTo").value });
      const rep = r.report || { designs: [], detail: [] };
      if (!rep.designs.length && !rep.detail.length) { el.innerHTML = `<div style="color:#888;padding:20px 0;">No runs in this range.</div>`; return; }
      // Issues noted when each run was finished (migrations/0046): a column per kind, per design and per machine.
      const kinds = rep.issueKinds || RUN_ISSUE_KINDS_;
      const totals = rep.issueTotals || {};
      const n0 = (v) => v ? `<b>${v}</b>` : `<span style="color:#bbb;">0</span>`;
      const issueHead = kinds.map(k => `<th style="${th}" title="${escapeHtml(k.label)} — how many times, over these runs">${escapeHtml(RUN_ISSUE_SHORT_[k.key] || k.label)}</th>`).join("");
      const issueCells = (x) => kinds.map(k => `<td style="${cell}">${n0((x.issues || {})[k.key])}</td>`).join("");
      const anyIssues = kinds.some(k => totals[k.key]);
      const summary = `<div id="rrIssueSummary" style="font-size:13px;color:#444;margin:0 0 16px;">${anyIssues
        ? `<b>Issues in this range</b> (${rep.runsWithIssues} of ${rep.doneRuns} finished run${rep.doneRuns === 1 ? "" : "s"} had one): ` + kinds.filter(k => totals[k.key]).map(k => `${escapeHtml(k.label)} <b>${totals[k.key]}</b>`).join(" · ")
        : `No issues were noted on the ${rep.doneRuns || 0} finished run${rep.doneRuns === 1 ? "" : "s"} in this range.`}</div>`;
      // Stitches (migrations/0071): over timed runs whose design's stitch count is known.
      const ss = rep.stitchSummary || null;
      const st = (n) => n ? Number(n).toLocaleString() : `<span style="color:#bbb;">—</span>`;
      const stitchSummary = ss ? `<div id="rrStitchSummary" style="font-size:13px;color:#444;margin:-8px 0 16px;"><b>Stitches</b>: ${Number(ss.stitches || 0).toLocaleString()} on timed runs${ss.stitchesPerMin ? ` (${ss.stitchesPerMin.toLocaleString()} a minute on average)` : ""}${ss.untimedRuns ? ` · ${Number(ss.untimedStitches || 0).toLocaleString()} more on ${ss.untimedRuns} untimed run${ss.untimedRuns === 1 ? "" : "s"}` : ""}${ss.runsNoStitches ? ` · <span style="color:#92400e;">${ss.runsNoStitches} run${ss.runsNoStitches === 1 ? "" : "s"} with no stitch count (set it on the design)</span>` : ""}</div>` : "";
      const designBlocks = summary + stitchSummary + rep.designs.map(d => `
        <div style="overflow-x:auto;margin-bottom:6px;"><table style="width:100%;border-collapse:collapse;">
          <thead><tr><th style="${thL}">${escapeHtml(d.designName)}</th><th style="${th}">Completed</th><th style="${th}">Avg</th><th style="${th}">Total</th><th style="${th}">Aborted</th>${issueHead}<th style="${th}" title="Stitches over these runs">Stitches</th><th style="${th}" title="Average stitches per run">Avg stitches</th><th style="${th}" title="Stitches a minute of run time">Stitches/min</th></tr></thead>
          <tbody>
            <tr><td style="${cellL};font-weight:700;">All machines</td><td style="${cell}">${d.runs}</td><td style="${cell}">${dur(d.avgMs)}</td><td style="${cell}">${dur(d.totalMs)}</td><td style="${cell}">${d.abortedCount}</td>${issueCells(d)}<td style="${cell}">${st(d.stitches)}</td><td style="${cell}">${st(d.avgStitches)}</td><td style="${cell}">${st(d.stitchesPerMin)}</td></tr>
            ${d.byMachine.map(m => `<tr><td style="${cellL};padding-left:28px;color:#555;">${escapeHtml(m.machineName)}</td><td style="${cell}">${m.runs}</td><td style="${cell}">${dur(m.avgMs)}</td><td style="${cell}">${dur(m.totalMs)}</td><td style="${cell}">—</td>${issueCells(m)}<td style="${cell}">${st(m.stitches)}</td><td style="${cell}">${st(m.avgStitches)}</td><td style="${cell}">${st(m.stitchesPerMin)}</td></tr>`).join("")}
          </tbody>
        </table></div>`).join("");
      const detail = `<h3 style="margin:24px 0 8px;font-size:15px;">Run log</h3>
        <table style="width:100%;border-collapse:collapse;">
          <thead><tr><th style="${thL}">Started</th><th style="${thL}">Design</th><th style="${thL}">Machine</th><th style="${thL}">Order</th><th style="${th}">Duration</th><th style="${th}">Stitches</th><th style="${thL}">Status</th><th style="${thL}">Issues</th></tr></thead>
          <tbody>${rep.detail.map(x => `<tr>
            <td style="${cellL}">${escapeHtml(x.startedAt ? new Date(x.startedAt).toLocaleString() : "")}</td>
            <td style="${cellL}">${escapeHtml(x.designName)}</td>
            <td style="${cellL}">${escapeHtml(x.machineName)}</td>
            <td style="${cellL}">${escapeHtml(x.orgName)} · ${escapeHtml(x.orderId)}</td>
            <td style="${cell}">${x.status === "done" ? dur(x.durationMs) : "—"}</td>
            <td style="${cell}" class="rr-stitches">${x.status === "aborted" ? (x.stitchesCounted ? Number(x.stitchesCounted).toLocaleString() : "—") : x.stitchCount != null ? Number(x.stitchCount).toLocaleString() : `<span style="color:#bbb;">—</span>`}</td>
            <td style="${cellL}">${x.status === "aborted" ? "Aborted" + (x.abortReasonLabel ? " — " + escapeHtml(x.abortReasonLabel) : "") + (x.abortNote ? " (" + escapeHtml(x.abortNote) + ")" : "") : (x.status === "done" ? "Done" : "Running")}</td>
            <td style="${cellL}">${escapeHtml(runIssuesText_(x.issues, kinds)) || `<span style="color:#bbb;">—</span>`}</td>
          </tr>`).join("")}</tbody>
        </table>`;
      // The free-text details typed for "Other", newest first.
      const notes = rep.otherNotes || [];
      const other = `<h3 style="margin:24px 0 8px;font-size:15px;">Other issue details</h3>` + (notes.length ? `
        <div style="overflow-x:auto;"><table id="rrOtherNotes" style="width:100%;border-collapse:collapse;">
          <thead><tr><th style="${thL}">Started</th><th style="${thL}">Design</th><th style="${thL}">Machine</th><th style="${thL}">Order</th><th style="${thL}">Details</th></tr></thead>
          <tbody>${notes.map(x => `<tr>
            <td style="${cellL}white-space:nowrap;">${escapeHtml(x.startedAt ? new Date(x.startedAt).toLocaleString() : "")}</td>
            <td style="${cellL}">${escapeHtml(x.designName)}${x.stepLabel ? ` <span style="color:#888;">· ${escapeHtml(x.stepLabel)}</span>` : ""}</td>
            <td style="${cellL}">${escapeHtml(x.machineName)}</td>
            <td style="${cellL}">${escapeHtml(x.orgName)} · ${escapeHtml(x.orderId)}</td>
            <td style="${cellL}">${x.count > 1 ? `<b>×${x.count}</b> ` : ""}${escapeHtml(x.note)}</td>
          </tr>`).join("")}</tbody>
        </table></div>` : `<div id="rrOtherNotes" style="color:#888;font-size:13px;">No “Other” details were entered in this range.</div>`);
      el.innerHTML = designBlocks + detail + other;
    } catch (e) { el.innerHTML = `<div style="color:#b03a2e;">${escapeHtml(e.message)}</div>`; }
  }
  document.getElementById("rrFilters").onsubmit = (e) => { e.preventDefault(); load(); };
  await load();
}

// ---- Graphics / selectable options catalog (migrations/0036) ------------------------------------
// Per-org menu of options a configurable product's locations draw from: an embroidery design or a
// transfer-sheet graphic, each with an image (+thumb), a tier add-on price and ink colors.
const TIER_LABEL_ = { small: "Small", medium: "Medium", large: "Large" };
async function renderGraphics(app, orgId){
  adminSetHash("graphics/" + orgId);
  adminNoteShop_(orgId);
  document.title = adminTitle_("Graphics");
  app.innerHTML = `
    ${adminPageHead_("Graphics", { crumbs: [{label:"Manage catalog", hash:"catalog"}, {label: ((window._adminOrgRegistry || adminOrgs || []).find(o => o.orgId === orgId) || {}).name || orgId}, {label:"Graphics"}] })}
    <div class="admin-panel" style="--org-accent:var(--accent);max-width:900px;margin:8px auto 60px;">
      <h2 class="shop-page-h">Graphics — ${escapeHtml(((adminOrgs || []).find(o => o.orgId === orgId) || {}).name || orgId)}</h2>
      <div style="font-size:13px;color:#666;margin-bottom:12px;">Selectable options for configurable products — an embroidery design or a transfer sheet (DTF / sublimation). The tier sets the add-on price (set on the shop: Manage catalog → the shop → Edit → Reorder QR code &amp; option prices); no tier = included.</div>
      <div style="margin-bottom:14px;"><button type="button" class="admin-btn" id="grNewBtn">+ New graphic</button></div>
      <div id="grBody" style="color:#888;font-size:14px;max-height:65vh;overflow-y:auto;">Loading…</div>
    </div>`;
  let graphics = [], designs = [], transfers = [], tiers = {}, allLocations = [], allColors = [];
  function draw(){
    const body = document.getElementById("grBody");
    if (!graphics.length) { body.innerHTML = `<div style="color:#888;padding:16px 0;">No graphics yet.</div>`; return; }
    // The shop's own graphics, then every global one (migrations/0078) in its own group.
    const groupRow = (label) => `<tr><td colspan="6" style="padding:10px 6px 4px;font-weight:700;font-size:12px;color:#374151;">${label}</td></tr>`;
    const ordered = graphics.filter(g => !g.isGlobal).concat(graphics.filter(g => g.isGlobal));
    const firstGlobal = ordered.findIndex(g => g.isGlobal);
    const homeName = (id) => ((adminOrgs || []).find(o => o.orgId === id) || {}).name || id;
    body.innerHTML = `<table style="width:100%;border-collapse:collapse;font-size:13px;">
      <thead><tr style="text-align:left;background:#f3f4f6;"><th style="padding:5px 6px;"></th><th style="padding:5px 6px;">Name</th><th style="padding:5px 6px;">Kind</th><th style="padding:5px 6px;">Tier</th><th style="padding:5px 6px;">Ink</th><th style="padding:5px 6px;"></th></tr></thead>
      <tbody>${ordered.map((g, i) => (i === firstGlobal ? groupRow("🌐 Global — every shop") : "") + `<tr style="border-bottom:1px solid #eee;">
        <td style="padding:5px 6px;">${g.thumbUrl || g.imageUrl ? `<img src="${escapeHtml(g.thumbUrl || g.imageUrl)}" alt="" style="width:34px;height:34px;object-fit:cover;border:1px solid #ddd;border-radius:4px;">` : ""}</td>
        <td style="padding:5px 6px;font-weight:600;">${escapeHtml(g.name)}${g.visible ? "" : ` <span style="color:#b26a00;font-size:11px;">(hidden)</span>`}${g.isGlobal ? ` <span class="global-badge" title="Every shop can use it; changes apply everywhere">GLOBAL</span> <span style="font-weight:400;color:#666;font-size:11px;">home: ${escapeHtml(homeName(g.orgId))}</span>` : ""}</td>
        <td style="padding:5px 6px;">${g.kind === "embroidery" ? "Embroidery" : "Transfer"}</td>
        <td style="padding:5px 6px;">${g.tier ? TIER_LABEL_[g.tier] : "—"}</td>
        <td style="padding:5px 6px;color:#666;">${escapeHtml((g.inkColors || []).join(", "))}</td>
        <td style="padding:5px 6px;text-align:right;white-space:nowrap;">
          <button type="button" class="admin-btn" style="padding:2px 8px;font-size:11px;" data-gid="${g.id}" onclick="graphicEdit_(this.dataset.gid)">Edit</button>
          <button type="button" class="admin-btn admin-btn-danger" style="padding:2px 8px;font-size:11px;margin-left:4px;" data-gid="${g.id}" onclick="graphicDelete_(this.dataset.gid)">Delete</button>
        </td></tr>`).join("")}</tbody></table>`;
  }
  async function load(){
    try {
      const r = await hoopApi_({ action: "listGraphics", org: orgId });
      graphics = r.graphics || []; tiers = r.tiersCents || {};
      let products = [];
      [designs, transfers, products] = await Promise.all([
        !adminFeatureOn_("production") ? [] : hoopApi_({ action: "listDesigns", org: orgId }).then(x => x.designs || []).catch(() => []),
        hoopApi_({ action: "listTransfers", org: orgId }).then(x => x.transfers || []).catch(() => []),
        hoopApi_({ action: "listProducts", org: orgId }).then(x => x.products || []).catch(() => []),
      ]);
      // The real location keys + garment colors this org's configurable products define — so a
      // graphic's "offered at" is picked from a checklist, never a free-typed name that must match
      // a product location key exactly (a mismatch would silently hide the options). Each
      // value also carries the product names that use it, since the filter is global to the graphic
      // across every product — so ticking a key/colour shows its cross-product reach.
      const locMap = {}; const colorMap = {};
      const add_ = (map, key, label, prodName) => { const e = map[key] || (map[key] = { label, prods: [] }); if (prodName && !e.prods.includes(prodName)) e.prods.push(prodName); };
      products.filter(p => p.configurable).forEach(p => {
        const nm = p.name || p.productId || "";
        (p.locations || []).forEach(l => { if (l.key) add_(locMap, l.key, l.label || l.key, nm); });
        (p.garmentColors || []).forEach(c => { if (c) add_(colorMap, c, c, nm); });
      });
      allLocations = Object.keys(locMap).sort().map(k => ({ key: k, label: locMap[k].label, prods: locMap[k].prods }));
      allColors = Object.keys(colorMap).sort().map(c => ({ value: c, prods: colorMap[c].prods }));
      draw();
    } catch (e) { document.getElementById("grBody").innerHTML = `<div style="color:#b03a2e;">${escapeHtml(e.message)}</div>`; }
  }
  document.getElementById("grNewBtn").onclick = () => showGraphicFormModal_(null, orgId, { designs, transfers, tiers, allLocations, allColors }, load);
  window.graphicEdit_ = (idStr) => { const g = graphics.find(x => x.id === Number(idStr)); if (g) showGraphicFormModal_(g, orgId, { designs, transfers, tiers, allLocations, allColors }, load); };
  window.graphicDelete_ = async (idStr) => {
    const g = graphics.find(x => x.id === Number(idStr)); if (!g) return;
    if (!await askConfirm_(`Delete "${g.name}"?`)) return;
    try { await hoopApi_({ action: "deleteGraphic", id: g.id, org: orgId }); showToast("Graphic deleted."); await load(); }
    catch (e) { showToast(e.message, true); }
  };
  await load();
}

// A checklist for a graphic's "offered at" fields: `items` are the real values from the org's
// configurable products ([{value, label, prods?}]); `prods` names the products that use each value,
// shown beneath it — because this filter is global to the graphic, so ticking a value reaches every
// one of those products. Any value already on the graphic that no product uses any more is kept
// (checked, marked "(unused)") so editing never silently drops it. No boxes checked = any.
function gfChecklist_(items, selected, cls){
  const sel = (selected || []).map(String);
  const known = new Set(items.map(i => String(i.value)));
  const all = items.concat(sel.filter(v => !known.has(v)).map(v => ({ value: v, label: v + " (unused)", unused: true })));
  if (!all.length) return `<em style="font-weight:400;color:#888;font-size:12px;">None defined on a configurable product yet.</em>`;
  return all.map(i => {
    const sub = i.unused ? `<span style="color:#b26a00;">used by no product</span>`
      : (i.prods && i.prods.length ? escapeHtml(i.prods.join(", ")) : "");
    return `<label style="font-size:12px;font-weight:400;display:flex;gap:6px;align-items:flex-start;padding:3px 0;">` +
      `<input type="checkbox" class="${cls}" value="${escapeHtml(String(i.value))}" ${sel.includes(String(i.value)) ? "checked" : ""} style="margin-top:2px;">` +
      `<span>${escapeHtml(i.label)}${sub ? `<br><span style="color:#888;font-size:11px;">${sub}</span>` : ""}</span></label>`;
  }).join("");
}
function showGraphicFormModal_(graphic, orgId, ctx, onDone){
  const isNew = !graphic;
  const f = graphic || { name: "", kind: ctx.kind === "embroidery" ? "embroidery" : "transfer", designId: ctx.designId || null, transferId: null, tier: null, inkColors: [], imageUrl: "", thumbUrl: "", allowedLocations: [], allowedGarmentColors: [], visible: true };
  const inp = "font-size:13px;padding:6px 8px;border:1px solid #ccc;border-radius:4px;width:100%;box-sizing:border-box;";
  const tierOpt = (v) => ["", "small", "medium", "large"].map(t => `<option value="${t}" ${(f.tier || "") === t ? "selected" : ""}>${t ? TIER_LABEL_[t] + " (+" + (((ctx.tiers || {})[t] || 0) / 100).toFixed(2) + ")" : "— included ($0) —"}</option>`).join("");
  const { ov, close } = inventoryModal_(isNew ? "New graphic" : "Edit graphic", `
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px;">
      <label style="font-size:12px;font-weight:600;grid-column:1/-1;">Name<br><input id="gfName" value="${escapeHtml(f.name)}" style="${inp}"></label>
      <label style="font-size:12px;font-weight:600;">Kind<br><select id="gfKind" style="${inp}"><option value="transfer" ${f.kind !== "embroidery" ? "selected" : ""}>Transfer sheet</option><option value="embroidery" ${f.kind === "embroidery" ? "selected" : ""}>Embroidery</option></select></label>
      <label style="font-size:12px;font-weight:600;">Tier (add-on)<br><select id="gfTier" style="${inp}">${tierOpt()}</select></label>
      <label style="font-size:12px;font-weight:600;grid-column:1/-1;display:flex;align-items:flex-start;gap:6px;"><input type="checkbox" id="gfGlobal" ${f.isGlobal ? "checked" : ""} style="margin-top:2px;">
        <span>Global — every shop can use it <span style="font-weight:400;color:#666;">(kept in one place, like a global design; its design must be global too${f.isGlobal && f.orgId && f.orgId !== orgId ? ` · home shop: ${escapeHtml(((adminOrgs || []).find(o => o.orgId === f.orgId) || {}).name || f.orgId)} · changes apply to every shop` : ""})</span></span></label>
      <label style="font-size:12px;font-weight:600;" id="gfTransferWrap">Transfer item<br><select id="gfTransfer" style="${inp}"></select></label>
      <label style="font-size:12px;font-weight:600;" id="gfDesignWrap">Design (stitch file) <span style="font-weight:400;color:#666;">— optional; link it once it's digitized</span><br><select id="gfDesign" style="${inp}"></select></label>
      <div id="gfGlobalNote" style="grid-column:1/-1;font-size:12px;color:#92400e;"></div>
      <label style="font-size:12px;font-weight:600;grid-column:1/-1;" id="gfInkWrap">Ink colors (comma-separated)<br><input id="gfInk" value="${escapeHtml((f.inkColors || []).join(", "))}" placeholder="White, Old Gold, Navy" style="${inp}"></label>
      <div style="font-size:12px;font-weight:600;grid-column:1/-1;">Offered at these decoration locations
        <div style="font-weight:400;color:#888;font-size:11px;margin-top:1px;">Leave all unchecked to offer it wherever a product offers this graphic. Checking some restricts it to those decoration locations across every product below.</div>
        <div id="gfLocs" style="margin-top:4px;">${gfChecklist_((ctx.allLocations || []).map(l => ({ value: l.key, label: l.label && l.label !== l.key ? l.label + " (" + l.key + ")" : l.key, prods: l.prods })), f.allowedLocations, "gfLocChk")}</div></div>
      <div style="font-size:12px;font-weight:600;grid-column:1/-1;">Allowed garment colors
        <div style="font-weight:400;color:#888;font-size:11px;margin-top:1px;">Leave all unchecked for any color. Checking some restricts this graphic to those colors across every product below.</div>
        <div id="gfColors" style="margin-top:4px;">${gfChecklist_((ctx.allColors || []).map(c => ({ value: c.value, label: c.value, prods: c.prods })), f.allowedGarmentColors, "gfColorChk")}</div></div>
      <div style="grid-column:1/-1;">
        <label style="font-size:12px;font-weight:600;">Image</label>
        <div style="display:flex;gap:10px;align-items:center;margin-top:3px;">
          <img id="gfImg" src="${escapeHtml(f.thumbUrl || f.imageUrl || "")}" alt="" style="width:48px;height:48px;object-fit:cover;border:1px solid #ddd;border-radius:4px;${f.imageUrl ? "" : "display:none;"}">
          <input type="file" id="gfFile" accept="image/jpeg,image/png,image/webp,image/gif,image/heic,image/heif,.heic,.heif" style="font-size:12px;">
          <span id="gfImgStatus" style="font-size:12px;color:#666;"></span>
        </div>
      </div>
      <label style="font-size:12px;font-weight:600;display:flex;align-items:center;gap:6px;grid-column:1/-1;"><input type="checkbox" id="gfVisible" ${f.visible !== false ? "checked" : ""}> Visible</label>
    </div>
    <div id="gfErr" style="color:#b03a2e;font-size:13px;min-height:18px;"></div>
    <div style="display:flex;gap:8px;justify-content:flex-end;">
      <button type="button" id="gfCancel" style="padding:6px 14px;border:1px solid #ccc;border-radius:5px;background:#fff;cursor:pointer;">Cancel</button>
      <button type="button" id="gfSave" class="admin-btn">${isNew ? "Create" : "Save changes"}</button>
    </div>`, 560);
  let imageUrl = f.imageUrl || "", thumbUrlV = f.thumbUrl || "";
  const syncKind = () => {
    const emb = ov.querySelector("#gfKind").value === "embroidery";
    ov.querySelector("#gfTransferWrap").style.display = emb ? "none" : "";
    ov.querySelector("#gfDesignWrap").style.display = emb ? "" : "none";
    ov.querySelector("#gfInkWrap").style.display = emb ? "none" : "";
  };
  ov.querySelector("#gfKind").onchange = syncKind; syncKind();
  // A global graphic may only use a global design and a transfer every shop can use (migrations/0078): the selects offer
  // only those while Global is ticked, and a pick that doesn't qualify is cleared with a note.
  let pickDesign = f.designId, pickTransfer = f.transferId;
  const drawLinks = () => {
    const glob = ov.querySelector("#gfGlobal").checked, note = [];
    const designs = (ctx.designs || []).filter(d => !glob || d.isGlobal);
    const transfers = (ctx.transfers || []).filter(t => !glob || !(t.orgIds || []).length);
    if (pickDesign && !designs.some(d => d.id === Number(pickDesign))) { note.push("its design isn't global, so it was unlinked — make the design global (Designs screen) to link it"); pickDesign = null; }
    if (pickTransfer && !transfers.some(t => t.id === Number(pickTransfer))) { note.push("its transfer is limited to some shops, so it was unlinked"); pickTransfer = null; }
    ov.querySelector("#gfDesign").innerHTML = `<option value="">— not linked yet —</option>` + designs.map(d => `<option value="${d.id}" ${Number(pickDesign) === d.id ? "selected" : ""}>${d.isGlobal ? "🌐 " : ""}${escapeHtml(d.name)}</option>`).join("");
    ov.querySelector("#gfTransfer").innerHTML = `<option value="">— none —</option>` + transfers.map(t => `<option value="${t.id}" ${Number(pickTransfer) === t.id ? "selected" : ""}>${escapeHtml(t.name)}</option>`).join("");
    ov.querySelector("#gfGlobalNote").textContent = note.length ? "Global: " + note.join("; ") + "." : "";
  };
  ov.querySelector("#gfDesign").onchange = (e) => { pickDesign = e.target.value ? Number(e.target.value) : null; };
  ov.querySelector("#gfTransfer").onchange = (e) => { pickTransfer = e.target.value ? Number(e.target.value) : null; };
  ov.querySelector("#gfGlobal").onchange = drawLinks;
  drawLinks();
  ov.querySelector("#gfFile").onchange = async (e) => {
    const file = e.target.files[0]; if (!file) return;
    const st = ov.querySelector("#gfImgStatus"); st.textContent = "Uploading…";
    try { imageUrl = await uploadImage(file, orgId); thumbUrlV = (typeof thumbUrl === "function" ? thumbUrl(imageUrl) : imageUrl);
      const img = ov.querySelector("#gfImg"); img.src = thumbUrlV || imageUrl; img.style.display = ""; st.textContent = "Uploaded"; }
    catch (err) { st.textContent = err.message || "Upload failed"; }
  };
  ov.querySelector("#gfCancel").onclick = close;
  ov.querySelector("#gfSave").onclick = async () => {
    const err = ov.querySelector("#gfErr");
    const kind = ov.querySelector("#gfKind").value;
    const list = (id) => ov.querySelector(id).value.split(",").map(s => s.trim()).filter(Boolean);
    const payload = { id: f.id, name: ov.querySelector("#gfName").value.trim(), kind,
      tier: ov.querySelector("#gfTier").value || null,
      transferId: kind === "transfer" ? (Number(ov.querySelector("#gfTransfer").value) || null) : null,
      designId: kind === "embroidery" ? (Number(ov.querySelector("#gfDesign").value) || null) : null,
      inkColors: kind === "transfer" ? list("#gfInk") : [],
      imageUrl, thumbUrl: thumbUrlV,
      allowedLocations: [...ov.querySelectorAll("#gfLocs .gfLocChk:checked")].map(c => c.value),
      allowedGarmentColors: [...ov.querySelectorAll("#gfColors .gfColorChk:checked")].map(c => c.value),
      visible: ov.querySelector("#gfVisible").checked, isGlobal: ov.querySelector("#gfGlobal").checked };
    if (!payload.name) { err.textContent = "Name is required."; return; }
    if (kind === "embroidery" && !payload.designId) { err.textContent = "Pick a design."; return; }
    try { const r = await hoopApi_({ action: "saveGraphic", org: orgId, graphic: payload }); close(); showToast(isNew ? "Graphic created." : "Graphic updated."); onDone && onDone(r && r.id); }
    catch (e) { err.textContent = e.message; }
  };
}

// ---- Transfers inventory (migrations/0036) — mirrors Blanks ------------------
async function renderTransfers(app){
  adminSetHash("transfers");
  document.title = adminTitle_("Transfers");
  app.innerHTML = `
    ${adminPageHead_("Transfers")}
    <div class="admin-panel" style="--org-accent:var(--accent);max-width:900px;margin:8px auto 60px;">
      <div style="font-size:13px;color:#666;margin-bottom:12px;">Transfer-sheet inventory (DTF / sublimation). The portion of a sheet a job uses is consumed like a blank and flows into COGS.</div>
      <div style="margin-bottom:14px;display:flex;gap:8px;flex-wrap:wrap;">
        <button type="button" class="admin-btn" id="trNewBtn">+ New transfer</button>
        <button type="button" class="admin-btn" id="trReceiveBtn">Receive sheet</button>
      </div>
      <div id="trBody" style="color:#888;font-size:14px;max-height:65vh;overflow-y:auto;">Loading…</div>
    </div>`;
  let transfers = [];
  function draw(){
    const body = document.getElementById("trBody");
    if (!transfers.length) { body.innerHTML = `<div style="color:#888;padding:16px 0;">No transfers yet.</div>`; return; }
    body.innerHTML = `<table class="stack-mobile" style="width:100%;border-collapse:collapse;font-size:13px;">
      <thead><tr style="text-align:left;background:#f3f4f6;"><th style="padding:5px 6px;">Name</th><th style="padding:5px 6px;">On hand</th><th style="padding:5px 6px;">Avg cost</th><th style="padding:5px 6px;"></th></tr></thead>
      <tbody>${transfers.map(t => `<tr style="border-bottom:1px solid #eee;">
        <td style="padding:5px 6px;font-weight:600;">${escapeHtml(t.name)}${t.description ? `<br><span style="font-size:11px;color:#777;">${escapeHtml(t.description)}</span>` : ""}</td>
        <td style="padding:5px 6px;">${t.quantity}</td>
        <td style="padding:5px 6px;">$${Number(t.purchasePrice).toFixed(2)}</td>
        <td style="padding:5px 6px;text-align:right;white-space:nowrap;">
          <button type="button" class="admin-btn" style="padding:2px 8px;font-size:11px;" data-tid="${t.id}" onclick="transferEdit_(this.dataset.tid)">Edit</button>
          <button type="button" class="admin-btn" style="padding:2px 8px;font-size:11px;" data-tid="${t.id}" onclick="transferHistory_(this.dataset.tid)">History</button>
          <button type="button" class="admin-btn" style="padding:2px 8px;font-size:11px;" data-tid="${t.id}" onclick="transferWriteOff_(this.dataset.tid)">Write off</button>
          <button type="button" class="admin-btn admin-btn-danger" style="padding:2px 8px;font-size:11px;" data-tid="${t.id}" onclick="transferDelete_(this.dataset.tid)">Delete</button>
        </td></tr>`).join("")}</tbody></table>`;
  }
  async function load(){ try { transfers = (await hoopApi_({ action: "listTransfers" })).transfers || []; draw(); }
    catch (e) { document.getElementById("trBody").innerHTML = `<div style="color:#b03a2e;">${escapeHtml(e.message)}</div>`; } }
  window._transfersCache = () => transfers;
  document.getElementById("trNewBtn").onclick = () => showTransferFormModal_(null, load);
  document.getElementById("trReceiveBtn").onclick = () => showReceiveTransferModal_(transfers, load);
  window.transferEdit_ = (id) => { const t = transfers.find(x => x.id === Number(id)); if (t) showTransferFormModal_(t, load); };
  window.transferWriteOff_ = async (id) => {
    const t = transfers.find(x => x.id === Number(id)); if (!t) return;
    const qty = prompt(`Write off how many "${t.name}"? (on hand: ${t.quantity})`); if (!qty) return;
    try { await hoopApi_({ action: "writeOffTransfers", transferId: t.id, qty: Number(qty), note: "Write-off", occurredAt: new Date().toISOString().slice(0, 10) }); showToast("Written off."); await load(); }
    catch (e) { showToast(e.message, true); }
  };
  window.transferDelete_ = async (id) => {
    const t = transfers.find(x => x.id === Number(id)); if (!t) return;
    if (!await askConfirm_(`Delete "${t.name}"?`)) return;
    try { await hoopApi_({ action: "deleteTransfer", id: t.id }); showToast("Deleted."); await load(); }
    catch (e) { showToast(e.message, true); }
  };
  window.transferHistory_ = async (id) => {
    const t = transfers.find(x => x.id === Number(id)); if (!t) return;
    let moves = []; try { moves = (await hoopApi_({ action: "getTransferMovements", transferId: t.id })).movements || []; } catch (e) { showToast(e.message, true); return; }
    const { ov, close } = inventoryModal_("History — " + escapeHtml(t.name), `<div style="max-height:60vh;overflow:auto;"><table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="text-align:left;background:#f3f4f6;"><th style="padding:4px 6px;">Date</th><th style="padding:4px 6px;">Kind</th><th style="padding:4px 6px;">Qty</th><th style="padding:4px 6px;">Unit</th><th style="padding:4px 6px;"></th></tr></thead>
      <tbody>${moves.map(m => `<tr style="border-bottom:1px solid #eee;${m.voidedAt ? "text-decoration:line-through;color:#999;" : ""}">
        <td style="padding:4px 6px;">${escapeHtml((m.occurredAt || "").slice(0, 10))}</td><td style="padding:4px 6px;">${escapeHtml(m.kind)}</td>
        <td style="padding:4px 6px;">${m.qtyDelta}</td><td style="padding:4px 6px;">$${Number(m.unitCost).toFixed(2)}</td>
        <td style="padding:4px 6px;white-space:nowrap;">${!m.voidedAt && ["purchase", "adjust", "writeoff"].includes(m.kind) ? `<button class="admin-btn" style="padding:1px 6px;font-size:11px;" data-mid="${m.id}" onclick="transferVoid_(this.dataset.mid)">Void</button>` : ""}${m.voidedAt && ["purchase", "adjust", "writeoff"].includes(m.kind) ? `<button class="admin-btn" style="padding:1px 6px;font-size:11px;background:#dcfce7;color:#166534;border:1px solid #86efac;" data-mid="${m.id}" title="${escapeHtml("Voided" + (m.voidReason ? ": " + m.voidReason : "") + " — click to make this entry count again")}" onclick="transferRestore_(this.dataset.mid)">Undo void</button>` : ""}</td>
      </tr>`).join("")}</tbody></table></div>`, 560);
    window.transferVoid_ = async (mid) => {
      const ans = await confirmModal_({ title: "Void this entry?", text: "It stays in history (struck through) but stops counting toward stock or cost.", reason: "required", confirmLabel: "Void", danger: true });
      if (!ans.ok) return;
      const reason = ans.reason;
      try { await hoopApi_({ action: "voidTransferMovement", movementId: Number(mid), reason }); showToast("Voided."); close(); await load(); } catch (e) { showToast(e.message, true); } };
    // Undo a void: the entry counts toward stock and cost again. The server refuses in a closed month, or
    // when restoring a write-off would take stock below zero.
    window.transferRestore_ = async (mid) => {
      if (!await askConfirm_("Undo this void?\n\nThe entry will count toward stock and cost again, exactly as if it had never been voided.")) return;
      try { await hoopApi_({ action: "restoreTransferMovement", movementId: Number(mid) }); showToast("Entry restored."); close(); await load(); }
      catch (e) { showToast("Couldn't undo the void: " + e.message, true); } };
  };
  await load();
}

function showTransferFormModal_(t, onDone){
  const isNew = !t; const f = t || { name: "", description: "", visible: true };
  const inp = "font-size:13px;padding:6px 8px;border:1px solid #ccc;border-radius:4px;width:100%;box-sizing:border-box;";
  const { ov, close } = inventoryModal_(isNew ? "New transfer" : "Edit transfer", `
    <label style="font-size:12px;font-weight:600;">Name<br><input id="tfName" value="${escapeHtml(f.name)}" style="${inp}"></label>
    <label style="font-size:12px;font-weight:600;display:block;margin-top:8px;">Description<br><input id="tfDesc" value="${escapeHtml(f.description || "")}" style="${inp}"></label>
    <label style="font-size:12px;font-weight:600;display:flex;align-items:center;gap:6px;margin-top:8px;"><input type="checkbox" id="tfVis" ${f.visible !== false ? "checked" : ""}> Visible</label>
    <div id="tfErr" style="color:#b03a2e;font-size:13px;min-height:18px;margin-top:6px;"></div>
    <div style="display:flex;gap:8px;justify-content:flex-end;"><button type="button" id="tfCancel" style="padding:6px 14px;border:1px solid #ccc;border-radius:5px;background:#fff;cursor:pointer;">Cancel</button><button type="button" id="tfSave" class="admin-btn">${isNew ? "Create" : "Save"}</button></div>`, 440);
  ov.querySelector("#tfCancel").onclick = close;
  ov.querySelector("#tfSave").onclick = async () => {
    const payload = { id: f.id, name: ov.querySelector("#tfName").value.trim(), description: ov.querySelector("#tfDesc").value.trim(), visible: ov.querySelector("#tfVis").checked };
    if (!payload.name) { ov.querySelector("#tfErr").textContent = "Name is required."; return; }
    try { await hoopApi_({ action: "saveTransfer", transfer: payload }); close(); showToast(isNew ? "Created." : "Saved."); onDone && onDone(); }
    catch (e) { ov.querySelector("#tfErr").textContent = e.message; }
  };
}

// Receive a sheet: a total, then rows (transfer item, count, % of sheet) showing running $ + per-item.
// Pulls just the grand total off a vendor-invoice PDF (unlike the Blanks importer, a transfer
// sheet's receive only needs the one number). Scans the grouped text for total-labelled lines and
// takes the largest dollar amount — a grand total is never smaller than a subtotal or a line — and
// returns 0 when nothing matches, so it's only ever a prefill the admin confirms. Reuses the same
// pdf.js text extraction (extractPdfItems_) + groupTextRows_/lineText_/pdfNum_ as the PDF importer.
function parseInvoiceTotal_(items){
  const lines = groupTextRows_(items, 4).map(lineText_);
  const re = /\b(?:invoice\s+total|order\s+total|grand\s+total|total\s+due|amount\s+due|balance\s+due|total)\b[^$\d]*\$?\s*([\d,]+\.\d{2})/ig;
  let best = 0;
  for (const t of lines) { let m; re.lastIndex = 0; while ((m = re.exec(t))) { const v = pdfNum_(m[1]); if (v > best) best = v; } }
  return best;
}
function showReceiveTransferModal_(transfers, onDone){
  const inp = "font-size:13px;padding:5px 7px;border:1px solid #ccc;border-radius:4px;";
  const opt = transfers.map(t => `<option value="${t.id}">${escapeHtml(t.name)}</option>`).join("");
  const rowHtml = () => `<tr class="trRow">
    <td style="padding:3px 4px;"><select class="trItem" style="${inp}">${opt}</select></td>
    <td style="padding:3px 4px;"><input class="trCount" type="number" min="1" style="${inp}width:70px;"></td>
    <td style="padding:3px 4px;"><input class="trPct" type="number" min="0" max="100" step="0.1" style="${inp}width:70px;"></td>
    <td style="padding:3px 4px;" class="trRowDollars">—</td>
    <td style="padding:3px 4px;" class="trRowPer">—</td>
    <td style="padding:3px 4px;"><button type="button" class="admin-btn trRm admin-btn-danger" style="padding:1px 7px;">✕</button></td></tr>`;
  const { ov, close } = inventoryModal_("Receive a transfer sheet", `
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px;align-items:end;">
      <label style="font-size:12px;font-weight:600;">Date<br><input id="trDate" type="date" value="${new Date().toISOString().slice(0, 10)}" style="${inp}"></label>
      <label style="font-size:12px;font-weight:600;">Sheet total ($)<br>$<input id="trTotal" type="number" min="0" step="0.01" style="${inp}width:100px;"></label>
      <label style="font-size:12px;font-weight:600;">Invoice #<br><input id="trRef" style="${inp}width:120px;"></label>
      <label style="font-size:12px;font-weight:600;">Paid from<br><select id="trPaid" style="${inp}"><option value="">Loading…</option></select></label>
      <label style="font-size:12px;font-weight:600;">Receipt (optional)<br><input type="file" id="trReceipt" accept="image/jpeg,image/png,image/webp,image/heic,image/heif,.heic,.heif,application/pdf" style="font-size:12px;"></label>
      <button type="button" class="admin-btn" id="trImport" style="padding:6px 10px;align-self:flex-end;">Import total from PDF…</button>
    </div>
    <div id="trImportNote" style="font-size:11px;color:#666;min-height:14px;margin:-4px 0 8px;"></div>
    ${transfers.length ? `<table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="text-align:left;background:#f3f4f6;"><th style="padding:4px;">Item</th><th style="padding:4px;">Count</th><th style="padding:4px;">% of sheet</th><th style="padding:4px;">$</th><th style="padding:4px;">per item</th><th></th></tr></thead>
      <tbody id="trRows">${rowHtml()}</tbody></table>
      <div style="margin-top:6px;display:flex;justify-content:space-between;"><button type="button" class="admin-btn" id="trAddRow" style="padding:2px 10px;">+ Add row</button><span id="trSum" style="font-size:12px;color:#666;"></span></div>
      <div id="trOther" style="margin-top:8px;padding:8px 10px;border:1px solid #e5e7eb;background:#f9fafb;border-radius:6px;font-size:12px;">
        <div style="font-weight:600;margin-bottom:2px;">Not going into stock (optional)</div>
        <div style="color:#555;margin-bottom:6px;">If part of the sheet wasn't for stock, say how much. The rows, written off and personal use must add up to 100%.</div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:end;margin-bottom:6px;">
          <label style="font-weight:600;">Written off %<br><input id="trWoPct" type="number" min="0" max="100" step="0.1" value="0" style="${inp}width:70px;"></label>
          <span id="trWoAmt" style="min-width:56px;padding-bottom:6px;color:#555;"></span>
          <label id="trWoCatWrap" style="font-weight:600;display:none;">Expense category<br><select id="trWoCat" style="${inp}"><option value="">Loading…</option></select></label>
          <label id="trWoDescWrap" style="font-weight:600;flex:1;min-width:200px;display:none;">What was written off<br><input id="trWoDesc" maxlength="200" placeholder="e.g. test prints, misprints, scrap" style="${inp}width:100%;box-sizing:border-box;"></label>
        </div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:end;">
          <label style="font-weight:600;">Personal use %<br><input id="trPePct" type="number" min="0" max="100" step="0.1" value="0" style="${inp}width:70px;"></label>
          <span id="trPeAmt" style="min-width:56px;padding-bottom:6px;color:#555;"></span>
          <label id="trPeDescWrap" style="font-weight:600;flex:1;min-width:200px;display:none;">What it was for<br><input id="trPeDesc" maxlength="200" placeholder="e.g. my own shirts" style="${inp}width:100%;box-sizing:border-box;"></label>
        </div>
        <div style="color:#555;margin-top:6px;">Written off is recorded as an expense in the category you pick. Personal use is an owner draw (not deductible); if the sheet was paid with personal funds, nothing is recorded for it.</div>
      </div>`
      : `<div style="color:#b03a2e;">Add a transfer item first (+ New transfer).</div>`}
    <div id="trErr" style="color:#b03a2e;font-size:13px;min-height:18px;margin-top:6px;"></div>
    <div style="display:flex;gap:8px;justify-content:flex-end;"><button type="button" id="trCancel" style="padding:6px 14px;border:1px solid #ccc;border-radius:5px;background:#fff;cursor:pointer;">Cancel</button><button type="button" id="trSave" class="admin-btn">Receive</button></div>`, 640);
  loadAccounts_().then(d => { const cc = d.accounts.find(a => a.type === "credit_card" && a.active);
    ov.querySelector("#trPaid").innerHTML = accountOptions_(d.accounts, (cc && cc.id) || "", { personal: true, blank: !cc }); })
    .catch(() => { ov.querySelector("#trPaid").innerHTML = `<option value="">(accounts unavailable)</option>`; });
  const recompute = () => {
    const total = parseFloat(ov.querySelector("#trTotal").value) || 0;
    const rows = [...ov.querySelectorAll(".trRow")];
    const pcts = rows.map(r => parseFloat(r.querySelector(".trPct").value) || 0);
    const pctSum = pcts.reduce((a, b) => a + b, 0);
    rows.forEach((r, i) => {
      const count = parseInt(r.querySelector(".trCount").value) || 0;
      const dollars = pctSum ? total * (pcts[i] / 100) : 0;
      r.querySelector(".trRowDollars").textContent = "$" + dollars.toFixed(2);
      r.querySelector(".trRowPer").textContent = count ? "$" + (dollars / count).toFixed(2) : "—";
    });
    const woPct = Math.max(0, parseFloat(ov.querySelector("#trWoPct").value) || 0), pePct = Math.max(0, parseFloat(ov.querySelector("#trPePct").value) || 0);
    const all = pctSum + woPct + pePct, left = 100 - all, over = all > 100.05, done = Math.abs(left) <= 0.05;
    const r2 = (x) => Math.round(x * 100) / 100;
    // Don't nag on a blank form: only once something has been entered.
    const started = rows.some((r, i) => (parseInt(r.querySelector(".trCount").value) || 0) > 0 || pcts[i] > 0) || woPct > 0 || pePct > 0;
    const sum = ov.querySelector("#trSum");
    sum.textContent = `Rows ${r2(pctSum)}%` + (woPct ? ` + written off ${r2(woPct)}%` : "") + (pePct ? ` + personal ${r2(pePct)}%` : "") + ` = ${r2(all)}% of the sheet` +
      (done ? " ✓" : over ? " — over 100%" : started ? ` — ${r2(left)}% still to assign` : "");
    sum.style.color = over ? "#b03a2e" : done ? "#166534" : started ? "#b45309" : "#666";
    ov.querySelector("#trWoAmt").textContent = woPct ? "$" + (total * woPct / 100).toFixed(2) : "";
    ov.querySelector("#trPeAmt").textContent = pePct ? "$" + (total * pePct / 100).toFixed(2) : "";
    ov.querySelector("#trWoCatWrap").style.display = woPct > 0 ? "" : "none";
    ov.querySelector("#trWoDescWrap").style.display = woPct > 0 ? "" : "none";
    ov.querySelector("#trPeDescWrap").style.display = pePct > 0 ? "" : "none";
    updateSave(started);
  };
  // The sheet can only be saved when it's fully accounted for: the rows, the written-off part and the personal
  // part add up to 100%, and each part that isn't zero is described. The server enforces the same rules.
  const problem = () => {
    const rows = [...ov.querySelectorAll(".trRow")].map(r => ({ count: parseInt(r.querySelector(".trCount").value) || 0, pct: parseFloat(r.querySelector(".trPct").value) || 0 })).filter(r => r.count > 0);
    if (!rows.length) return "Add at least one row with a count.";
    const woPct = Math.max(0, parseFloat(ov.querySelector("#trWoPct").value) || 0), pePct = Math.max(0, parseFloat(ov.querySelector("#trPePct").value) || 0);
    const all = rows.reduce((a, r) => a + r.pct, 0) + woPct + pePct;
    if (all > 100.05) return "The rows, written off and personal parts add up to more than 100% of the sheet.";
    if (all < 99.95) return `Only ${Math.round(all * 100) / 100}% of the sheet is accounted for — the rows, written off and personal use must add up to 100%.`;
    if (woPct > 0 && !ov.querySelector("#trWoDesc").value.trim()) return "Describe what was written off.";
    if (woPct > 0 && !Number(ov.querySelector("#trWoCat").value)) return "Choose an expense category for the written-off part.";
    if (pePct > 0 && !ov.querySelector("#trPeDesc").value.trim()) return "Describe what the personal part was for.";
    if ((woPct > 0 || pePct > 0) && !ov.querySelector("#trPaid").value) return "Choose what the sheet was paid from, so the extra part can be recorded.";
    return "";
  };
  const updateSave = (started) => {
    const save = ov.querySelector("#trSave"), why = problem();
    save.disabled = !!why; save.style.opacity = why ? ".5" : ""; save.title = why;
    ov.querySelector("#trErr").textContent = why && started ? why : "";
  };
  if (transfers.length) {
    ov.querySelector("#trAddRow").onclick = () => { ov.querySelector("#trRows").insertAdjacentHTML("beforeend", rowHtml()); wireRows(); recompute(); };
    const wireRows = () => {
      ov.querySelectorAll(".trRm").forEach(b => b.onclick = () => { if (ov.querySelectorAll(".trRow").length > 1) { b.closest("tr").remove(); recompute(); } });
      ov.querySelectorAll(".trCount, .trPct").forEach(i => i.oninput = recompute);
    };
    ov.querySelector("#trTotal").oninput = recompute;
    ["#trWoCat", "#trPaid"].forEach(sel => ov.querySelector(sel).onchange = recompute);
    ["#trWoPct", "#trPePct", "#trWoDesc", "#trPeDesc"].forEach(sel => ov.querySelector(sel).oninput = recompute);
    (adminFeatureOn_("bookkeeping") ? mnApi_({ action: "listExpenseCategories" }) : Promise.reject(new Error("off"))).then(d => {
      const cats = d.categories || [];
      ov.querySelector("#trWoCat").innerHTML = cats.map(c => `<option value="${c.id}"${/^supplies/i.test(c.name) ? " selected" : ""}>${escapeHtml(c.name)}</option>`).join("");
      recompute();
    }).catch(() => { ov.querySelector("#trWoCat").innerHTML = `<option value="">(categories unavailable)</option>`; });
    wireRows();
    recompute();
  }
  hideBookkeepingFields_(ov, ["#trPaid", "#trReceipt", "#trOther"]);
  // Import total from a PDF invoice: pull just the grand total into Sheet total (confirm it), and
  // keep the PDF itself as the receipt so it's stored, not just parsed (same DataTransfer trick the
  // Blanks PDF importer uses). Best-effort — a PDF with no recognisable total just asks you to type it.
  ov.querySelector("#trImport").onclick = () => {
    const fi = document.createElement("input"); fi.type = "file"; fi.accept = "application/pdf";
    fi.onchange = async () => {
      const file = fi.files[0]; if (!file) return;
      const note = ov.querySelector("#trImportNote"); note.textContent = "Reading the PDF…";
      try {
        const total = parseInvoiceTotal_(await extractPdfItems_(file));
        if (total > 0) { ov.querySelector("#trTotal").value = total.toFixed(2); recompute(); }
        if (adminFeatureOn_("bookkeeping")) { try { const dt = new DataTransfer(); dt.items.add(file); ov.querySelector("#trReceipt").files = dt.files; } catch (e) {} }
        note.textContent = total > 0 ? `Found total $${total.toFixed(2)} in ${file.name} — confirm it's right. Saved as the receipt.`
          : `No total found in ${file.name}; enter the sheet total by hand. Saved as the receipt.`;
      } catch (e) { note.textContent = e.message || "Could not read that PDF."; }
    };
    fi.click();
  };
  ov.querySelector("#trCancel").onclick = close;
  ov.querySelector("#trSave").onclick = async () => {
    const err = ov.querySelector("#trErr");
    const save = ov.querySelector("#trSave");
    const paid = ov.querySelector("#trPaid").value;
    const rows = [...ov.querySelectorAll(".trRow")].map(r => ({ transferId: Number(r.querySelector(".trItem").value),
      count: parseInt(r.querySelector(".trCount").value) || 0, pctOfSheet: parseFloat(r.querySelector(".trPct").value) || 0 })).filter(r => r.count > 0);
    if (!rows.length) { err.textContent = "Add at least one row with a count."; return; }
    const why = problem(); if (why) { err.textContent = why; return; }
    const woPct = Math.max(0, parseFloat(ov.querySelector("#trWoPct").value) || 0), pePct = Math.max(0, parseFloat(ov.querySelector("#trPePct").value) || 0);
    const body = { action: "receiveTransferSheet", rows, total: parseFloat(ov.querySelector("#trTotal").value) || 0,
      receivedAt: ov.querySelector("#trDate").value, vendorRef: ov.querySelector("#trRef").value.trim(),
      ...(paid === "personal" ? { paidPersonally: true } : paid ? { accountId: Number(paid) } : {}),
      ...(woPct > 0 ? { writeoff: { pct: woPct, description: ov.querySelector("#trWoDesc").value.trim(), categoryId: Number(ov.querySelector("#trWoCat").value) || 0 } } : {}),
      ...(pePct > 0 ? { personal: { pct: pePct, description: ov.querySelector("#trPeDesc").value.trim() } } : {}) };
    try {
      const receiptFile = ov.querySelector("#trReceipt") && ov.querySelector("#trReceipt").files[0];
      if (receiptFile) { save.textContent = "Uploading receipt…"; const r = await uploadReceipt_(receiptFile); body.receiptKey = r.key; body.receiptName = r.name; }
      save.textContent = "Receiving…";
      await hoopApi_(body);
      close(); showToast("Sheet received."); onDone && onDone();
    } catch (e) { err.textContent = e.message; save.textContent = "Receive"; }
  };
}

// ---- Run Transfer Sheets (migrations/0036) — ready cards + waiting + gang sheet ------------------
// One line on a card saying where its transfers come from (getTransferQueue's transferSource), or what's short.
function rtTransferNote_(c) {
  const line = (color, text) => `<div class="rt-xfer" style="font-size:12px;margin-bottom:8px;color:${color};">${text}</div>`;
  if (c.transferSource === "used") return line("#166534", "✓ Transfers already used — taken out of stock when the line was made.");
  if (c.transferSource === "marked") return line("#166534", "✓ Transfers marked received.");
  if (c.transferSource === "stock") return line("#166534", "✓ Transfers in stock — set aside for this line.");
  const short = (c.transferShort || []).map(s => s.custom ? "the customer's design (print it, then mark received)"
    : s.unlinked ? escapeHtml(s.name) + " (no transfer linked)"
    : escapeHtml(s.name) + ` — ${s.free} free in stock, needs ${s.needed}`);
  return short.length ? line("#b26a00", "Transfers short: " + short.join("; ") + ".") : "";
}
async function renderRunTransfer(app){
  adminSetHash("runtransfer");
  document.title = adminTitle_("Run Transfer Sheets");
  app.innerHTML = `
    ${adminPageHead_("Run Transfer Sheets")}
    <div class="admin-panel" style="--org-accent:var(--accent);max-width:1000px;margin:8px auto 60px;">
      <div style="margin-bottom:10px;"><button type="button" class="admin-btn" id="rtGang">Gang sheet totals</button></div>
      <div id="rtBody" style="color:#888;font-size:15px;">Loading…</div>
    </div>`;
  async function load(){
    const body = document.getElementById("rtBody");
    let data; try { data = await hoopApi_({ action: "getTransferQueue" }); } catch (e) { body.innerHTML = `<div style="color:#b03a2e;">${escapeHtml(e.message)}</div>`; return; }
    const card = (c, ready) => `<div style="border:1px solid ${ready ? "#2c6b2f" : "#ddd"};border-radius:10px;padding:14px;margin-bottom:12px;background:${ready ? "#f3f9f4" : "#fff"};">
      <div style="font-weight:700;">${escapeHtml(c.orgName)} · ${escapeHtml(c.customerName)} · Qty ${c.qty}</div>
      ${dueBadge_(c.dueDate) ? `<div style="margin:2px 0;">${dueBadge_(c.dueDate)}</div>` : ""}
      <div style="font-size:13px;color:#666;margin:2px 0 6px;">${escapeHtml(c.itemName)}${c.itemSize ? " (" + escapeHtml(c.itemSize) + ")" : ""}${c.garmentColor ? " · " + escapeHtml(c.garmentColor) : ""} · Blank: ${c.blank ? escapeHtml(c.blank.name + (c.blank.color ? " / " + c.blank.color : "")) : "— none linked —"}</div>
      <div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:8px;">${c.transfers.map(t => t.custom
        // The customer's own image (migrations/0054): private, so a signed link fills the picture in after the page draws.
        ? `<div style="text-align:center;font-size:11px;color:#555;">${t.fileKey ? `<img data-design-key="${escapeHtml(t.fileKey)}" alt="The customer's design" style="width:64px;height:64px;object-fit:contain;border:1px solid #ddd;border-radius:6px;display:block;background:#fff;">` : `<div style="width:64px;height:64px;border:1px dashed #ccc;border-radius:6px;"></div>`}<div style="max-width:90px;">${escapeHtml(t.location)}<br>Customer design${t.fileKey ? `<br><button type="button" class="admin-btn rtDl" data-key="${escapeHtml(t.fileKey)}" style="padding:1px 6px;font-size:11px;margin-top:2px;">Download</button>` : " — no file (Edit items → Files)"}</div></div>`
        : `<div style="text-align:center;font-size:11px;color:#555;">${t.thumbUrl || t.imageUrl ? `<img src="${escapeHtml(t.thumbUrl || t.imageUrl)}" alt="" style="width:64px;height:64px;object-fit:cover;border:1px solid #ddd;border-radius:6px;display:block;">` : `<div style="width:64px;height:64px;border:1px dashed #ccc;border-radius:6px;"></div>`}<div style="max-width:72px;">${escapeHtml(t.location)}${t.auto ? " (QR)" : ""}<br>${escapeHtml(t.graphicName)}${t.ink ? " · " + escapeHtml(t.ink) : ""}</div></div>`).join("")}</div>
      ${c.hasEmbroidery ? `<div class="rt-emb" style="font-size:12px;margin-bottom:8px;color:${c.embroideryDone ? "#166534" : "#555"};">Also embroidered — ${c.embroideryDone ? "✓ embroidery done" : `embroidery still to run on <a href="#runorder" style="color:inherit;">Run Order</a>`}. Marking the transfers applied here doesn't make the piece; finishing the embroidery does.</div>` : ""}
      ${rtTransferNote_(c)}
      <div style="display:flex;gap:8px;flex-wrap:wrap;">
        ${!c.blankReceived ? `<span style="font-size:12px;color:#b26a00;align-self:center;">Waiting on blank</span>` : ""}
        ${!c.transferReceived ? `<button type="button" class="admin-btn rtRecv" data-item="${c.itemId}" data-order="${escapeHtml(c.orderId)}" data-org="${escapeHtml(c.orgId)}" style="padding:4px 12px;">Mark transfer received</button>` : ""}
        ${ready && c.hasEmbroidery ? `<button type="button" class="admin-btn rtApply" data-item="${c.itemId}" data-order="${escapeHtml(c.orderId)}" data-org="${escapeHtml(c.orgId)}" style="padding:6px 16px;font-weight:700;background:var(--org-accent,#2c6b2f);color:#fff;">Mark transfers applied</button>` : ""}
        ${ready && !c.hasEmbroidery ? `<button type="button" class="admin-btn rtMake" data-item="${c.itemId}" data-order="${escapeHtml(c.orderId)}" data-org="${escapeHtml(c.orgId)}" style="padding:6px 16px;font-weight:700;background:var(--org-accent,#2c6b2f);color:#fff;">Mark made</button>` : ""}
      </div></div>`;
    body.innerHTML = paidUnrunHtml_(data.paidUnrun || []) + `
      <h2 style="font-size:17px;margin:4px 0 8px;">Ready to press (${data.ready.length})</h2>
      ${data.ready.length ? data.ready.map(c => card(c, true)).join("") : `<div style="color:#888;padding:8px 0;">Nothing ready — needs the blank received and the transfers in stock (or marked received).</div>`}
      <h2 style="font-size:17px;margin:20px 0 8px;">Waiting on blanks or transfer sheets (${data.waiting.length})</h2>
      ${data.waiting.length ? data.waiting.map(c => card(c, false)).join("") : `<div style="color:#888;padding:8px 0;">Nothing waiting.</div>`}`;
    fillDesignThumbs_(body);
    body.querySelectorAll(".rtDl").forEach(b => b.onclick = () => downloadDesignFile_(b.dataset.key));
    body.querySelectorAll(".rtRecv").forEach(b => b.onclick = async () => {
      try { await hoopApi_({ action: "setTransferReceived", itemId: Number(b.dataset.item), orderId: b.dataset.order, org: b.dataset.org, received: true }); showToast("Transfer received."); await load(); }
      catch (e) { showToast(e.message, true); } });
    body.querySelectorAll(".rtApply").forEach(b => b.onclick = async () => {
      try { await hoopApi_({ action: "setTransfersApplied", orderId: b.dataset.order, itemId: Number(b.dataset.item), org: b.dataset.org, applied: true }); showToast("Transfers marked applied."); await load(); }
      catch (e) { showToast(e.message, true); } });
    body.querySelectorAll(".rtMake").forEach(b => b.onclick = async () => {
      if (!await askConfirm_("Mark this line made? Consumes the blank and the transfer applications.")) return;
      try { const r = await hoopApi_({ action: "makeTransferLine", orderId: b.dataset.order, itemId: Number(b.dataset.item), org: b.dataset.org }); showToast(r.orderComplete ? "Order complete." : "Marked made."); await load(); }
      catch (e) { showToast(e.message, true); } });
  }
  document.getElementById("rtGang").onclick = async () => {
    let rows = []; try { rows = (await hoopApi_({ action: "getGangSheet" })).rows || []; } catch (e) { showToast(e.message, true); return; }
    const gangNote = `<div style="font-size:12px;color:#666;margin-bottom:8px;">What still has to be printed — transfers already in stock, used or marked received are left out.</div>`;
    inventoryModal_("Gang sheet totals", rows.length ? gangNote + `<div style="margin-bottom:10px;"><button type="button" class="admin-btn" id="rtGangCsv">Download CSV</button></div>
      <div style="max-height:60vh;overflow:auto;"><table style="width:100%;border-collapse:collapse;font-size:13px;">
      <thead><tr style="text-align:left;background:#f3f4f6;"><th style="padding:5px 6px;">Graphic</th><th style="padding:5px 6px;">Ink</th><th style="padding:5px 6px;">Size</th><th style="padding:5px 6px;">Count</th></tr></thead>
      <tbody>${rows.map(r => `<tr style="border-bottom:1px solid #eee;"><td style="padding:5px 6px;">${escapeHtml(r.graphic)}</td><td style="padding:5px 6px;">${escapeHtml(r.ink)}</td><td style="padding:5px 6px;">${escapeHtml(r.size)}</td><td style="padding:5px 6px;font-weight:600;">${r.count}</td></tr>`).join("")}</tbody></table></div>`
      : gangNote + `<div style="color:#888;">Nothing to print — every queued transfer is in stock or already in hand.</div>`, 520);
    const csvBtn = document.getElementById("rtGangCsv");
    if (csvBtn) csvBtn.onclick = () => downloadCsv_(`odd-gang-sheet-${new Date().toISOString().slice(0, 10)}.csv`, rows,
      [["graphic", "Graphic"], ["ink", "Ink"], ["size", "Size"], ["count", "Count"]]);
  };
  await load();
}

// ---- Designs (migrations/0024) — per-org: files, versions, thread map, required hoop -------
// One design per product (products.designId, set from the product form — see
// loadProductDesignSection above). A design's file history is append-only (design_versions);
// the "current" version is just the newest row, returned first by listDesignVersions.
// A version requires TWO files: the native, editable design-software project file (what you'd
// open to make an edit — e.g. .emb/.jdx) and the actual stitch file a machine runs (e.g.
// .dst/.dsb/.pes — what "Send design to machine", phase 6, pushes to the machine). ANY embroidery
// extension is accepted for either; only the formats we know are kept to their own role.
// Mirrors functions/api/design.js (the server is what enforces it).
const DESIGN_NATIVE_EXTS = ["emb", "jdx", "art", "ofm", "pxf"];
const MACHINE_STITCH_EXTS = ["dst", "dsb", "dsz", "pes", "pec", "exp", "vp3", "vip", "xxx", "hus", "jef", "sew", "csd", "shv", "u01", "edr", "pcs", "pcm", "tap", "tbf", "fdr", "ksm", "10o", "gt", "inb", "max", "emd", "new", "stx", "sst", "phb", "phc"];
const NOT_EMBROIDERY_EXTS = ["html", "htm", "xhtml", "shtml", "mht", "svg", "svgz", "xml", "xsl", "js", "mjs", "cjs", "css", "json", "wasm",
  "php", "phtml", "asp", "aspx", "jsp", "cgi", "pl", "py", "rb", "sh", "bash", "zsh", "ps1", "psm1", "vbs", "vbe", "wsf", "hta",
  "exe", "com", "bat", "cmd", "msi", "msp", "dll", "scr", "cpl", "jar", "app", "dmg", "pkg", "deb", "rpm", "apk", "lnk", "reg",
  "jpg", "jpeg", "png", "gif", "webp", "bmp", "tif", "tiff", "heic", "ico", "pdf", "doc", "docx", "docm", "xls", "xlsx", "xlsm",
  "ppt", "pptx", "rtf", "txt", "csv", "zip", "rar", "7z", "gz", "tar", "iso"];
const isEmbroideryExt_ = (ext) => /^[a-z0-9]{1,10}$/.test(ext) && !NOT_EMBROIDERY_EXTS.includes(ext);
// Why a file can't be this role's file ("" = fine).
function embroideryFileProblem_(fileName, role) {
  const ext = fileName.includes(".") ? fileName.split(".").pop().toLowerCase() : "";
  if (!isEmbroideryExt_(ext)) return `"${fileName}" isn't an embroidery file.`;
  if (role === "design" && MACHINE_STITCH_EXTS.includes(ext)) return `A .${ext} is a machine stitch file — choose it as the Machine file. The Design file is the editable project file from your design software.`;
  if (role === "machine" && DESIGN_NATIVE_EXTS.includes(ext)) return `A .${ext} is a design-software project file — choose it as the Design file. The Machine file is the stitch file the machine runs (e.g. .dst, .dsb, .pes).`;
  return "";
}
// Stitch files this page can read (needle stops, preview, colors): Tajima .dst and Barudan .dsb.
const STITCH_PREVIEW_EXTS = ["dst", "dsb"];
const stitchExt_ = (nameOrExt) => String(nameOrExt || "").toLowerCase().replace(/^.*\./, "");
const canPreviewStitch_ = (nameOrExt) => STITCH_PREVIEW_EXTS.includes(stitchExt_(nameOrExt));

// Reads a Tajima .dst (512-byte header, then 3-byte records) and counts its needle stops —
// the color blocks that actually contain stitches, i.e. how many thread-map entries the design
// needs. Record decoding follows the Tajima DST format (end = b2&0xF3==0xF3, color
// change = b2&0xC3==0xC3, jump = b2&0x83==0x83), including its base64-encoded-file fallback.
function analyzeDstNeedleStops_(buffer){
  let data = new Uint8Array(buffer);
  if (data.length >= 3 && data[2] !== 0x3A) {
    try {
      const b64 = new TextDecoder("ascii").decode(data).replace(/\s/g, "");
      data = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
    } catch (e) {}
  }
  if (data.length < 512) throw new Error("File is too short to be a DST file.");
  let colorChanges = 0, stitches = 0, blocks = 0, blockHasStitch = false;
  for (let i = 512; i + 2 < data.length; i += 3) {
    const b2 = data[i + 2];
    if ((b2 & 0xF3) === 0xF3) break;
    if ((b2 & 0xC3) === 0xC3) { colorChanges++; if (blockHasStitch) blocks++; blockHasStitch = false; continue; }
    if ((b2 & 0x83) === 0x83) continue;
    stitches++; blockHasStitch = true;
  }
  if (blockHasStitch) blocks++;
  if (!stitches) throw new Error("No stitches found in this DST file.");
  return { needleStops: blocks, colorChanges, stitches };
}

// Full DST parser for the on-screen preview: decodes each 3-byte record's dx/dy (the standard
// Tajima bit layout) into an absolute stitch path, split into colour blocks at each colour change.
// Returns { stitches:[{x,y,jump,color}], needleStops, colorChanges, stitchCount, bbox }.
function parseDst_(buffer){
  let data = new Uint8Array(buffer);
  if (data.length >= 3 && data[2] !== 0x3A) {
    try { const b64 = new TextDecoder("ascii").decode(data).replace(/\s/g, ""); data = Uint8Array.from(atob(b64), c => c.charCodeAt(0)); } catch (e) {}
  }
  if (data.length < 512) throw new Error("File is too short to be a DST file.");
  const stitches = [];
  let x = 0, y = 0, color = 0, stitchCount = 0, colorChanges = 0;
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  const blockHasStitch = {};
  for (let i = 512; i + 2 < data.length; i += 3) {
    const b0 = data[i], b1 = data[i + 1], b2 = data[i + 2];
    if ((b2 & 0xF3) === 0xF3) break; // end of file
    let dx = 0, dy = 0;
    if (b0 & 0x01) dx += 1; if (b0 & 0x02) dx -= 1; if (b0 & 0x04) dx += 9; if (b0 & 0x08) dx -= 9;
    if (b0 & 0x80) dy += 1; if (b0 & 0x40) dy -= 1; if (b0 & 0x20) dy += 9; if (b0 & 0x10) dy -= 9;
    if (b1 & 0x01) dx += 3; if (b1 & 0x02) dx -= 3; if (b1 & 0x04) dx += 27; if (b1 & 0x08) dx -= 27;
    if (b1 & 0x80) dy += 3; if (b1 & 0x40) dy -= 3; if (b1 & 0x20) dy += 27; if (b1 & 0x10) dy -= 27;
    if (b2 & 0x04) dx += 81; if (b2 & 0x08) dx -= 81; if (b2 & 0x20) dy += 81; if (b2 & 0x10) dy -= 81;
    x += dx; y += dy;
    if ((b2 & 0xC3) === 0xC3) { colorChanges++; color++; continue; } // colour change: advance block, no stitch
    const jump = (b2 & 0x83) === 0x83;
    stitches.push({ x, y, jump, color });
    if (!jump) { stitchCount++; blockHasStitch[color] = true;
      if (x < minX) minX = x; if (y < minY) minY = y; if (x > maxX) maxX = x; if (y > maxY) maxY = y; }
  }
  if (!stitchCount) throw new Error("No stitches found in this DST file.");
  return { stitches, needleStops: Object.keys(blockHasStitch).length, colorChanges, stitchCount,
    bbox: { minX, minY, maxX, maxY } };
}

// Barudan .dsb: the same 512-byte header as a .dst, then 3-byte records — a control byte, then Y, then X as
// whole steps (0.1 mm) whose sign is in the control byte (0x40 → Y negative, 0x20 → X negative). The control
// byte's LOW 5 BITS say what it is: 0 stitch, 1 jump, 7 trim, 8 stop, 9–23 needle change (needle = low − 8),
// 24 end. Most software writes the codes as 0xE7 / 0xE8 / 0xE9–0xF7 / 0xF8 (the layout pyembroidery reads);
// some writes them with only the top bit (0x8A, 0x98 — files in the shop's own archive), so the top bits are
// ignored. Same result shape as parseDst_ (Y up-positive like a DST), plus `needles`: the needle each color block
// runs on (the file names them). Blocks are counted only once they stitch, so block i is needle stop i.
function parseDsb_(buffer){
  const data = new Uint8Array(buffer);
  if (data.length < 512) throw new Error("File is too short to be a DSB file.");
  const stitches = [], needles = [];
  let x = 0, y = 0, color = 0, stitchCount = 0, colorChanges = 0, needle = null, blockStitched = false;
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (let i = 512; i + 2 < data.length; i += 3) {
    const ctrl = data[i], low = ctrl & 0x1F;
    if (low === 0 || low === 1) {
      const dy = (ctrl & 0x40) ? -data[i + 1] : data[i + 1], dx = (ctrl & 0x20) ? -data[i + 2] : data[i + 2];
      x += dx; y += dy;
      const jump = low === 1;
      stitches.push({ x, y, jump, color });
      if (!jump) {
        stitchCount++;
        if (!blockStitched) { blockStitched = true; needles[color] = needle; }
        if (x < minX) minX = x; if (y < minY) minY = y; if (x > maxX) maxX = x; if (y > maxY) maxY = y;
      }
      continue;
    }
    if (low === 24) break;                         // end
    if (low === 7 || low === 8) continue;          // trim / stop: same needle
    if (low >= 9 && low <= 23) {                   // needle change: a new block once this one has stitched
      colorChanges++;
      if (blockStitched) { color++; blockStitched = false; }
      needle = low - 8;
      continue;
    }
    break;                                         // a code this reader doesn't know: stop here
  }
  if (!stitchCount) throw new Error("No stitches found in this DSB file.");
  const needleStops = color + (blockStitched ? 1 : 0);
  return { stitches, needleStops, colorChanges, stitchCount, needles: needles.slice(0, needleStops), bbox: { minX, minY, maxX, maxY } };
}

// Reads a stitch file this page understands (canPreviewStitch_) by its extension or file name.
function parseStitchFile_(buffer, nameOrExt){
  const ext = stitchExt_(nameOrExt);
  if (ext === "dsb") return parseDsb_(buffer);
  if (ext === "dst") return parseDst_(buffer);
  throw new Error("Preview is available for .DST and .DSB files only.");
}
// Needle stops of a stitch file (the thread map's length): DST through its own counter, DSB through the parser.
function analyzeStitchNeedleStops_(buffer, nameOrExt){
  if (stitchExt_(nameOrExt) === "dsb") { const p = parseDsb_(buffer); return { needleStops: p.needleStops, colorChanges: p.colorChanges, stitches: p.stitchCount, needles: p.needles }; }
  return analyzeDstNeedleStops_(buffer);
}

// Distinct fallback colours for needle blocks that don't have a thread picked yet, so the preview
// still shows the design's separate colour areas.
const DST_PREVIEW_PALETTE = ["#444","#c0392b","#2471a3","#1e8449","#8e44ad","#d35400","#148f77","#b7950b","#616a6b","#7b241c","#1f618d","#196f3d","#6c3483","#935116"];

// Draws the parsed DST onto a canvas, colouring each block via colorFor(blockIndex) -> "#hex".
function renderDstPreview_(canvas, parsed, colorFor){
  const ctx = canvas && canvas.getContext && canvas.getContext("2d");
  if (!ctx) return; // no 2D canvas (e.g. jsdom) — the preview just doesn't draw
  const cw = canvas.width, ch = canvas.height;
  ctx.clearRect(0, 0, cw, ch);
  const { stitches, bbox } = parsed;
  const w = (bbox.maxX - bbox.minX) || 1, h = (bbox.maxY - bbox.minY) || 1;
  const pad = 12, scale = Math.min((cw - 2 * pad) / w, (ch - 2 * pad) / h);
  const offX = (cw - w * scale) / 2, offY = (ch - h * scale) / 2;
  const tx = (px) => offX + (px - bbox.minX) * scale;
  const ty = (py) => ch - (offY + (py - bbox.minY) * scale); // flip Y (DST is up-positive)
  ctx.lineJoin = "round"; ctx.lineCap = "round"; ctx.lineWidth = Math.max(0.6, scale * 1.1);
  let curColor = -1, penDown = false, prev = null;
  for (const s of stitches) {
    if (s.color !== curColor) { if (penDown) { ctx.stroke(); penDown = false; } curColor = s.color; ctx.strokeStyle = colorFor(curColor); prev = null; }
    if (s.jump) { if (penDown) { ctx.stroke(); penDown = false; } prev = s; continue; }
    if (!penDown) { ctx.beginPath(); ctx.moveTo(tx((prev || s).x), ty((prev || s).y)); penDown = true; }
    ctx.lineTo(tx(s.x), ty(s.y)); prev = s;
  }
  if (penDown) ctx.stroke();
}

// Downloads a stored design/machine file's bytes via the admin-gated signed link (same endpoint
// downloadDesignFile_ opens in a tab), for parsing/preview.
async function fetchDesignFileBytes_(key){
  const r = await fetch("/api/design", { method: "POST", headers: { "Content-Type": "application/json", "X-Admin-Key": adminKey || "" }, body: JSON.stringify({ key }) });
  const d = await r.json().catch(() => ({ status: "error", message: "Server error (" + r.status + ")" }));
  if (!r.ok || d.status === "error") throw new Error((d && d.message) || "Could not fetch the file");
  const fr = await fetch(d.url);
  if (!fr.ok) throw new Error("Could not download the file (" + fr.status + ")");
  return await fr.arrayBuffer();
}

// The thread-colour swatch <select> list shared by the upload and edit-colours modals. `rows` is
// [{threadId}] in needle order. Renders each row, wires change/remove, and calls onChange after any
// edit (so the caller re-renders the preview). `allowAddRemove` shows the ✕ (upload only).
function designThreadRowsHtml_(threads){
  return (selected) => `<option value="">— pick a thread —</option>` +
    threads.map(t => `<option value="${t.id}" ${t.id === selected ? "selected" : ""}>${escapeHtml(t.brand)}${t.type ? " " + escapeHtml(t.type) : ""}${t.weight ? " " + escapeHtml(t.weight) : ""} ${escapeHtml(t.code)} — ${escapeHtml(t.name)}</option>`).join("");
}

async function renderDesigns(app, orgId, openDesignId){
  adminSetHash("designs/" + encodeURIComponent(orgId) + (openDesignId ? "/" + openDesignId : ""));
  const orgName = ((window._adminOrgRegistry || []).find(o => o.orgId === orgId) || {}).name || orgId;
  document.title = adminTitle_("Designs — " + orgName);
  adminNoteShop_(orgId);
  app.innerHTML = `
    ${adminPageHead_("Designs", { crumbs: adminCan_("manager") ? [{label:"Manage catalog", hash:"catalog"}, {label: orgName}, {label:"Designs"}] : [{label:"Catalog"}, {label: orgName}, {label:"Designs"}] })}
    <h2 class="shop-page-h">Designs — ${escapeHtml(orgName)}</h2>
    <div class="admin-panel dsg-layout${openDesignId ? " dsg-has-open" : ""}" style="--org-accent:var(--accent);max-width:1000px;margin:8px auto 60px;">
      <div class="dsg-list-col">
        <button type="button" class="admin-btn" id="dsgNewBtn" style="width:100%;margin-bottom:10px;">+ New design</button>
        <div id="dsgList" style="color:#888;font-size:13px;">Loading&hellip;</div>
      </div>
      <div class="dsg-detail-col">
        ${openDesignId ? `<button type="button" class="admin-btn dsg-back" data-org="${escapeHtml(orgId)}" onclick="location.hash='#designs/'+encodeURIComponent(this.dataset.org)">&larr; All designs</button>` : ""}
        <div id="dsgDetail" style="color:#888;font-size:13px;">${openDesignId ? "Loading&hellip;" : "Pick a design from the list, or create a new one."}</div>
      </div>
    </div>`;
  let designs = [], hoops = [], threads = [];
  // See loadProductDesignSection's comment above — adminKey must be resolved before firing
  // these three admin-gated calls in parallel, or each pops its own passphrase overlay.
  if (!adminKey) adminKey = (await adminLogin()) || "";
  try {
    const [d, h, t] = await Promise.all([designApi_({ action: "listDesigns", org: orgId }), hoopApi_({ action: "listHoops" }), threadApi_({ action: "listThreads" })]);
    designs = d.designs || []; hoops = h.hoops || []; threads = t.threads || [];
  } catch (e) { document.getElementById("dsgList").innerHTML = `<div style="color:#b03a2e;">${escapeHtml(e.message)}</div>`; return; }
  window._dsgCtx = { orgId, orgName, designs, hoops, threads, issues: null };
  window._dsgCtx.refreshIssues = () => fetchCatalogIssues_(orgId).then(issues => {
    if (!issues || !window._dsgCtx) return;
    window._dsgCtx.issues = issues; drawList(); showDesignIssues_();
  });
  if (!openDesignId) window._dsgCtx.refreshIssues(); // with a design open, its detail load refreshes them
  const listEl = document.getElementById("dsgList");
  // The shop's own designs, then the GLOBAL ones every shop can use (migrations/0033).
  const drawList = () => {
    const btn = (d) => `
      <button type="button" data-did="${d.id}" data-org="${escapeHtml(orgId)}" onclick="location.hash='#designs/'+encodeURIComponent(this.dataset.org)+'/'+this.dataset.did"
        style="display:block;width:100%;text-align:left;padding:8px 10px;margin-bottom:4px;border:1px solid #ddd;border-radius:5px;background:${d.id === openDesignId ? "#eef3ee" : "#fff"};cursor:pointer;">${escapeHtml(d.name)}</button>`;
    const own = designs.filter(d => !d.isGlobal), global = designs.filter(d => d.isGlobal);
    listEl.innerHTML = (own.length ? own.map(btn).join("") : `<div style="color:#888;">No designs for this shop yet.</div>`) +
      (global.length ? `<div class="dsg-global-head" style="font-size:11px;font-weight:700;color:#666;text-transform:uppercase;letter-spacing:.05em;margin:14px 0 6px;">🌐 Global — every shop</div>${global.map(btn).join("")}` : "");
    markDesignIssues_();
  };
  // ⚠ on each design with something missing (getCatalogIssues; global designs too).
  const markDesignIssues_ = () => {
    const issues = window._dsgCtx && window._dsgCtx.issues;
    if (!issues) return;
    const mine = (issues.orgs[orgId] || {}).designs || {};
    listEl.querySelectorAll("button[data-did]").forEach(b => {
      const list = mine[b.dataset.did] || issues.globalDesigns[b.dataset.did];
      const old = b.querySelector(".cat-issue-badge"); if (old) old.remove();
    if (list) b.insertAdjacentHTML("beforeend", issueBadge_(list.length, [list], list.map(x => x.text).join("; ")));
    });
  };
  drawList();
  document.getElementById("dsgNewBtn").onclick = () => showDesignFormModal_(orgId, null, hoops, async (id) => {
    const r = await designApi_({ action: "listDesigns", org: orgId }); window._dsgCtx.designs = designs = r.designs || []; drawList();
    location.hash = "#designs/" + encodeURIComponent(orgId) + "/" + id;
  });
  if (openDesignId) await loadDesignDetail_(openDesignId);
}

// The open design's missing pieces, at the top of its detail.
function showDesignIssues_(){
  const el = document.getElementById("dsgDetailIssues"), ctx = window._dsgCtx;
  if (!el || !ctx || !ctx.issues) return;
  const id = el.dataset.did;
  const list = ((ctx.issues.orgs[ctx.orgId] || {}).designs || {})[id] || ctx.issues.globalDesigns[id];
  el.innerHTML = list ? `<div style="border:1px solid ${issueColor_(list)};border-radius:6px;padding:6px 10px;margin:8px 0;"><b style="color:${issueColor_(list)};font-size:13px;">⚠ Needs attention</b>${issueListHtml_(list)}</div>` : "";
}
async function loadDesignDetail_(designId){
  const el = document.getElementById("dsgDetail");
  if (!el) return;
  el.innerHTML = "Loading&hellip;";
  let data;
  try { data = await designApi_({ action: "getDesign", id: designId }); }
  catch (e) { el.innerHTML = `<div style="color:#b03a2e;">${escapeHtml(e.message)}</div>`; return; }
  const { orgId, orgName, hoops, threads } = window._dsgCtx;
  const design = data.design, versions = data.versions || [];
  // Keep the page's design list in step with what was just loaded — the Edit button opens the form
  // from that list, so after a save (which reloads this detail) it would otherwise show the old
  // hoops/name until the page was re-entered. The list button's name follows too.
  const ctxDesigns = window._dsgCtx.designs, at = ctxDesigns.findIndex(d => d.id === design.id);
  if (at >= 0) ctxDesigns[at] = design; else ctxDesigns.push(design);
  const listBtn = document.querySelector(`#dsgList button[data-did="${design.id}"]`);
  if (listBtn) listBtn.textContent = design.name;
  // Fresh ⚠ markers after the load (a save or upload may have fixed — or caused — something).
  setTimeout(() => window._dsgCtx && window._dsgCtx.refreshIssues && window._dsgCtx.refreshIssues(), 0);
  window._dsgVersions = versions; // for editVersionColors_ to look up the clicked version
  const hoopList_ = (ids) => (ids || []).map(id => (hoops.find(h => h.id === id) || {}).name).filter(Boolean).join(" or ") || "—";
  const threadName_ = (id) => { const t = threads.find(x => x.id === id); return t ? `${t.brand}${t.type ? " " + t.type : ""}${t.weight ? " " + t.weight : ""} ${t.code} — ${t.name}` : "(unknown thread)"; };
  const threadSwatch_ = (id) => { const t = threads.find(x => x.id === id); return t && t.colorHex ? `<span style="display:inline-block;width:12px;height:12px;border-radius:2px;background:#${escapeHtml(t.colorHex)};border:1px solid #999;vertical-align:middle;margin-right:5px;"></span>` : ""; };
  el.innerHTML = `
    <div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:8px;">
      <div>
        <h2 style="margin:0 0 4px;">${escapeHtml(design.name)}${design.isGlobal ? ` <span title="Every shop can use this design" style="font-size:11px;font-weight:700;padding:2px 7px;border-radius:999px;background:#e0e7ff;color:#3730a3;vertical-align:middle;">🌐 GLOBAL</span>` : ""}</h2>
        <div id="dsgDetailIssues" data-did="${design.id}"></div>
        ${design.isGlobal ? `<div style="font-size:12px;color:#666;margin-bottom:4px;">Shared by every shop${design.orgId !== orgId ? ` · home shop ${escapeHtml(orgNameOf_(design.orgId))}` : ""} — changes here apply everywhere it's used.</div>` : ""}
        <div style="font-size:13px;color:#666;">Stabilizer: ${escapeHtml(design.stabilizer || "—")} &nbsp;·&nbsp; Hoops: ${escapeHtml(hoopList_(requiredHoopIds_(design)))}</div>
        ${(design.personalizationHoopIds || []).length ? `<div style="font-size:13px;color:#666;">With a typed-in name: ${escapeHtml(hoopList_(design.personalizationHoopIds))}</div>` : ""}
        ${design.notes ? `<div style="font-size:13px;color:#666;margin-top:4px;">${escapeHtml(design.notes)}</div>` : ""}
      </div>
      <div style="display:flex;gap:6px;">
        <button type="button" class="admin-btn" data-org="${escapeHtml(orgId)}" onclick="showDesignFormModal_(this.dataset.org, window._dsgCtx.designs.find(d=>d.id===${Number(design.id)}), window._dsgCtx.hoops, () => loadDesignDetail_(${Number(design.id)}))">Edit</button>
        <button type="button" class="admin-btn admin-btn-danger" data-org="${escapeHtml(orgId)}" onclick="deleteDesign_(${Number(design.id)}, this.dataset.org)">Delete</button>
      </div>
    </div>
    ${versions.length && canPreviewStitch_(versions[0].machineFileExt) ? `
    <div style="margin-top:14px;">
      <canvas id="dsgDetailCanvas" width="320" height="320" style="width:320px;max-width:100%;height:320px;background:#faf9f6;border:1px solid #ddd;border-radius:6px;display:block;"></canvas>
      <div id="dsgDetailCanvasInfo" style="font-size:12px;color:#888;margin-top:4px;">Rendering current version&hellip;</div>
    </div>` : ""}
    <div style="margin-top:18px;">
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;">
        <h3 style="margin:0;">Versions</h3>
        <button type="button" class="admin-btn" onclick="showDesignVersionUploadModal_(${design.id}, () => loadDesignDetail_(${design.id}))">+ Upload version</button>
      </div>
      ${versions.length ? `<table class="stack-mobile dsg-versions" style="width:100%;border-collapse:collapse;font-size:13px;margin-top:8px;">
        <thead><tr style="text-align:left;background:#f3f4f6;"><th style="padding:5px 6px;">Uploaded</th><th style="padding:5px 6px;">Design file</th><th style="padding:5px 6px;">Machine file</th><th style="padding:5px 6px;">Threads</th><th style="padding:5px 6px;">Stitches</th><th style="padding:5px 6px;">Notes</th></tr></thead>
        <tbody>${versions.map((v, i) => `<tr style="border-bottom:1px solid #eee;${i === 0 ? "font-weight:600;" : ""}">
          <td data-label="Uploaded" style="padding:5px 6px;">${escapeHtml((v.uploadedAt || "").slice(0, 10))}${i === 0 ? ' <span style="font-weight:400;color:#2c6b2f;">(current)</span>' : ""}</td>
          <td data-label="Design file" style="padding:5px 6px;">${escapeHtml(v.designFileName)} <button type="button" class="admin-btn" style="padding:2px 8px;font-size:11px;" onclick="downloadDesignFile_('${v.designFileKey.replace(/'/g, "\\'")}')">Download</button></td>
          <td data-label="Machine file" style="padding:5px 6px;">${escapeHtml(v.machineFileName)} <button type="button" class="admin-btn" style="padding:2px 8px;font-size:11px;" onclick="downloadDesignFile_('${v.machineFileKey.replace(/'/g, "\\'")}')">Download</button></td>
          <td data-label="Threads" style="padding:5px 6px;">${v.threadColors.length ? v.threadColors.map(tc => threadSwatch_(tc.threadId)).join("") + v.threadColors.length + " needle" + (v.threadColors.length === 1 ? "" : "s") : "—"} <button type="button" class="admin-btn" style="padding:2px 8px;font-size:11px;" onclick="editVersionColors_(${v.id})">Edit colors</button></td>
          <td data-label="Stitches" style="padding:5px 6px;">${v.stitchCount != null ? Number(v.stitchCount).toLocaleString() : '<span style="color:#888;font-weight:400;">not known</span>'} <button type="button" class="admin-btn" style="padding:2px 8px;font-size:11px;" data-vid="${v.id}" data-did="${design.id}" data-cur="${v.stitchCount == null ? "" : v.stitchCount}" onclick="setVersionStitches_(this)">Set</button></td>
          <td data-label="Notes" style="padding:5px 6px;color:#666;">${escapeHtml(v.notes)}</td>
        </tr>`).join("")}</tbody></table>
      ${versions[0].threadColors.length ? `<div style="margin-top:10px;font-size:13px;"><b>Current thread map</b> (needle order):<br>
        ${versions[0].threadColors.map((tc, i) => `${i + 1}. ${threadSwatch_(tc.threadId)}${escapeHtml(threadName_(tc.threadId))}`).join("<br>")}
      </div>` : ""}` : `<div style="color:#888;margin-top:8px;">No versions uploaded yet.</div>`}
    </div>`;
  // Render the current version's design onto the detail canvas, coloured by its thread map.
  if (versions.length && canPreviewStitch_(versions[0].machineFileExt)) {
    const threadsById = {}; threads.forEach(t => { threadsById[t.id] = t; });
    const cur = versions[0];
    const rows = (cur.threadColors || []).slice().sort((a, b) => a.needle - b.needle).map(tc => ({ threadId: tc.threadId }));
    (async () => {
      const canvas = document.getElementById("dsgDetailCanvas"), info = document.getElementById("dsgDetailCanvasInfo");
      if (!canvas) return;
      try {
        const parsed = parseStitchFile_(await fetchDesignFileBytes_(cur.machineFileKey), cur.machineFileExt);
        renderDstPreview_(canvas, parsed, dstColorForNeedle_(rows, threadsById));
        if (info) info.textContent = `${parsed.needleStops} needle stop${parsed.needleStops === 1 ? "" : "s"} · ${parsed.stitchCount.toLocaleString()} stitches · current version (${(cur.uploadedAt || "").slice(0, 10)})`;
        // A version uploaded before stitch counts were kept (migrations/0071) gets its count from this read.
        if (cur.stitchCount == null && parsed.stitchCount) designApi_({ action: "setDesignVersionStitches", versionId: cur.id, stitchCount: parsed.stitchCount }).catch(() => {});
      } catch (e) { if (info) info.textContent = "Couldn't render preview: " + e.message; }
    })();
  }
}

// Types a version's stitch count by hand — for a machine-file format this page can't read (migrations/0071). Every run
// of the design adds it to its machine's stitch counter.
async function setVersionStitches_(btn){
  const v = prompt("Stitches in this version's machine file:", btn.dataset.cur || "");
  if (v == null) return;
  try {
    await designApi_({ action: "setDesignVersionStitches", versionId: Number(btn.dataset.vid), stitchCount: v.replace(/[,\s]/g, "") });
    showToast("Stitch count saved."); loadDesignDetail_(Number(btn.dataset.did));
  } catch (e) { showToast(e.message, true); }
}

async function deleteDesign_(id, orgId){
  if (!await askConfirm_("Delete this design? This only works while no product is still linked to it.")) return;
  try {
    await designApi_({ action: "deleteDesign", id });
    showToast("Design deleted.");
    // Open the design that took its place in the list (the next one, else the one before) instead of an empty page.
    const list = ((window._dsgCtx && window._dsgCtx.designs) || []).filter(d => !d.isGlobal || d.orgId === orgId);
    const i = list.findIndex(d => d.id === id), next = list[i + 1] || list[i - 1];
    location.hash = "#designs/" + encodeURIComponent(orgId) + (next && next.id !== id ? "/" + next.id : "");
  } catch (e) { showToast(e.message, true); }
}

function orgNameOf_(orgId){
  const o = (window._adminOrgRegistry || []).find(x => x.orgId === orgId) || (adminOrgs || []).find(x => x.orgId === orgId);
  return (o && o.name) || orgId;
}
function showDesignFormModal_(orgId, design, hoops, onDone){
  const isNew = !design;
  const f = design || { name: "", notes: "", stabilizer: "", hoopId: "" };
  const inp = "font-size:13px;padding:6px 8px;border:1px solid #ccc;border-radius:4px;width:100%;box-sizing:border-box;";
  // migrations/0032: a design can run in several hoops — on its own, and (a separate list) with a
  // typed-in name stitched in the same hooping.
  const own = new Set(requiredHoopIds_(f)), pers = new Set((f.personalizationHoopIds || []).map(Number));
  const hoopBoxes = (cls, chosen) => hoops.length ? hoops.map(h => `<label style="display:flex;align-items:center;gap:6px;font-size:13px;font-weight:400;margin:2px 0;">
      <input type="checkbox" class="${cls}" value="${h.id}" ${chosen.has(h.id) ? "checked" : ""}> ${escapeHtml(h.name)}${h.isCapFrame ? " (cap frame)" : ""}</label>`).join("")
    : `<div style="color:#888;font-size:12px;">No hoops yet — add them under Tools → Hoops.</div>`;
  const { ov, close } = inventoryModal_(isNew ? "New design" : "Edit design", `
    <label style="font-size:12px;font-weight:600;display:block;margin-bottom:10px;">Name<br><input id="dsgfName" value="${escapeHtml(f.name)}" style="${inp}"></label>
    <label style="font-size:12px;font-weight:600;display:block;margin-bottom:10px;">Stabilizer<br><input id="dsgfStabilizer" value="${escapeHtml(f.stabilizer)}" placeholder="e.g. medium-weight cutaway" style="${inp}"></label>
    <div style="display:flex;gap:16px;flex-wrap:wrap;margin-bottom:10px;">
      <div style="flex:1;min-width:170px;"><div style="font-size:12px;font-weight:600;">Hoops — design on its own</div>
        <div style="font-size:11px;color:#888;margin-bottom:4px;">Any of these works; Run Order picks the cheapest change.</div>${hoopBoxes("dsgfHoopOwn", own)}</div>
      <div style="flex:1;min-width:170px;"><div style="font-size:12px;font-weight:600;">Hoops — with a typed-in name</div>
        <div style="font-size:11px;color:#888;margin-bottom:4px;">When the name is stitched in the same hooping (e.g. logo + name in a 7.7" x 12.5"). Empty = same as on its own.</div>${hoopBoxes("dsgfHoopPers", pers)}</div>
    </div>
    <label style="font-size:12px;font-weight:600;display:block;margin-bottom:10px;">Notes<br><textarea id="dsgfNotes" style="${inp}min-height:60px;">${escapeHtml(f.notes)}</textarea></label>
    <label style="display:flex;align-items:flex-start;gap:8px;font-size:13px;margin-bottom:10px;">
      <input type="checkbox" id="dsgfGlobal" ${f.isGlobal ? "checked" : ""} style="margin-top:2px;">
      <span><b>Global</b> — every shop can use this design (e.g. a set of closure designs every shop shares). One design, one set of files: an edit here updates it for every shop.${f.isGlobal && f.orgId && f.orgId !== orgId ? `<br><span style="color:#888;">Home shop: ${escapeHtml(orgNameOf_(f.orgId))}</span>` : ""}</span>
    </label>
    <div id="dsgfErr" style="color:#b03a2e;font-size:13px;min-height:18px;"></div>
    <div style="display:flex;gap:8px;justify-content:flex-end;">
      <button type="button" id="dsgfCancel" style="padding:6px 14px;border:1px solid #ccc;border-radius:5px;background:#fff;cursor:pointer;">Cancel</button>
      <button type="button" id="dsgfSave" class="admin-btn">${isNew ? "Create design" : "Save changes"}</button>
    </div>`, 440);
  ov.querySelector("#dsgfCancel").onclick = close;
  ov.querySelector("#dsgfSave").onclick = async () => {
    const err = ov.querySelector("#dsgfErr");
    const payload = { id: f.id, name: ov.querySelector("#dsgfName").value.trim(), stabilizer: ov.querySelector("#dsgfStabilizer").value.trim(),
      hoopIds: [...ov.querySelectorAll(".dsgfHoopOwn:checked")].map(c => Number(c.value)),
      personalizationHoopIds: [...ov.querySelectorAll(".dsgfHoopPers:checked")].map(c => Number(c.value)),
      notes: ov.querySelector("#dsgfNotes").value.trim(), isGlobal: ov.querySelector("#dsgfGlobal").checked };
    if (f.isGlobal && !payload.isGlobal && !await askConfirm_("Make this design shop-only? Other shops won't be able to pick it any more.")) return;
    if (!payload.name) { err.textContent = "Name is required."; return; }
    try {
      const r = await designApi_({ action: "saveDesign", org: orgId, design: payload });
      close(); showToast(isNew ? "Design created." : "Design updated."); onDone && onDone(r.id);
    } catch (e) { err.textContent = e.message; }
  };
}

// A signed, short-lived link to a file in the private DESIGNS bucket (/api/design). Also how a
// customer's own design is shown as a picture (an <img> loads it straight away, inside the minute).
async function signedDesignUrl_(key){
  const r = await fetch("/api/design", { method: "POST", headers: { "Content-Type": "application/json", "X-Admin-Key": adminKey || "" }, body: JSON.stringify({ key }) });
  const d = await r.json().catch(() => ({ status: "error", message: "Server error (" + r.status + ")" }));
  if (!r.ok || d.status === "error") throw new Error((d && d.message) || "Could not open file");
  return d.url;
}
async function downloadDesignFile_(key){
  const w = window.open("about:blank", "_blank");
  try {
    const url = await signedDesignUrl_(key);
    if (w) { w.opener = null; w.location.href = url; } else location.href = url;
  } catch (e) { if (w) w.close(); showToast(e.message, true); }
}
// Fills every <img data-design-key> under `root` with its signed link (the customer's own design).
function fillDesignThumbs_(root){
  if (!root) return;
  root.querySelectorAll("img[data-design-key]").forEach(async (img) => {
    const key = img.dataset.designKey; img.removeAttribute("data-design-key");
    try { img.src = await signedDesignUrl_(key); } catch (e) { img.alt = "Couldn't load the picture"; }
  });
}
const isImageExt_ = (ext) => ["png", "jpg", "jpeg", "webp", "gif"].includes(String(ext || "").toLowerCase());

// Helper: a function blockIndex -> "#hex" for the preview, using the picked thread's colour,
// else a distinct fallback so unmapped blocks are still visible as separate areas.
function dstColorForNeedle_(rows, threadsById){
  return (i) => {
    const tid = rows[i] && rows[i].threadId;
    const t = tid && threadsById[tid];
    if (t && /^[0-9a-fA-F]{6}$/.test(t.colorHex || "")) return "#" + t.colorHex;
    return DST_PREVIEW_PALETTE[i % DST_PREVIEW_PALETTE.length];
  };
}
function drawPreviewPlaceholder_(canvas, text){
  const ctx = canvas && canvas.getContext && canvas.getContext("2d");
  if (!ctx) return;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = "#aaa"; ctx.font = "13px sans-serif"; ctx.textAlign = "center";
  ctx.fillText(text, canvas.width / 2, canvas.height / 2);
}

// Also uploads an ORDER-SPECIFIC design (migrations/0032) when opts.itemId is given: the digitized
// typed-in name for one line item (alone, or with the main design) — same files + thread map, but
// the native design file is optional, it's stored under the line item, and opts.threads supplies
// the thread catalog (the Designs screen's context isn't loaded elsewhere).
function showDesignVersionUploadModal_(designId, onDone, opts){
  opts = opts || {};
  const itemId = opts.itemId || null;
  const threads = opts.threads || (window._dsgCtx && window._dsgCtx.threads) || [];
  const threadsById = {}; threads.forEach(t => { threadsById[t.id] = t; });
  const threadOptions = designThreadRowsHtml_(threads);
  let rows = [{ threadId: "" }];
  let parsed = null; // parseDst_ result once a DST machine file is chosen
  const { ov, close } = inventoryModal_(escapeHtml(opts.title || (itemId ? "Upload order design" : "Upload design version")), `
    <div style="display:flex;gap:16px;flex-wrap:wrap;align-items:flex-start;">
      <div style="flex:0 0 340px;max-width:100%;">
        <canvas id="dsgvCanvas" width="340" height="340" style="width:340px;max-width:100%;height:340px;background:#faf9f6;border:1px solid #ddd;border-radius:6px;display:block;"></canvas>
        <div id="dsgvStops" style="font-size:12px;margin:6px 0 10px;min-height:16px;"></div>
        <label style="font-size:12px;font-weight:600;display:block;margin-bottom:10px;">Design file — the editable project file from your design software (any format, e.g. .emb)${itemId ? " — optional" : ""}<br>
          <input type="file" id="dsgvDesignFile" style="font-size:13px;"></label>
        <label style="font-size:12px;font-weight:600;display:block;margin-bottom:10px;">Machine file — the stitch file the machine runs (any format, e.g. .dst, .dsb, .pes)<br>
          <input type="file" id="dsgvMachineFile" style="font-size:13px;"></label>
        <label style="font-size:12px;font-weight:600;display:block;margin-bottom:6px;">Notes<br><textarea id="dsgvNotes" style="font-size:13px;padding:6px 8px;border:1px solid #ccc;border-radius:4px;width:100%;box-sizing:border-box;min-height:50px;"></textarea></label>
      </div>
      <div style="flex:1;min-width:230px;">
        <div style="font-size:12px;font-weight:600;margin-bottom:4px;">Thread color map (needle order)</div>
        <div style="font-size:11px;color:#888;margin-bottom:8px;">Pick a thread per needle stop — the preview recolors live.</div>
        <div id="dsgvThreadRows" style="max-height:320px;overflow:auto;"></div>
        <button type="button" id="dsgvAddThread" class="admin-btn" style="font-size:11px;padding:3px 8px;margin-top:6px;">+ Add thread</button>
      </div>
    </div>
    <div id="dsgvErr" style="color:#b03a2e;font-size:13px;min-height:18px;margin-top:8px;"></div>
    <div style="display:flex;gap:8px;justify-content:flex-end;">
      <button type="button" id="dsgvCancel" style="padding:6px 14px;border:1px solid #ccc;border-radius:5px;background:#fff;cursor:pointer;">Cancel</button>
      <button type="button" id="dsgvSave" class="admin-btn">Upload</button>
    </div>`, 820);
  const canvas = ov.querySelector("#dsgvCanvas");
  const renderPreview = () => { if (parsed) renderDstPreview_(canvas, parsed, dstColorForNeedle_(rows, threadsById)); };
  drawPreviewPlaceholder_(canvas, "Select a .DST or .DSB machine file to preview");
  let neededStops = 0, stopsSummary = "";
  const drawStops = () => {
    const el = ov.querySelector("#dsgvStops");
    if (!neededStops) { el.innerHTML = ""; return; }
    const filled = rows.filter(r => r.threadId).length;
    const ok = filled === neededStops;
    el.innerHTML = stopsSummary + `<span style="color:${ok ? "#15803d" : "#b45309"};">${ok ? "✓" : "⚠"} ${filled} of ${neededStops} needle definition${neededStops === 1 ? "" : "s"} picked</span>`;
  };
  const drawRows = () => {
    drawStops();
    ov.querySelector("#dsgvThreadRows").innerHTML = rows.map((r, i) => `
      <div style="display:flex;gap:6px;align-items:center;margin-bottom:6px;">
        <span style="display:inline-block;width:12px;height:12px;border-radius:2px;border:1px solid #999;background:${dstColorForNeedle_(rows, threadsById)(i)};"></span>
        <span style="font-size:12px;color:#888;width:20px;">${i + 1}.</span>
        <select data-i="${i}" class="dsgvThreadSelect" style="flex:1;font-size:13px;padding:4px 6px;">${threadOptions(r.threadId)}</select>
        <button type="button" data-i="${i}" class="dsgvRemoveRow" style="font-size:11px;padding:2px 8px;">✕</button>
      </div>`).join("");
    ov.querySelectorAll(".dsgvThreadSelect").forEach(sel => sel.onchange = () => { rows[Number(sel.dataset.i)].threadId = Number(sel.value) || ""; drawRows(); renderPreview(); });
    ov.querySelectorAll(".dsgvRemoveRow").forEach(btn => btn.onclick = () => { rows.splice(Number(btn.dataset.i), 1); drawRows(); renderPreview(); });
  };
  drawRows();
  // Reading the DST sizes the thread map to its needle stops AND renders the preview.
  ov.querySelector("#dsgvMachineFile").onchange = async (e) => {
    const file = e.target.files[0];
    const el = ov.querySelector("#dsgvStops");
    neededStops = 0; stopsSummary = ""; parsed = null; el.innerHTML = "";
    if (!file) { drawPreviewPlaceholder_(canvas, "Select a .DST or .DSB machine file to preview"); return; }
    if (!canPreviewStitch_(file.name)) { drawPreviewPlaceholder_(canvas, "Preview available for .DST and .DSB files only"); drawRows(); return; }
    try {
      parsed = parseStitchFile_(await file.arrayBuffer(), file.name);
      neededStops = parsed.needleStops;
      // A .dsb names the needle each color runs on (the digitizer's setup) — shown for reference.
      const needleNote = (parsed.needles || []).some(n => n != null) ? ` · needles ${parsed.needles.map(n => n == null ? "?" : n).join(", ")}` : "";
      stopsSummary = `<div style="color:#111;margin-bottom:2px;"><strong>${neededStops} needle stop${neededStops === 1 ? "" : "s"}</strong> · ${parsed.colorChanges} color change${parsed.colorChanges === 1 ? "" : "s"} · ${parsed.stitchCount.toLocaleString()} stitches${needleNote}</div>`;
      while (rows.length < neededStops) rows.push({ threadId: "" });
      while (rows.length > neededStops && !rows[rows.length - 1].threadId) rows.pop();
      drawRows(); renderPreview();
    } catch (err) { const kind = stitchExt_(file.name).toUpperCase(); drawPreviewPlaceholder_(canvas, "Couldn't read this " + kind); el.innerHTML = `<span style="color:#b03a2e;">Couldn't read the ${kind} file: ${escapeHtml(err.message)}</span>`; }
  };
  ov.querySelector("#dsgvAddThread").onclick = () => { rows.push({ threadId: "" }); drawRows(); renderPreview(); };
  ov.querySelector("#dsgvCancel").onclick = close;
  const uploadFile_ = async (file, role) => {
    const ext = (file.name.split(".").pop() || "").toLowerCase();
    const problem = embroideryFileProblem_(file.name, role);
    if (problem) throw new Error(problem);
    const target = itemId ? `itemId=${itemId}` : `designId=${designId}`;
    const up = await fetch(`/api/design?${target}&role=${role}&ext=${encodeURIComponent(ext)}&name=${encodeURIComponent(file.name)}`,
      { method: "POST", headers: { "X-Admin-Key": adminKey || "", "Content-Type": "application/octet-stream" }, body: file });
    const ud = await up.json().catch(() => ({ status: "error", message: "Server error (" + up.status + ")" }));
    if (!up.ok || ud.status === "error") throw new Error((ud && ud.message) || "Upload failed");
    return ud;
  };
  ov.querySelector("#dsgvSave").onclick = async () => {
    const err = ov.querySelector("#dsgvErr");
    const designFile = ov.querySelector("#dsgvDesignFile").files[0];
    const machineFile = ov.querySelector("#dsgvMachineFile").files[0];
    if (!designFile && !itemId) { err.textContent = "Choose a design file."; return; }
    if (!machineFile) { err.textContent = "Choose a machine file."; return; }
    const threadColors = rows.filter(r => r.threadId).map((r, i) => ({ needle: i + 1, threadId: r.threadId }));
    try {
      const [designUp, machineUp] = await Promise.all([designFile ? uploadFile_(designFile, "design") : Promise.resolve(null), uploadFile_(machineFile, "machine")]);
      const files = { designFileKey: designUp ? designUp.key : "", designFileName: designUp ? designUp.name : "", designFileExt: designUp ? designUp.ext : "",
        machineFileKey: machineUp.key, machineFileName: machineUp.name, machineFileExt: machineUp.ext,
        threadColors, notes: ov.querySelector("#dsgvNotes").value.trim(),
        // Read from the file above (DST / DSB); a machine's stitch counter adds it for every run (migrations/0071).
        stitchCount: parsed && parsed.stitchCount ? parsed.stitchCount : null };
      if (itemId) await designApi_(Object.assign({ action: "saveOrderItemDesign", itemId, location: opts.location || "" }, files));
      else await designApi_(Object.assign({ action: "saveDesignVersion", designId }, files));
      close(); showToast(itemId ? "Order design uploaded." : "Version uploaded."); onDone && onDone();
    } catch (e) { err.textContent = e.message; }
  };
}

// Edit ONLY the thread colours of an existing version — the files and everything else stay put.
// Renders the version's machine file (fetched via signed link) so recolouring is visual and live;
// the needle rows are fixed (no add/remove), pre-filled from the version's saved map.
function showEditVersionColorsModal_(version, onDone){
  const { threads } = window._dsgCtx;
  const threadsById = {}; threads.forEach(t => { threadsById[t.id] = t; });
  const threadOptions = designThreadRowsHtml_(threads);
  // Start from the saved map (needle order); may be grown to the DST's stop count once parsed.
  let rows = (version.threadColors || []).slice().sort((a, b) => a.needle - b.needle).map(tc => ({ threadId: tc.threadId }));
  if (!rows.length) rows = [{ threadId: "" }];
  let parsed = null;
  const { ov, close } = inventoryModal_("Edit thread colors — " + escapeHtml((version.uploadedAt || "").slice(0, 10)), `
    <div style="display:flex;gap:16px;flex-wrap:wrap;align-items:flex-start;">
      <div style="flex:0 0 340px;max-width:100%;">
        <canvas id="dsgcCanvas" width="340" height="340" style="width:340px;max-width:100%;height:340px;background:#faf9f6;border:1px solid #ddd;border-radius:6px;display:block;"></canvas>
        <div id="dsgcInfo" style="font-size:12px;color:#666;margin-top:6px;min-height:16px;">Loading preview…</div>
        <div style="font-size:12px;color:#888;margin-top:8px;">${escapeHtml(version.machineFileName || "")}</div>
      </div>
      <div style="flex:1;min-width:230px;">
        <div style="font-size:12px;font-weight:600;margin-bottom:4px;">Thread color map (needle order)</div>
        <div style="font-size:11px;color:#888;margin-bottom:8px;">Only the colors change — the design and machine files are untouched. The preview recolors live.</div>
        <div id="dsgcThreadRows" style="max-height:340px;overflow:auto;"></div>
      </div>
    </div>
    <div id="dsgcErr" style="color:#b03a2e;font-size:13px;min-height:18px;margin-top:8px;"></div>
    <div style="display:flex;gap:8px;justify-content:flex-end;">
      <button type="button" id="dsgcCancel" style="padding:6px 14px;border:1px solid #ccc;border-radius:5px;background:#fff;cursor:pointer;">Cancel</button>
      <button type="button" id="dsgcSave" class="admin-btn">Save colors</button>
    </div>`, 820);
  const canvas = ov.querySelector("#dsgcCanvas");
  const renderPreview = () => { if (parsed) renderDstPreview_(canvas, parsed, dstColorForNeedle_(rows, threadsById)); };
  const drawRows = () => {
    ov.querySelector("#dsgcThreadRows").innerHTML = rows.map((r, i) => `
      <div style="display:flex;gap:6px;align-items:center;margin-bottom:6px;">
        <span style="display:inline-block;width:12px;height:12px;border-radius:2px;border:1px solid #999;background:${dstColorForNeedle_(rows, threadsById)(i)};"></span>
        <span style="font-size:12px;color:#888;width:20px;">${i + 1}.</span>
        <select data-i="${i}" class="dsgcThreadSelect" style="flex:1;font-size:13px;padding:4px 6px;">${threadOptions(r.threadId)}</select>
      </div>`).join("");
    ov.querySelectorAll(".dsgcThreadSelect").forEach(sel => sel.onchange = () => { rows[Number(sel.dataset.i)].threadId = Number(sel.value) || ""; drawRows(); renderPreview(); });
  };
  drawPreviewPlaceholder_(canvas, "Loading preview…");
  drawRows();
  ov.querySelector("#dsgcCancel").onclick = close;
  // Fetch + parse the machine file for the live preview (best-effort; editing still works without it).
  (async () => {
    const info = ov.querySelector("#dsgcInfo");
    if (!canPreviewStitch_(version.machineFileExt)) { drawPreviewPlaceholder_(canvas, "Preview available for .DST and .DSB files only"); info.textContent = ""; return; }
    try {
      parsed = parseStitchFile_(await fetchDesignFileBytes_(version.machineFileKey), version.machineFileExt);
      info.textContent = `${parsed.needleStops} needle stops · ${parsed.stitchCount.toLocaleString()} stitches`;
      // Grow (never shrink below the saved map) to the DST's stop count so every block is editable.
      while (rows.length < parsed.needleStops) rows.push({ threadId: "" });
      drawRows(); renderPreview();
    } catch (e) { drawPreviewPlaceholder_(canvas, "Couldn't load preview"); info.textContent = e.message; }
  })();
  ov.querySelector("#dsgcSave").onclick = async () => {
    const err = ov.querySelector("#dsgcErr");
    const threadColors = rows.map((r, i) => ({ needle: i + 1, threadId: r.threadId })).filter(tc => tc.threadId);
    try {
      await designApi_({ action: "updateDesignVersionColors", versionId: version.id, threadColors });
      close(); showToast("Thread colors updated."); onDone && onDone();
    } catch (e) { err.textContent = e.message; }
  };
}
window.editVersionColors_ = (versionId) => {
  const v = (window._dsgVersions || []).find(x => x.id === versionId);
  if (v) showEditVersionColorsModal_(v, () => loadDesignDetail_(v.designId));
};

// Per-line-item customization uploads (order_item_files) — images or embroidery files,
// reachable from the admin Edit-items modal's "Files" button on a saved, personalized row.
// `slots` = the order designs the line takes: [{location, label}] — one per location carrying the
// customer's own stitched design (migrations/0055), and/or '' for the line's one design (a typed-in
// name). Default: just the one.
async function showOrderItemFilesModal_(itemId, itemLabel, onCountChange, slots){
  slots = (slots && slots.length) ? slots : [{ location: "", label: "" }];
  const customSlots = slots.filter(x => x.location).length;
  const { ov, close } = inventoryModal_(`Files — ${escapeHtml(itemLabel)}`, `
    <div id="oifDesignWrap"${adminFeatureOn_("production") ? "" : ' style="display:none;"'}>
    <div style="font-size:12px;font-weight:700;margin-bottom:4px;">Order design <span style="font-weight:400;color:#888;">(the digitized design — what the machine runs for this line)</span></div>
    <div id="oifDesign" style="font-size:13px;color:#888;margin-bottom:14px;padding-bottom:12px;border-bottom:1px solid #eee;">Loading&hellip;</div>
    </div>
    <div style="font-size:12px;font-weight:700;margin-bottom:4px;">Other files</div>
    <div id="oifBody" style="font-size:13px;color:#888;">Loading&hellip;</div>
    <label style="font-size:12px;font-weight:600;display:block;margin:12px 0 4px;">Add a file (image or embroidery file)<br>
      <input type="file" id="oifFile" style="font-size:13px;">
    </label>
    <div id="oifErr" style="color:#b03a2e;font-size:13px;min-height:18px;"></div>
    <div style="display:flex;gap:8px;justify-content:flex-end;">
      <button type="button" id="oifClose" style="padding:6px 14px;border:1px solid #ccc;border-radius:5px;background:#fff;cursor:pointer;">Close</button>
      <button type="button" id="oifUpload" class="admin-btn">Upload</button>
    </div>`, 440);
  let files = [];
  const draw = () => {
    const body = ov.querySelector("#oifBody");
    // The customer's own design (migrations/0054) shows as a picture and can't be deleted — the line is made from it.
    body.innerHTML = files.length ? files.map(f => `
      <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;padding:4px 0;border-bottom:1px solid #eee;">
        <span style="display:flex;align-items:center;gap:8px;min-width:0;">
          ${f.uploadedBy === "customer" && isImageExt_(f.fileExt) ? `<img data-design-key="${escapeHtml(f.fileKey)}" alt="The customer's design" style="width:64px;height:64px;object-fit:contain;border:1px solid #ddd;border-radius:4px;background:#fff;flex:none;">` : ""}
          <span style="overflow-wrap:anywhere;">${escapeHtml(f.fileName)} <span style="color:#999;">(${f.uploadedBy === "customer" ? "the customer's design" : escapeHtml(f.uploadedBy)})</span></span>
        </span>
        <span style="flex:none;">
          <button type="button" class="admin-btn" style="padding:2px 8px;font-size:11px;" data-key="${escapeHtml(f.fileKey)}">Download</button>
          ${f.uploadedBy === "customer" ? "" : `<button type="button" class="admin-btn admin-btn-danger" style="padding:2px 8px;font-size:11px;" data-fid="${f.id}">Delete</button>`}
        </span>
      </div>`).join("") : `<div style="color:#888;">No files uploaded yet.</div>`;
    fillDesignThumbs_(body);
    body.querySelectorAll("button[data-key]").forEach(btn => btn.onclick = () => downloadDesignFile_(btn.dataset.key));
    body.querySelectorAll("button[data-fid]").forEach(btn => btn.onclick = async () => {
      try { await designApi_({ action: "deleteOrderItemFile", id: Number(btn.dataset.fid) }); await load(); }
      catch (e) { showToast(e.message, true); }
    });
    onCountChange && onCountChange(files.length);
  };
  const load = async () => {
    try { files = (await designApi_({ action: "getOrderItemFiles", itemId })).files || []; draw(); }
    catch (e) { ov.querySelector("#oifBody").innerHTML = `<div style="color:#b03a2e;">${escapeHtml(e.message)}</div>`; }
  };
  // The order-specific designs (migrations/0032): newest upload per location wins; Run Order runs them.
  const loadDesign = async () => {
    const el = ov.querySelector("#oifDesign");
    try {
      const list = (await designApi_({ action: "getOrderItemDesigns", itemId })).designs || [];
      // Newest first. A single custom spot from before 0055 has its design under ''.
      const curFor = (loc) => list.find(d => (d.location || "") === loc) || (loc && customSlots === 1 ? list.find(d => !d.location) : null) || null;
      el.innerHTML = slots.map((slot, i) => { const cur = curFor(slot.location);
        return `<div style="${i ? "margin-top:10px;" : ""}">${slots.length > 1 || slot.label ? `<div style="font-weight:600;color:#111;margin-bottom:2px;">${escapeHtml(slot.label || "Typed-in name")}</div>` : ""}
          ${cur ? `<div style="color:#111;">${escapeHtml(cur.machineFileName)} · ${cur.threadColors.length} thread${cur.threadColors.length === 1 ? "" : "s"} · uploaded ${escapeHtml(String(cur.uploadedAt || "").slice(0, 10))}
            <button type="button" class="admin-btn oifDesignDl" data-key="${escapeHtml(cur.machineFileKey)}" style="padding:2px 8px;font-size:11px;margin-left:6px;">Download</button></div>`
          : `<div style="color:#b45309;">None yet — upload it before the design is sent for approval.</div>`}
          <button type="button" class="admin-btn oifDesignUp" data-i="${i}" style="margin-top:6px;">${cur ? "Upload a new version…" : "Upload order design…"}</button></div>`; }).join("");
      el.querySelectorAll(".oifDesignDl").forEach(b => b.onclick = () => downloadDesignFile_(b.dataset.key));
      el.querySelectorAll(".oifDesignUp").forEach(b => b.onclick = async () => {
        const slot = slots[Number(b.dataset.i)];
        let threads = [];
        try { threads = (await threadApi_({ action: "listThreads" })).threads || []; } catch (e) { showToast(e.message, true); return; }
        // Refresh the Orders page behind the window too — Digitizing / Design approved may now be allowed.
        showDesignVersionUploadModal_(null, () => { loadDesign(); if (/^#orders/.test(location.hash) && typeof rerenderOrdersView === "function") rerenderOrdersView(); },
          { itemId, threads, location: slot.location, title: "Order design — " + itemLabel + (slot.label ? " · " + slot.label : "") });
      });
    } catch (e) { el.innerHTML = `<div style="color:#b03a2e;">${escapeHtml(e.message)}</div>`; }
  };
  if (adminFeatureOn_("production")) loadDesign();
  ov.querySelector("#oifClose").onclick = close;
  ov.querySelector("#oifUpload").onclick = async () => {
    const err = ov.querySelector("#oifErr");
    const fileInput = ov.querySelector("#oifFile");
    const file = fileInput.files && fileInput.files[0];
    if (!file) { err.textContent = "Choose a file."; return; }
    const ext = (file.name.split(".").pop() || "").toLowerCase();
    const isImage = ["jpg", "jpeg", "png", "webp", "gif"].includes(ext);
    const contentType = isImage ? (ext === "jpg" ? "image/jpeg" : "image/" + ext) : "application/octet-stream";
    try {
      const up = await fetch(`/api/design?itemId=${itemId}&ext=${encodeURIComponent(ext === "jpeg" ? "jpg" : ext)}&name=${encodeURIComponent(file.name)}`,
        { method: "POST", headers: { "X-Admin-Key": adminKey || "", "Content-Type": contentType }, body: file });
      const ud = await up.json().catch(() => ({ status: "error", message: "Server error (" + up.status + ")" }));
      if (!up.ok || ud.status === "error") throw new Error((ud && ud.message) || "Upload failed");
      await designApi_({ action: "saveOrderItemFile", itemId, fileKey: ud.key, fileName: ud.name, fileExt: ud.ext, uploadedBy: "admin" });
      fileInput.value = ""; err.textContent = ""; await load();
    } catch (e) { err.textContent = e.message; }
  };
  await load();
}

// ---- Machines (migrations/0025) — global catalog + each machine's LIVE state ---------------
// Not per-org (like Threads/Hoops) — the shop's machines run jobs for any org. A machine's
// currentHoopId and machine_needles are its LIVE state: what's physically mounted/threaded on
// it right now. The mounted hoop follows what Run Order last ran on it; the needles are kept
// up to date by hand here.
async function machineApi_(body){
  if (!adminKey) adminKey = (await adminLogin()) || "";
  if (!adminKey) throw new Error("Sign-in required");
  const r = await fetch("/api/orders", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ ...body, key: adminKey }) });
  const d = await r.json().catch(() => ({ status: "error", message: "Server error (" + r.status + ")" }));
  if (!r.ok || d.status === "error") throw new Error((d && d.message) || "Request failed");
  return d;
}

async function renderMachines(app){
  adminSetHash("machines");
  document.title = adminTitle_("Machines");
  app.innerHTML = `
    ${adminPageHead_("Machines")}
    <div class="admin-panel" style="--org-accent:var(--accent);max-width:900px;margin:8px auto 60px;">
      <div style="font-size:13px;color:#666;margin-bottom:14px;">Each machine's current hoop and per-needle thread reflect what's physically loaded on it right now. Run Order updates the hoop when a run uses another one; correct either here by hand after a manual change. <b>The hoop and needle boxes save as soon as you change them.</b></div>
      <div style="margin-bottom:14px;"><button type="button" class="admin-btn" id="mchNewBtn">+ New machine</button>
        <button type="button" class="admin-btn" id="mchScanBtn" style="margin-left:8px;">Scan for machines&hellip;</button>
        <button type="button" class="admin-btn" id="mchStitchesBtn" style="margin-left:8px;" title="Reads the stitch count of every design file (DST / DSB) that doesn't have one yet">Read design stitch counts</button>
        <a href="#maintenance" style="margin-left:10px;font-size:13px;">Maintenance log &rarr;</a>
      </div>
      <div id="mchBody" style="color:#888;font-size:14px;max-height:65vh;overflow-y:auto;">Loading&hellip;</div>
    </div>`;
  if (!adminKey) adminKey = (await adminLogin()) || ""; // resolve once before firing these in parallel
  let machines = [], hoops = [], threads = [];
  try {
    const [m, h, t] = await Promise.all([machineApi_({ action: "listMachines" }), hoopApi_({ action: "listHoops" }), threadApi_({ action: "listThreads" })]);
    machines = m.machines || []; hoops = h.hoops || []; threads = t.threads || [];
  } catch (e) { document.getElementById("mchBody").innerHTML = `<div style="color:#b03a2e;">${escapeHtml(e.message)}</div>`; return; }
  window._mchCtx = { machines, hoops, threads };
  const threadLabel_ = (id) => { const t = threads.find(x => x.id === id); return t ? `${t.brand}${t.type ? " " + t.type : ""}${t.weight ? " " + t.weight : ""} ${t.code} — ${t.name}` : ""; };
  const threadOptions_ = (selected) => `<option value="">—</option>` + threads.map(t => `<option value="${t.id}" ${t.id === selected ? "selected" : ""}>${escapeHtml(threadLabel_(t.id))}</option>`).join("");
  const draw = () => {
    const body = document.getElementById("mchBody");
    if (!machines.length) { body.innerHTML = `<div style="color:#888;padding:16px 0;">No machines yet.</div>`; return; }
    body.innerHTML = machines.map(m => {
      const supportedHoops = hoops.filter(h => m.hoopIds.includes(h.id));
      return `
      <div style="border:1px solid #ddd;border-radius:8px;padding:14px;margin-bottom:14px;">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;">
          <div>
            <div style="font-weight:700;font-size:15px;">${escapeHtml(m.name)}</div>
            <div style="font-size:12px;color:#666;margin-top:2px;">${m.needleCount} needles &nbsp;·&nbsp; IP: ${escapeHtml(m.ipAddress || "—")} &nbsp;·&nbsp; EMB dir: ${escapeHtml(m.embDir)}</div>
            <div style="font-size:12px;color:#666;margin-top:2px;">MAC: ${escapeHtml(m.macAddress || "— not scanned —")} &nbsp;·&nbsp; ${machineVerifiedLabel_(m)}</div>
            ${m.notes ? `<div style="font-size:12px;color:#666;margin-top:2px;">${escapeHtml(m.notes)}</div>` : ""}
          </div>
          <div style="white-space:nowrap;">
            <button type="button" class="admin-btn" style="padding:2px 8px;font-size:11px;" data-mid="${m.id}" onclick="machineEdit_(this.dataset.mid)">Edit</button>
            <button type="button" class="admin-btn admin-btn-danger" style="padding:2px 8px;font-size:11px;margin-left:4px;" data-mid="${m.id}" onclick="machineDelete_(this.dataset.mid)">Delete</button>
          </div>
        </div>
        <div style="margin-top:10px;font-size:13px;">
          <b>Supported hoops:</b> ${supportedHoops.length ? escapeHtml(supportedHoops.map(h => h.name).join(", ")) : "— none set —"}
        </div>
        <div style="margin-top:6px;font-size:13px;display:flex;align-items:center;gap:6px;">
          <b>Current hoop:</b> <span style="font-size:12px;color:#888;">(saves as you change it)</span>
          <select data-mid="${m.id}" class="mchHoopSelect" style="font-size:13px;padding:3px 6px;">
            <option value="">— None —</option>
            ${hoops.map(h => `<option value="${h.id}" ${h.id === m.currentHoopId ? "selected" : ""}>${escapeHtml(h.name)}${h.isCapFrame ? " (cap frame)" : ""}</option>`).join("")}
          </select>
        </div>
        ${machineCounterHtml_(m)}
        <div style="margin-top:10px;">
          <b style="font-size:13px;">Needles</b> <span style="font-size:12px;color:#888;">— saves as you change it</span>
          <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:6px;margin-top:6px;">
            ${Array.from({ length: m.needleCount }, (_, i) => i + 1).map(n => `
              <div style="display:flex;align-items:center;gap:4px;font-size:12px;">
                <span style="color:#888;width:20px;">${n}.</span>
                <select data-mid="${m.id}" data-needle="${n}" class="mchNeedleSelect" style="flex:1;font-size:12px;padding:2px 4px;">${threadOptions_(m.needles[n])}</select>
              </div>`).join("")}
          </div>
        </div>
      </div>`;
    }).join("");
    // These save as soon as they change; a failed save puts the box back to what's stored, so the screen never
    // shows something the server didn't keep.
    body.querySelectorAll(".mchHoopSelect, .mchNeedleSelect").forEach(sel => sel.dataset.saved = sel.value);
    body.querySelectorAll(".mchHoopSelect").forEach(sel => sel.onchange = async () => {
      const mid = Number(sel.dataset.mid);
      try { await machineApi_({ action: "setMachineHoop", machineId: mid, hoopId: sel.value || null }); showToast("Current hoop saved."); await load(); }
      catch (e) { sel.value = sel.dataset.saved; showToast("Not saved: " + e.message, true); }
    });
    body.querySelectorAll(".mchNeedleSelect").forEach(sel => sel.onchange = async () => {
      const mid = Number(sel.dataset.mid), needle = Number(sel.dataset.needle);
      try { await machineApi_({ action: "setMachineNeedle", machineId: mid, needle, threadId: sel.value || null }); sel.dataset.saved = sel.value; showToast(`Needle ${needle} saved.`); }
      catch (e) { sel.value = sel.dataset.saved; showToast("Not saved: " + e.message, true); }
    });
  };
  async function load(){
    try { machines = (await machineApi_({ action: "listMachines" })).machines || []; window._mchCtx.machines = machines; draw(); }
    catch (e) { document.getElementById("mchBody").innerHTML = `<div style="color:#b03a2e;">${escapeHtml(e.message)}</div>`; }
  }
  // Counter & maintenance (migrations/0071): every window answers with the machine list, so the cards redraw from it.
  const afterMaint = (d) => { if (d && d.machines) { machines = d.machines; window._mchCtx.machines = machines; draw(); } else load(); };
  window.machineReading_ = (idStr) => { const m = machines.find(x => x.id === Number(idStr)); if (m) showMachineReadingModal_(m, afterMaint); };
  window.machineTasks_ = (idStr) => { const m = machines.find(x => x.id === Number(idStr)); if (m) showMaintenanceTasksModal_(m, machines, afterMaint); };
  window.machineMaintDone_ = (idStr, taskIdStr) => { const m = machines.find(x => x.id === Number(idStr)); if (m) showMaintenanceDoneModal_(m, taskIdStr ? m.maintenance.find(t => t.id === Number(taskIdStr)) : null, afterMaint); };
  document.getElementById("mchStitchesBtn").onclick = () => fillDesignStitchCounts_();
  document.getElementById("mchNewBtn").onclick = () => showMachineFormModal_(null, hoops, load);
  document.getElementById("mchScanBtn").onclick = () => showMachineScanModal_(hoops, load);
  window.machineEdit_ = (idStr) => { const m = machines.find(x => x.id === Number(idStr)); if (m) showMachineFormModal_(m, hoops, load); };
  window.machineDelete_ = async (idStr) => {
    const m = machines.find(x => x.id === Number(idStr)); if (!m) return;
    if (!await askConfirm_(`Delete "${m.name}"? This also clears its supported hoops and needle state.`)) return;
    try { await machineApi_({ action: "deleteMachine", id: m.id }); showToast("Machine deleted."); await load(); }
    catch (e) { showToast(e.message, true); }
  };
  draw();
}

// ---- Machine counters & maintenance (migrations/0071) ------------------------------------------------------------
// A machine's stitch counter (kept in step with its display by readings typed here) and run time grow with every run;
// its maintenance tasks are due every N run hours and/or N stitches, whichever comes first.
const fmtHours_ = (sec) => { const h = (Number(sec) || 0) / 3600; return (h >= 100 ? Math.round(h) : Math.round(h * 10) / 10).toLocaleString() + " h"; };
const fmtStitchesShort_ = (n) => { n = Number(n) || 0; return n >= 1e6 ? (Math.round(n / 1e5) / 10).toLocaleString() + "M" : n >= 1e4 ? Math.round(n / 1000).toLocaleString() + "k" : n.toLocaleString(); };
// "1.2 h / 4 h · 310k / 2M stitches" — how far a task is through each of its thresholds.
function maintProgressText_(t){
  const parts = [];
  if (t.everySeconds) parts.push(`${fmtHours_(t.usedSeconds)} / ${fmtHours_(t.everySeconds)}`);
  if (t.everyStitches) parts.push(`${fmtStitchesShort_(t.usedStitches)} / ${fmtStitchesShort_(t.everyStitches)} stitches`);
  return parts.join(" · ");
}
function maintChipHtml_(t){
  const look = { due: ["#fee2e2", "#b03a2e", "Due"], soon: ["#fef3c7", "#92400e", "Due soon"], ok: ["#dcfce7", "#166534", "OK"], off: ["#f3f4f6", "#666", "Off"] }[t.status] || ["#f3f4f6", "#666", ""];
  return `<span class="maint-chip maint-${t.status}" style="display:inline-block;padding:1px 8px;border-radius:10px;font-size:11px;font-weight:700;background:${look[0]};color:${look[1]};">${look[2]}</span>`;
}
function machineCounterHtml_(m){
  const tasks = m.maintenance || [];
  return `<div class="mch-counter" style="margin-top:10px;border-top:1px solid #eee;padding-top:8px;font-size:13px;">
    <div style="display:flex;flex-wrap:wrap;gap:6px 14px;align-items:center;">
      <span><b>Stitch counter:</b> <span class="mch-stitches">${(Number(m.stitchCount) || 0).toLocaleString()}</span></span>
      <span><b>Run time:</b> ${fmtHours_(m.runSeconds)}</span>
      <span style="color:#888;font-size:12px;">${m.counterUpdatedAt ? "updated " + escapeHtml(new Date(m.counterUpdatedAt).toLocaleDateString()) : "no reading entered yet"}</span>
      <button type="button" class="admin-btn" style="padding:2px 8px;font-size:11px;" data-mid="${m.id}" onclick="machineReading_(this.dataset.mid)">Enter machine reading&hellip;</button>
    </div>
    <div style="margin-top:8px;"><b>Maintenance</b>
      <button type="button" class="admin-btn" style="padding:2px 8px;font-size:11px;margin-left:6px;" data-mid="${m.id}" onclick="machineTasks_(this.dataset.mid)">Tasks&hellip;</button>
      <button type="button" class="admin-btn" style="padding:2px 8px;font-size:11px;margin-left:4px;" data-mid="${m.id}" onclick="machineMaintDone_(this.dataset.mid, '')">Log other work&hellip;</button>
      <a href="#maintenance/${m.id}" style="font-size:12px;margin-left:6px;">Log</a></div>
    ${tasks.length ? `<div style="margin-top:4px;">${tasks.map(t => `<div class="mch-task" style="display:flex;align-items:center;gap:8px;padding:3px 0;${t.active ? "" : "opacity:.6;"}">
        ${maintChipHtml_(t)} <span style="flex:1;">${escapeHtml(t.name)} <span style="color:#666;font-size:12px;">· ${escapeHtml(maintProgressText_(t))}</span></span>
        <button type="button" class="admin-btn" style="padding:2px 8px;font-size:11px;" data-mid="${m.id}" data-tid="${t.id}" onclick="machineMaintDone_(this.dataset.mid, this.dataset.tid)">Done</button></div>`).join("")}</div>`
      : `<div style="color:#888;font-size:12px;margin-top:4px;">No maintenance tasks yet — Tasks&hellip; adds them (e.g. oil the rotary hook every 4 run hours).</div>`}
  </div>`;
}

function showMachineReadingModal_(m, onDone){
  const { ov, close } = inventoryModal_(`Machine reading — ${escapeHtml(m.name)}`, `
    <div style="font-size:13px;color:#555;margin-bottom:10px;">Type the stitch count shown on the machine. From now on every run adds its design's stitches, so this only needs entering again to correct it (e.g. after the machine's counter is reset).</div>
    <label style="display:block;font-size:13px;font-weight:600;">Stitch counter on the machine
      <input type="text" inputmode="numeric" id="mrStitches" value="${Number(m.stitchCount) || 0}" style="display:block;width:100%;box-sizing:border-box;padding:6px;margin-top:4px;"></label>
    <label style="display:block;font-size:13px;font-weight:600;margin-top:10px;">Run hours <span style="font-weight:400;color:#888;">(optional — if the machine shows them)</span>
      <input type="number" min="0" step="0.1" id="mrHours" value="${Math.round((Number(m.runSeconds) || 0) / 360) / 10}" style="display:block;width:100%;box-sizing:border-box;padding:6px;margin-top:4px;"></label>
    <label style="display:block;font-size:13px;font-weight:600;margin-top:10px;">Note <input type="text" id="mrNote" placeholder="Reading entered" style="display:block;width:100%;box-sizing:border-box;padding:6px;margin-top:4px;"></label>
    <div id="mrErr" style="color:#b03a2e;font-size:13px;margin-top:8px;"></div>
    <div style="margin-top:14px;text-align:right;"><button type="button" class="admin-btn" id="mrCancel" style="background:#e5e7eb;color:#111;">Cancel</button> <button type="button" class="admin-btn" id="mrSave">Save reading</button></div>`, 420);
  ov.querySelector("#mrCancel").onclick = close;
  ov.querySelector("#mrSave").onclick = async () => {
    const hours = ov.querySelector("#mrHours").value.trim(), oldHours = Math.round((Number(m.runSeconds) || 0) / 360) / 10;
    try {
      const d = await machineApi_({ action: "setMachineStitchCount", machineId: m.id, reading: ov.querySelector("#mrStitches").value.replace(/[,\s]/g, ""),
        runHours: hours !== "" && Number(hours) !== oldHours ? Number(hours) : undefined, note: ov.querySelector("#mrNote").value.trim() });
      close(); showToast("Reading saved."); onDone && onDone(d);
    } catch (e) { ov.querySelector("#mrErr").textContent = e.message; }
  };
}

// Starting points the Tasks window offers (all editable). Hours are RUN hours, not clock hours.
const MAINT_COMMON_TASKS_ = [
  { name: "Oil the rotary hook", everyHours: 4 },
  { name: "Clean lint from the bobbin case and hook area", everyHours: 8 },
  { name: "Change needles", everyStitches: 2000000 },
  { name: "Full clean and grease", everyHours: 40 },
];
function showMaintenanceTasksModal_(m, machines, onDone){
  let tasks = (m.maintenance || []).slice();
  const { ov, close } = inventoryModal_(`Maintenance tasks — ${escapeHtml(m.name)}`, `
    <div style="font-size:13px;color:#555;margin-bottom:10px;">A task is due after this many <b>run hours</b> and/or <b>stitches</b> since it was last done — whichever comes first. Leave one blank to use only the other.</div>
    <div id="mtList"></div>
    <div style="border-top:1px solid #eee;margin-top:12px;padding-top:10px;">
      <b style="font-size:13px;">Add a task</b>
      <div style="display:grid;grid-template-columns:2fr 1fr 1fr;gap:6px;margin-top:6px;" class="mt-add">
        <input type="text" id="mtName" placeholder="e.g. Oil the rotary hook" style="padding:6px;">
        <input type="number" min="0" step="0.5" id="mtHours" placeholder="Every … run h" style="padding:6px;">
        <input type="text" inputmode="numeric" id="mtStitches" placeholder="Every … stitches" style="padding:6px;">
      </div>
      <div style="margin-top:6px;"><button type="button" class="admin-btn" id="mtAdd">+ Add task</button></div>
      <div style="margin-top:10px;font-size:13px;"><b>Common tasks</b> <span style="color:#888;">— tick to add, then edit the numbers to the machine's manual</span>
        <div id="mtCommon" style="margin-top:4px;"></div>
        <button type="button" class="admin-btn" id="mtAddCommon" style="margin-top:4px;padding:2px 10px;font-size:12px;">Add ticked</button></div>
      ${machines.filter(x => x.id !== m.id && (x.maintenance || []).length).length ? `<div style="margin-top:10px;font-size:13px;"><b>Copy from</b>
        <select id="mtCopyFrom" style="padding:4px;">${machines.filter(x => x.id !== m.id && (x.maintenance || []).length).map(x => `<option value="${x.id}">${escapeHtml(x.name)} (${x.maintenance.length})</option>`).join("")}</select>
        <button type="button" class="admin-btn" id="mtCopy" style="padding:2px 10px;font-size:12px;">Copy tasks</button></div>` : ""}
    </div>
    <div id="mtErr" style="color:#b03a2e;font-size:13px;margin-top:8px;"></div>
    <div style="margin-top:12px;text-align:right;"><button type="button" class="admin-btn" id="mtClose">Done</button></div>`, 640);
  ov.querySelector("#mtClose").onclick = close;
  const err = (msg) => { ov.querySelector("#mtErr").textContent = msg || ""; };
  // Each change answers with the machine list: the page behind redraws at once, and so does this window.
  const fromList = (d) => { onDone && onDone(d); const mm = (d.machines || []).find(x => x.id === m.id); tasks = mm ? mm.maintenance : tasks; draw(); };
  const save = async (task) => { err(); const d = await machineApi_({ action: "saveMaintenanceTask", task }); fromList(d); return d; };
  const draw = () => {
    const names = new Set(tasks.map(t => t.name.toLowerCase()));
    ov.querySelector("#mtCommon").innerHTML = MAINT_COMMON_TASKS_.filter(c => !names.has(c.name.toLowerCase())).map((c, i) => `<label class="pick-row" style="display:block;font-weight:400;"><input type="checkbox" class="mtCommonTick" data-i="${MAINT_COMMON_TASKS_.indexOf(c)}"> ${escapeHtml(c.name)} — every ${c.everyHours ? c.everyHours + " run h" : (c.everyStitches).toLocaleString() + " stitches"}</label>`).join("") || `<span style="color:#888;">All added.</span>`;
    ov.querySelector("#mtList").innerHTML = tasks.length ? `<table style="width:100%;border-collapse:collapse;font-size:13px;" class="stack-mobile">
      <thead><tr style="text-align:left;background:#f3f4f6;"><th style="padding:4px;">Task</th><th style="padding:4px;">Every run h</th><th style="padding:4px;">Every stitches</th><th style="padding:4px;">On</th><th style="padding:4px;"></th></tr></thead>
      <tbody>${tasks.map(t => `<tr data-tid="${t.id}" style="border-bottom:1px solid #eee;">
        <td data-label="Task" style="padding:4px;"><input type="text" class="mtE" data-f="name" value="${escapeHtml(t.name)}" style="width:100%;padding:4px;"><div style="font-size:11px;color:#666;margin-top:2px;">${maintChipHtml_(t)} ${escapeHtml(maintProgressText_(t))}</div></td>
        <td data-label="Every run h" style="padding:4px;"><input type="number" min="0" step="0.5" class="mtE" data-f="everyHours" value="${t.everySeconds ? Math.round(t.everySeconds / 360) / 10 : ""}" style="width:80px;padding:4px;"></td>
        <td data-label="Every stitches" style="padding:4px;"><input type="text" inputmode="numeric" class="mtE" data-f="everyStitches" value="${t.everyStitches || ""}" style="width:110px;padding:4px;"></td>
        <td data-label="On" style="padding:4px;"><input type="checkbox" class="mtE" data-f="active" ${t.active ? "checked" : ""}></td>
        <td style="padding:4px;white-space:nowrap;"><button type="button" class="admin-btn mtSave" style="padding:2px 8px;font-size:11px;">Save</button>
          <button type="button" class="admin-btn mtDel admin-btn-danger" style="padding:2px 8px;font-size:11px;">Delete</button></td></tr>`).join("")}</tbody></table>`
      : `<div style="color:#888;font-size:13px;">No tasks yet.</div>`;
    ov.querySelectorAll("#mtList tr[data-tid]").forEach(tr => {
      const t = tasks.find(x => x.id === Number(tr.dataset.tid));
      const val = (f) => tr.querySelector(`.mtE[data-f="${f}"]`);
      tr.querySelector(".mtSave").onclick = async () => {
        try { await save({ id: t.id, name: val("name").value, everyHours: val("everyHours").value, everyStitches: val("everyStitches").value.replace(/[,\s]/g, ""),
          active: val("active").checked, notes: t.notes, sortOrder: t.sortOrder }); showToast("Task saved."); } catch (e) { err(e.message); }
      };
      tr.querySelector(".mtDel").onclick = async () => {
        if (!await askConfirm_(`Delete "${t.name}"? Its past log entries stay.`)) return;
        try { fromList(await machineApi_({ action: "deleteMaintenanceTask", taskId: t.id })); } catch (e) { err(e.message); }
      };
    });
  };
  ov.querySelector("#mtAdd").onclick = async () => {
    try { await save({ machineId: m.id, name: ov.querySelector("#mtName").value, everyHours: ov.querySelector("#mtHours").value,
      everyStitches: ov.querySelector("#mtStitches").value.replace(/[,\s]/g, ""), sortOrder: (tasks.length + 1) * 10 });
      ["#mtName", "#mtHours", "#mtStitches"].forEach(q => { ov.querySelector(q).value = ""; }); } catch (e) { err(e.message); }
  };
  ov.querySelector("#mtAddCommon").onclick = async () => {
    const picks = [...ov.querySelectorAll(".mtCommonTick:checked")].map(c => MAINT_COMMON_TASKS_[Number(c.dataset.i)]);
    try { for (const c of picks) await save({ machineId: m.id, name: c.name, everyHours: c.everyHours || "", everyStitches: c.everyStitches || "", sortOrder: (tasks.length + 1) * 10 }); }
    catch (e) { err(e.message); }
  };
  const copyBtn = ov.querySelector("#mtCopy");
  if (copyBtn) copyBtn.onclick = async () => {
    const src = machines.find(x => x.id === Number(ov.querySelector("#mtCopyFrom").value));
    const have = new Set(tasks.map(t => t.name.toLowerCase()));
    try {
      for (const t of (src ? src.maintenance : []).filter(t => !have.has(t.name.toLowerCase())))
        await save({ machineId: m.id, name: t.name, everyHours: t.everySeconds ? t.everySeconds / 3600 : "", everyStitches: t.everyStitches || "", notes: t.notes, active: t.active, sortOrder: (tasks.length + 1) * 10 });
      showToast("Tasks copied.");
    } catch (e) { err(e.message); }
  };
  draw();
}

// Records maintenance done — a listed task (it starts counting again) or, with no task, other work typed in.
function showMaintenanceDoneModal_(m, task, onDone){
  const today = new Date(Date.now() - new Date().getTimezoneOffset() * 60000).toISOString().slice(0, 10);
  const { ov, close } = inventoryModal_(task ? `Done — ${escapeHtml(task.name)}` : `Log work — ${escapeHtml(m.name)}`, `
    ${task ? `<div style="font-size:13px;color:#555;margin-bottom:8px;">${escapeHtml(m.name)} · ${escapeHtml(maintProgressText_(task))} since it was last done. Saving starts the count again.</div>`
      : `<label style="display:block;font-size:13px;font-weight:600;">What was done <input type="text" id="mdName" placeholder="e.g. Replaced the rotary hook" style="display:block;width:100%;box-sizing:border-box;padding:6px;margin-top:4px;"></label>`}
    <label style="display:block;font-size:13px;font-weight:600;margin-top:8px;">Date <input type="date" id="mdDate" value="${today}" max="${today}" style="display:block;padding:6px;margin-top:4px;"></label>
    <label style="display:block;font-size:13px;font-weight:600;margin-top:8px;">Note <input type="text" id="mdNote" style="display:block;width:100%;box-sizing:border-box;padding:6px;margin-top:4px;"></label>
    <div style="font-size:12px;color:#888;margin-top:6px;">Logged with the counters now: ${(Number(m.stitchCount) || 0).toLocaleString()} stitches · ${fmtHours_(m.runSeconds)}.</div>
    <div id="mdErr" style="color:#b03a2e;font-size:13px;margin-top:8px;"></div>
    <div style="margin-top:14px;text-align:right;"><button type="button" class="admin-btn" id="mdCancel" style="background:#e5e7eb;color:#111;">Cancel</button> <button type="button" class="admin-btn" id="mdSave">Save</button></div>`, 440);
  ov.querySelector("#mdCancel").onclick = close;
  ov.querySelector("#mdSave").onclick = async () => {
    const date = ov.querySelector("#mdDate").value;
    try {
      const d = await machineApi_({ action: "recordMaintenance", machineId: m.id, taskId: task ? task.id : null, name: task ? "" : ov.querySelector("#mdName").value,
        note: ov.querySelector("#mdNote").value.trim(), doneAt: date && date !== today ? date + "T12:00:00" : "" });
      close(); showToast("Logged."); onDone && onDone(d);
    } catch (e) { ov.querySelector("#mdErr").textContent = e.message; }
  };
}

// Tools → Machine maintenance (#maintenance, #maintenance/<machineId>): what's due across the machines, then the
// maintenance log and the counter changes (readings, runs — summed per machine per day), newest first.
async function renderMaintenance(app, machineIdStr){
  adminSetHash("maintenance" + (machineIdStr ? "/" + machineIdStr : ""));
  document.title = adminTitle_("Machine maintenance");
  const today = new Date(Date.now() - new Date().getTimezoneOffset() * 60000).toISOString().slice(0, 10);
  const from = new Date(Date.now() - 90 * 86400000 - new Date().getTimezoneOffset() * 60000).toISOString().slice(0, 10);
  app.innerHTML = `
    ${adminPageHead_("Machine maintenance")}
    <div class="admin-panel" style="--org-accent:var(--accent);max-width:960px;margin:8px auto 60px;">
      <div style="font-size:13px;color:#666;margin-bottom:12px;">Tasks are set per machine on <a href="#machines">Machines</a> (Tasks&hellip;). Run time and stitches come from Run Order: every finished run adds its design's stitches; an untimed "Mark done" adds an estimated time (marked ≈).</div>
      <div id="mntDue" style="margin-bottom:16px;"></div>
      <div style="display:flex;flex-wrap:wrap;gap:8px;align-items:flex-end;margin-bottom:10px;font-size:13px;">
        <label>Machine<br><select id="mntMachine" style="padding:4px;"><option value="">All machines</option></select></label>
        <label>From<br><input type="date" id="mntFrom" value="${from}" style="padding:4px;"></label>
        <label>To<br><input type="date" id="mntTo" value="${today}" style="padding:4px;"></label>
        <button type="button" class="admin-btn" id="mntGo">Show</button>
      </div>
      <div id="mntBody" style="color:#888;">Loading&hellip;</div>
    </div>`;
  let machines = [];
  try { machines = (await machineApi_({ action: "listMachines" })).machines || []; }
  catch (e) { document.getElementById("mntBody").innerHTML = `<div style="color:#b03a2e;">${escapeHtml(e.message)}</div>`; return; }
  const sel = document.getElementById("mntMachine");
  sel.innerHTML += machines.map(m => `<option value="${m.id}" ${String(m.id) === machineIdStr ? "selected" : ""}>${escapeHtml(m.name)}</option>`).join("");
  const due = [];
  for (const m of machines) for (const t of m.maintenance || []) if (t.status === "due" || t.status === "soon") due.push({ m, t });
  document.getElementById("mntDue").innerHTML = `<h3 style="margin:0 0 6px;font-size:15px;">Due now</h3>` + (due.length
    ? due.sort((a, b) => b.t.pct - a.t.pct).map(({ m, t }) => `<div class="mnt-due" style="display:flex;align-items:center;gap:8px;padding:4px 0;font-size:13px;">${maintChipHtml_(t)}
        <span style="flex:1;"><b>${escapeHtml(m.name)}</b> — ${escapeHtml(t.name)} <span style="color:#666;">· ${escapeHtml(maintProgressText_(t))}</span></span>
        <button type="button" class="admin-btn mntDone" style="padding:2px 8px;font-size:11px;" data-mid="${m.id}" data-tid="${t.id}">Done</button></div>`).join("")
    : `<div style="color:#2c6b2f;font-size:13px;">Nothing due.</div>`);
  document.querySelectorAll(".mntDone").forEach(b => b.onclick = () => {
    const m = machines.find(x => x.id === Number(b.dataset.mid));
    showMaintenanceDoneModal_(m, m.maintenance.find(t => t.id === Number(b.dataset.tid)), () => renderMaintenance(app, sel.value));
  });
  const load = async () => {
    const body = document.getElementById("mntBody");
    body.innerHTML = "Loading&hellip;";
    let d;
    // The dates are days on this computer's clock; the server stores UTC times, so send the exact instants.
    const fromDay = document.getElementById("mntFrom").value, toDay = document.getElementById("mntTo").value;
    const fromAt = fromDay ? new Date(fromDay + "T00:00:00").toISOString() : "", toAt = toDay ? new Date(toDay + "T23:59:59.999").toISOString() : "";
    try { d = await machineApi_({ action: "getMaintenanceLog", machineId: sel.value ? Number(sel.value) : null, from: fromAt, to: toAt }); }
    catch (e) { body.innerHTML = `<div style="color:#b03a2e;">${escapeHtml(e.message)}</div>`; return; }
    const day = (iso) => new Date(iso).toLocaleDateString();
    // Runs summed per machine per day; readings listed one by one.
    const usage = new Map();
    for (const e of d.events) {
      if (e.kind === "reading") continue;
      const k = e.machineId + "|" + day(e.at);
      const u = usage.get(k) || { machineName: e.machineName, day: day(e.at), at: e.at, runs: 0, stitches: 0, seconds: 0, estimated: false, unknown: 0 };
      u.runs++; u.stitches += e.stitchesDelta; u.seconds += e.secondsDelta; u.estimated = u.estimated || e.estimated; if (e.note) u.unknown++;
      usage.set(k, u);
    }
    const rows = [
      ...d.log.map(l => ({ at: l.doneAt, html: `<tr class="mnt-log" style="border-bottom:1px solid #eee;"><td data-label="Date" style="padding:4px;">${escapeHtml(day(l.doneAt))}</td><td data-label="Machine" style="padding:4px;">${escapeHtml(l.machineName)}</td>
        <td data-label="What" style="padding:4px;"><b>🔧 ${escapeHtml(l.taskName)}</b>${l.note ? `<div style="color:#666;">${escapeHtml(l.note)}</div>` : ""}</td>
        <td data-label="Counters" style="padding:4px;color:#666;">${l.stitchCountAt.toLocaleString()} stitches · ${fmtHours_(l.runSecondsAt)}</td><td data-label="By" style="padding:4px;color:#888;">${escapeHtml(l.actor)}</td></tr>` })),
      ...d.events.filter(e => e.kind === "reading").map(e => ({ at: e.at, html: `<tr class="mnt-reading" style="border-bottom:1px solid #eee;"><td data-label="Date" style="padding:4px;">${escapeHtml(day(e.at))}</td><td data-label="Machine" style="padding:4px;">${escapeHtml(e.machineName)}</td>
        <td data-label="What" style="padding:4px;">Reading: ${e.stitchTotalAfter.toLocaleString()} stitches (${e.stitchesDelta >= 0 ? "+" : ""}${e.stitchesDelta.toLocaleString()})${e.secondsDelta ? ` · ${fmtHours_(e.secondsTotalAfter)}` : ""}${e.note && e.note !== "Reading entered" ? `<div style="color:#666;">${escapeHtml(e.note)}</div>` : ""}</td>
        <td data-label="Counters" style="padding:4px;color:#666;">${e.stitchTotalAfter.toLocaleString()} · ${fmtHours_(e.secondsTotalAfter)}</td><td data-label="By" style="padding:4px;color:#888;">${escapeHtml(e.actor)}</td></tr>` })),
      ...[...usage.values()].map(u => ({ at: u.at, html: `<tr class="mnt-usage" style="border-bottom:1px solid #eee;color:#555;"><td data-label="Date" style="padding:4px;">${escapeHtml(u.day)}</td><td data-label="Machine" style="padding:4px;">${escapeHtml(u.machineName)}</td>
        <td data-label="What" style="padding:4px;">${u.runs} run${u.runs === 1 ? "" : "s"}: +${u.stitches.toLocaleString()} stitches · +${u.estimated ? "≈" : ""}${fmtHours_(u.seconds)}${u.unknown ? ` <span style="color:#92400e;">(${u.unknown} with no stitch count)</span>` : ""}</td>
        <td data-label="Counters" style="padding:4px;"></td><td style="padding:4px;"></td></tr>` })),
    ].sort((a, b) => String(b.at).localeCompare(String(a.at)));
    body.innerHTML = rows.length ? `<table class="stack-mobile" style="width:100%;border-collapse:collapse;font-size:13px;color:#111;">
      <thead><tr style="text-align:left;background:#f3f4f6;"><th style="padding:4px;">Date</th><th style="padding:4px;">Machine</th><th style="padding:4px;">What</th><th style="padding:4px;">Counters</th><th style="padding:4px;">By</th></tr></thead>
      <tbody>${rows.map(r => r.html).join("")}</tbody></table>` : `<div style="color:#888;">Nothing in this range.</div>`;
  };
  document.getElementById("mntGo").onclick = load;
  sel.onchange = () => { adminSetHash("maintenance" + (sel.value ? "/" + sel.value : "")); load(); };
  load();
}

// Reads the stitch counts of design files that have none yet, a batch per request, until none are left.
async function fillDesignStitchCounts_(){
  let filled = 0, unreadable = 0;
  try {
    for (let i = 0; i < 25; i++) {
      const d = await machineApi_({ action: "fillDesignStitchCounts" });
      filled += d.filled; unreadable = d.unreadable;
      if (!d.more) break;
    }
    showToast(filled ? `Read ${filled} design stitch count${filled === 1 ? "" : "s"}.` + (unreadable ? ` ${unreadable} couldn't be read — type them on the design.` : "")
      : unreadable ? `${unreadable} design file${unreadable === 1 ? "" : "s"} couldn't be read — type the count on the design.` : "Every DST / DSB design already has its stitch count.");
  } catch (e) { showToast(e.message, true); }
}

function showMachineFormModal_(machine, hoops, onDone, prefill){
  const isNew = !machine;
  const f = machine || { name: "", needleCount: 15, ipAddress: "", embDir: "/EMB", macAddress: "", notes: "", hoopIds: [], ...(prefill || {}) };
  const inp = "font-size:13px;padding:6px 8px;border:1px solid #ccc;border-radius:4px;width:100%;box-sizing:border-box;";
  const roInp = inp + "background:#f3f4f6;color:#666;";
  const { ov, close } = inventoryModal_(isNew ? "New machine" : "Edit machine", `
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px;">
      <label style="font-size:12px;font-weight:600;grid-column:1/-1;">Name<br><input id="mchfName" value="${escapeHtml(f.name)}" placeholder="e.g. Machine 1" style="${inp}"></label>
      <label style="font-size:12px;font-weight:600;">Needle count<br><input id="mchfNeedles" type="number" min="1" step="1" value="${f.needleCount}" style="${inp}"></label>
      <label style="font-size:12px;font-weight:600;">MAC address<br><input id="mchfMac" value="${escapeHtml(f.macAddress || "")}" placeholder="e.g. AA:BB:CC:00:11:22" style="${inp}"></label>
      <label style="font-size:12px;font-weight:600;grid-column:1/-1;">IP address <span style="font-weight:400;color:#888;">— set automatically by "Scan for machines"</span><br><input id="mchfIp" value="${escapeHtml(f.ipAddress)}" readonly title="Populated by the scanner from this machine's MAC address" style="${roInp}"></label>
      <label style="font-size:12px;font-weight:600;grid-column:1/-1;">EMB directory<br><input id="mchfEmbDir" value="${escapeHtml(f.embDir)}" style="${inp}"></label>
      <div style="grid-column:1/-1;">
        <div style="font-size:12px;font-weight:600;margin-bottom:4px;">Supported hoops</div>
        ${hoops.length ? hoops.map(h => `<label style="display:block;font-size:13px;margin-bottom:2px;"><input type="checkbox" class="mchfHoopCk" value="${h.id}" ${f.hoopIds.includes(h.id) ? "checked" : ""}> ${escapeHtml(h.name)}${h.isCapFrame ? " (cap frame)" : ""}</label>`).join("") : `<div style="color:#888;font-size:13px;">No hoops in the catalog yet.</div>`}
      </div>
      <label style="font-size:12px;font-weight:600;grid-column:1/-1;">Notes<br><input id="mchfNotes" value="${escapeHtml(f.notes)}" style="${inp}"></label>
    </div>
    <div id="mchfErr" style="color:#b03a2e;font-size:13px;min-height:18px;"></div>
    <div style="display:flex;gap:8px;justify-content:flex-end;">
      <button type="button" id="mchfCancel" style="padding:6px 14px;border:1px solid #ccc;border-radius:5px;background:#fff;cursor:pointer;">Cancel</button>
      <button type="button" id="mchfSave" class="admin-btn">${isNew ? "Create machine" : "Save changes"}</button>
    </div>`, 460);
  ov.querySelector("#mchfCancel").onclick = close;
  ov.querySelector("#mchfSave").onclick = async () => {
    const err = ov.querySelector("#mchfErr");
    const hoopIds = Array.from(ov.querySelectorAll(".mchfHoopCk:checked")).map(ck => Number(ck.value));
    const payload = { id: f.id, name: ov.querySelector("#mchfName").value.trim(), needleCount: ov.querySelector("#mchfNeedles").value,
      ipAddress: ov.querySelector("#mchfIp").value.trim(), macAddress: ov.querySelector("#mchfMac").value.trim(),
      embDir: ov.querySelector("#mchfEmbDir").value.trim() || "/EMB",
      notes: ov.querySelector("#mchfNotes").value.trim(), hoopIds };
    if (!payload.name) { err.textContent = "Name is required."; return; }
    if (!payload.needleCount || Number(payload.needleCount) <= 0) { err.textContent = "Needle count must be a positive number."; return; }
    try { await machineApi_({ action: "saveMachine", machine: payload }); close(); showToast(isNew ? "Machine created." : "Machine updated."); onDone && onDone(); }
    catch (e) { err.textContent = e.message; }
  };
}

// Sweeps the LAN via the local agent's UDP discovery (the machines' own proprietary protocol,
// not FTP — see the send-agent, a separate project) and lets the operator either create a new
// machine record from a discovery result or fill a discovered IP into an existing one, rather
// than typing an IP address by hand.
async function showMachineScanModal_(hoops, onDone){
  const { ov, close } = inventoryModal_("Scan for machines", `
    <div id="mchScanBody" style="font-size:13px;color:#888;min-height:60px;">Scanning the shop network&hellip; (a few seconds; up to a minute if the agent was idle)</div>
    <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:10px;">
      <button type="button" id="mchScanClose" style="padding:6px 14px;border:1px solid #ccc;border-radius:5px;background:#fff;cursor:pointer;">Close</button>
    </div>`, 480);
  ov.querySelector("#mchScanClose").onclick = close;
  const body = ov.querySelector("#mchScanBody");
  let found;
  try {
    const r = await agentFetch_("/discover", { method: "GET" });
    const d = await r.json().catch(() => ({ status: "error", message: "Send agent returned an error (" + r.status + ")" }));
    if (!r.ok || d.status !== "ok") throw new Error((d && d.message) || "Scan failed");
    found = d.machines || [];
  } catch (e) {
    const notRunning = /Failed to fetch|NetworkError|Load failed/i.test(e.message || "");
    body.innerHTML = `<div style="color:#b03a2e;">${escapeHtml(notRunning ? "Send agent isn't reachable — see the send-agent's README (it's a separate download)." : e.message)}</div>`;
    return;
  }
  if (!found.length) { body.innerHTML = `<div style="color:#888;">No machines answered. Make sure they're powered on and on the same network.</div>`; return; }
  // Auto-match by MAC and refresh every already-known machine's IP + verifiedAt in one call, so a
  // machine that already has its MAC on file gets its (possibly-changed) IP updated without any
  // clicking — the scanner, not a human, keeps the IP current.
  let machines = window._mchCtx.machines;
  const knownMacs = new Set(machines.filter(mm => mm.macAddress).map(mm => normalizeMac_(mm.macAddress)));
  const autoMatched = found.filter(m => m.mac && knownMacs.has(normalizeMac_(m.mac)));
  if (autoMatched.length) {
    try {
      const res = await machineApi_({ action: "recordMachineDiscovery", discovered: autoMatched.map(m => ({ mac: m.mac, ip: m.ip })) });
      if (res.machines) { machines = res.machines; window._mchCtx.machines = machines; }
      showToast(`Updated ${autoMatched.length} machine${autoMatched.length === 1 ? "" : "s"} from the scan.`);
    } catch (e) { /* non-fatal — the manual buttons below still work */ }
  }
  const macToMachine = new Map(machines.filter(mm => mm.macAddress).map(mm => [normalizeMac_(mm.macAddress), mm]));
  body.innerHTML = found.map((m, i) => {
    const matched = m.mac ? macToMachine.get(normalizeMac_(m.mac)) : null;
    return `
    <div style="border:1px solid #ddd;border-radius:6px;padding:10px;margin-bottom:8px;">
      <div style="font-weight:600;">${escapeHtml(m.model || "Unknown model")}</div>
      <div style="color:#666;">IP: ${escapeHtml(m.ip)} ${m.mac ? "&nbsp;·&nbsp; MAC: " + escapeHtml(m.mac) : ""} ${m.firmware ? "&nbsp;·&nbsp; Firmware: " + escapeHtml(m.firmware) : ""}</div>
      ${matched ? `<div style="color:#2c6b2f;margin-top:4px;font-size:12px;">✓ Matched "${escapeHtml(matched.name)}" by MAC — its IP is now up to date.</div>` : `
      <div style="margin-top:6px;display:flex;gap:6px;align-items:center;flex-wrap:wrap;">
        <button type="button" class="admin-btn mchScanNewBtn" data-i="${i}" style="padding:3px 8px;font-size:12px;">+ New machine</button>
        ${machines.length ? `
          <select class="mchScanAssignSelect" data-i="${i}" style="font-size:12px;padding:3px 6px;">
            <option value="">— assign to existing machine —</option>
            ${machines.map(mm => `<option value="${mm.id}">${escapeHtml(mm.name)}</option>`).join("")}
          </select>` : ""}
      </div>`}
    </div>`;
  }).join("");
  body.querySelectorAll(".mchScanNewBtn").forEach(btn => btn.onclick = () => {
    const m = found[Number(btn.dataset.i)];
    close();
    showMachineFormModal_(null, hoops, onDone, { name: m.model || "", ipAddress: m.ip, macAddress: m.mac || "" });
  });
  body.querySelectorAll(".mchScanAssignSelect").forEach(sel => sel.onchange = async () => {
    if (!sel.value) return;
    const m = found[Number(sel.dataset.i)];
    const target = machines.find(mm => mm.id === Number(sel.value));
    if (!target) return;
    try {
      // Give the existing record this machine's MAC (its stable identity) plus the discovered IP,
      // then stamp verifiedAt via the same discovery path so it's treated as freshly confirmed.
      await machineApi_({ action: "saveMachine", machine: { id: target.id, name: target.name, needleCount: target.needleCount,
        ipAddress: m.ip, macAddress: m.mac || target.macAddress || "", embDir: target.embDir, notes: target.notes, hoopIds: target.hoopIds } });
      if (m.mac) await machineApi_({ action: "recordMachineDiscovery", discovered: [{ mac: m.mac, ip: m.ip }] });
      showToast(`${target.name} linked to MAC ${escapeHtml(m.mac || "?")} at ${escapeHtml(m.ip)}.`);
      close(); onDone && onDone();
    } catch (e) { showToast(e.message, true); }
  });
}

// ---- Run Order — touch-friendly "what to run next", grouped by blank ----------
// Every item one manufacture away (paid, design approved, blanks received, not yet made) across
// EVERY org, grouped by blank type → blank → size (same grouping shape renderAdminBlanks uses).
// Per job: the design's thread map, a proposed machine (favoring no hoop change — especially
// avoiding a cap-hoop swap, the most time-consuming one), and needle-readiness against that
// machine's live state. "Mark manufactured" both advances the order (existing fulfillment-stage
// flow) and brings the chosen machine's live state up to date with what was just run.
const HOOP_CHANGE_COST_SAME = 0, HOOP_CHANGE_COST_SWAP = 10, HOOP_CHANGE_COST_CAP = 100;

// ---- Local send agent — "Send design to machine" ------------------------------
// A Cloudflare Function can't reach a machine's private LAN IP, so the actual transfer happens
// through a small standalone program the operator runs on whatever computer drives this screen
// (a separate project — see its README). This page only ever talks to it
// over http://127.0.0.1 — browsers treat localhost as secure, so an HTTPS admin page is allowed
// to call it (the one carve-out in the mixed-content rules that makes this pattern work at all).
const EMBROIDERY_AGENT_URL = "http://127.0.0.1:8787";

// Two ways to reach the agent, tried in this order:
//  1. A loopback agent on THIS computer — answers /ping within a moment.
//  2. The site's relay (functions/api/agent.js): an agent running anywhere on the shop network connects
//     OUT to the site, and this page just queues a job and waits for the answer — so a phone or tablet
//     (which can't call a LAN address from an HTTPS page) works. Jobs live ~2 minutes on the server and
//     are dropped if the agent doesn't take them, so nothing is ever sent to a machine late.
const AGENT_LOCAL_PING_MS = 700, AGENT_LOCAL_CACHE_MS = 30000;
const AGENT_WAIT_MS = { discover: 90000, list: 90000, send: 110000, read: 110000, delete: 90000 };
let _agentLocal = { at: 0, up: false };

async function agentLocalUp_(){
  if (Date.now() - _agentLocal.at < AGENT_LOCAL_CACHE_MS) return _agentLocal.up;
  let up = false;
  try {
    const ctl = new AbortController(), t = setTimeout(() => ctl.abort(), AGENT_LOCAL_PING_MS);
    try { up = (await fetch(EMBROIDERY_AGENT_URL + "/ping", { method: "GET", signal: ctl.signal })).ok; }
    finally { clearTimeout(t); }
  } catch (e) { up = false; }
  _agentLocal = { at: Date.now(), up };
  return up;
}

async function agentRelayApi_(op, body){
  const r = await fetch("/api/agent?op=" + op, { method: "POST", headers: { "Content-Type": "application/json", "X-Admin-Key": adminKey || "" },
    body: JSON.stringify(body || {}) });
  const d = await r.json().catch(() => ({ status: "error", message: "Server error (" + r.status + ")" }));
  if (!r.ok || d.status === "error") throw new Error((d && d.message) || "Agent relay error");
  return d;
}

// {online, lastSeenSec, agentIp}. `hot` tells a sleeping agent someone is about to use it.
async function agentRelayStatus_(hot){
  try { return await agentRelayApi_("status", { hot: !!hot }); }
  catch (e) { return { online: false }; }
}

// Queues a job on the relay and waits for the agent's answer. Resolves like a fetch Response
// ({ok, status, json()}) so callers read it exactly as they did the loopback agent's reply.
async function agentRelayCall_(job){
  if (adminKey === "" || adminKey == null) adminKey = await adminLogin();
  const { id } = await agentRelayApi_("submit", job);
  const deadline = Date.now() + (AGENT_WAIT_MS[job.type] || 90000);
  let delay = 1000;
  while (Date.now() < deadline) {
    await new Promise(res => setTimeout(res, delay));
    delay = Math.min(delay + 500, 2500);
    const d = await agentRelayApi_("result", { id });
    if (d.done) { const body = d.result.body, status = d.result.httpStatus || 200;
      return { ok: status >= 200 && status < 300, status, json: async () => body }; }
  }
  throw new Error("The send agent didn't answer in time — check that it's running on the shop network.");
}

// fetch()-shaped call to "the agent". `path` is /discover | /list | /send | /read | /delete.
async function agentFetch_(path, opts){
  if (await agentLocalUp_()) return fetch(EMBROIDERY_AGENT_URL + path, opts);
  const b = opts && opts.body ? JSON.parse(opts.body) : {};
  const type = path.replace("/", "");
  return agentRelayCall_({ type, machineIp: b.machineIp, remoteDir: b.remoteDir, fileKey: b.fileKey, fileName: b.fileName });
}

async function checkSendAgent_(){
  if (await agentLocalUp_()) return true;
  return !!(await agentRelayStatus_(true)).online;
}

// A machine's LAN IP can change (DHCP), so the MAC is its stable identity and the scanner keeps
// the IP current. Before a list/upload, if it's been over an hour since discovery last confirmed
// this machine present (or we have a MAC but no IP), re-run discovery and, if the IP changed,
// persist it server-side (recordMachineDiscovery) so verifiedAt is stamped and the new IP sticks.
// Returns the machine to actually operate on — the freshened copy when we could confirm it, else
// the one passed in (so a machine with no MAC, or a down agent, still works with its stored IP).
const MACHINE_FRESH_MS = 60 * 60 * 1000; // 1 hour
function normalizeMac_(mac){ return String(mac || "").toLowerCase().replace(/[^0-9a-f]/g, ""); }
function machineIsFresh_(machine){
  if (!machine || !machine.ipAddress || !machine.verifiedAt) return false;
  const t = Date.parse(machine.verifiedAt);
  return !isNaN(t) && (Date.now() - t) < MACHINE_FRESH_MS;
}
// A human-readable "last verified present by the scanner" label for the Machines card.
function machineVerifiedLabel_(machine){
  if (!machine || !machine.verifiedAt) return "Not yet verified";
  const t = Date.parse(machine.verifiedAt);
  if (isNaN(t)) return "Not yet verified";
  const when = new Date(t).toLocaleString();
  return machineIsFresh_(machine) ? `Verified ${escapeHtml(when)}` : `Verified ${escapeHtml(when)} (stale — will rescan before use)`;
}
async function ensureMachineFresh_(machine){
  if (!machine || machineIsFresh_(machine)) return machine;
  if (!machine.macAddress) return machine; // no stable identity to rediscover by — use the stored IP
  let found = [];
  try {
    const r = await agentFetch_("/discover", { method: "GET" });
    const d = await r.json().catch(() => ({}));
    if (r.ok && d.status === "ok") found = d.machines || [];
  } catch (e) { return machine; } // agent down — fall back to the stored IP (the op itself will report if unreachable)
  const match = found.find(f => normalizeMac_(f.mac) === normalizeMac_(machine.macAddress));
  if (!match || !match.ip) return machine; // not on the network right now — use the stored IP
  try {
    const res = await machineApi_({ action: "recordMachineDiscovery", discovered: [{ mac: match.mac, ip: match.ip }] });
    const updated = (res.machines || []).find(m => m.id === machine.id);
    if (updated) {
      if (window._mchCtx && Array.isArray(window._mchCtx.machines)) {
        const i = window._mchCtx.machines.findIndex(m => m.id === updated.id);
        if (i >= 0) window._mchCtx.machines[i] = updated;
      }
      if (window._mfCtx && Array.isArray(window._mfCtx.machines)) {
        const i = window._mfCtx.machines.findIndex(m => m.id === updated.id);
        if (i >= 0) window._mfCtx.machines[i] = updated;
      }
      return updated;
    }
  } catch (e) { /* persistence failed — still use the IP we just discovered */ }
  return { ...machine, ipAddress: match.ip, verifiedAt: new Date().toISOString() };
}

// Gets a signed 60-second download link for a machine file — always the stitch file
// (machineFileKey/machineFileName), never the native design-software project file, which a
// machine can't run — then hands the agent that link plus the target machine's IP/EMB-dir so it
// can fetch and send it in one step; the file's bytes never pass through this browser tab.
// `file` is anything with {machineFileKey, machineFileName} — a Run Order job's `.design`, or a
// design version picked directly on the Machine Files screen.
async function sendDesignToMachine_(file, machine){
  if (!file || !file.machineFileKey) { showToast("No machine file uploaded for this design yet.", true); return false; }
  if (!machine) { showToast("Pick a machine first.", true); return false; }
  machine = await ensureMachineFresh_(machine); // refresh the IP via discovery if it's gone stale
  if (!machine.ipAddress) { showToast(`${machine.name} has no IP address yet — run "Scan for machines" in Machines to find it.`, true); return false; }
  // If the machine already has a file with this design's base name, this is a resend (the machine
  // stores files as <base>.<NNN>, so the names won't match exactly — compare base names). Best-effort:
  // a listing failure just means we send without the "resend" wording, never a blocked send.
  let already = false;
  try { already = machineHasFile_(await listMachineFiles_(machine), file.machineFileName); } catch (e) {}
  try {
    // Loopback agent: it downloads the file itself, so hand it a signed 60 s link now. Relay agent: the
    // server mints that link when the agent picks the job up (a queued job must not carry a stale one),
    // so only the file reference goes in the job.
    let downloadUrl = "";
    if (await agentLocalUp_()) {
      const linkRes = await fetch("/api/design", { method: "POST", headers: { "Content-Type": "application/json", "X-Admin-Key": adminKey || "" },
        body: JSON.stringify({ key: file.machineFileKey }) });
      const linkData = await linkRes.json().catch(() => ({ status: "error", message: "Server error (" + linkRes.status + ")" }));
      if (!linkRes.ok || linkData.status === "error") throw new Error((linkData && linkData.message) || "Could not get a download link");
      downloadUrl = location.origin + linkData.url;
    }
    const sendRes = await agentFetch_("/send", { method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ downloadUrl, fileKey: file.machineFileKey, machineIp: machine.ipAddress, remoteDir: machine.embDir || "/EMB", fileName: file.machineFileName || "design.dst" }) });
    const sendData = await sendRes.json().catch(() => ({ status: "error", message: "Send agent returned an error (" + sendRes.status + ")" }));
    if (!sendRes.ok || sendData.status !== "ok") throw new Error((sendData && sendData.message) || "Send failed");
    showToast(`${already ? "Resent" : "Sent"} "${file.machineFileName}" to ${machine.name}.`);
    return true;
  } catch (e) {
    const notRunning = /Failed to fetch|NetworkError|Load failed/i.test(e.message || "");
    showToast(notRunning ? "Send agent isn't reachable — see the send-agent's README (it's a separate download)." : e.message, true);
    return false;
  }
}

// A machine stores an uploaded design as "<base>.<NNN>" (the ".DST" is stripped and a sequence
// number appended), so a sent file never matches its on-machine name exactly. Compare BASE names
// instead: strip the one trailing ".<ext-or-sequence>" segment from each, case-insensitively.
function fileBaseKey_(name){ return String(name || "").replace(/\.[^.]*$/, "").trim().toLowerCase(); }
function machineHasFile_(files, machineFileName){
  const base = fileBaseKey_(machineFileName);
  return !!base && (files || []).some(f => fileBaseKey_(f.name) === base);
}

// Lists the files currently in a machine's EMB directory via the local agent.
async function listMachineFiles_(machine){
  machine = await ensureMachineFresh_(machine); // refresh the IP via discovery if it's gone stale
  const r = await agentFetch_("/list", { method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ machineIp: machine.ipAddress, remoteDir: machine.embDir || "/EMB" }) });
  const d = await r.json().catch(() => ({ status: "error", message: "Send agent returned an error (" + r.status + ")" }));
  if (!r.ok || d.status !== "ok") throw new Error((d && d.message) || "Could not list files");
  return d.files || [];
}

// Copies one file off a machine (the agent's /read): `storedName` exactly as the listing shows it ("LOGO.012").
// What comes back is the machine's stored form — a DST-style header with Barudan records — whatever was sent to
// it, so it's named <base>.DSB. → {name, bytes: Uint8Array}.
function machineDownloadName_(storedName){
  const base = String(storedName || "").replace(/\.[^.]*$/, "").trim() || String(storedName || "design").trim();
  return base.replace(/[\u0000-\u001f\u007f\/\\:*?"<>|]/g, "_") + ".DSB";
}
async function readMachineFile_(machine, storedName){
  machine = await ensureMachineFresh_(machine);
  const r = await agentFetch_("/read", { method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ machineIp: machine.ipAddress, fileName: storedName }) });
  const d = await r.json().catch(() => ({ status: "error", message: "Send agent returned an error (" + r.status + ")" }));
  if (!r.ok || d.status !== "ok") {
    // An agent from before /read: the local one answers 404, a relay one "Unknown job type."
    if (r.status === 404 || /unknown job type/i.test((d && d.message) || "")) {
      throw new Error("The send agent on the shop computer is an older version — update it (see the send-agent's README — it's a separate download) to copy files off a machine.");
    }
    throw new Error((d && d.message) || "Could not copy the file");
  }
  const bin = atob(d.dataBase64 || "");
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return { name: machineDownloadName_(storedName), bytes };
}
function saveDownload_(blob, filename){
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
}
// Copies the files named (as listed) off the machine, one after another, and saves them: one file as itself,
// several as one .zip. `report(text)` shows progress. A file that can't be read is left out and named.
async function downloadMachineFiles_(machine, storedNames, report){
  const got = [], failed = [];
  for (let i = 0; i < storedNames.length; i++) {
    report(`Copying ${i + 1} of ${storedNames.length} from ${machine.name}…`);
    try { got.push(await readMachineFile_(machine, storedNames[i])); }
    catch (e) {
      failed.push({ name: storedNames[i], message: e.message });
      if (/older version|isn't online|didn't answer|not reachable|Failed to fetch/i.test(e.message)) break; // no point trying the rest
    }
  }
  // Two files can share a base name (LOGO.003 and LOGO.017): number the second.
  const seen = new Map();
  for (const f of got) {
    const k = f.name.toLowerCase(), n = seen.get(k) || 0;
    seen.set(k, n + 1);
    if (n) f.name = f.name.replace(/\.DSB$/, ` (${n + 1}).DSB`);
  }
  if (got.length === 1) saveDownload_(new Blob([got[0].bytes], { type: "application/octet-stream" }), got[0].name);
  else if (got.length > 1) saveDownload_(makeZip_(got), `${machine.name.replace(/[^\w .-]/g, "_")} files ${new Date().toISOString().slice(0, 10)}.zip`);
  const msg = got.length
    ? `Downloaded ${got.length} file${got.length === 1 ? "" : "s"}${got.length > 1 ? " (one .zip)" : ""}.`
    : "Nothing was downloaded.";
  report(failed.length ? `${msg} Couldn't copy ${failed.map(f => f.name).join(", ")}: ${failed[0].message}` : msg);
  return { got, failed };
}

// Deletes one file from a machine's EMB directory via the local agent.
async function deleteMachineFile_(machine, fileName){
  machine = await ensureMachineFresh_(machine); // refresh the IP via discovery if it's gone stale
  const r = await agentFetch_("/delete", { method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ machineIp: machine.ipAddress, remoteDir: machine.embDir || "/EMB", fileName }) });
  const d = await r.json().catch(() => ({ status: "error", message: "Send agent returned an error (" + r.status + ")" }));
  if (!r.ok || d.status !== "ok") throw new Error((d && d.message) || "Delete failed");
}

// Pure, unit-tested-in-spirit scoring: same hoop already mounted → 0 (free); a design with no
// required hoop → 0 (nothing to check); either side of the swap being a cap frame → the largest
// cost, since that's the one change confirmed to be the most time-consuming; any other swap
// between two non-cap hoops → a small fixed cost.
function hoopChangeCost_(machine, requiredHoopId, hoopsById){
  if (!requiredHoopId) return HOOP_CHANGE_COST_SAME;
  if (machine.currentHoopId === requiredHoopId) return HOOP_CHANGE_COST_SAME;
  const cur = machine.currentHoopId ? hoopsById[machine.currentHoopId] : null;
  const req = hoopsById[requiredHoopId];
  if ((cur && cur.isCapFrame) || (req && req.isCapFrame)) return HOOP_CHANGE_COST_CAP;
  return HOOP_CHANGE_COST_SWAP;
}

// For each colour the design uses (in its colour-change order), find which machine needle
// currently carries that thread — that's the needle to run this colour on. The design's colour
// order is INDEPENDENT of the physical needle numbers (colour 1 might live on needle 15, colour 2
// on needle 1, colour 3 back on needle 15), so we match by THREAD, never by position. A colour
// loaded on a needle → ready (tells the operator which needle); a colour not loaded on any needle
// → load it from the rack. `machineNeedle` is the lowest needle that has it; `machineNeedles` lists
// all of them (a colour can be on more than one needle).
function needleReadiness_(threadColors, machineNeedles){
  const needlesByThread = {};
  for (const n of Object.keys(machineNeedles || {})) {
    const tid = (machineNeedles || {})[n];
    if (tid != null) (needlesByThread[tid] = needlesByThread[tid] || []).push(Number(n));
  }
  return (threadColors || []).map(tc => {
    const needles = (needlesByThread[tc.threadId] || []).slice().sort((a, b) => a - b);
    return { needle: tc.needle, threadId: tc.threadId,
      status: needles.length ? "ready" : "load",
      machineNeedle: needles.length ? needles[0] : null, machineNeedles: needles };
  });
}

// Eligible machines are only those supporting the design's required hoop (or every machine, if
// the design has none); the proposal is whichever eligible machine has the lowest hoop-change cost.
// The hoops a hooping can run in (migrations/0032: a hooping — or design — may allow several, e.g.
// a 6.9" or a 7.7" x 12.5"); an older single-hoop design object gives [hoopId].
function requiredHoopIds_(x){
  if (!x) return [];
  if (Array.isArray(x.hoopIds) && x.hoopIds.length) return x.hoopIds.map(Number);
  return x.hoopId ? [Number(x.hoopId)] : [];
}
// The hoop this machine would use for the hooping: one of the allowed hoops it supports, cheapest
// change first (already mounted = free). null when nothing is required or it supports none.
function hoopForMachine_(machine, x, hoopsById){
  const req = requiredHoopIds_(x).filter(h => (machine.hoopIds || []).includes(h));
  let best = null, bestCost = Infinity;
  for (const h of req) { const c = hoopChangeCost_(machine, h, hoopsById); if (c < bestCost) { bestCost = c; best = h; } }
  return best;
}
function minHoopCost_(machine, x, hoopsById){
  const h = hoopForMachine_(machine, x, hoopsById);
  return h == null ? HOOP_CHANGE_COST_SAME : hoopChangeCost_(machine, h, hoopsById);
}
// Eligible machines support at least one of the hooping's hoops (any machine when none is set);
// the proposal is the one with the cheapest hoop change — a cap-frame swap costs the most.
function proposeMachine_(design, machines, hoopsById, excludeIds){
  const req = requiredHoopIds_(design);
  const busy = excludeIds || new Set();
  const eligible = machines.filter(m => !busy.has(m.id) && (!req.length || req.some(h => (m.hoopIds || []).includes(h))));
  let best = null, bestCost = Infinity;
  for (const m of eligible) {
    const cost = minHoopCost_(m, design, hoopsById);
    if (cost < bestCost) { bestCost = cost; best = m; }
  }
  return { eligible, proposedId: best ? best.id : null };
}

async function runOrderApi_(body){
  if (!adminKey) adminKey = (await adminLogin()) || "";
  if (!adminKey) throw new Error("Sign-in required");
  const r = await fetch("/api/orders", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ ...body, key: adminKey }) });
  const d = await r.json().catch(() => ({ status: "error", message: "Server error (" + r.status + ")" }));
  if (!r.ok || d.status === "error") throw new Error((d && d.message) || "Request failed");
  return d;
}

// Run Order with nothing ready to run: the orders whose blanks are ordered but not received yet, so
// the operator can see what's coming (and chase a late delivery). Each links to its shop's orders.
// A carrier tracking URL from a carrier name + number (mirrors email.js's trackingUrl).
function carrierTrackUrl_(carrier, tracking){
  const t = String(carrier || "").toLowerCase(), n = encodeURIComponent(String(tracking || "").trim());
  if (!n) return "";
  if (/\bups\b/.test(t) && !/usps/.test(t)) return "https://www.ups.com/track?tracknum=" + n;
  if (/fedex/.test(t)) return "https://www.fedex.com/fedextrack/?trknbr=" + n;
  if (/dhl/.test(t)) return "https://www.dhl.com/us-en/home/tracking/tracking-express.html?tracking-id=" + n;
  return "https://tools.usps.com/go/TrackConfirmAction?tLabels=" + n;
}
function blankStatusLabel_(s){
  return { TRANSIT: "In transit", DELIVERED: "Delivered", RETURNED: "Returned to sender",
    FAILURE: "Carrier issue", UNKNOWN: "Unknown", PRE_TRANSIT: "Pre-transit" }[String(s || "").toUpperCase()] || s || "";
}
// A tracking event's date/time, e.g. "Oct 8, 2:14 PM". Falls back to the raw string if unparseable.
function shipEventWhen_(iso){
  if(!iso) return "";
  const d = new Date(iso);
  return isNaN(d) ? String(iso) : d.toLocaleString(undefined, { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });
}
// The carrier's own latest wording — e.g. UPS "Loaded on Delivery Vehicle" — preferred over the
// coarse normalized status ("In transit"); falls back to the normalized label when no detail exists.
function blankStatusText_(s){
  const detail = (s.statusDetail || "").trim();
  const label = blankStatusLabel_(s.status);
  if(detail && label && detail.toLowerCase() !== label.toLowerCase()) return detail;  // show the specific wording
  return detail || label;
}
// One blank shipment as a line: 📦 carrier tracking# — carrier's latest status · when · View history
// (migrations/0039). Stashes the shipment (with events) so the history modal can look it up by id.
function blankShipmentLine_(s){
  const u = carrierTrackUrl_(s.carrier, s.trackingNumber), tn = escapeHtml(s.trackingNumber || "");
  const color = s.status === "DELIVERED" ? "#166534" : s.status === "RETURNED" || s.status === "FAILURE" ? "#b03a2e" : "#555";
  const status = blankStatusText_(s);
  const when = s.statusDate ? ` <span style="color:#888;">· ${escapeHtml(shipEventWhen_(s.statusDate))}</span>` : "";
  let hist = "";
  if(s.id != null){
    (window._blankShipments = window._blankShipments || {})[s.id] = s;
    if((s.events || []).length) hist = ` <a href="#" onclick="showShipmentHistoryModal_(${Number(s.id)});return false;" style="font-size:11px;">View history</a>`;
  }
  return `<div style="color:${color};">📦 ${escapeHtml(s.carrier || "")} ${u ? `<a href="${u}" target="_blank" rel="noopener">${tn}</a>` : tn}${status ? " — " + escapeHtml(status) : ""}${when}${hist}</div>`;
}
// Full per-scan carrier history for one shipment (its events were loaded with the order). Read-only
// modal; closes on ✕ / Close / Escape only (never a backdrop click — project rule, test46).
function showShipmentHistoryModal_(id){
  const s = (window._blankShipments || {})[id];
  if(!s){ showToast("No tracking history is available for this shipment yet.", true); return; }
  const events = (s.events || []);
  const rowsHtml = events.length ? events.map(e => {
    const loc = e.location ? ` <span style="color:#888;">· ${escapeHtml(e.location)}</span>` : "";
    const sub = (e.statusDetail && e.statusDetail.toLowerCase() !== blankStatusLabel_(e.status).toLowerCase())
      ? `<div style="font-size:12px;color:#555;">${escapeHtml(blankStatusLabel_(e.status) || e.status || "")}</div>` : "";
    return `<tr>
      <td style="padding:6px 10px;border-bottom:1px solid #eee;white-space:nowrap;color:#666;font-size:12px;vertical-align:top;">${escapeHtml(shipEventWhen_(e.occurredAt))}</td>
      <td style="padding:6px 10px;border-bottom:1px solid #eee;">${escapeHtml(e.statusDetail || blankStatusLabel_(e.status) || e.status || "")}${loc}${sub}</td>
    </tr>`; }).join("")
    : `<tr><td colspan="2" style="padding:12px;color:#888;">No carrier scans recorded yet. Status is checked in the daily roll-up, or use “Check now” on the Communications page.</td></tr>`;
  const u = carrierTrackUrl_(s.carrier, s.trackingNumber);
  const ov = document.createElement("div"); ov.className = "admin-pass-overlay"; ov.style.zIndex = "1003";
  ov.innerHTML = `<div class="admin-pass-box" style="max-width:560px;width:calc(100% - 32px);max-height:85vh;overflow-y:auto;">
      <div style="display:flex;justify-content:space-between;align-items:start;gap:10px;">
        <div><div style="font-weight:700;font-size:16px;">Tracking history</div>
          <div style="font-size:13px;color:#555;margin-top:2px;">${escapeHtml(s.carrier || "")} ${u ? `<a href="${u}" target="_blank" rel="noopener">${escapeHtml(s.trackingNumber || "")}</a>` : escapeHtml(s.trackingNumber || "")}</div></div>
        <button type="button" class="shClose admin-btn" style="padding:2px 8px;">✕</button>
      </div>
      <table style="width:100%;border-collapse:collapse;font-size:14px;margin-top:12px;color:#111;background:#fff;"><tbody>${rowsHtml}</tbody></table>
      <div class="admin-pass-actions"><button type="button" class="shClose2 admin-pass-submit">Close</button></div>
    </div>`;
  document.body.appendChild(ov);
  const finish = () => { if(ov.parentNode) document.body.removeChild(ov); };
  ov.querySelector(".shClose").onclick = finish;
  ov.querySelector(".shClose2").onclick = finish;
  document.addEventListener("keydown", function esc(e){ if(e.key === "Escape"){ finish(); document.removeEventListener("keydown", esc); } }, { once: true });
}
// Orders → stage "Use blanks from stock" and the run pages' "Use from stock": the order's blanks come off
// the shelf instead of from a supplier — marked ordered and received now; they come out of stock when
// the order is made. The server checks the stock covers them and says what's short when it doesn't.
async function useBlanksFromStock_(orgId, orderId){
  if (!await askConfirm_(`Use blanks from stock for order ${orderId}? They're marked received now, and come out of stock when the order is made.`)) return false;
  try {
    const d = await hoopApi_({ action: "useBlanksFromStock", org: orgId, orderId });
    const what = (d.lines || []).map(l => `${l.qty} × ${l.blank}${l.color ? " " + l.color : ""}${l.size && l.size !== "OSFA" ? " " + l.size : ""}`).join(", ");
    showToast(`Blanks from stock: ${what}.`);
    return true;
  } catch (e) { showToast(e.message, true); return false; }
}
async function paidUnrunUseStock_(btn){
  btn.disabled = true;
  if (await useBlanksFromStock_(btn.dataset.org, btn.dataset.order)) {
    const app = document.getElementById("app");
    if (/^#runtransfer/.test(location.hash)) await keepView_(() => renderRunTransfer(app)); else await refreshRunOrder_();
  } else btn.disabled = false;
}
function waitingOnBlanksHtml_(orders){
  if (!orders || !orders.length) return "";
  const day = (s) => { const m = String(s || "").match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? `${+m[2]}/${+m[3]}/${m[1]}` : ""; };
  const today = new Date().toISOString().slice(0, 10);
  const orgName = (id) => ((adminOrgs || []).find(o => o.orgId === id) || {}).name || id;
  const sizeOf = (it) => itemHasSize_(it) ? " · " + it.size : "";
  const cards = orders.map(o => {
    const late = o.blankEstDelivery && String(o.blankEstDelivery).slice(0, 10) < today;
    const vendor = [o.blankVendor, o.blankVendorOrderId].filter(Boolean).map(escapeHtml).join(" · ");
    return `<div class="ro-waiting-card" style="border:1px solid #ddd;border-radius:8px;padding:10px 12px;background:#fff;color:#1a1a1a;">
      <div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;">
        <div><b>${escapeHtml(o.customerName)}</b> <a href="#orders/${encodeURIComponent(o.orgId)}" style="color:inherit;font-size:13px;">${escapeHtml(o.orderId)}</a>
          <div style="font-size:12px;color:#777;">${escapeHtml(orgName(o.orgId))}</div></div>
        <div style="text-align:right;font-size:13px;">Blanks ordered ${escapeHtml(day(o.blankOrderedAt))}${vendor ? `<div style="font-size:12px;color:#777;">${vendor}</div>` : ""}
          ${o.blankEstDelivery ? `<div style="font-size:12px;${late ? "color:#b03a2e;font-weight:600;" : "color:#777;"}">${late ? "Overdue — expected " : "Expected "}${escapeHtml(day(o.blankEstDelivery))}</div>` : ""}</div>
      </div>
      <div style="font-size:13px;margin-top:6px;">${o.items.map(it => `${it.qty} × ${escapeHtml(it.name)}${escapeHtml(sizeOf(it))}${it.shipped ? ` <span style="color:#b45309;font-size:12px;">· shipped</span>` : ""}`).join("<br>")}</div>
      ${(o.shipments || []).length ? `<div style="margin-top:6px;font-size:12px;">${o.shipments.map(blankShipmentLine_).join("")}</div>` : ""}
    </div>`;
  }).join("");
  return `<h3 style="margin:8px 0 8px;font-size:15px;color:#1a1a1a;">Waiting on blanks (${orders.length})</h3>
    <div class="ro-waiting" style="display:flex;flex-direction:column;gap:8px;">${cards}</div>`;
}

// Every paid order not yet run (migrations/0038), due-date first — a prioritized backlog shown on
// both run pages so nothing with a due date is missed, whether or not it's ready to run right now.
// Collapsible; starts open. Each row links to its shop's orders.
function paidUnrunHtml_(orders){
  if (!orders || !orders.length) return "";
  const rows = orders.map(o => {
    const items = o.items.map(it => `${it.qty} × ${escapeHtml(it.name)}${it.size && it.size !== "OSFA" ? " · " + escapeHtml(it.size) : ""}`).join(", ");
    return `<tr style="border-bottom:1px solid #eee;">
      <td style="padding:5px 8px;white-space:nowrap;">${o.dueDate ? dueBadge_(o.dueDate) : `<span style="color:#999;">—</span>`}</td>
      <td style="padding:5px 8px;white-space:nowrap;color:#777;">${escapeHtml(new Date(o.placedAt).toLocaleDateString())}</td>
      <td style="padding:5px 8px;"><b>${escapeHtml(o.customerName)}</b> <a href="#orders/${encodeURIComponent(o.orgId)}" style="color:inherit;font-size:12px;">${escapeHtml(o.orderId)}</a><div style="font-size:12px;color:#777;">${escapeHtml(o.orgName)}</div></td>
      <td style="padding:5px 8px;font-size:13px;">${items}</td>
      <td style="padding:5px 8px;white-space:nowrap;font-size:12px;">${o.needsBlanks === false ? (o.allFromStock ? `<span style="color:#166534;">From stock</span>` : `<span style="color:#666;">No blank needed</span>`) : o.blankReceived ? `<span style="color:#166534;">Blanks in</span>` : o.blankOrdered ? `<span style="color:#b45309;">Blanks ordered</span>`
        : o.blanksInStock ? `<span style="color:#166534;">In stock</span> <button type="button" class="admin-btn ro-use-stock" data-org="${escapeHtml(o.orgId)}" data-order="${escapeHtml(o.orderId)}" onclick="paidUnrunUseStock_(this)" title="Take this order's blanks from stock on hand" style="padding:2px 8px;font-size:11px;margin-left:4px;">Use from stock</button>`
        : `<span style="color:#b03a2e;">Blanks not ordered yet</span>`}</td>
    </tr>`;
  }).join("");
  return `<details open style="margin:4px 0 16px;"><summary style="cursor:pointer;font-size:15px;font-weight:700;color:#1a1a1a;">Paid, not yet run — by due date (${orders.length})</summary>
    <div style="overflow:auto;border:1px solid #eee;border-radius:8px;margin-top:8px;"><table style="width:100%;border-collapse:collapse;font-size:13px;color:#1a1a1a;background:#fff;">
      <thead><tr style="text-align:left;background:#f3f4f6;"><th style="padding:5px 8px;">Due</th><th style="padding:5px 8px;">Placed</th><th style="padding:5px 8px;">Customer</th><th style="padding:5px 8px;">Items</th><th style="padding:5px 8px;">Blanks</th></tr></thead>
      <tbody>${rows}</tbody></table></div></details>`;
}

// A due-date chip for the run queues (migrations/0038): red when overdue, amber within 3 days.
function dueBadge_(dueDate){
  if(!dueDate) return "";
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const d = new Date(dueDate + "T00:00:00");
  const days = Math.round((d - today) / 86400000);
  const color = days < 0 ? "#b03a2e" : days <= 3 ? "#b45309" : "#2563eb";
  const txt = days < 0 ? `${-days} day${days === -1 ? "" : "s"} overdue` : days === 0 ? "due today" : `due in ${days} day${days === 1 ? "" : "s"}`;
  return `<span style="display:inline-block;margin-top:4px;font-size:12px;font-weight:700;color:${color};">⏱ Due ${escapeHtml(dueDate)} · ${txt}</span>`;
}
// opts.soft: after an action, refill the cards in place (no page rebuild, no "Loading…") — see refreshRunOrder_.
async function renderRunOrder(app, opts){
  const soft = !!(opts && opts.soft && document.getElementById("roBody"));
  if (!soft) {
  adminSetHash("runorder");
  document.title = adminTitle_("Run Order");
  app.innerHTML = `
    ${adminPageHead_("Run Order")}
    <div class="admin-panel" style="--org-accent:var(--accent);max-width:1100px;margin:8px auto 60px;">
      <div id="roAgentStatus" style="font-size:12px;color:#888;margin-bottom:10px;">Checking send agent&hellip;</div>
      <div id="roBody" data-keep-scroll="runorder" style="color:#888;font-size:15px;max-height:72vh;overflow-y:auto;">Loading&hellip;</div>
    </div>`;
  }
  if (!soft) checkSendAgent_().then(ok => {
    const el = document.getElementById("roAgentStatus");
    if (el) el.innerHTML = ok ? `<span style="color:#2c6b2f;">● Send agent: connected</span>`
      : `<span style="color:#b03a2e;">● Send agent: not running</span> — start the send-agent (a separate download) to enable "Send design to machine"`;
  });
  if (!adminKey) adminKey = (await adminLogin()) || ""; // resolve once before firing these in parallel
  let queue = [], waiting = [], paidUnrun = [], machines = [], hoops = [], threads = [], activeRuns = [], abortReasons = [], needleSizes = [];
  try {
    const [q, m, h, t, ar, rsn] = await Promise.all([runOrderApi_({ action: "getProductionQueue" }), machineApi_({ action: "listMachines" }),
      hoopApi_({ action: "listHoops" }), threadApi_({ action: "listThreads" }),
      runOrderApi_({ action: "listActiveRuns" }), runOrderApi_({ action: "listAbortReasons" })]);
    queue = q.queue || []; waiting = q.waitingOnBlanks || []; paidUnrun = q.paidUnrun || []; machines = m.machines || []; hoops = h.hoops || []; threads = t.threads || [];
    activeRuns = ar.activeRuns || []; abortReasons = rsn.reasons || []; needleSizes = q.needleSizes || [];
  } catch (e) { document.getElementById("roBody").innerHTML = `<div style="color:#b03a2e;">${escapeHtml(e.message)}</div>`; return; }
  // A running run marks its piece in progress AND its machine busy. Group running runs per line item.
  const busyMachineIds = new Set(activeRuns.map(r => r.machineId).filter(id => id != null));
  const runningByItem = {};
  for (const r of activeRuns) (runningByItem[r.itemId] = runningByItem[r.itemId] || []).push(r);
  queue.forEach(job => { job.runningRuns = runningByItem[job.itemId] || []; });
  const hoopsById = Object.fromEntries(hoops.map(h => [h.id, h]));
  const threadLabel_ = (id) => { const t = threads.find(x => x.id === id); return t ? `${t.brand}${t.type ? " " + t.type : ""}${t.weight ? " " + t.weight : ""} ${t.code} — ${t.name}` : "(unknown thread)"; };
  const threadSwatch_ = (id) => { const t = threads.find(x => x.id === id); return t && t.colorHex ? `<span style="display:inline-block;width:11px;height:11px;border-radius:2px;background:#${escapeHtml(t.colorHex)};border:1px solid #999;vertical-align:middle;margin-right:4px;"></span>` : ""; };
  // Preserve any machine picks the operator already made across this full re-fetch (the
  // machine-select's onchange re-renders the whole screen rather than patching one card).
  const prevSelected = (window._roCtx && window._roCtx.selected) || {};
  window._roCtx = { queue, machines, hoops, threads, hoopsById, selected: prevSelected, activeRuns, abortReasons, busyMachineIds };

  const body = document.getElementById("roBody");
  if (!queue.length) {
    body.innerHTML = paidUnrunHtml_(paidUnrun) +
      `<div style="color:#888;padding:16px 0;">Nothing ready to run — every paid order with its blanks received and its design ready is already manufactured.</div>
      ${waitingOnBlanksHtml_(waiting)}`;
    return;
  }

  // Group: blank productType -> blank name+size -> jobs. Items with no linked blank fall into
  // a single "Unlinked" bucket so they're still visible, not silently dropped.
  const groups = {};
  for (const job of queue) {
    const typeKey = (job.blank && job.blank.productType) || (job.noBlankNeeded ? "No blank" : "Unlinked");
    const blankKey = job.blank ? `${job.blank.name}${job.blank.color ? " — " + job.blank.color : ""}` : job.noBlankNeeded ? "No blank needed" : "No blank linked";
    groups[typeKey] = groups[typeKey] || {};
    const sizeKey = (job.blank && job.blank.size) || job.itemSize || "—";
    const key = blankKey + "|" + sizeKey;
    groups[typeKey][key] = groups[typeKey][key] || { blankKey, sizeKey, jobs: [] };
    groups[typeKey][key].jobs.push(job);
  }

  // Per design colour: which machine needle it's on (→ Needle N), or load it from the rack.
  const needleBadge_ = (st) => {
    if (!st) return "";
    if (st.status === "ready") return `<span style="color:#2c6b2f;font-weight:600;">→ Needle ${st.machineNeedle}${st.machineNeedles.length > 1 ? " (or " + st.machineNeedles.slice(1).join(", ") + ")" : ""}</span>`;
    return `<span style="color:#b03a2e;font-weight:600;">⬇ Load from rack</span>`;
  };

  // One card per PHYSICAL PIECE, showing the piece's CURRENT HOOPING (migrations/0032 — a piece can
  // need several: front, back, a pick-list closure, …). A card is either RUNNING (bound to its
  // production_runs row — machine locked, Mark done finishes & times that hooping, Abort cancels it)
  // or IDLE (pick a machine, Start to time the hooping, or the untimed Mark done). After a hooping
  // is done the same piece comes back at its next hooping with the best machine proposed, until all
  // are done and the piece is made. pkey = "<itemId>#<piece>#<stepNo>" keys a card's machine pick;
  // busy machines are kept out of idle pickers so two cards can't grab the same machine.
  const stepOf_ = (job, stepNo) => (job.steps && job.steps[stepNo - 1]) || legacyStepFromDesign_(job.design);
  window._roCtx.cards = {};
  window._roCtx.cardHtml = (job, piece) => jobCardHtml_(job, piece);   // one card redrawn on its own (machine pick)
  function jobCardHtml_(job, piece){
    const stepNo = piece.running ? piece.running.stepNo : piece.nextStepNo;
    const step = stepOf_(job, stepNo);
    const stepCount = (job.steps && job.steps.length) || 1;
    const pkey = job.itemId + "#" + (piece.pieceNo != null ? piece.pieceNo : "n" + piece.idx) + "#" + stepNo;
    window._roCtx.cards[pkey] = { job, piece, step };
    const run = piece.running;
    const pieceAttr = piece.pieceNo != null ? piece.pieceNo : "";
    const ids = `data-pkey="${pkey}" data-itemid="${job.itemId}" data-orgid="${escapeHtml(job.orgId)}" data-orderid="${escapeHtml(job.orderId)}" data-piece="${pieceAttr}" data-step="${stepNo}"`;
    let machine, machineBox, actions;
    if (run) {
      machine = machines.find(m => m.id === run.machineId) || null;
      const since = run.startedAt ? new Date(run.startedAt).toLocaleString() : "";
      const hoopNow = run.hoopId && hoopsById[run.hoopId] ? ` · ${escapeHtml(hoopsById[run.hoopId].name)}` : "";
      machineBox = `<div style="text-align:right;min-width:180px;">
          <label style="font-size:11px;font-weight:600;color:#888;display:block;">Machine</label>
          <div style="font-size:13px;font-weight:700;color:#2c6b2f;">● Running on ${escapeHtml(run.machineName || (machine && machine.name) || "machine")}${hoopNow}</div>
          <div style="font-size:11px;color:#888;">since ${escapeHtml(since)}</div>
        </div>`;
      actions = `
          <button type="button" class="run-complete-btn" data-runid="${run.runId}" ${ids}
            style="min-height:56px;padding:14px 28px;font-size:16px;font-weight:700;border-radius:10px;border:none;background:var(--org-accent,#2c6b2f);color:#fff;cursor:pointer;flex:2;">
            ${stepNo < stepCount ? `Mark hooping ${stepNo} done` : "Mark piece done"}
          </button>
          <button type="button" class="run-abort-btn admin-btn-danger" data-runid="${run.runId}" ${ids}
      style="min-height:56px;padding:14px 20px;font-size:14px;font-weight:700;border-radius:10px;border:1px solid #b03a2e;cursor:pointer;flex:1;">
            Abort job
          </button>`;
    } else {
      const state = window._roCtx.selected[pkey] || {};
      const { eligible, proposedId } = proposeMachine_(step, machines, hoopsById, window._roCtx.busyMachineIds);
      const selectedId = state.machineId !== undefined ? state.machineId : proposedId;
      machine = machines.find(m => m.id === selectedId);
      const blocked = step.blocked || "";
      machineBox = `<div style="text-align:right;min-width:180px;">
          <label style="font-size:11px;font-weight:600;color:#888;display:block;">Machine</label>
          <select class="run-machine-select" data-pkey="${pkey}" style="font-size:13px;padding:5px 8px;min-height:36px;">
            ${eligible.length ? eligible.map(m => `<option value="${m.id}" ${m.id === selectedId ? "selected" : ""}>${m.id === proposedId ? "Propose: " : ""}${escapeHtml(m.name)}${minHoopCost_(m, step, hoopsById) >= HOOP_CHANGE_COST_CAP ? " (cap swap)" : ""}${(m.maintenanceDue || []).some(t => t.status === "due") ? " ⚠ maintenance due" : ""}</option>`).join("")
              : `<option value="">No free eligible machine</option>`}
          </select>
          ${machine && requiredHoopIds_(step).length ? `<div style="font-size:11px;color:#666;margin-top:3px;">Hoop: ${escapeHtml((hoopsById[hoopForMachine_(machine, step, hoopsById)] || {}).name || "—")}</div>` : ""}
          ${machine ? runMaintWarnHtml_(machine) : ""}
        </div>`;
      const off = blocked || !eligible.length;
      actions = blocked ? `
          <div style="flex:1 1 100%;color:#b03a2e;font-size:14px;font-weight:600;">⚠ ${escapeHtml(blocked)}</div>
          ${step.kind === "itemDesign" ? `<button type="button" class="run-upload-item-design-btn" ${ids} data-design-loc="${escapeHtml(step.itemDesignLocation || "")}" data-design-label="${escapeHtml(step.label || "")}"
            style="min-height:48px;padding:10px 18px;font-size:14px;font-weight:700;border-radius:10px;border:1px solid var(--org-accent,#2c6b2f);background:#fff;color:var(--org-accent,#2c6b2f);cursor:pointer;">
            Upload order design…</button>` : ""}` : `
          ${step.machineFileKey ? `
          <button type="button" class="run-send-btn" ${ids}
            style="min-height:56px;padding:14px 18px;font-size:14px;font-weight:700;border-radius:10px;border:1px solid var(--org-accent,#2c6b2f);background:#fff;color:var(--org-accent,#2c6b2f);cursor:pointer;flex:1;">
            Send design to machine
          </button>` : ""}
          <button type="button" class="run-start-btn" ${ids} ${off ? "disabled" : ""}
            style="min-height:56px;padding:14px 22px;font-size:15px;font-weight:700;border-radius:10px;border:none;background:var(--org-accent,#2c6b2f);color:#fff;cursor:pointer;flex:2;${off ? "opacity:.5;cursor:not-allowed;" : ""}">
            ${stepCount > 1 ? `Start hooping ${stepNo}` : "Start job"}
          </button>
          <button type="button" class="run-btn" ${ids}
            style="min-height:56px;padding:14px 16px;font-size:13px;font-weight:600;border-radius:10px;border:1px solid #ccc;background:#fff;color:#555;cursor:pointer;flex:1;" title="Record this hooping as done without timing it">
            Mark done (no timing)
          </button>`;
    }
    const readiness = machine ? needleReadiness_(step.threadColors, machine.needles) : [];
    // Recommended needle (migrations/0044): size from this hooping's thread weights, type from the blank.
    const needleRec = recommendedNeedle_(step.threadColors, threads, needleSizes, job.blank || (job.noBlankNeeded ? { none: true } : null));
    const pieceNoShown = piece.pieceNo != null ? piece.pieceNo : (job.manufacturedQty || 0) + piece.idx;
    const pieceLabel = job.qty > 1 ? ` · Piece ${pieceNoShown} of ${job.qty}` : "";
    const progress = stepCount > 1 ? `<div class="run-hoopings" style="margin-top:6px;font-size:12px;display:flex;flex-wrap:wrap;gap:4px;">
        ${job.steps.map(st => {
          const done = (piece.done || []).includes(st.stepNo), cur = st.stepNo === stepNo;
          return `<span style="padding:2px 8px;border-radius:999px;${done ? "background:#dcfce7;color:#166534;" : cur ? "background:#2c6b2f;color:#fff;" : "background:#eee;color:#666;"}">${done ? "✓" : cur ? "▶" : "○"} ${st.stepNo}. ${escapeHtml(st.label)}</span>`;
        }).join("")}</div>` : "";
    return `
      <div class="run-job-card" data-itemid="${job.itemId}" data-pkey="${pkey}" style="border:1px solid ${run ? "#2c6b2f" : "#ddd"};border-radius:10px;padding:16px;margin-bottom:14px;background:${run ? "#f3f9f4" : "#fff"};">
        <div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px;">
          <div style="display:flex;gap:12px;align-items:flex-start;">
            ${step.machineFileKey && /\.(dst|dsb)$/i.test(step.machineFileName || "") ? `<canvas class="run-job-canvas" data-pkey="${pkey}" width="150" height="150" title="Design preview" style="width:150px;height:150px;flex:0 0 auto;background:#faf9f6;border:1px solid #eee;border-radius:6px;"></canvas>` : ""}
            <div>
            ${stepCount > 1 ? `<div style="font-size:12px;font-weight:700;color:#2c6b2f;text-transform:uppercase;letter-spacing:.04em;">Hooping ${stepNo} of ${stepCount} · ${escapeHtml(step.label)}</div>` : ""}
            <div style="font-weight:700;font-size:16px;">${escapeHtml(step.designName || (step.designId ? "" : "No design linked") || "No design linked")}</div>
            <div style="font-size:13px;color:#666;margin-top:2px;">${escapeHtml(job.orgName)} · ${escapeHtml(job.customerName)}${pieceLabel} · ${escapeHtml(job.itemName)}${job.itemSize ? " (" + escapeHtml(job.itemSize) + ")" : ""}</div>
            ${dueBadge_(job.dueDate) ? `<div>${dueBadge_(job.dueDate)}</div>` : ""}
            ${job.activeItemCount > 1 ? `<div style="font-size:12px;color:#888;margin-top:2px;">+${job.activeItemCount - 1} more item${job.activeItemCount - 1 === 1 ? "" : "s"} on this order</div>` : ""}
            <div style="font-size:13px;color:#666;margin-top:6px;">
              Stabilizer: ${escapeHtml(step.stabilizer || "—")} &nbsp;·&nbsp;
              Hoop${(step.hoopNames || []).length > 1 ? "s" : ""}: ${escapeHtml((step.hoopNames || []).filter(Boolean).join(" or ") || "—")}
            </div>
            ${needleLineHtml_(needleRec)}
            ${runTransfersNoteHtml_(job)}
            ${progress}
            </div>
          </div>
          ${machineBox}
        </div>
        ${(step.threadColors || []).length ? `<div style="margin-top:12px;font-size:13px;">
          <b>Colors → machine needles</b>${machine ? " (run each color on the needle shown)" : " (pick a machine to see which needle has each color)"}:
          <div style="margin-top:4px;display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:4px;">
            ${step.threadColors.map((tc, i) => {
              const st = readiness[i];
              // A hooping that mixes thread weights needs different needle sizes on different needles: say which.
              const sz = needleRec.sizes.length > 1 && needleRec.perColor[i] && needleRec.perColor[i].size ? ` <span style="color:#666;">· ${escapeHtml(needleRec.perColor[i].size)} needle</span>` : "";
              return `<div style="font-size:12px;"><span style="color:#999;">${tc.needle}.</span> ${threadSwatch_(tc.threadId)}${escapeHtml(threadLabel_(tc.threadId))}${sz} ${needleBadge_(st)}</div>`;
            }).join("")}
          </div>
        </div>` : ""}
        <div style="margin-top:14px;display:flex;gap:10px;flex-wrap:wrap;">${actions}</div>
      </div>`;
  }

  // Expand each queued line into cards: one per piece already started (running, or between
  // hoopings), then one per piece not started yet (its hooping 1).
  const pieceCards_ = (job) => {
    let pieces = job.pieces;
    if (!pieces) { // a server without hoopings: running runs, then idle pieces
      pieces = (job.runningRuns || []).map(r => ({ pieceNo: null, done: [], nextStepNo: 1, running: Object.assign({ stepNo: 1 }, r) }));
    }
    const idle = job.idlePieces != null ? job.idlePieces
      : Math.max(0, Math.max(pieces.length, (job.remaining != null ? job.remaining : job.qty) || 1) - pieces.length);
    let out = "", n = 0;
    for (const p of pieces) out += jobCardHtml_(job, Object.assign({ idx: ++n }, p));
    for (let k = 0; k < idle; k++) out += jobCardHtml_(job, { pieceNo: null, done: [], nextStepNo: 1, running: null, idx: ++n });
    return out;
  };

  body.innerHTML = paidUnrunHtml_(paidUnrun) + Object.keys(groups).sort().map(typeKey => `
    <div style="margin-bottom:28px;">
      <h2 style="font-size:18px;margin:0 0 10px;text-transform:capitalize;">${escapeHtml(typeKey)}</h2>
      ${Object.values(groups[typeKey]).map(g => `
        <div style="margin-bottom:16px;">
          <div style="font-size:14px;font-weight:600;color:#555;margin-bottom:8px;">${escapeHtml(g.blankKey)} — ${escapeHtml(g.sizeKey)}</div>
          ${g.jobs.map(pieceCards_).join("")}
        </div>`).join("")}
    </div>`).join("");

  wireRunOrderHandlers_(body, queue);
  renderRunPreviews_();
  updateRunSendLabels_();
}

// After a Run Order action: reload the queue in place — the scroll and the other cards' machine picks stay — and
// flash the cards that are new (a piece's next hooping, a piece just started).
async function refreshRunOrder_(){
  const before = new Set(Object.keys((window._roCtx && window._roCtx.cards) || {}));
  await keepView_(() => renderRunOrder(document.getElementById("app"), { soft: true }));
  const now = Object.keys((window._roCtx && window._roCtx.cards) || {});
  if (before.size) flashRows_(now.filter(k => !before.has(k)).map(k => `.run-job-card[data-pkey="${k}"]`));
}
// One Run Order card redrawn from what's already loaded (no server call).
function redrawRunCard_(pkey, queue){
  const ctx = window._roCtx, card = ctx && ctx.cards && ctx.cards[pkey];
  const el = [...document.querySelectorAll(".run-job-card")].find(x => x.dataset.pkey === pkey);
  if (!card || !el || !ctx.cardHtml) return;
  const tmp = document.createElement("div"); tmp.innerHTML = ctx.cardHtml(card.job, card.piece);
  const fresh = tmp.firstElementChild;
  el.replaceWith(fresh);
  wireRunOrderHandlers_(fresh, queue);
  renderRunPreviews_(); updateRunSendLabels_();
}

// A queue job from a server that predates hoopings has only job.design: treat it as one hooping.
function legacyStepFromDesign_(design){
  return { stepNo: 1, label: design ? design.name : "", kind: "design", designId: design ? design.id : null,
    designName: design ? design.name : "", stabilizer: design ? design.stabilizer : "",
    hoopIds: design && design.hoopId ? [design.hoopId] : [], hoopNames: design && design.hoopName ? [design.hoopName] : [],
    threadColors: design ? design.threadColors || [] : [], machineFileKey: design ? design.machineFileKey : "",
    machineFileName: design ? design.machineFileName : "", blocked: "" };
}

// For each card's Send button, check (best-effort, cached per machine) whether that hooping's
// design is already on the machine it currently targets, and relabel "Send" → "Resend" so the
// operator knows before clicking. A listing failure leaves the default wording.
async function updateRunSendLabels_(){
  const ctx = window._roCtx; if (!ctx) return;
  window._roMachineFiles = window._roMachineFiles || {};
  for (const btn of document.querySelectorAll(".run-send-btn")) {
    const card = ctx.cards && ctx.cards[btn.dataset.pkey];
    if (!card || !card.step.machineFileName) continue;
    const machine = resolveSelectedMachine_(card.step, btn.dataset.pkey);
    if (!machine || !machine.ipAddress) continue;
    let files = window._roMachineFiles[machine.id];
    if (files === undefined) {
      try { files = await listMachineFiles_(machine); } catch (e) { files = null; }
      window._roMachineFiles[machine.id] = files;
    }
    if (!files) continue;
    if (machineHasFile_(files, card.step.machineFileName)) {
      btn.textContent = "Resend design (already on machine)";
      btn.dataset.exists = "1";
    } else {
      btn.textContent = "Send design to machine";
      btn.dataset.exists = "";
    }
  }
}

// Renders each card's hooping design onto its canvas, coloured by that hooping's thread map — same
// stitch-file pipeline (DST / DSB) as the Designs screen. Parsed files are cached by machine-file key.
async function renderRunPreviews_(){
  const ctx = window._roCtx; if (!ctx) return;
  const threadsById = {}; (ctx.threads || []).forEach(t => { threadsById[t.id] = t; });
  window._roDstCache = window._roDstCache || {};
  for (const canvas of document.querySelectorAll(".run-job-canvas")) {
    const card = ctx.cards && ctx.cards[canvas.dataset.pkey];
    if (!card || !card.step.machineFileKey) continue;
    const key = card.step.machineFileKey;
    const rows = (card.step.threadColors || []).slice().sort((a, b) => a.needle - b.needle).map(tc => ({ threadId: tc.threadId }));
    try {
      if (!window._roDstCache[key]) window._roDstCache[key] = parseStitchFile_(await fetchDesignFileBytes_(key), card.step.machineFileName || "");
      renderDstPreview_(canvas, window._roDstCache[key], dstColorForNeedle_(rows, threadsById));
    } catch (e) { /* leave the thumbnail blank if the file can't be read */ }
  }
}

// Which machine a card currently has selected — the operator's own pick (keyed by the card's pkey)
// or the proposed default for that hooping. Shared by Send / Start / Mark done.
function resolveSelectedMachine_(step, pkey){
  const state = (window._roCtx.selected[pkey]) || {};
  const { proposedId } = proposeMachine_(step, window._roCtx.machines, window._roCtx.hoopsById, window._roCtx.busyMachineIds);
  const machineId = state.machineId !== undefined ? state.machineId : proposedId;
  return window._roCtx.machines.find(m => m.id === machineId) || null;
}

function wireRunOrderHandlers_(body, queue){
  const cardFor_ = (btn) => (window._roCtx.cards || {})[btn.dataset.pkey];
  const pieceArg_ = (btn) => btn.dataset.piece === "" ? undefined : Number(btn.dataset.piece);
  const rerender_ = () => refreshRunOrder_();
  // What a finished hooping means for the piece, in words.
  const doneToast_ = (r, card) => {
    if (r && r.orderComplete) return `${card.job.orderId} fully manufactured.`;
    if (r && r.pieceComplete === false && r.nextStepNo) {
      const next = (card.job.steps || [])[r.nextStepNo - 1];
      return `Hooping done — next: ${next ? next.label : "hooping " + r.nextStepNo}.`;
    }
    return "Piece done.";
  };
  // Another machine: redraw just this card (hoop, needle readiness, Send label) — nothing else moves.
  body.querySelectorAll(".run-machine-select").forEach(sel => sel.onchange = () => {
    window._roCtx.selected[sel.dataset.pkey] = { machineId: sel.value ? Number(sel.value) : null };
    redrawRunCard_(sel.dataset.pkey, queue);
  });
  body.querySelectorAll(".run-send-btn").forEach(btn => btn.onclick = async () => {
    const card = cardFor_(btn); if (!card) return;
    const machine = resolveSelectedMachine_(card.step, btn.dataset.pkey);
    btn.disabled = true; const original = btn.textContent; btn.textContent = btn.dataset.exists === "1" ? "Resending…" : "Sending…";
    let ok = false;
    try { ok = await sendDesignToMachine_(card.step, machine); }
    finally { btn.disabled = false; btn.textContent = original; }
    if (ok && machine) { if (window._roMachineFiles) delete window._roMachineFiles[machine.id]; updateRunSendLabels_(); }
  });
  // Untimed: records this hooping done (and the piece, when it was the last one).
  body.querySelectorAll(".run-btn").forEach(btn => btn.onclick = async () => {
    const card = cardFor_(btn); if (!card) return;
    const machine = resolveSelectedMachine_(card.step, btn.dataset.pkey);
    const count = (card.job.steps || []).length || 1;
    const what = count > 1 ? `hooping ${btn.dataset.step} (${card.step.label}) of ` : card.job.qty > 1 ? "this piece of " : "";
    if (!await askConfirm_(`Mark ${what}${btn.dataset.orderid} done?`)) return;
    btn.disabled = true; btn.textContent = "Working…";
    try {
      const r = await runOrderApi_({ action: "markHoopingDone", org: btn.dataset.orgid, orderId: btn.dataset.orderid, itemId: card.job.itemId,
        pieceNo: pieceArg_(btn), stepNo: Number(btn.dataset.step), machineId: machine ? machine.id : null,
        hoopId: machine ? hoopForMachine_(machine, card.step, window._roCtx.hoopsById) : null });
      showToast(doneToast_(r, card));
      await rerender_();
    } catch (e) { showToast(e.message, true); btn.disabled = false; btn.textContent = "Mark done (no timing)"; }
  });
  // Start timing this hooping: locks the card's machine (and that machine for other cards).
  body.querySelectorAll(".run-start-btn").forEach(btn => btn.onclick = async () => {
    const card = cardFor_(btn); if (!card) return;
    const machine = resolveSelectedMachine_(card.step, btn.dataset.pkey);
    if (!machine) { showToast("Pick a machine first.", true); return; }
    btn.disabled = true; btn.textContent = "Starting…";
    try {
      await runOrderApi_({ action: "startRun", org: btn.dataset.orgid, orderId: btn.dataset.orderid, itemId: card.job.itemId,
        pieceNo: pieceArg_(btn), stepNo: Number(btn.dataset.step), machineId: machine.id,
        hoopId: hoopForMachine_(machine, card.step, window._roCtx.hoopsById) });
      showToast(`Started on ${machine.name}.`);
      await rerender_();
    } catch (e) { showToast(e.message, true); btn.disabled = false; btn.textContent = "Start"; }
  });
  // Finish the running hooping: records its time; the piece moves to its next hooping (with the best
  // machine proposed) or, after the last one, is made (consumes a blank).
  // The run was timed (Start was pressed), so first ask what went wrong during it — see
  // showRunFinishModal_. The clock stops when the button is pressed, not when the prompt is answered.
  body.querySelectorAll(".run-complete-btn").forEach(btn => btn.onclick = () => {
    const card = cardFor_(btn);
    showRunFinishModal_({ runId: Number(btn.dataset.runid), orgId: btn.dataset.orgid, orderId: btn.dataset.orderid, pressedAt: new Date().toISOString(),
      doneLabel: btn.textContent.trim() || "Mark done",
      onDone: async (r) => { showToast(card ? doneToast_(r, card) : "Done."); await rerender_(); } });
  });
  body.querySelectorAll(".run-abort-btn").forEach(btn => btn.onclick = () =>
    showAbortModal_(Number(btn.dataset.runid), btn.dataset.orgid, btn.dataset.orderid));
  // A typed-in-personalization hooping waits for its order-specific design.
  body.querySelectorAll(".run-upload-item-design-btn").forEach(btn => btn.onclick = () => {
    const card = cardFor_(btn); if (!card) return;
    showDesignVersionUploadModal_(null, () => rerender_(), { itemId: card.job.itemId, threads: window._roCtx.threads, location: btn.dataset.designLoc || "",
      title: `Order design — ${card.job.orderId} · ${card.job.itemName}${card.job.itemSize ? " (" + card.job.itemSize + ")" : ""}${btn.dataset.designLoc ? " · " + btn.dataset.designLabel : ""}` });
  });
}

// ---- Finishing a timed run: what went wrong? (migrations/0046) -----------------------------------
// The kinds mirror RUN_ISSUE_KINDS in db.js (the server sends its own list with getRunStats and the
// report; this copy is the fallback and gives the report's short column headings).
const RUN_ISSUE_KINDS_ = [
  { key: "threadBreak", label: "Thread break" }, { key: "bobbinOut", label: "Bobbin ran out" }, { key: "birdsNest", label: "Bird's nest" },
  { key: "needleBreak", label: "Needle break" }, { key: "needleReplaced", label: "Needle replaced" }, { key: "other", label: "Other" },
];
const RUN_ISSUE_SHORT_ = { threadBreak: "Thread brk", bobbinOut: "Bobbin", birdsNest: "Bird's nest", needleBreak: "Needle brk", needleReplaced: "Needle repl", other: "Other" };
// {threadBreak: 3, bobbinOut: 1} → "Thread break ×3, Bobbin ran out"
function runIssuesText_(issues, kinds){
  return (kinds || RUN_ISSUE_KINDS_).filter(k => issues && issues[k.key]).map(k => k.label + (issues[k.key] > 1 ? " ×" + issues[k.key] : "")).join(", ");
}
function runDurationText_(ms){
  if (ms == null || !Number.isFinite(ms)) return "—";
  const s = Math.max(0, Math.round(ms / 1000)), h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), ss = s % 60;
  return (h ? h + "h " : "") + (h || m ? m + "m " : "") + ss + "s";
}
// Shown when "Mark done" is pressed on a job that was started with the timer. At the top: this run's
// time and how long this design usually takes on this machine. Then a tick box per kind of issue with
// a count beside it (1 when ticked; 3 thread breaks can be entered as 3), and a text box for "Other".
// Nothing ticked = a clean run. Cancel leaves the job running. opts: {runId, orgId, orderId,
// pressedAt (when the button was pressed — the run's end), doneLabel, onDone(result)}.
async function showRunFinishModal_(opts){
  const { ov, close } = inventoryModal_("Finish job", `<div id="rfBody" style="font-size:14px;color:#777;">Loading…</div>`, 560);
  const body = ov.querySelector("#rfBody");
  let stats = null, kinds = RUN_ISSUE_KINDS_;
  try { const r = await runOrderApi_({ action: "getRunStats", runId: opts.runId }); stats = r.stats; if (r.issueKinds && r.issueKinds.length) kinds = r.issueKinds; }
  catch (e) { /* the averages are a nicety — the job can still be finished without them */ }
  const ranMs = stats && stats.startedAt ? Date.parse(opts.pressedAt) - Date.parse(stats.startedAt) : null;
  const on = stats && stats.onMachine, all = stats && stats.allMachines;
  const versus = (avg) => { if (ranMs == null || !avg) return ""; const d = ranMs - avg, big = Math.abs(d) >= 1000;
    return big ? ` <span style="color:${d > 0 ? "#b45309" : "#166534"};">(${d > 0 ? "+" : "−"}${runDurationText_(Math.abs(d))} ${d > 0 ? "slower" : "faster"})</span>` : ` <span style="color:#666;">(same)</span>`; };
  const avgLine = !stats ? ""
    : on && on.runs ? `Average for this design on ${escapeHtml(stats.machineName || "this machine")}: <b>${runDurationText_(on.avgMs)}</b> over ${on.runs} run${on.runs === 1 ? "" : "s"}${versus(on.avgMs)}`
    : all && all.runs ? `No earlier timed run of this design on ${escapeHtml(stats.machineName || "this machine")}. On other machines it averages <b>${runDurationText_(all.avgMs)}</b> over ${all.runs} run${all.runs === 1 ? "" : "s"}${versus(all.avgMs)}`
    : `This is the first timed run of this design, so there's no average yet.`;
  const step = "width:44px;height:44px;font-size:22px;line-height:1;border:1px solid #bbb;border-radius:8px;background:#fff;cursor:pointer;";
  body.style.color = "";
  body.innerHTML = `
    <div id="rfTimes" style="background:#f3f4f6;border-radius:8px;padding:12px 14px;margin-bottom:14px;">
      ${stats && stats.designName ? `<div style="font-size:13px;color:#555;margin-bottom:4px;">${escapeHtml(stats.designName)}${stats.stepLabel ? " · " + escapeHtml(stats.stepLabel) : ""}${stats.stitchCount != null ? ` · <span class="rf-stitches">${Number(stats.stitchCount).toLocaleString()} stitches</span>` : ""}</div>` : ""}
      <div style="font-size:20px;font-weight:700;">Run time: <span id="rfRan">${runDurationText_(ranMs)}</span></div>
      <div id="rfAvg" style="font-size:13px;color:#333;margin-top:4px;">${avgLine}</div>
    </div>
    <div style="font-weight:700;margin-bottom:2px;">Any issues during this run?</div>
    <div style="font-size:12px;color:#666;margin-bottom:8px;">Tick what happened and set how many times. Leave everything unticked for a clean run.</div>
    <div id="rfIssues">${kinds.map(k => `
      <div class="rf-row" data-key="${escapeHtml(k.key)}" style="display:flex;align-items:center;gap:10px;padding:6px 0;border-top:1px solid #eee;">
        <label style="display:flex;align-items:center;gap:10px;flex:1;font-size:16px;cursor:pointer;min-height:44px;">
          <input type="checkbox" class="rf-on" style="width:24px;height:24px;"> ${escapeHtml(k.label)}</label>
        <div class="rf-count" style="display:flex;align-items:center;gap:6px;visibility:hidden;">
          <button type="button" class="rf-minus" aria-label="One fewer ${escapeHtml(k.label)}" style="${step}">−</button>
          <input type="number" class="rf-n" min="1" max="99" step="1" value="1" inputmode="numeric" aria-label="How many times: ${escapeHtml(k.label)}" style="width:62px;height:44px;font-size:18px;text-align:center;border:1px solid #bbb;border-radius:8px;box-sizing:border-box;">
          <button type="button" class="rf-plus" aria-label="One more ${escapeHtml(k.label)}" style="${step}">+</button>
        </div>
      </div>`).join("")}</div>
    <div id="rfNoteWrap" style="display:none;margin-top:6px;">
      <label style="font-size:13px;font-weight:600;">What was the other issue?<br>
        <textarea id="rfNote" rows="2" maxlength="500" style="width:100%;box-sizing:border-box;font-size:15px;padding:8px;border:1px solid #bbb;border-radius:8px;margin-top:3px;"></textarea></label>
    </div>
    <div id="rfFoot" style="position:sticky;bottom:-22px;background:#fff;margin:0 -22px -22px;padding:0 22px 22px;border-top:1px solid #eee;">
    <div id="rfErr" style="color:#b03a2e;font-size:13px;min-height:18px;margin-top:8px;"></div>
    <div style="display:flex;gap:10px;justify-content:flex-end;margin-top:4px;">
      <button type="button" id="rfCancel" style="min-height:52px;padding:12px 20px;font-size:15px;border:1px solid #bbb;border-radius:10px;background:#fff;cursor:pointer;">Cancel — still running</button>
      <button type="button" id="rfDone" style="min-height:52px;padding:12px 26px;font-size:16px;font-weight:700;border:none;border-radius:10px;background:var(--org-accent,#2c6b2f);color:#fff;cursor:pointer;">${escapeHtml(opts.doneLabel || "Mark done")}</button>
    </div></div>`;
  const clampN = (v) => Math.max(1, Math.min(99, Math.floor(Number(v)) || 1));
  body.querySelectorAll(".rf-row").forEach(row => {
    const box = row.querySelector(".rf-on"), cnt = row.querySelector(".rf-count"), n = row.querySelector(".rf-n");
    const sync = () => {
      cnt.style.visibility = box.checked ? "visible" : "hidden";
      if (box.checked && !(Number(n.value) >= 1)) n.value = 1;
      if (row.dataset.key === "other") { body.querySelector("#rfNoteWrap").style.display = box.checked ? "" : "none"; if (box.checked) body.querySelector("#rfNote").focus(); }
    };
    box.onchange = () => { if (box.checked) n.value = 1; sync(); };   // ticking always starts the count at 1
    row.querySelector(".rf-minus").onclick = () => { n.value = clampN(Number(n.value) - 1); };
    row.querySelector(".rf-plus").onclick = () => { n.value = clampN(Number(n.value) + 1); };
    n.onchange = () => { n.value = clampN(n.value); };
  });
  const read = () => {
    const issues = {};
    body.querySelectorAll(".rf-row").forEach(row => { if (row.querySelector(".rf-on").checked) issues[row.dataset.key] = clampN(row.querySelector(".rf-n").value); });
    return { issues, note: issues.other ? body.querySelector("#rfNote").value.trim() : "" };
  };
  body.querySelector("#rfCancel").onclick = close;
  const doneBtn = body.querySelector("#rfDone");
  doneBtn.onclick = async () => {
    const err = body.querySelector("#rfErr"), { issues, note } = read();
    if (issues.other && !note) { err.textContent = "Say what the other issue was, or untick Other."; body.querySelector("#rfNote").focus(); return; }
    err.textContent = ""; doneBtn.disabled = true; const label = doneBtn.textContent; doneBtn.textContent = "Finishing…";
    try {
      const r = await runOrderApi_({ action: "completeRun", runId: opts.runId, org: opts.orgId, orderId: opts.orderId, issues, issueNote: note, finishedAt: opts.pressedAt });
      close();
      if (opts.onDone) await opts.onDone(r);
    } catch (e) { err.textContent = e.message; doneBtn.disabled = false; doneBtn.textContent = label; }
  };
  return { ov, close, read };
}

// Abort-job modal: a reason dropdown (defaulting to "Machine problem") + an optional note.
// Maintenance due on the machine a job card proposes (migrations/0071) — advisory, it never stops a run.
function runMaintWarnHtml_(machine){
  const due = (machine.maintenanceDue || []);
  if (!due.length) return "";
  return `<div class="run-maint-warn" style="font-size:11px;margin-top:3px;color:${due.some(t => t.status === "due") ? "#b03a2e" : "#92400e"};">${due.map(t =>
    `⚠ ${escapeHtml(t.name)} ${t.status === "due" ? "due" : "due soon"}`).join("<br>")} · <a href="#maintenance/${machine.id}">log</a></div>`;
}

function showAbortModal_(runId, orgId, orderId){
  const reasons = (window._roCtx && window._roCtx.abortReasons) || [];
  const def = reasons.find(r => /^machine problem$/i.test(r.label)) || reasons[0];
  const inp = "font-size:13px;padding:6px 8px;border:1px solid #ccc;border-radius:4px;width:100%;box-sizing:border-box;";
  const { ov, close } = inventoryModal_("Abort job", `
    <div style="margin-bottom:10px;">
      <label style="font-size:12px;font-weight:600;">Reason<br>
        <select id="abReason" style="${inp}">
          ${reasons.map(r => `<option value="${r.id}" ${def && r.id === def.id ? "selected" : ""}>${escapeHtml(r.label)}</option>`).join("")}
        </select></label>
    </div>
    <div style="margin-bottom:10px;">
      <label style="font-size:12px;font-weight:600;">Note (optional)<br><textarea id="abNote" rows="2" style="${inp}"></textarea></label>
    </div>
    <div style="margin-bottom:10px;">
      <label style="font-size:12px;font-weight:600;">Stitches run (optional)<br><input type="text" inputmode="numeric" id="abStitches" placeholder="From the machine's display" style="${inp}"></label>
      <div style="font-size:11px;color:#888;margin-top:2px;">Added to the machine's stitch counter with the time it ran. Blank = none.</div>
    </div>
    <div id="abErr" style="color:#b03a2e;font-size:13px;min-height:18px;"></div>
    <div style="display:flex;gap:8px;justify-content:flex-end;">
      <button type="button" id="abCancel" style="padding:6px 14px;border:1px solid #ccc;border-radius:5px;background:#fff;cursor:pointer;">Cancel</button>
      <button class="admin-btn-danger admin-btn-danger-solid" type="button" id="abDo" style="padding:6px 14px;border:1px solid #b03a2e;border-radius:5px;color:#fff;cursor:pointer;">Abort job</button>
    </div>`, 420);
  ov.querySelector("#abCancel").onclick = close;
  ov.querySelector("#abDo").onclick = async () => {
    const reasonId = ov.querySelector("#abReason").value;
    const note = ov.querySelector("#abNote").value.trim();
    try {
      const stitchesRun = ov.querySelector("#abStitches").value.replace(/[,\s]/g, "");
      await runOrderApi_({ action: "abortRun", runId, org: orgId, orderId, abortReasonId: reasonId ? Number(reasonId) : null, abortNote: note, stitchesRun });
      close(); showToast("Job aborted."); await refreshRunOrder_();
    } catch (e) { ov.querySelector("#abErr").textContent = e.message; }
  };
}

// ---- Machine Files — browse a machine's files, copy them off it (Download, as .DSB), and send a
// design version to it directly, outside the Run Order flow (e.g. re-sending an old version, or
// loading a machine before any order needs it). Talks to the same local agent as the Run Order
// screen's Send button.
async function renderMachineFiles(app){
  adminSetHash("machinefiles");
  document.title = adminTitle_("Machine files");
  app.innerHTML = `
    ${adminPageHead_("Machine files")}
    <div class="admin-panel" style="--org-accent:var(--accent);max-width:900px;margin:8px auto 60px;">
      <div id="mfAgentStatus" style="font-size:12px;color:#888;margin-bottom:14px;">Checking send agent&hellip;</div>
      <label style="font-size:12px;font-weight:600;display:block;margin-bottom:14px;max-width:360px;">Machine<br>
        <select id="mfMachineSelect" style="font-size:14px;padding:6px 8px;width:100%;"><option value="">Loading&hellip;</option></select>
      </label>
      <div id="mfBody" style="color:#888;font-size:14px;"></div>
    </div>`;
  checkSendAgent_().then(ok => {
    const el = document.getElementById("mfAgentStatus");
    if (el) el.innerHTML = ok ? `<span style="color:#2c6b2f;">● Send agent: connected</span>`
      : `<span style="color:#b03a2e;">● Send agent: not running</span> — start the send-agent (a separate download) to browse or send files`;
  });
  if (!adminKey) adminKey = (await adminLogin()) || ""; // resolve once before the parallel calls
  let machines = [], orgs = [], showDelete = false;
  try {
    const [m, o, s] = await Promise.all([machineApi_({ action: "listMachines" }), designApi_({ action: "listOrgsAdmin" }), machineApi_({ action: "getMachineSettings" })]);
    machines = m.machines || []; orgs = o.orgs || [];
    showDelete = !!(s.machineSettings && s.machineSettings.showDeleteButton);
  } catch (e) { document.getElementById("mfBody").innerHTML = `<div style="color:#b03a2e;">${escapeHtml(e.message)}</div>`; return; }
  window._mfCtx = { machines, orgs, selectedMachineId: null, showDelete };
  const sel = document.getElementById("mfMachineSelect");
  sel.innerHTML = `<option value="">— pick a machine —</option>` + machines.map(m => `<option value="${m.id}">${escapeHtml(m.name)}</option>`).join("");
  sel.onchange = () => { window._mfCtx.selectedMachineId = sel.value ? Number(sel.value) : null; drawMachineFilesBody_(); };
  drawMachineFilesBody_();
}

async function drawMachineFilesBody_(){
  const body = document.getElementById("mfBody");
  const { machines, selectedMachineId } = window._mfCtx;
  const machine = machines.find(m => m.id === selectedMachineId);
  if (!machine) { body.innerHTML = `<div style="color:#888;">Pick a machine to see its files.</div>`; return; }
  if (!machine.ipAddress) { body.innerHTML = `<div style="color:#b03a2e;">${escapeHtml(machine.name)} has no IP address set — add one in Machines first.</div>`; return; }
  body.innerHTML = `
    <div style="margin-bottom:24px;">
      <h3 style="margin:0 0 8px;">Files on ${escapeHtml(machine.name)} (${escapeHtml(machine.embDir || "/EMB")})</h3>
      <div id="mfFileList" style="color:#888;font-size:13px;">Loading&hellip;</div>
    </div>
    <div>
      <h3 style="margin:0 0 8px;">Send a design version</h3>
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:8px;align-items:end;max-width:760px;">
        <label style="font-size:12px;font-weight:600;">Shop<br><select id="mfOrgSelect" style="font-size:13px;padding:5px 6px;width:100%;"><option value="">— pick a shop —</option></select></label>
        <label style="font-size:12px;font-weight:600;">Design<br><select id="mfDesignSelect" style="font-size:13px;padding:5px 6px;width:100%;" disabled><option value="">—</option></select></label>
        <label style="font-size:12px;font-weight:600;">Version<br><select id="mfVersionSelect" style="font-size:13px;padding:5px 6px;width:100%;" disabled><option value="">—</option></select></label>
        <button type="button" id="mfSendBtn" class="admin-btn" disabled>Send to machine</button>
      </div>
      <div id="mfSendErr" style="color:#b03a2e;font-size:13px;margin-top:6px;min-height:18px;"></div>
    </div>`;
  loadMachineFileList_(machine);

  const orgSel = document.getElementById("mfOrgSelect");
  orgSel.innerHTML = `<option value="">— pick a shop —</option>` + window._mfCtx.orgs.map(o => `<option value="${escapeHtml(o.orgId)}">${escapeHtml(o.name)}</option>`).join("");
  const designSel = document.getElementById("mfDesignSelect");
  const versionSel = document.getElementById("mfVersionSelect");
  const sendBtn = document.getElementById("mfSendBtn");
  let versions = [];

  // Relabel the send button "Send"/"Resend" depending on whether the picked version's machine
  // file is already on this machine's listing (loaded into _mfCtx.files by loadMachineFileList_).
  const relabelSend = () => {
    if (sendBtn.disabled && !versionSel.value) { sendBtn.textContent = "Send to machine"; return; }
    const v = versions.find(x => x.id === Number(versionSel.value));
    const files = window._mfCtx && window._mfCtx.files;
    sendBtn.textContent = (v && files && machineHasFile_(files, v.machineFileName)) ? "Resend to machine" : "Send to machine";
  };
  window._mfRelabelSend = relabelSend;
  versionSel.onchange = relabelSend;

  orgSel.onchange = async () => {
    designSel.innerHTML = `<option value="">Loading&hellip;</option>`; designSel.disabled = true;
    versionSel.innerHTML = `<option value="">—</option>`; versionSel.disabled = true; sendBtn.disabled = true;
    if (!orgSel.value) { designSel.innerHTML = `<option value="">—</option>`; return; }
    try {
      const r = await designApi_({ action: "listDesigns", org: orgSel.value });
      const designs = r.designs || [];
      designSel.innerHTML = designs.length ? `<option value="">— pick a design —</option>` + designs.map(d => `<option value="${d.id}">${escapeHtml(d.name)}</option>`).join("")
        : `<option value="">No designs for this shop</option>`;
      designSel.disabled = !designs.length;
    } catch (e) { designSel.innerHTML = `<option value="">Error loading designs</option>`; }
  };

  designSel.onchange = async () => {
    versionSel.innerHTML = `<option value="">Loading&hellip;</option>`; versionSel.disabled = true; sendBtn.disabled = true;
    if (!designSel.value) { versionSel.innerHTML = `<option value="">—</option>`; return; }
    try {
      const r = await designApi_({ action: "getDesign", id: Number(designSel.value) });
      versions = r.versions || [];
      const withMachine = versions.filter(v => v.machineFileKey);
      versionSel.innerHTML = withMachine.length
        ? withMachine.map((v, i) => `<option value="${v.id}">${escapeHtml((v.uploadedAt || "").slice(0, 10))} — ${escapeHtml(v.machineFileName)}${i === 0 ? " (current)" : ""}</option>`).join("")
        : `<option value="">No version has a machine file</option>`;
      versionSel.disabled = !withMachine.length;
      sendBtn.disabled = !withMachine.length;
      relabelSend();
    } catch (e) { versionSel.innerHTML = `<option value="">Error loading versions</option>`; }
  };

  sendBtn.onclick = async () => {
    const err = document.getElementById("mfSendErr");
    err.textContent = "";
    const version = versions.find(v => v.id === Number(versionSel.value));
    if (!version) { err.textContent = "Pick a version first."; return; }
    const wasResend = sendBtn.textContent.indexOf("Resend") === 0;
    sendBtn.disabled = true; sendBtn.textContent = wasResend ? "Resending…" : "Sending…";
    try { await sendDesignToMachine_(version, machine); await loadMachineFileList_(machine, { keep: true }); }
    catch (e) { err.textContent = e.message; }
    finally { sendBtn.disabled = false; relabelSend(); } // reloaded listing → correct Send/Resend wording
  };
}

// opts.keep: after a send / delete, reload without the "Loading…" swap and keep the list's scroll.
async function loadMachineFileList_(machine, opts){
  const el = document.getElementById("mfFileList");
  if (!el) return;
  if (opts && opts.keep && el.querySelector("table")) {
    await keepView_(() => loadMachineFileList_(machine));
    if (el._syncPicks) el._syncPicks(); // ticks put back by keepView_ → the "Download selected (N)" count
    return;
  }
  el.textContent = "Loading…";
  let files;
  try { files = await listMachineFiles_(machine); }
  catch (e) { if (window._mfCtx) window._mfCtx.files = null; el.innerHTML = `<div style="color:#b03a2e;">${escapeHtml(e.message)}</div>`; return; }
  if (window._mfCtx) window._mfCtx.files = files;
  if (typeof window._mfRelabelSend === "function") window._mfRelabelSend();
  if (!files.length) { el.innerHTML = `<div style="color:#888;">No files in this directory.</div>`; return; }
  const ck = name => `mf:${machine.id}|${name}`;
  // The Delete column only shows when the Global Settings "Show delete buttons on Machine Files"
  // toggle is on (off by default — deleting is firmware-disabled today; see the send-agent's protocol notes).
  const showDelete = !!(window._mfCtx && window._mfCtx.showDelete);
  el.innerHTML = `<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:8px;">
      <button type="button" class="admin-btn" id="mfDownloadSel" disabled>Download selected</button>
      <button type="button" class="admin-btn" id="mfDownloadAll">Download all (${files.length})</button>
      <span id="mfDownloadStatus" role="status" aria-live="polite" style="font-size:12px;color:#666;"></span>
    </div>
    <div style="font-size:12px;color:#888;margin-bottom:6px;">Files come off the machine in its own format and are saved as <b>.DSB</b>; several at once come as one .zip.</div>
    <div data-keep-scroll="machinefiles" style="max-height:55vh;overflow-y:auto;border:1px solid #eee;border-radius:6px;"><table style="width:100%;border-collapse:collapse;">
    <thead><tr style="text-align:left;background:#f3f4f6;position:sticky;top:0;"><th style="padding:5px 6px;width:28px;"><input type="checkbox" id="mfPickAll" aria-label="Select all files"></th><th style="padding:5px 6px;">Name</th><th style="padding:5px 6px;">Size</th><th style="padding:5px 6px;">Modified</th><th></th>${showDelete ? "<th></th>" : ""}</tr></thead>
    <tbody>${files.map(f => `<tr style="border-bottom:1px solid #eee;">
      <td style="padding:5px 6px;"><input type="checkbox" class="mfPick" data-name="${escapeHtml(f.name)}" data-keep-check="${escapeHtml(ck(f.name))}" aria-label="Select ${escapeHtml(f.name)}"></td>
      <td style="padding:5px 6px;">${escapeHtml(f.name)}</td>
      <td style="padding:5px 6px;">${f.size != null ? (f.size / 1024).toFixed(1) + " KB" : "—"}</td>
      <td style="padding:5px 6px;">${escapeHtml(f.modified || "—")}</td>
      <td style="padding:5px 6px;text-align:right;"><button type="button" class="admin-btn mfDownloadBtn" data-name="${escapeHtml(f.name)}" style="padding:2px 8px;font-size:11px;">Download</button></td>
      ${showDelete ? `<td style="padding:5px 6px;text-align:right;"><button type="button" class="admin-btn mfDeleteBtn admin-btn-danger" data-name="${escapeHtml(f.name)}" style="padding:2px 8px;font-size:11px;">Delete</button></td>` : ""}
    </tr>`).join("")}</tbody></table></div>`;
  const picks = () => [...el.querySelectorAll(".mfPick")];
  const selBtn = document.getElementById("mfDownloadSel"), allBtn = document.getElementById("mfDownloadAll");
  const status = document.getElementById("mfDownloadStatus"), pickAll = document.getElementById("mfPickAll");
  let busy = false;
  const syncPicks = () => {
    const n = picks().filter(cb => cb.checked).length;
    selBtn.disabled = busy || !n;
    selBtn.textContent = n ? `Download selected (${n})` : "Download selected";
    allBtn.disabled = busy;
    el.querySelectorAll(".mfDownloadBtn").forEach(b => { b.disabled = busy; });
    pickAll.checked = n > 0 && n === picks().length;
    pickAll.indeterminate = n > 0 && n < picks().length;
  };
  const run = async (names) => {
    if (busy || !names.length) return;
    busy = true; syncPicks();
    try { await downloadMachineFiles_(machine, names, t => { status.textContent = t; }); }
    finally { busy = false; syncPicks(); }
  };
  picks().forEach(cb => cb.onchange = syncPicks);
  el._syncPicks = syncPicks;
  pickAll.onchange = () => { picks().forEach(cb => { cb.checked = pickAll.checked; }); syncPicks(); };
  selBtn.onclick = () => run(picks().filter(cb => cb.checked).map(cb => cb.dataset.name));
  allBtn.onclick = () => run(files.map(f => f.name));
  el.querySelectorAll(".mfDownloadBtn").forEach(btn => btn.onclick = () => run([btn.dataset.name]));
  syncPicks();
  if (showDelete) el.querySelectorAll(".mfDeleteBtn").forEach(btn => btn.onclick = async () => {
    if (!await askConfirm_(`Delete "${btn.dataset.name}" from ${machine.name}?`)) return;
    try { await deleteMachineFile_(machine, btn.dataset.name); showToast("File deleted."); await loadMachineFileList_(machine, { keep: true }); }
    catch (e) { showToast(e.message, true); }
  });
}

// ---- Order item editing --------------------------------------------------------

async function editOrder(orgId, orderId){
  const cache = (window._ordersCache && window._ordersCache[orgId]) || [];
  const order = cache.find(o => o.orderId === orderId);
  if(!order){ showToast("Order not found in cache — refresh the page.", true); return; }

  if(!adminKey) adminKey = (await adminLogin()) || "";
  if(!adminKey) return;

  // Fetch all org products so the product picker is populated
  let products = [];
  try{
    const res = await fetch("/api/orders", {
      method:"POST", headers:{"Content-Type":"application/json"},
      body: JSON.stringify({action:"listProducts", org:orgId, key:adminKey})
    });
    const data = await res.json();
    if(res.ok && data.status === "ok") products = data.products || [];
  }catch(e){}

  // If any item is a configurable product, fetch the org's graphics + tier prices so the editor can
  // offer its per-location picks and preview the price (the server re-validates and reprices on save).
  let graphics = [], tiersCents = {};
  if(products.some(p => p.configurable) || (order.items || []).some(it => it.config)){
    try{ const g = await hoopApi_({ action: "listGraphics", org: orgId }); graphics = g.graphics || []; tiersCents = g.tiersCents || {}; }catch(e){}
  }

  const result = await showEditOrderModal(order, products, { graphics, tiersCents });
  if(!result) return;

  if(!adminKey) adminKey = (await adminLogin()) || "";
  if(!adminKey) return;

  const payload = {
    action: "editOrder",
    key: adminKey,
    org: orgId,
    orderId,
    removals:   result.removals,
    updates:    result.updates,
    additions:  result.additions,
    requestPayment: result.requestPayment,
    emailBody:  result.emailBody || "",
  };

  try{
    const res = await fetch("/api/orders", {
      method:"POST", headers:{"Content-Type":"application/json"},
      body: JSON.stringify(payload)
    });
    const data = await res.json();
    if(!res.ok || data.status === "error"){
      if(data && data.message === "Unauthorized") clearAdminAuth();
      showToast("Edit failed: " + ((data && data.message) || "unknown error"), true);
      return;
    }
    let msg = "Order updated.";
    if(data.priceDiff > 0 && result.requestPayment){
      msg = data.emailSent ? "Order updated. Payment link emailed to customer." : "Order updated. Payment link created but email failed.";
    } else if(data.priceDiff < 0){
      msg = "Order updated. Total decreased by $" + Math.abs(data.priceDiff).toFixed(2) + ".";
    }
    showToast(msg);
    const org = (adminOrgs || []).find(o => o.orgId === orgId);
    if(org) refreshOrdersInPlace_(org);
  }catch(e){
    showToast("Could not reach the server.", true);
  }
}

// An order line keeps a copy of its options from when it was placed, so fixing a graphic (transfer →
// embroidery, linking its transfer) or turning on a reorder QR doesn't reach orders that already
// exist. This shows what would change on this order, then applies it. Prices are never touched.
async function refreshOrderFromCatalog_(order){
  const org = order._org || (currentOrg && currentOrg.id) || order.orgId || "";
  const describe = (lines) => lines.map(l => "• " + l.name + (l.size ? " (" + l.size + ")" : "") + ": " + l.changes.join("; ")).join("\n");
  try{
    const pre = await hoopApi_({ action: "refreshOrderFromCatalog", org, orderId: order.orderId, preview: true });
    if(!(pre.lines || []).length){ showToast("This order already matches the catalog — nothing to update."); return false; }
    if(!await askConfirm_("Update this order from the catalog?\n\n" + describe(pre.lines) + "\n\nPrices and what the customer chose don't change.")) return false;
    const res = await hoopApi_({ action: "refreshOrderFromCatalog", org, orderId: order.orderId });
    showToast("Updated " + (res.lines || []).length + " line" + ((res.lines || []).length === 1 ? "" : "s") + " from the catalog.");
    if(typeof route !== "undefined" && route && typeof render === "function") render();
    return true;
  }catch(e){ showToast((e && e.message) || "Could not update the order", true); return false; }
}

function showEditOrderModal(order, products, ctx){
  ctx = ctx || {};
  const gById_ = {}; (ctx.graphics || []).forEach(g => { gById_[g.id] = g; });
  const addOnCents_ = (g) => (g && g.tier ? (ctx.tiersCents && ctx.tiersCents[g.tier]) || 0 : 0);
  // Options a configurable product's location offers, filtered the same way the storefront does.
  const cfgOptsForLoc_ = (prod, loc, color) => (loc.graphicIds || []).map(id => gById_[id]).filter(Boolean)
    .filter(g => g.visible !== false)
    .filter(g => !(g.allowedLocations && g.allowedLocations.length) || g.allowedLocations.includes(loc.key))
    .filter(g => !(g.allowedGarmentColors && g.allowedGarmentColors.length) || !color || g.allowedGarmentColors.includes(color))
    .filter(g => !(color && (prod.blockedGraphicColors || []).some(b => Number(b.graphicId) === g.id && b.color === color)));
  const cfgBase_ = (prod, size) => prod.pricingMode === "flat" ? (prod.flatPrice || 0) : ((prod.sizePricing || {})[size] || 0);
  const cfgUnitPrice_ = (row, prod) => {
    let u = cfgBase_(prod, row.size);
    for (const l of ((row.config && row.config.locations) || [])) {
      if (l.custom) { u += ((row._customCents || {})[l.location] || 0) / 100; continue; }   // the customer's own design, at what it was ordered for
      const g = gById_[l.graphicId]; if (g) u += addOnCents_(g) / 100;
    }
    return u;
  };
  return new Promise((resolve) => {
    const visibleProducts = products.filter(p => p.visible);

    // Build state: editable copy of current active items
    // Each row: { _id, itemId (null if new), productId, name, type, size, qty, unitPrice, personalizationFee, personalized, persName, originalLineTotal, originalItemId }
    const rows = order.items
      .filter(it => !it.cancelDate)
      .map(it => {
        // Configurable line (migrations/0036): keep an editable copy of the picks (customer-facing
        // entries only — drop the auto reorder-QR, which the server re-adds on save).
        // `plain` = a non-configurable product whose snapshot only carries its automatic reorder QR
        // (migrations/0048) — nothing on it was picked, so it's edited like any plain line.
        const configurable = !!(it.config && Array.isArray(it.config.locations) && !it.config.plain);
        // The customer's own design (migrations/0054) stays on the line: a configurable line keeps its
        // custom picks (the server rebuilds the file details from the line's saved copy, never from
        // here); an ordinary line keeps its upload as long as the product isn't changed.
        const customLocs = ((it.config && it.config.locations) || []).filter(l => l.custom);
        const customCents = {}; for (const l of customLocs) customCents[l.location] = Number(l.addOnCents) || 0;
        const plainCustomCents = !configurable ? customLocs.reduce((s2, l) => s2 + (Number(l.addOnCents) || 0), 0) : 0;
        const config = configurable
          ? { garmentColor: it.config.garmentColor || "", locations: it.config.locations.filter(l => !l.auto && !l.fixed && l.location !== "reorderqr").map(l => l.custom ? { location: l.location, custom: true } : ({ location: l.location, graphicId: l.graphicId, ink: l.ink || "" })) }
          : null;
        return {
          _id: Math.random().toString(36).slice(2),
          itemId: it.sheetRow,
          productId: it.productId || "",
          name: it.name,
          type: it.type,
          size: it.size || "",
          qty: it.qty,
          unitPrice: it.unitPrice - plainCustomCents / 100,   // the custom add-on is counted on its own below
          personalizationFee: it.personalizationFee,
          personalized: it.personalized,
          persName: it.persName || "",
          configurable,
          config,
          _hasCustom: customLocs.length > 0,
          // The order designs this line takes (Files → Order design): one per stitched custom spot,
          // plus the typed-in name's — which an ordinary line made from the customer's design folds in.
          _designSlots: (() => { const emb = customLocs.filter(l => l.kind === "embroidery").map(l => ({ location: String(l.location), label: configurable ? (l.label || l.location) : "Customer design" }));
            return emb.concat(it.personalized && !(emb.length && !configurable) ? [{ location: "", label: emb.length ? "Typed-in name" : "" }] : []); })(),
          _customCents: customCents,
          _customLocs: customLocs.map(l => l.location),
          _plainCustomCents: plainCustomCents,
          _origProductId: it.productId || "",
          originalLineTotal: it.lineTotal,
          originalItemId: it.sheetRow,
          _origConfigJson: config ? JSON.stringify(config) : "",
          _removed: false,
          _refundAmount: Number(it.lineTotal).toFixed(2),
          _refundReason: "",
        };
      });

    const state = { rows, nextId: 0, originalTotal: order.total };
    // Sales tax added on top of the prices is worked out by the server when the edit is saved, so
    // the running total here is the listed prices only — compare like with like.
    const taxOnTop = order.taxMode === "exclusive";

    function getProductById(pid){ return products.find(p => p.productId === pid); }

    function getSizesForProduct(p){
      if(!p) return [];
      if(p.pricingMode === "flat") return ["OSFA"];
      return Object.keys(p.sizePricing || {});
    }

    function getPriceForProduct(p, size, personalized){
      if(!p) return { unitPrice: 0, personalizationFee: 0 };
      let unitPrice = 0;
      if(p.pricingMode === "flat") unitPrice = p.flatPrice || 0;
      else unitPrice = (p.sizePricing && p.sizePricing[size]) || 0;
      const personalizationFee = personalized && p.personalizationPrice != null ? p.personalizationPrice : 0;
      return { unitPrice, personalizationFee };
    }

    function calcRowTotal(row){
      if(row.configurable){ const prod = getProductById(row.productId); return row.qty * (prod ? cfgUnitPrice_(row, prod) : row.unitPrice); }
      const custom = row._plainCustomCents && row.productId === row._origProductId ? row._plainCustomCents / 100 : 0;
      return row.qty * (row.unitPrice + row.personalizationFee + custom);
    }

    // Per-location picker + colour + ink for a configurable line, shown in place of the
    // personalization cell. The server re-validates and reprices on save.
    function cfgEditorHtml_(row, idx, prod){
      if(!prod) return `<span style="font-size:12px;color:var(--ink-soft);">—</span>`;
      const ss = "font-size:12px;padding:2px 4px;border:1px solid var(--border,#ccc);border-radius:3px;background:var(--surface,#fff);color:var(--ink,#111);";
      const colors = prod.garmentColors || [];
      const colorSel = colors.length
        ? `<div style="margin-bottom:3px;"><span style="font-size:11px;color:var(--ink-soft);">Color</span> <select data-rowidx="${idx}" data-cfgfield="color" style="${ss}">${colors.map(c => `<option ${c === (row.config.garmentColor || "") ? "selected" : ""}>${escapeHtml(c)}</option>`).join("")}</select></div>`
        : "";
      const locHtml = (prod.locations || []).map(loc => {
        const cur = ((row.config.locations || []).find(l => l.location === loc.key)) || {};
        const opts = cfgOptsForLoc_(prod, loc, row.config.garmentColor);
        // "Customer design" only where this line was ordered with one — adding one here isn't offered (Files is).
        const customOpt = (row._customLocs || []).includes(loc.key) ? `<option value="custom" ${cur.custom ? "selected" : ""}>Customer design</option>` : "";
        const optHtml = `<option value="">None</option>` + customOpt + opts.map(g => `<option value="${g.id}" ${!cur.custom && String(cur.graphicId) === String(g.id) ? "selected" : ""}>${escapeHtml(g.name)}${addOnCents_(g) ? ` (+$${(addOnCents_(g) / 100).toFixed(2)})` : ""}</option>`).join("");
        const g = gById_[cur.graphicId];
        const inkHtml = g && g.inkColors && g.inkColors.length > 1
          ? ` <select data-rowidx="${idx}" data-cfgfield="ink" data-loc="${escapeHtml(loc.key)}" style="${ss}">${g.inkColors.map(ic => `<option ${ic === (cur.ink || "") ? "selected" : ""}>${escapeHtml(ic)}</option>`).join("")}</select>`
          : "";
        return `<div style="margin-bottom:2px;"><span style="font-size:11px;color:var(--ink-soft);">${escapeHtml(loc.label || loc.key)}</span> <select data-rowidx="${idx}" data-cfgfield="graphic" data-loc="${escapeHtml(loc.key)}" style="${ss}">${optHtml}</select>${inkHtml}</div>`;
      }).join("");
      return `<div style="min-width:180px;">${colorSel}${locHtml}</div>`;
    }

    function calcNewTotal(){
      return order.shippingCost + state.rows.reduce((s, r) => s + (r._removed ? 0 : calcRowTotal(r)), 0);
    }
    if(taxOnTop) state.originalTotal = calcNewTotal();

    function renderRows(tbody){
      tbody.innerHTML = "";
      state.rows.forEach((row, idx) => {
        const tr = document.createElement("tr");
        if(row._removed) tr.style.opacity = "0.4";

        // Product select
        const prodOpts = visibleProducts.map(p =>
          `<option value="${escapeHtml(p.productId)}" ${p.productId === row.productId ? "selected" : ""}>${escapeHtml(p.name)}${p.versionGroup && p.versionLabel ? " — " + escapeHtml(p.versionLabel) : ""}</option>`
        ).join("");
        // Include current product if not visible
        const currentProd = getProductById(row.productId);
        const extraOpt = (!currentProd && row.productId)
          ? `<option value="${escapeHtml(row.productId)}" selected>${escapeHtml(row.name)} (unavailable)</option>` : "";

        // Size select
        const curProd = getProductById(row.productId);
        const sizes = getSizesForProduct(curProd);
        const sizeOpts = sizes.map(s =>
          `<option value="${escapeHtml(s)}" ${s === row.size ? "selected" : ""}>${escapeHtml(s)}</option>`
        ).join("");

        tr.innerHTML = `
          <td style="padding:6px 4px;vertical-align:top;">
            ${row._removed || row.configurable
              ? `<span style="font-size:12px;${row.configurable && !row._removed ? "" : "color:var(--ink-soft);"}">${escapeHtml(row.name)}</span>`
              : `<select data-rowidx="${idx}" data-field="productId" style="font-size:12px;width:140px;padding:3px 4px;border:1px solid var(--border,#ccc);border-radius:3px;background:var(--surface,#fff);color:var(--ink,#111);">
                  ${extraOpt}${prodOpts}
                </select>`
            }
          </td>
          <td style="padding:6px 4px;vertical-align:top;">
            ${row._removed
              ? `<span style="font-size:12px;color:var(--ink-soft);">${escapeHtml(row.size || "—")}</span>`
              : sizes.length > 1
                ? `<select data-rowidx="${idx}" data-field="size" style="font-size:12px;width:70px;padding:3px 4px;border:1px solid var(--border,#ccc);border-radius:3px;background:var(--surface,#fff);color:var(--ink,#111);">${sizeOpts}</select>`
                : `<span style="font-size:12px;">${escapeHtml(row.size || sizes[0] || "—")}</span>`
            }
          </td>
          <td style="padding:6px 4px;vertical-align:top;">
            ${row._removed
              ? `<span style="font-size:12px;color:var(--ink-soft);">${row.qty}</span>`
              : `<input type="number" min="1" max="50" value="${row.qty}" data-rowidx="${idx}" data-field="qty" style="font-size:12px;width:48px;padding:3px 4px;border:1px solid var(--border,#ccc);border-radius:3px;">`
            }
          </td>
          <td style="padding:6px 4px;vertical-align:top;">
            ${row.configurable
              ? (row._removed
                  ? `<span style="font-size:12px;color:var(--ink-soft);">${escapeHtml([row.config.garmentColor, ...((row.config.locations || []).map(l => { if (l.custom) return "Customer design"; const g = gById_[l.graphicId]; return g ? g.name : ""; }).filter(Boolean))].filter(Boolean).join(" · ") || "—")}</span>`
                  : cfgEditorHtml_(row, idx, curProd))
              : row._removed
                ? (row.personalized ? `<span style="font-size:12px;color:var(--ink-soft);">"${escapeHtml(row.persName || "")}"</span>` : `<span style="font-size:12px;color:var(--ink-soft);">—</span>`)
                : curProd && curProd.personalizationPrice != null
                  ? `<label style="display:flex;align-items:center;gap:4px;font-size:11px;white-space:nowrap;"><input type="checkbox" data-rowidx="${idx}" data-field="personalized" ${row.personalized ? "checked" : ""}> Personalized${Number(curProd.personalizationPrice) ? ` (+$${Number(curProd.personalizationPrice).toFixed(2)})` : ""}</label>
                     ${row.personalized ? `<input type="text" placeholder="Name / text" value="${escapeHtml(row.persName || "")}" data-rowidx="${idx}" data-field="persName" style="font-size:12px;width:100px;padding:3px 4px;margin-top:3px;border:1px solid var(--border,#ccc);border-radius:3px;background:var(--surface,#fff);color:var(--ink,#111);">` : ""}`
                  : `<span style="font-size:12px;color:var(--ink-soft);">—</span>`
            }
          </td>
          <td style="padding:6px 4px;vertical-align:top;">
            ${!row._removed && row.itemId && ((curProd && curProd.personalizationPrice != null) || row._hasCustom)
              ? `<button type="button" data-rowidx="${idx}" data-action="files" style="font-size:11px;padding:2px 8px;border:1px solid var(--border,#ccc);border-radius:3px;cursor:pointer;background:var(--surface,#fff);">Files${row._fileCount ? ` (${row._fileCount})` : ""}</button>`
              : `<span style="font-size:12px;color:var(--ink-soft);">—</span>`
            }
          </td>
          <td style="padding:6px 4px;vertical-align:top;text-align:right;font-size:12px;">
            $${calcRowTotal(row).toFixed(2)}
          </td>
          <td style="padding:6px 4px;vertical-align:top;">
            ${row._removed
              ? `<div style="font-size:11px;">
                  <input type="text" placeholder="Reason" value="${escapeHtml(row._refundReason)}" data-rowidx="${idx}" data-field="_refundReason" style="font-size:11px;width:90px;padding:2px 4px;border:1px solid var(--border,#ccc);border-radius:3px;margin-bottom:3px;">
                  <div>Refund: $<input type="number" min="0" step="0.01" value="${escapeHtml(row._refundAmount)}" data-rowidx="${idx}" data-field="_refundAmount" style="font-size:11px;width:60px;padding:2px 4px;border:1px solid var(--border,#ccc);border-radius:3px;"></div>
                  <button data-rowidx="${idx}" data-action="unremove" style="font-size:11px;margin-top:3px;padding:2px 6px;border:1px solid var(--border,#ccc);border-radius:3px;cursor:pointer;background:var(--surface,#fff);">Undo</button>
                </div>`
              : `<button class="admin-btn-danger" data-rowidx="${idx}" data-action="remove" style="font-size:11px;padding:2px 8px;border-radius:3px;cursor:pointer;">Remove</button>`
            }
          </td>
        `;
        tbody.appendChild(tr);
      });
    }

    function updateSummary(overlay){
      const newTotal = calcNewTotal();
      const diff = Math.round((newTotal - state.originalTotal) * 100) / 100;
      const diffEl = overlay.querySelector("#editOrderDiff");
      const saveBtn = overlay.querySelector("#editOrderSave");
      const payBtn = overlay.querySelector("#editOrderPay");
      const newTotalEl = overlay.querySelector("#editOrderNewTotal");
      if(diffEl){
        if(Math.abs(diff) < 0.005){
          diffEl.textContent = "No price change";
          diffEl.style.color = "var(--ink-soft,#666)";
        } else if(diff > 0){
          diffEl.textContent = "+" + diff.toFixed(2) + " additional charge" + (taxOnTop ? " + sales tax" : "");
          diffEl.style.color = "#dc2626";
        } else {
          diffEl.textContent = diff.toFixed(2) + " credit due" + (taxOnTop ? " (and its sales tax)" : "");
          diffEl.style.color = "#15803d";
        }
      }
      if(newTotalEl) newTotalEl.textContent = "$" + newTotal.toFixed(2) + (taxOnTop ? " + sales tax" : "");
      if(payBtn) payBtn.style.display = diff > 0 ? "inline-block" : "none";
      if(payBtn) payBtn.textContent = "Save & request payment (+" + diff.toFixed(2) + (taxOnTop ? " + tax" : "") + ")";
    }

    const overlay = document.createElement("div");
    overlay.className = "admin-pass-overlay";
    overlay.style.zIndex = "1003";
    overlay.innerHTML = `
      <div class="admin-pass-box" style="max-width:720px;width:95vw;max-height:85vh;overflow-y:auto;">
        <div style="font-weight:700;font-size:16px;margin-bottom:4px;">Edit items — ${escapeHtml(order.orderId)}</div>
        <div style="font-size:13px;color:var(--ink-soft,#666);margin-bottom:12px;">${escapeHtml(order.customerName)} · Original total: $${Number(order.total).toFixed(2)}</div>
        <table style="width:100%;border-collapse:collapse;font-size:13px;margin-bottom:10px;">
          <thead>
            <tr style="border-bottom:1px solid var(--border,#ccc);">
              <th style="text-align:left;padding:4px;font-size:11px;font-weight:600;color:var(--ink-soft);">Product</th>
              <th style="text-align:left;padding:4px;font-size:11px;font-weight:600;color:var(--ink-soft);">Size</th>
              <th style="text-align:left;padding:4px;font-size:11px;font-weight:600;color:var(--ink-soft);">Qty</th>
              <th style="text-align:left;padding:4px;font-size:11px;font-weight:600;color:var(--ink-soft);">Personalization</th>
              <th style="text-align:left;padding:4px;font-size:11px;font-weight:600;color:var(--ink-soft);">Files</th>
              <th style="text-align:right;padding:4px;font-size:11px;font-weight:600;color:var(--ink-soft);">Price</th>
              <th style="padding:4px;"></th>
            </tr>
          </thead>
          <tbody id="editOrderRows"></tbody>
        </table>
        <div style="margin-bottom:12px;">
          <button id="editOrderAddRow" style="font-size:12px;padding:4px 10px;border:1px dashed var(--border,#ccc);border-radius:3px;cursor:pointer;background:var(--surface,#fff);color:var(--ink,#111);">+ Add item</button>
        </div>
        <div style="display:flex;align-items:center;gap:12px;margin-bottom:14px;font-size:13px;">
          <span>New total: <strong id="editOrderNewTotal">$0.00</strong></span>
          <span id="editOrderDiff" style="font-weight:600;"></span>
        </div>
        <div class="admin-pass-actions" style="flex-wrap:wrap;gap:8px;">
          <button type="button" id="editOrderRefresh" title="Re-read this order's graphics and reorder QR from the catalog (prices don't change)" style="padding:8px 12px;font-size:13px;border-radius:5px;border:1px solid var(--border,#ccc);cursor:pointer;background:var(--surface,#fff);color:var(--ink,#111);margin-right:auto;">Update from catalog…</button>
          <button type="button" class="admin-pass-cancel" id="editOrderCancel">Cancel</button>
          <button type="button" id="editOrderSave" style="padding:8px 16px;font-size:14px;font-weight:600;border-radius:5px;border:none;cursor:pointer;background:#2563eb;color:#fff;">Save changes</button>
          <button type="button" id="editOrderPay" style="display:none;padding:8px 16px;font-size:14px;font-weight:600;border-radius:5px;border:none;cursor:pointer;background:#15803d;color:#fff;">Save &amp; request payment</button>
        </div>
      </div>
    `;
    document.body.appendChild(overlay);

    const tbody = overlay.querySelector("#editOrderRows");
    renderRows(tbody);
    updateSummary(overlay);

    // Event delegation on table
    tbody.addEventListener("change", (e) => {
      const el = e.target;
      // Configurable line pickers (colour / per-location graphic / ink) — update row.config, which
      // calcRowTotal reprices via cfgUnitPrice_; the server re-validates and reprices on save.
      if(el.dataset.cfgfield){
        const row2 = state.rows[Number(el.dataset.rowidx)];
        if(!row2 || !row2.config) return;
        const prod = getProductById(row2.productId);
        const cf = el.dataset.cfgfield, locKey = el.dataset.loc;
        if(cf === "color"){
          row2.config.garmentColor = el.value;
          row2.config.locations = (row2.config.locations || []).filter(l => {
            const loc = (prod.locations || []).find(x => x.key === l.location);
            return loc && (l.custom || cfgOptsForLoc_(prod, loc, el.value).some(g => String(g.id) === String(l.graphicId)));   // the customer's design suits any color
          });
        } else if(cf === "graphic"){
          row2.config.locations = (row2.config.locations || []).filter(l => l.location !== locKey);
          if(el.value === "custom") row2.config.locations.push({ location: locKey, custom: true });
          else if(el.value){ const g = gById_[Number(el.value)]; row2.config.locations.push({ location: locKey, graphicId: Number(el.value), ink: (g && g.inkColors && g.inkColors.length === 1) ? g.inkColors[0] : "" }); }
        } else if(cf === "ink"){
          const entry = (row2.config.locations || []).find(l => l.location === locKey);
          if(entry) entry.ink = el.value;
        }
        renderRows(tbody);
        updateSummary(overlay);
        return;
      }
      const idx = Number(el.dataset.rowidx);
      const field = el.dataset.field;
      if(!field || isNaN(idx)) return;
      const row = state.rows[idx];
      if(!row) return;

      if(field === "productId"){
        const prod = getProductById(el.value);
        row.productId = el.value;
        row.name = prod ? prod.name : el.value;
        row.type = prod ? prod.type : "";
        const sizes = getSizesForProduct(prod);
        row.size = sizes.includes(row.size) ? row.size : (sizes[0] || "");
        const pricing = getPriceForProduct(prod, row.size, row.personalized);
        row.unitPrice = pricing.unitPrice;
        row.personalizationFee = pricing.personalizationFee;
        renderRows(tbody);
      } else if(field === "size"){
        row.size = el.value;
        const prod = getProductById(row.productId);
        const pricing = getPriceForProduct(prod, row.size, row.personalized);
        row.unitPrice = pricing.unitPrice;
        row.personalizationFee = pricing.personalizationFee;
        renderRows(tbody);
      } else if(field === "qty"){
        row.qty = Math.max(1, Math.min(50, parseInt(el.value) || 1));
        renderRows(tbody);
      } else if(field === "personalized"){
        row.personalized = el.checked;
        if(!row.personalized) row.persName = "";
        const prod = getProductById(row.productId);
        const pricing = getPriceForProduct(prod, row.size, row.personalized);
        row.unitPrice = pricing.unitPrice;
        row.personalizationFee = pricing.personalizationFee;
        renderRows(tbody);
      } else if(field === "persName"){
        row.persName = el.value;
        return;
      } else if(field === "_refundReason"){
        row._refundReason = el.value;
        return;
      } else if(field === "_refundAmount"){
        row._refundAmount = el.value;
        return;
      }
      updateSummary(overlay);
    });
    // The personalization text field updates on every keystroke (not just on blur),
    // so it's never lost if Save is clicked without tabbing out first.
    tbody.addEventListener("input", (e) => {
      const el = e.target;
      if(el.dataset.field !== "persName") return;
      const row = state.rows[Number(el.dataset.rowidx)];
      if(row) row.persName = el.value;
    });

    tbody.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-action]");
      if(!btn) return;
      const idx = Number(btn.dataset.rowidx);
      const action = btn.dataset.action;
      const row = state.rows[idx];
      if(!row) return;
      if(action === "remove"){
        row._removed = true;
      } else if(action === "unremove"){
        row._removed = false;
      } else if(action === "files"){
        showOrderItemFilesModal_(row.itemId, row.name, (count) => { row._fileCount = count; renderRows(tbody); }, row._designSlots);
        return;
      }
      renderRows(tbody);
      updateSummary(overlay);
    });

    overlay.querySelector("#editOrderAddRow").addEventListener("click", () => {
      const firstProd = visibleProducts[0];
      const sizes = getSizesForProduct(firstProd);
      const pricing = getPriceForProduct(firstProd, sizes[0] || "", false);
      state.rows.push({
        _id: Math.random().toString(36).slice(2),
        itemId: null,
        productId: firstProd ? firstProd.productId : "",
        name: firstProd ? firstProd.name : "",
        type: firstProd ? firstProd.type : "",
        size: sizes[0] || "",
        qty: 1,
        unitPrice: pricing.unitPrice,
        personalizationFee: pricing.personalizationFee,
        personalized: false,
        persName: "",
        originalLineTotal: 0,
        originalItemId: null,
        _removed: false,
        _refundAmount: "0.00",
        _refundReason: "",
      });
      renderRows(tbody);
      updateSummary(overlay);
    });

    function finish(requestPayment){
      // Build diff arrays
      const removals = [];
      const updates = [];
      const additions = [];

      for(const row of state.rows){
        if(row._removed && row.itemId != null){
          removals.push({
            itemId: row.itemId,
            reason: row._refundReason || "Admin edit",
            refundAmount: parseFloat(row._refundAmount) || 0,
          });
        } else if(!row._removed && row.itemId != null){
          // Check if changed
          const orig = order.items.find(it => it.sheetRow === row.itemId);
          const cfgChanged = row.configurable && JSON.stringify(row.config) !== row._origConfigJson;
          const changed = !orig || orig.productId !== row.productId || orig.size !== row.size || orig.qty !== row.qty ||
            !!orig.personalized !== !!row.personalized || (orig.persName || "") !== (row.persName || "") || cfgChanged;
          if(changed){
            updates.push({
              itemId: row.itemId,
              productId: row.productId,
              size: row.size,
              qty: row.qty,
              personalized: row.personalized,
              persName: row.persName,
              ...(row.configurable ? { config: row.config } : {}),
            });
          }
        } else if(!row._removed && row.itemId == null){
          additions.push({
            productId: row.productId,
            size: row.size,
            qty: row.qty,
            personalized: row.personalized,
            persName: row.persName,
          });
        }
      }

      document.body.removeChild(overlay);
      resolve({ removals, updates, additions, requestPayment, emailBody: "" });
    }

    overlay.querySelector("#editOrderCancel").addEventListener("click", () => {
      document.body.removeChild(overlay);
      resolve(null);
    });
    overlay.querySelector("#editOrderRefresh").addEventListener("click", async () => {
      const done = await refreshOrderFromCatalog_(order);
      if(done){ document.body.removeChild(overlay); resolve(null); }
    });
    overlay.querySelector("#editOrderSave").addEventListener("click", () => finish(false));
    overlay.querySelector("#editOrderPay").addEventListener("click", () => finish(true));
    document.addEventListener("keydown", function esc(e){
      if(e.key === "Escape"){ document.body.removeChild(overlay); resolve(null); document.removeEventListener("keydown", esc); }
    }, {once: true});
  });
}

// Respond to the browser's back/forward buttons — skip hashchange events that
// WE fired (via adminSetHash) by comparing against _currentAdminHash.
// A product or shop form with unsaved changes (window._prodFormDirty) asks before going anywhere else — the menu,
// a link, back — and before the tab is closed or reloaded.
// The address has already changed when this fires, so it's put back first (the page stays as it is) and the
// question asked; Leave then goes to where the admin was heading.
window.addEventListener("hashchange", async function(){
  const hash = location.hash.replace(/^#\/?/, "");
  if (hash === _currentAdminHash) return;
  if (window._prodFormDirty) {
    const target = location.hash;
    adminSetHash(_currentAdminHash);
    if (window._leaveAsked) return;
    window._leaveAsked = true;
    const leave = await askConfirm_("Leave without saving?\n\nYou have changes on this page that aren't saved.", { confirmLabel: "Leave", cancelLabel: "Stay", danger: true });
    window._leaveAsked = false;
    if (!leave) return;
    window._prodFormDirty = false;
    location.hash = target;
    return;
  }
  adminRoute();
});
window.addEventListener("beforeunload", function(e){ if (window._prodFormDirty) { e.preventDefault(); e.returnValue = ""; } });
